    'zanzibar_beach_east_desc' => 'Matemwe faces Mnemba atoll, the best snorkelling on the island. Kizimkazi is where the dolphin boats leave from.',
    'zanzibar_beach_east_best' => 'Best for: snorkelling, diving, quiet',
    'zanzibar_tide_note' => '<strong>About the tides:</strong> on the east and south-east coasts the sea withdraws several hundred metres at low tide and swimming is not possible for part of the day. It is not a problem, it is simply how the island works, but if swimming whenever you like matters to you, choose the north.',

    'zanzibar_excursions_badge' => 'Beyond the beach',
    'zanzibar_excursions_title' => 'Excursions worth doing',
    'zanzibar_exc_stonetown_title' => 'Stone Town',
    'zanzibar_exc_stonetown_desc' => 'A UNESCO World Heritage site: carved doors, the old slave market, the Forodhani night food market. Half a day with a local guide.',
    'zanzibar_exc_spice_title' => 'Spice tour',
    'zanzibar_exc_spice_desc' => 'The plantations that gave the island its name: cloves, vanilla, nutmeg and cinnamon, tasted straight from the tree.',
    'zanzibar_exc_safariblue_title' => 'Safari Blue',
    'zanzibar_exc_safariblue_desc' => 'A full day by dhow: sandbanks, snorkelling, a seafood lunch on Kwale island and mangrove channels.',
    'zanzibar_exc_jozani_title' => 'Jozani Forest',
    'zanzibar_exc_jozani_desc' => 'The last habitat of the red colobus monkey, found nowhere else on earth. Two hours, easily combined with the south coast.',
    'zanzibar_exc_mnemba_title' => 'Mnemba atoll',
    'zanzibar_exc_mnemba_desc' => 'The island\'s best snorkelling and diving, reached by boat from Matemwe.',
    'zanzibar_exc_prison_title' => 'Prison Island',
    'zanzibar_exc_prison_desc' => 'Giant Aldabra tortoises, some of them well over a century old, and a short boat ride from Stone Town.',

    'zanzibar_when_badge' => 'Planning',
    'zanzibar_when_title' => 'When to go',
    'zanzibar_when_dry_period' => 'June – October',
    'zanzibar_when_dry_temp' => '26–30°C',
    'zanzibar_when_dry_desc' => 'Dry, sunny and less humid. The high season, and the natural continuation of a dry-season safari.',
    'zanzibar_when_dry_tag' => 'Best',
    'zanzibar_when_summer_period' => 'December – February',
    'zanzibar_when_summer_temp' => '28–32°C',
    'zanzibar_when_summer_desc' => 'Hot, calm sea, excellent visibility for diving. Short showers possible.',
    'zanzibar_when_summer_tag' => 'Very good',
    'zanzibar_when_long_rains_period' => 'March – May',
    'zanzibar_when_long_rains_temp' => '27–31°C',
    'zanzibar_when_long_rains_desc' => 'The long rains. Lowest prices and empty beaches, but some hotels close in April and May.',
    'zanzibar_when_long_rains_tag' => 'Low season',
    'zanzibar_when_nov_period' => 'November',
    'zanzibar_when_nov_temp' => '27–31°C',
    'zanzibar_when_nov_desc' => 'Short rains: brief afternoon downpours, otherwise sunny. Good value before the December rush.',
    'zanzibar_when_nov_tag' => 'Good value',

    'zanzibar_featured_badge' => 'Most requested combo',
    'zanzibar_featured_title' => '7-Day Safari + Zanzibar',
    'zanzibar_featured_desc' => '5 nights safari across the northern circuit, 2 nights unwinding in Zanzibar, internal flight included.',
    'zanzibar_featured_price' => 'from $2,200 per person',
    'zanzibar_featured_cta' => 'See this package',

    'zanzibar_practical_badge' => 'Good to know',
    'zanzibar_practical_title' => 'Practical notes',
    'zanzibar_practical_entry_title' => 'Entry requirements',
    'zanzibar_practical_entry_desc' => 'Zanzibar is part of Tanzania, so the same visa applies. Since 2024 an insurance policy issued by a Zanzibari-approved provider is also required on arrival; it costs around US$44 and we can arrange it with your booking.',
    'zanzibar_practical_dress_title' => 'Dress and customs',
    'zanzibar_practical_dress_desc' => 'Zanzibar is predominantly Muslim. Swimwear is fine on the beach and at your hotel, but cover shoulders and knees in Stone Town and the villages. During Ramadan many restaurants outside the resorts close during daylight.',
    'zanzibar_practical_flight_title' => 'Getting there from the safari',
    'zanzibar_practical_flight_desc' => 'A direct flight from the Serengeti airstrips takes about 1 hour 30 minutes; from Arusha or Kilimanjaro Airport, around an hour. We book these internal flights as part of your itinerary.',
    'zanzibar_practical_malaria_title' => 'Malaria',
    'zanzibar_practical_malaria_desc' => 'Zanzibar is a malaria area. Prophylaxis is recommended (ask your doctor or travel clinic) and use repellent at dusk. Drink bottled or filtered water.',

    'zanzibar_faq_title' => 'Common questions',
    'zanzibar_faq_q1' => 'How many days should I add for Zanzibar?',
    'zanzibar_faq_a1' => 'Three nights is the minimum to feel like a holiday rather than a stopover. Four to five gives you time for a beach day, one excursion and Stone Town without rushing.',
    'zanzibar_faq_q2' => 'Is Zanzibar included in the safari price?',
    'zanzibar_faq_a2' => 'No, it is an optional extension. We quote it separately alongside your safari so you can see exactly what it adds, including the internal flight.',
    'zanzibar_faq_q3' => 'Which beach should first-time visitors choose?',
    'zanzibar_faq_a3' => 'Nungwi or Kendwa in the north: swimmable at any tide, the most hotels and restaurants, and the easiest introduction to the island.',
    'zanzibar_faq_q4' => 'Do I need extra vaccinations for Zanzibar?',
    'zanzibar_faq_a4' => 'No vaccinations beyond what is required for mainland Tanzania. Malaria prophylaxis is recommended, and the local insurance policy is compulsory on arrival.',

    'zanzibar_cta_title' => 'Plan your trip with us',
    'zanzibar_cta_intro' => 'Send us your dates, group size and budget. We reply with a written itinerary and a full price breakdown, no obligation.',
    'zanzibar_cta_whatsapp' => 'Message us on WhatsApp',
    'zanzibar_cta_contact_form' => 'Contact form',

    'trekking_meta_title' => 'Kilimanjaro & Mount Meru Trekking | Serengeti Budget Safari',
    'trekking_meta_description' => 'Climb Kilimanjaro with a local Arusha operator: Machame, Lemosho, Marangu, Rongai and Northern Circuit routes, plus Mount Meru, Ol Doinyo Lengai and the Usambara mountains.',
    'trekking_hero_badge' => 'Trekking',
    'trekking_hero_title_1' => 'Kilimanjaro',
    'trekking_hero_title_2' => 'trekking',
    'trekking_hero_sub' => "Africa's highest point at 5,895 m, plus Mount Meru, Ol Doinyo Lengai and the Usambara hills, climbed with our own mountain crew.",
    'trekking_hero_cta_quote' => 'Request a quote',

    'trekking_routes_badge' => 'Pick your path',
    'trekking_routes_title' => 'Choose your route',
    'trekking_routes_intro' => 'The mountain is not technical: the challenge is altitude. The longer the route, the better your body acclimatises and the higher your chance of standing on Uhuru Peak.',

    'trekking_route_lemosho_tagline' => 'Best scenery & acclimatisation',
    'trekking_route_lemosho_name' => 'Lemosho',
    'trekking_route_lemosho_days' => '7–8 days',
    'trekking_route_lemosho_desc' => 'A quiet start through forest, joining Machame higher up. The best acclimatisation profile of any route.',
    'trekking_route_lemosho_success' => 'Highest',

    'trekking_route_machame_tagline' => 'The "Whiskey Route" · most popular',
    'trekking_route_machame_name' => 'Machame',
    'trekking_route_machame_days' => '6–7 days',
    'trekking_route_machame_desc' => 'Scenic, steep in places, a solid acclimatisation profile. The route most climbers choose.',
    'trekking_route_machame_success' => 'High',

    'trekking_route_northern_tagline' => 'Quietest trails, longest route',
    'trekking_route_northern_name' => 'Northern Circuit',
    'trekking_route_northern_days' => '9 days',
    'trekking_route_northern_desc' => 'Almost a full circle of the mountain. The longest route, with very few other groups on the trail.',
    'trekking_route_northern_success' => 'Highest',

    'trekking_route_rongai_tagline' => 'Driest in the rainy months',
    'trekking_route_rongai_name' => 'Rongai',
    'trekking_route_rongai_days' => '6–7 days',
    'trekking_route_rongai_desc' => 'Approaches from the drier north side. The best choice if you are climbing outside the main dry season.',
    'trekking_route_rongai_success' => 'Good',

    'trekking_route_marangu_tagline' => 'Huts instead of tents',
    'trekking_route_marangu_name' => 'Marangu',
    'trekking_route_marangu_days' => '5–6 days',
    'trekking_route_marangu_desc' => 'The only route with hut accommodation. Same path up and down, and the shortest option.',
    'trekking_route_marangu_success' => 'Lower',

    'trekking_routes_note' => 'If you have the days available, take the longer route. The extra night is the cheapest insurance you can buy against altitude sickness.',

    'trekking_included_title' => 'What every climb includes',
    'trekking_included_subtitle' => 'The same transparent pricing as our safaris, with no hidden extras once you are on the mountain.',
    'trekking_included_heading' => 'Included',
    'trekking_included_1' => 'Park fees, camping or hut fees and rescue fees',
    'trekking_included_2' => 'Certified mountain guide, assistant guides, cook and porters',
    'trekking_included_3' => 'All meals on the mountain and drinking water',
    'trekking_included_4' => 'Tents, sleeping mats, mess tent and cooking equipment',
    'trekking_included_5' => 'Pulse oximeter checks and a first-aid kit carried by the guide',
    'trekking_included_6' => 'Transfers between Arusha and the trailhead',
    'trekking_included_7' => 'Two nights in Arusha, before and after the climb',
    'trekking_excluded_heading' => 'Not included',
    'trekking_excluded_1' => 'International flights and visa',
    'trekking_excluded_2' => 'Travel insurance covering trekking to 6,000 m (compulsory)',
    'trekking_excluded_3' => 'Personal equipment and sleeping bag (rental available)',
    'trekking_excluded_4' => 'Tips for the mountain crew',
    'trekking_excluded_5' => 'Portable oxygen or personal porter, if requested',

    'trekking_other_badge' => 'Beyond Kilimanjaro',
    'trekking_other_title' => 'Other mountains',
    'trekking_meru_name' => 'Mount Meru, 4,566 m',
    'trekking_meru_desc' => 'Three or four days inside Arusha National Park, walking with an armed ranger past buffalo and giraffe. The best possible acclimatisation before Kilimanjaro.',
    'trekking_lengai_name' => 'Ol Doinyo Lengai, 2,962 m',
    'trekking_lengai_desc' => 'The Maasai\'s "Mountain of God", an active volcano climbed overnight to reach the crater rim at sunrise. Steep, hot and genuinely demanding.',
    'trekking_usambara_name' => 'Usambara & Udzungwa',
    'trekking_usambara_desc' => 'Green mountains, waterfalls and villages, walked over two to four days at low altitude. A good option in the rainy season or with children.',

    'trekking_guide_badge' => 'Go deeper',
    'trekking_guide_title' => 'Read the full park guide',
    'trekking_guide_intro' => 'Everything about Kilimanjaro National Park in one place: all seven routes compared with success rates, the 2026 park fees itemised, altitude sickness explained, and how porters should be treated.',
    'trekking_guide_kili_badge' => 'Park guide',
    'trekking_guide_kili_title' => 'Kilimanjaro National Park',
    'trekking_guide_kili_desc' => 'Five climate zones, seven routes, 5,895 m. Park fees alone are around $956 for a seven-day climb. We show you exactly how that is calculated.',
    'trekking_guide_kili_cta' => 'Full Kilimanjaro guide',
    'trekking_guide_meru_badge' => 'Park guide',
    'trekking_guide_meru_title' => 'Arusha NP & Mount Meru',
    'trekking_guide_meru_desc' => 'Meru at 4,566 m is the best acclimatisation available before Kilimanjaro, and a superb, almost empty mountain in its own right.',
    'trekking_guide_meru_cta' => 'Full Arusha NP guide',

    'trekking_faq_title' => 'Before you book',
    'trekking_faq_q1' => 'Do I need climbing experience?',
    'trekking_faq_a1' => 'No. Kilimanjaro is a long walk, not a climb: there is no rope work or technical ground. What it demands is stamina for six to nine days of walking and the ability to cope with thin air. Train by walking uphill for several hours at a time.',
    'trekking_faq_q2' => 'When is the best time to climb?',
    'trekking_faq_a2' => 'January to early March and June to October. April, May and November are the wet months: the mountain is still climbable, but the paths are slippery and the views often closed in. Rongai is the driest route in marginal conditions.',
    'trekking_faq_q3' => 'What about altitude sickness?',
    'trekking_faq_a3' => 'Mild headaches and breathlessness are normal above 4,000 m. Our guides check oxygen saturation twice daily and carry a first-aid kit. The rule on our climbs is simple: if a guide judges that you must descend, you descend. Nobody is pushed to continue.',

    'trekking_cta_title' => 'Plan your trip with us',
    'trekking_cta_intro' => 'Send us your dates, group size and budget. We reply with a written itinerary and a full price breakdown, no obligation.',
    'trekking_cta_whatsapp' => 'Message us on WhatsApp',
    'trekking_cta_contact_form' => 'Contact form',

