    'groups_faq_title' => 'Common questions',
    'groups_faq_q1' => 'What happens if a departure does not fill up?',
    'groups_faq_a1' => 'Our scheduled departures run with a minimum of 2 travellers. If fewer people have booked, we will tell you in advance rather than cancel at the last minute. You can wait for the next date or ask about a private safari at an adjusted price.',
    'groups_faq_q2' => 'Can I book a group safari alone?',
    'groups_faq_a2' => 'Yes, most of our group travellers are solo. You will share the vehicle and guide with a small number of other travellers on the same dates, not be the only guest.',
    'groups_faq_q3' => 'How far in advance should I book?',
    'groups_faq_a3' => 'For June to October (peak season) aim for 2-3 months ahead. Outside that window, 3-4 weeks is usually enough, but message us early if your dates are fixed.',
    'groups_faq_q4' => 'Can couples or friends travel together within a group safari?',
    'groups_faq_a4' => 'Yes, you will share the vehicle with other travellers but sit together as a pair or small party. We just fill the remaining seats with other guests on the same dates.',

    'pkg3d_meta_title' => '3-Day Serengeti Safari | Serengeti Budget Safari',
    'pkg3d_meta_description' => 'A 3-day safari through Serengeti Central and Ngorongoro Crater: Big Five, predators, private 4x4, from $1,000 per person. Price drops automatically for larger groups.',
    'pkg3d_hero_badge' => 'Best Seller',
    'pkg3d_hero_title' => '3-Day Serengeti Safari',
    'pkg3d_hero_sub' => 'Serengeti Central & Ngorongoro Crater: the fastest way to see the Big Five without rushing the trip.',

