    'pkg3d_calc_subtext' => 'Price per person drops automatically as your group grows.',
    'pkg3d_calc_people_label' => 'Travellers',
    'pkg3d_calc_pp_label' => 'Price per person',
    'pkg3d_calc_total_label' => 'Total price',
