    'pkg3d_calc_cta' => 'Ask on WhatsApp',
    'pkg3d_calc_note' => 'Estimate only. Park fees and final price confirmed on request.',
    'pkg3d_calc_wa_template' => "Hello, I'm interested in the 3-Day Serengeti Safari for {people} people. Estimated price: {pp} p.p. ({total} total). Can you confirm availability?",

    'pkg3d_itinerary_badge' => 'Day by day',
    'pkg3d_itinerary_title' => 'Your itinerary',
    'pkg3d_itinerary_intro' => 'Every stop, every drive, every meal: here is exactly what your three days look like.',

    'pkg3d_day1_title' => 'Arusha to Serengeti',
    'pkg3d_day1_mood' => 'Karibu Sana, welcome to Tanzania.',
    'pkg3d_day1_tl1_time' => '07:00',
    'pkg3d_day1_tl1_title' => 'Pickup in Arusha',
    'pkg3d_day1_tl1_desc' => 'Your driver-guide meets you at your hotel, Land Cruiser loaded and ready. This is the moment the trip actually begins, everything before it was just planning.',
    'pkg3d_day1_tl2_time' => '09:30',
    'pkg3d_day1_tl2_title' => 'Ngorongoro Highlands',
    'pkg3d_day1_tl2_desc' => 'The road climbs into cool, misty highland forest. A short stop at the crater viewpoint gives you your first look down into the caldera, and most guests go quiet for a moment here.',
    'pkg3d_day1_tl3_time' => '12:00',
    'pkg3d_day1_tl3_title' => 'Descent into the Serengeti',
    'pkg3d_day1_tl3_desc' => 'The highlands fall away behind you and the plains open up: this is the "Serengeti" the Maasai named for its endlessness. Lunch is a picnic with a view most restaurants can\'t match.',
    'pkg3d_day1_tl4_time' => '15:30',
    'pkg3d_day1_tl4_title' => 'First game drive',
    'pkg3d_day1_tl4_desc' => 'You\'ll reach camp by way of the bush, not the road, on an afternoon game drive that has produced more first-day lion sightings than we can count. Slowly, camp comes into view.',
    'pkg3d_day1_tl5_time' => '18:30',
    'pkg3d_day1_tl5_title' => 'Camp, dinner, first night under canvas',
    'pkg3d_day1_tl5_desc' => 'Settle into your tent before dark. Dinner is served under the stars, and somewhere out there, the Serengeti is already awake. You\'ll likely fall asleep to it.',
    'pkg3d_day1_drive' => '4–5 hours drive',
    'pkg3d_day1_meals' => 'Lunch & Dinner',
    'pkg3d_day1_stay' => 'Serengeti tented camp',

    'pkg3d_day2_title' => 'Full day, Serengeti Central',
    'pkg3d_day2_mood' => 'There is so much to see, it is worth every hour.',
    'pkg3d_day2_tl1_time' => '06:00',
    'pkg3d_day2_tl1_title' => 'Sunrise game drive',
    'pkg3d_day2_tl1_desc' => 'The best hour of any safari day. Predators that hunted overnight are still out, the light is soft and gold, and the Seronera plains, the highest predator density in Africa, start to move.',
    'pkg3d_day2_tl2_time' => '08:30',
    'pkg3d_day2_tl2_title' => 'Breakfast in the bush',
    'pkg3d_day2_tl2_desc' => 'A table is set wherever the morning finds you, sometimes with a view of grazing zebra. It is, without exception, the best breakfast setting our guests have ever had.',
    'pkg3d_day2_tl3_time' => '10:00',
    'pkg3d_day2_tl3_title' => 'Full-day exploration',
    'pkg3d_day2_tl3_desc' => 'The rest of the day is unhurried: your guide reads the radio chatter and the tracks in the dirt to decide where to go next. This is when the Serengeti stops being a place you visit and starts being a place you experience.',
    'pkg3d_day2_tl4_time' => '13:00',
    'pkg3d_day2_tl4_title' => 'Packed lunch, wherever you are',
    'pkg3d_day2_tl4_desc' => 'No rushing back to camp. Lunch comes to you, under an acacia tree, with the plains stretching in every direction.',
    'pkg3d_day2_tl5_time' => '19:00',
    'pkg3d_day2_tl5_title' => 'Dinner under the stars',
    'pkg3d_day2_tl5_desc' => 'Back at camp, the campfire is lit and the stories from the day get told and retold. Ask your guide about the Serengeti\'s name, "endless plains" in Maasai, and why it has earned every syllable of it.',
    'pkg3d_day2_drive' => 'Full-day, off-road',
    'pkg3d_day2_meals' => 'Breakfast, Lunch & Dinner',
    'pkg3d_day2_stay' => 'Serengeti tented camp',

    'pkg3d_day3_title' => 'Ngorongoro Crater to Arusha',
    'pkg3d_day3_mood' => 'Today, the eighth wonder of the world.',
    'pkg3d_day3_tl1_time' => '05:30',
    'pkg3d_day3_tl1_title' => 'Early departure',
    'pkg3d_day3_tl1_desc' => 'A pre-dawn start is worth it today. Breakfast is packed, and you\'ll be on the road while the Serengeti is still waking up around you.',
    'pkg3d_day3_tl2_time' => '08:00',
    'pkg3d_day3_tl2_title' => 'Crater rim, first light',
    'pkg3d_day3_tl2_desc' => 'The view from the rim gives almost everyone goosebumps, and not just from the cold at 2,300 metres. Below you, 264 km² of caldera holds one of the densest concentrations of wildlife on Earth.',
    'pkg3d_day3_tl3_time' => '09:00',
    'pkg3d_day3_tl3_title' => 'Descent to the crater floor',
    'pkg3d_day3_tl3_desc' => 'The track winds down to 1,700 metres. This is your best chance in Tanzania to see black rhino, alongside lion, elephant and the herds of zebra and wildebeest that never leave the crater floor.',
    'pkg3d_day3_tl4_time' => '12:30',
    'pkg3d_day3_tl4_title' => 'Picnic lunch, crater floor',
    'pkg3d_day3_tl4_desc' => 'Lunch is taken with the crater walls rising all around you, one of the more surreal dining rooms you\'ll ever sit in.',
    'pkg3d_day3_tl5_time' => '14:30',
    'pkg3d_day3_tl5_title' => 'Climb out, drive to Arusha',
    'pkg3d_day3_tl5_desc' => 'The exit from the crater is as spectacular as the entrance, so take a last look back. From here, it\'s a few hours\' drive back to Arusha, arriving in the late afternoon with three days of stories to tell.',
    'pkg3d_day3_drive' => '4–5 hours drive',
    'pkg3d_day3_meals' => 'Breakfast & Lunch',
    'pkg3d_day3_stay' => 'Trip ends, Arusha',

