    'pkg3d_gallery_badge' => 'What you will see',
    'pkg3d_gallery_title' => 'Serengeti & Ngorongoro in pictures',

    'pkg3d_faq_title' => 'Questions about this safari',
    'pkg3d_faq_q1' => 'Is 3 days enough to see the Serengeti?',
    'pkg3d_faq_a1' => 'It is the practical minimum. You get one full day inside the park plus the Ngorongoro Crater, which between them cover the highest concentrations of wildlife in Tanzania. Longer trips add more parks, not more of the Serengeti itself.',
    'pkg3d_faq_q2' => 'Will I see the Big Five?',
    'pkg3d_faq_a2' => 'Lion, elephant, buffalo and leopard are seen regularly on this route. Black rhino is only realistic in Ngorongoro Crater, which is why this itinerary includes it. No operator can guarantee a sighting of a wild animal, but this combination gives you the best odds in the country.',
    'pkg3d_faq_q3' => 'Can I extend this to more days?',
    'pkg3d_faq_a3' => 'Yes, this itinerary is the base of our 4, 5 and 8-day packages, which add Tarangire, more Serengeti days, or the migration route. Tell us your dates and we will adjust it.',

    'pkg3d_cta_title' => 'Ready to book this safari?',
    'pkg3d_cta_intro' => 'Send us your dates and group size. We reply with a written itinerary and final price, no obligation.',
    'pkg3d_cta_whatsapp' => 'Message us on WhatsApp',
    'pkg3d_cta_contact_form' => 'Book Now',

    'pkg5d_meta_title' => '5-Day Serengeti & Ngorongoro Safari | Serengeti Budget Safari',
    'pkg5d_meta_description' => '5-day Tanzania safari through Tarangire, Serengeti and Ngorongoro: Big Five, private 4x4, all park fees included, from $650 per person.',

