    'pkg5d_overview_badge' => 'Overview',
    'pkg5d_overview_title' => 'Experience the Wild Heart of Tanzania',
    'pkg5d_overview_p1' => 'Experience an unforgettable 5-day Tanzania safari through Tarangire, Serengeti and Ngorongoro. Search for the Big Five, explore breathtaking landscapes and enjoy comfortable accommodation while travelling in a private 4x4 safari vehicle.',
    'pkg5d_overview_p2' => 'Every game drive is led by our own guides, in our own vehicles: the same team from the first pickup in Arusha to the last drop-off. No subcontracted vehicles, no shared itineraries with strangers unless you choose a group departure.',
    'pkg5d_love_title' => "Why you'll love this safari",
    'pkg5d_love_1' => 'Big Five opportunities',
    'pkg5d_love_2' => 'Professional safari guide',
    'pkg5d_love_3' => 'Private 4x4 vehicle',
    'pkg5d_love_4' => 'All park fees included',
    'pkg5d_love_5' => 'Flexible itinerary',
    'pkg5d_love_6' => 'Comfortable tented camps',

    'pkg5d_route_badge' => 'The journey',
    'pkg5d_route_title' => 'Safari route',
    'pkg5d_route_arusha' => 'Arusha',
    'pkg5d_route_tarangire' => 'Tarangire',
    'pkg5d_route_serengeti' => 'Serengeti',
    'pkg5d_route_ngorongoro' => 'Ngorongoro',

    'pkg5d_itinerary_badge' => 'Day by day',
    'pkg5d_itinerary_title' => 'Your itinerary',
    'pkg5d_itinerary_intro' => 'Tap a day to expand it.',

    'pkg5d_day1_title' => 'Arusha → Tarangire National Park',
    'pkg5d_day1_mood' => 'Karibu Sana, welcome to Tanzania.',
    'pkg5d_day1_drive' => '2–3 hours drive',
    'pkg5d_day1_meals' => 'Lunch & Dinner',
    'pkg5d_day1_stay' => 'Marera Valley Lodge',
    'pkg5d_day1_desc' => 'Pickup from your Arusha hotel mid-morning and drive to Tarangire National Park, famous for its baobabs and huge elephant herds. Afternoon game drive along the Tarangire River before checking into your lodge.',
    'pkg5d_day1_act1' => 'Game drive',
    'pkg5d_day1_act2' => 'Wildlife viewing',
    'pkg5d_day1_tl1_time' => '09:30',
    'pkg5d_day1_tl1_title' => 'Pickup in Arusha',
    'pkg5d_day1_tl1_desc' => 'A mid-morning start means no pre-dawn alarm on your first day. Your driver-guide loads the Land Cruiser and the trip is finally, actually happening.',
    'pkg5d_day1_tl2_time' => '12:00',
    'pkg5d_day1_tl2_title' => 'Into Tarangire',
    'pkg5d_day1_tl2_desc' => 'The park gate marks the start of baobab country, and some of these trees have stood for over a thousand years. Elephants gather here in numbers found almost nowhere else in Tanzania.',
    'pkg5d_day1_tl3_time' => '14:30',
    'pkg5d_day1_tl3_title' => 'Afternoon game drive',
    'pkg5d_day1_tl3_desc' => 'Following the Tarangire River, where wildlife concentrates even in the dry months. Watch for elephant families crossing in single file, and the baobabs standing like sentinels over it all.',
    'pkg5d_day1_tl4_time' => '17:30',
    'pkg5d_day1_tl4_title' => 'Check-in, Marera Valley Lodge',
    'pkg5d_day1_tl4_desc' => 'Your first night sets the tone for the trip: dinner overlooking the valley, and the sound of Tarangire settling into the dark.',

    'pkg5d_day2_title' => 'Tarangire → Central Serengeti',
    'pkg5d_day2_mood' => 'From baobabs to the endless plains.',
    'pkg5d_day2_drive' => '4–5 hours drive',
    'pkg5d_day2_meals' => 'Breakfast, Lunch & Dinner',
    'pkg5d_day2_stay' => 'Serengeti Tented Camp',
    'pkg5d_day2_desc' => 'Morning drive west across the Great Rift Valley into central Serengeti, with a stop at a Maasai viewpoint. Afternoon game drive on arrival, watching for lion and cheetah on the open plains.',
    'pkg5d_day2_act1' => 'Scenic drive',
    'pkg5d_day2_act2' => 'Afternoon game drive',
    'pkg5d_day2_tl1_time' => '07:30',
    'pkg5d_day2_tl1_title' => 'West across the Rift Valley',
    'pkg5d_day2_tl1_desc' => 'The road drops off the highlands into the Great Rift Valley, one of the few places on Earth where you can see the planet\'s tectonic history simply by looking out the window.',
    'pkg5d_day2_tl2_time' => '10:00',
    'pkg5d_day2_tl2_title' => 'Maasai viewpoint',
    'pkg5d_day2_tl2_desc' => 'A short stop where the land opens up ahead of you: your first real glimpse of what "endless plains" actually means.',
    'pkg5d_day2_tl3_time' => '13:00',
    'pkg5d_day2_tl3_title' => 'Arrival, central Serengeti',
    'pkg5d_day2_tl3_desc' => 'You\'re now in Big Cat country. An afternoon game drive on arrival day has a habit of producing lion and cheetah sightings before you\'ve even unpacked.',
    'pkg5d_day2_tl4_time' => '18:30',
    'pkg5d_day2_tl4_title' => 'Camp, first Serengeti night',
    'pkg5d_day2_tl4_desc' => 'Dinner under canvas, with the plains stretching dark and quiet in every direction outside the firelight.',

    'pkg5d_day3_title' => 'Full Day Serengeti',
    'pkg5d_day3_mood' => 'There is so much to see, it is worth every hour.',
    'pkg5d_day3_drive' => 'In-park game drives',
    'pkg5d_day3_meals' => 'Breakfast, Lunch & Dinner',
    'pkg5d_day3_stay' => 'Serengeti Tented Camp',
    'pkg5d_day3_desc' => 'A full day exploring the Seronera region, the highest predator density in the park. Packed lunch in the bush, with the option to extend the afternoon drive toward the Mara River in migration season.',
    'pkg5d_day3_act1' => 'Full-day game drive',
    'pkg5d_day3_act2' => 'Bush lunch',
    'pkg5d_day3_tl1_time' => '06:00',
    'pkg5d_day3_tl1_title' => 'Sunrise game drive',
    'pkg5d_day3_tl1_desc' => 'The best hour of any safari day. Predators that hunted overnight are often still visible, and the Seronera region wakes up around you in gold light.',
    'pkg5d_day3_tl2_time' => '09:00',
    'pkg5d_day3_tl2_title' => 'Breakfast in the bush',
    'pkg5d_day3_tl2_desc' => 'A table set wherever the morning finds you. It\'s a strong contender for the best breakfast view you\'ll ever have.',
    'pkg5d_day3_tl3_time' => '11:00',
    'pkg5d_day3_tl3_title' => 'Full-day exploration',
    'pkg5d_day3_tl3_desc' => 'Your guide reads the radio and the tracks in the dirt to decide where the day leads. In migration season, this is when the drive can extend north toward the Mara River crossings.',
    'pkg5d_day3_tl4_time' => '19:00',
    'pkg5d_day3_tl4_title' => 'Dinner, campfire stories',
    'pkg5d_day3_tl4_desc' => 'Back at camp, the day\'s sightings get told and retold around the fire. Ask your guide what "Serengeti" means in Maasai, and why the name has earned every syllable.',

    'pkg5d_day4_title' => 'Serengeti → Ngorongoro',
    'pkg5d_day4_mood' => 'One last look at the plains, then up into the clouds.',
    'pkg5d_day4_drive' => '3–4 hours drive',
    'pkg5d_day4_meals' => 'Breakfast, Lunch & Dinner',
    'pkg5d_day4_stay' => 'Ngorongoro Rim Lodge',
    'pkg5d_day4_desc' => 'Final morning game drive in the Serengeti before driving up onto the Ngorongoro highlands. Afternoon at leisure at your lodge on the crater rim, with sweeping views over the caldera.',
    'pkg5d_day4_act1' => 'Morning game drive',
    'pkg5d_day4_act2' => 'Crater rim views',
    'pkg5d_day4_tl1_time' => '06:30',
    'pkg5d_day4_tl1_title' => 'Final Serengeti game drive',
    'pkg5d_day4_tl1_desc' => 'One more sunrise on the plains before you go, a fitting way to say goodbye to a place that\'s hard to leave.',
    'pkg5d_day4_tl2_time' => '10:00',
    'pkg5d_day4_tl2_title' => 'Climb to the highlands',
    'pkg5d_day4_tl2_desc' => 'The road rises out of the plains into cool, misty highland forest, a completely different Tanzania from the one you left that morning.',
    'pkg5d_day4_tl3_time' => '14:00',
    'pkg5d_day4_tl3_title' => 'Check-in, crater rim',
    'pkg5d_day4_tl3_desc' => 'Your lodge sits on the rim of the Ngorongoro Crater, one of the most extraordinary views on the entire safari, and a quiet afternoon to enjoy it.',
    'pkg5d_day4_tl4_time' => '19:00',
    'pkg5d_day4_tl4_title' => 'Dinner with a view',
    'pkg5d_day4_tl4_desc' => 'As the light fades over the caldera below, most guests agree this is the dinner setting they remember longest.',

    'pkg5d_day5_title' => 'Ngorongoro → Arusha',
    'pkg5d_day5_mood' => 'Today, the eighth wonder of the world.',
    'pkg5d_day5_drive' => '3 hours drive',
    'pkg5d_day5_meals' => 'Breakfast & Lunch',
    'pkg5d_day5_stay' => 'Departure',
    'pkg5d_day5_desc' => 'Descend into Ngorongoro Crater at dawn for the best chance at black rhino, alongside dense concentrations of lion, elephant and buffalo. Climb back out mid-morning and drive back to Arusha, arriving in the afternoon.',
    'pkg5d_day5_act1' => 'Crater floor game drive',
    'pkg5d_day5_act2' => 'Drop-off in Arusha',
    'pkg5d_day5_tl1_time' => '06:00',
    'pkg5d_day5_tl1_title' => 'Descent to the crater floor',
    'pkg5d_day5_tl1_desc' => 'The track winds down to 1,700 metres, into a 264 km² caldera holding one of the densest concentrations of wildlife on Earth, and your best chance in Tanzania at black rhino.',
    'pkg5d_day5_tl2_time' => '09:30',
    'pkg5d_day5_tl2_title' => 'The crater floor',
    'pkg5d_day5_tl2_desc' => 'Lion, elephant, buffalo and the herds of zebra and wildebeest that never leave the crater floor, all inside a space small enough to feel like a private wildlife reserve.',
    'pkg5d_day5_tl3_time' => '11:30',
    'pkg5d_day5_tl3_title' => 'Climb out',
    'pkg5d_day5_tl3_desc' => 'The exit is as spectacular as the descent, so take one last look back before the road turns toward Arusha.',
    'pkg5d_day5_tl4_time' => '15:00',
    'pkg5d_day5_tl4_title' => 'Drop-off in Arusha',
    'pkg5d_day5_tl4_desc' => 'Your trip ends where it began, with five days of stories and, if you\'re anything like our past guests, already planning your return.',

