    'contact_faq_title' => 'Before you write to us',
    'contact_faq_q1' => 'How quickly will I get a reply?',
    'contact_faq_a1' => 'WhatsApp messages are usually answered within an hour during our working hours. Contact form and email enquiries are answered within 24 hours.',
