    'arusha_meta_title' => 'Arusha National Park Guide (2026) | Serengeti Budget Safari',
    'arusha_meta_description' => 'Arusha National Park guide: Mount Meru, the Momella lakes, walking safaris, tree-climbing lions, 2026 park fees, when to go and where to stay. 40 minutes from Arusha town.',
    'arusha_hero_badge' => 'Arusha National Park',
    'arusha_hero_title' => 'Arusha National Park',
    'arusha_hero_sub' => "Tanzania's most underrated park: Mount Meru, the Momella lakes and walking safaris, just 40 minutes from Arusha.",
    'arusha_hero_cta_quote' => 'Request a quote',

    'arusha_intro_badge' => 'Overview',
    'arusha_intro_title' => 'A small park with an outsized range of scenery',
    'arusha_intro_p1' => "Arusha National Park is the most convenient park in Tanzania, 40 minutes from Arusha town and often visited as a half-day trip or the acclimatisation day before a Kilimanjaro or Meru climb. Despite its size, it covers four distinct landscapes in one visit: the Ngurdoto Crater, the Momella lakes, montane forest, and the lower slopes of Mount Meru itself.",
    'arusha_intro_p2' => "It is also one of only three parks in Tanzania where walking safaris are permitted, and the only place near Arusha where you can canoe among hippos and flamingos on the Momella lakes.",
    'arusha_intro_p3' => "Most visitors combine it with a half-day itinerary, though it also serves as the acclimatisation trek before climbing Mount Meru, whose summit lies inside the park boundary.",
    'arusha_fact_area' => 'Area',
    'arusha_fact_established' => 'Established',
    'arusha_fact_meru' => 'Mount Meru summit',
    'arusha_fact_birds' => 'Bird species',
    'arusha_fact_lions' => 'Predators',
    'arusha_fact_lions_value' => 'Leopard, present but rarely seen',
    'arusha_fact_stay' => 'Typical visit',
    'arusha_fact_stay_value' => 'Half day, or 3–4 days for Meru',
    'arusha_fact_from_arusha' => 'From Arusha town',
    'arusha_fact_from_airport' => 'From Kilimanjaro Airport',

    'arusha_regions_badge' => 'Three landscapes in one park',
    'arusha_regions_title' => 'What to see',
    'arusha_regions_intro' => 'Arusha packs an unusual range of terrain into a small area. Plan your route around these three zones.',
    'arusha_region_ngurdoto_name' => 'Ngurdoto Crater',
    'arusha_region_ngurdoto_desc' => 'A lush, swampy crater floor ringed by forest, often called "Little Ngorongoro". Vehicles cannot descend into it, so viewing is from the rim, looking down on buffalo, warthog and waterbuck grazing below.',
    'arusha_region_momella_name' => 'Momella Lakes',
    'arusha_region_momella_desc' => 'A chain of shallow alkaline lakes, each a different shade of green or blue depending on its algae and mineral content. Flamingos, giraffe and buffalo gather at the shorelines, and this is where canoe safaris launch.',
    'arusha_region_meru_name' => 'Mount Meru',
    'arusha_region_meru_desc' => "Africa's fifth-highest peak at 4,566m, and the dramatic backdrop to most of the park. Climbable in 3–4 days, with far fewer trekkers than Kilimanjaro and superb views of Kilimanjaro itself on a clear day.",

    'arusha_walking_badge' => 'A rare permission',
    'arusha_walking_title' => 'Walking safaris',
    'arusha_walking_intro' => 'Arusha is one of only three parks in Tanzania where walking safaris are permitted. Most northern-circuit parks require you to stay in the vehicle.',
    'arusha_walking_p1' => 'Guided walks with an armed ranger let you get close to giraffe, zebra and buffalo on foot, reading tracks and dung, and hearing the bush at ground level rather than through a windscreen.',
    'arusha_walking_p2' => 'Because large predators are largely absent, walking here is safer than in the bigger parks. Dangerous encounters are almost always with buffalo, which the ranger is trained to manage from a safe distance.',

    'arusha_wildlife_badge' => 'What lives here',
    'arusha_wildlife_title' => 'Wildlife',
    'arusha_wildlife_intro' => 'Arusha has no lion and very little of the classic "big game" of the Serengeti. Its wildlife draw is different: primates, birds and forest species you will not see on a savannah safari.',
    'arusha_animal_giraffe' => 'Giraffe',
    'arusha_animal_colobus' => 'Black-and-white colobus',
    'arusha_animal_zebra' => 'Zebra',
    'arusha_animal_buffalo' => 'Buffalo',
    'arusha_animal_waterbuck' => 'Waterbuck',
    'arusha_animal_flamingo' => 'Flamingo',
    'arusha_animal_elephant' => 'Elephant (occasional)',
    'arusha_animal_warthog' => 'Warthog',
    'arusha_wildlife_p1' => "The park's real specialty is its troops of black-and-white colobus monkeys, easily seen in the montane forest, along with over 400 recorded bird species around the Momella lakes alone.",
    'arusha_wildlife_p2' => 'Elephant sightings do happen but are occasional rather than reliable. This is not the park to choose if the Big Five is your priority, but it rewards visitors interested in scenery, birds and a quieter pace.',

    'arusha_when_badge' => 'Planning',
    'arusha_when_title' => 'When to go',
    'arusha_when_intro' => 'Arusha is a year-round park: its low altitude and proximity to town mean it rarely closes, unlike higher-altitude treks.',
    'arusha_when_p1' => 'June to October (dry season) gives the clearest views of Mount Meru and Kilimanjaro, and the easiest walking conditions.',
    'arusha_when_p2' => 'The wetter months (March–May) turn the crater and lake edges a vivid green and bring more birdlife, though tracks can be muddy and the mountain views less reliable.',

    'arusha_stay_badge' => 'Where to stay',
    'arusha_stay_title' => 'Accommodation',
    'arusha_stay_intro' => "Most visitors base themselves in Arusha town and visit as a day trip, but a few properties sit close to the park gate for those climbing Meru or combining it with another park.",
    'arusha_stay_town_title' => 'Arusha town',
    'arusha_stay_town_price' => 'Budget – Luxury',
    'arusha_stay_town_desc' => 'The most common choice: 30–40 minutes from the park gate, with the widest range of hotels and easy onward transfers to Kilimanjaro Airport or the northern circuit.',
    'arusha_stay_lodge_title' => 'Lodges near the gate',
    'arusha_stay_lodge_price' => 'Mid-range – Luxury',
    'arusha_stay_lodge_desc' => 'A handful of lodges sit within a short drive of the park entrance, useful for an early start on a Meru climb or a walking safari at dawn.',
    'arusha_stay_camp_title' => 'Meru mountain huts',
    'arusha_stay_camp_price' => 'Included in trek package',
    'arusha_stay_camp_desc' => 'Climbers overnight in a series of mountain huts on the ascent, Miriakamba and Saddle Hut, included as part of any Mount Meru trekking package.',
    'arusha_stay_note' => 'We can arrange accommodation at any tier as part of a day trip or Meru trekking package. Ask us for current availability.',

    'arusha_fees_badge' => '2026 fees',
    'arusha_fees_title' => 'Park entrance fees',
    'arusha_fees_intro' => 'Fees are per person per 24-hour period and include 18% VAT. Paid by card or pre-loaded park card. Cash is not accepted at the gate.',
    'arusha_table_category' => 'Category',
    'arusha_table_adult' => 'Adult',
    'arusha_table_child' => 'Child (5–15)',
    'arusha_fee_entry' => 'Park entrance',
    'arusha_fee_concession' => 'Meru trekking concession',
    'arusha_fee_campsite' => 'Campsite fee',
    'arusha_fees_note' => 'When you travel with us, all park fees are calculated and included in your quoted price, with no separate payment needed at the gate.',

    'arusha_gallery_badge' => 'Arusha in pictures',
    'arusha_gallery_title' => 'What you will see',
    'arusha_gallery_caption_1' => 'Colobus monkeys in the forest',
    'arusha_gallery_caption_2' => 'Savanna at sunrise',
    'arusha_gallery_caption_3' => 'Canoeing on the Momella lakes',
    'arusha_gallery_caption_4' => 'Zebra on the plains',
    'arusha_gallery_caption_5' => 'Elephant under an acacia tree',
    'arusha_gallery_caption_6' => 'A crater rim, similar in shape to Ngurdoto',

    'arusha_back_to_parks' => 'Compare all nine parks',

    'arusha_faq_badge' => 'FAQ',
    'arusha_faq_title' => 'Common questions',
    'arusha_faq_q1' => 'Can I visit Arusha National Park in half a day?',
    'arusha_faq_a1' => "Yes, it is the most common way to visit, usually combined with a morning departure from Arusha town and return by early afternoon.",
    'arusha_faq_q2' => 'Will I see the Big Five here?',
    'arusha_faq_a2' => 'No. Arusha has no lion and rhino, and elephant sightings are occasional. It is chosen for scenery, walking safaris, colobus monkeys and birdlife rather than the Big Five.',
    'arusha_faq_q3' => 'Is walking safe here?',
    'arusha_faq_a3' => 'Yes, relatively. The absence of lion makes Arusha one of the safer parks for walking, though buffalo still require caution and an armed ranger always accompanies walking groups.',
    'arusha_faq_q4' => 'Can I climb Mount Meru without climbing Kilimanjaro?',
    'arusha_faq_a4' => 'Yes, Meru is a standalone trek and a popular choice in its own right. Many climbers prefer it for its quieter trails and dramatic crater rim walk.',
    'arusha_faq_q5' => 'How does Meru compare to Kilimanjaro as a climb?',
    'arusha_faq_a5' => 'Meru is shorter (3–4 days vs 5–9), steeper in places, and far less crowded. It is also commonly used as acclimatisation practice before a Kilimanjaro attempt.',
    'arusha_faq_q6' => 'Can I combine Arusha with other parks?',
    'arusha_faq_a6' => 'Yes, its proximity to town makes it an easy add-on to a Tarangire or Ngorongoro itinerary, or a relaxed first/last day of a longer safari.',
    'arusha_faq_q7' => 'Are there canoe safaris?',
    'arusha_faq_a7' => 'Yes, on the Momella lakes: a gentle way to see hippos, flamingos and waterbirds from the water, usually combined with a walking or driving portion of the visit.',
    'arusha_faq_q8' => 'Is a guide required?',
    'arusha_faq_a8' => 'Yes for walking safaris and the Meru trek (an armed ranger is compulsory), and strongly recommended for game drives given the limited signage inside the park.',

    'arusha_cta_title' => 'Ready to visit Arusha National Park?',
    'arusha_cta_intro' => 'Send us your dates and group size. We reply with a written itinerary and full price, no obligation.',
    'arusha_cta_whatsapp' => 'Message us on WhatsApp',
    'arusha_cta_safaris' => 'See safari packages',

    'kilimanjaro_meta_title' => 'Kilimanjaro National Park Guide (2026) | Serengeti Budget Safari',
    'kilimanjaro_meta_description' => 'Kilimanjaro National Park guide: all seven routes compared, 2026 park fees, success rates, altitude sickness, when to climb and where to sleep on the mountain.',
    'kilimanjaro_hero_badge' => 'Kilimanjaro National Park',
    'kilimanjaro_hero_title' => 'Kilimanjaro National Park',
    'kilimanjaro_hero_sub' => "Africa's highest point at 5,895m: five climate zones, seven routes, and a summit within reach of any reasonably fit walker.",
    'kilimanjaro_hero_cta_quote' => 'Request a quote',

    'kilimanjaro_intro_badge' => 'Overview',
    'kilimanjaro_intro_title' => 'The roof of Africa',
    'kilimanjaro_intro_p1' => "Kilimanjaro is Africa's highest mountain and the world's tallest free-standing peak, rising from savanna at around 900m to a glaciated summit at 5,895m without a connecting mountain range. The climb is a long walk, not a technical ascent: no ropes, no climbing gear, just multiple days of steady uphill walking through five distinct climate zones.",
    'kilimanjaro_intro_p2' => "Those zones (cultivated farmland, rainforest, moorland, alpine desert and the arctic summit zone) mean a Kilimanjaro trek feels like walking from the equator to the poles in under a week.",
    'kilimanjaro_intro_p3' => "The real challenge is altitude, not fitness or technical skill. The single biggest factor in reaching the summit is choosing a route with enough days for your body to acclimatise.",
    'kilimanjaro_fact_area' => 'Park area',
    'kilimanjaro_fact_summit' => 'Summit',
    'kilimanjaro_fact_status' => 'Status',
    'kilimanjaro_fact_routes' => 'Routes',
    'kilimanjaro_fact_duration' => 'Typical duration',
    'kilimanjaro_fact_success' => 'Success rate range',
    'kilimanjaro_fact_climbers' => 'Climbers per year',
    'kilimanjaro_fact_days' => 'Minimum recommended',
    'kilimanjaro_fact_year' => '5+ days',
    'kilimanjaro_fact_from_arusha' => 'From Arusha',

    'kilimanjaro_routes_badge' => 'Choose your path',
    'kilimanjaro_routes_title' => 'The routes',
    'kilimanjaro_routes_intro' => 'Seven official routes reach the summit. These four are the ones we run, chosen for their acclimatisation profile and reliability.',
    'kilimanjaro_route_marangu_name' => 'Marangu',
    'kilimanjaro_route_marangu_desc' => 'The only route with hut accommodation instead of tents, and the same path used for both ascent and descent. The shortest option, which also gives it the lowest success rate: less time to acclimatise.',
    'kilimanjaro_route_machame_name' => 'Machame',
    'kilimanjaro_route_machame_desc' => 'Known as the "Whiskey Route" for its reputation as a tougher climb. Scenic and varied, camping in tents, and the most popular route on the mountain thanks to its solid acclimatisation profile.',
    'kilimanjaro_route_lemosho_name' => 'Lemosho',
    'kilimanjaro_route_lemosho_desc' => 'A quieter start through untouched rainforest, joining the Machame route higher up. Widely considered the best combination of scenery and acclimatisation.',
    'kilimanjaro_route_rongai_name' => 'Rongai',
    'kilimanjaro_route_rongai_desc' => 'Approaches from the drier northern side of the mountain, close to the Kenyan border. The best choice during the shoulder rainy months, when southern routes are wetter.',

    'kilimanjaro_compare_badge' => 'Side by side',
    'kilimanjaro_compare_title' => 'Compare all routes',
    'kilimanjaro_compare_intro' => 'Success rates are indicative. They rise sharply with more days on the mountain, regardless of route.',
    'kilimanjaro_table_route' => 'Route',
    'kilimanjaro_table_days' => 'Days',
    'kilimanjaro_table_sleeping' => 'Sleeping',
    'kilimanjaro_table_scenery' => 'Scenery',
    'kilimanjaro_table_success' => 'Success rate',
    'kilimanjaro_sleep_tents' => 'Tents',
    'kilimanjaro_sleep_huts' => 'Huts',
    'kilimanjaro_scenery_varied' => 'Varied, steep in places',
    'kilimanjaro_scenery_best' => 'Best overall',
    'kilimanjaro_scenery_full' => 'Full mountain circuit',
    'kilimanjaro_scenery_direct' => 'Direct, less varied',
    'kilimanjaro_scenery_dry' => 'Drier, quieter trails',
    'kilimanjaro_northern_circuit' => 'Northern Circuit',
    'kilimanjaro_compare_note' => 'The extra night on a longer route is the cheapest insurance you can buy against altitude sickness. If your schedule allows it, choose the longer option.',

    'kilimanjaro_wildlife_badge' => 'On the way up',
    'kilimanjaro_wildlife_title' => 'Wildlife on the mountain',
    'kilimanjaro_wildlife_intro' => "Kilimanjaro is not a game-viewing destination, but the lower forest zones hold genuine wildlife interest. Most climbers are surprised by how much life exists on the mountain's flanks.",
    'kilimanjaro_animal_colobus' => 'Black-and-white colobus',
    'kilimanjaro_animal_blue_monkey' => 'Blue monkey',
    'kilimanjaro_animal_bushbuck' => 'Bushbuck',
    'kilimanjaro_animal_buffalo' => 'Buffalo (forest zone)',
    'kilimanjaro_animal_elephant' => 'Elephant (forest zone, rare)',
    'kilimanjaro_animal_sunbird' => 'Malachite sunbird',
    'kilimanjaro_animal_raven' => 'White-necked raven',
    'kilimanjaro_animal_groundsel' => 'Giant groundsel (plant)',
    'kilimanjaro_wildlife_p1' => 'The rainforest zone, crossed in the first day or two on most routes, is home to colobus and blue monkeys, forest antelope and occasional buffalo or elephant, all encountered on the trail rather than sought out.',
    'kilimanjaro_wildlife_p2' => 'Above the forest, the moorland and alpine zones are stranger than wild: giant groundsels and lobelias found nowhere else, and birds like the white-necked raven that follow climbers for scraps at high camps.',

    'kilimanjaro_when_badge' => 'Planning',
    'kilimanjaro_when_title' => 'When to climb',
    'kilimanjaro_when_intro' => "Kilimanjaro can technically be climbed year-round, but conditions vary considerably by season.",
    'kilimanjaro_when_p1' => 'January to early March and June to October are the two dry windows: the most reliable conditions, clearest summit views and busiest trails, especially July–September.',
    'kilimanjaro_when_p2' => 'April, May and November are the wet months. The mountain stays open and climbable, but paths are slippery and cloud cover often hides the summit. Rongai, on the drier northern side, is the best choice if you must climb in this window.',

    'kilimanjaro_stay_badge' => 'Where you sleep',
    'kilimanjaro_stay_title' => 'Accommodation on the mountain',
    'kilimanjaro_stay_intro' => 'What you sleep in depends entirely on your chosen route. This is fixed, not a matter of budget tier.',
    'kilimanjaro_stay_huts_title' => 'Mountain huts (Marangu only)',
    'kilimanjaro_stay_huts_price' => 'Included in the Marangu route',
    'kilimanjaro_stay_huts_desc' => 'Dormitory-style huts with bunk beds, shared dining halls and basic facilities. The only route offering this option, and part of why it is the shortest and most affordable.',
    'kilimanjaro_stay_camping_title' => 'Mountain camping (all other routes)',
    'kilimanjaro_stay_camping_price' => 'Included in the route price',
    'kilimanjaro_stay_camping_desc' => 'Two-person tents carried and pitched by the crew at each camp, with a separate mess tent for meals. The standard for Machame, Lemosho, Rongai and the Northern Circuit.',
    'kilimanjaro_stay_private_title' => 'Arusha, before and after',
    'kilimanjaro_stay_private_price' => 'Included in every package',
    'kilimanjaro_stay_private_desc' => 'A hotel night in Arusha before the climb and after your descent is included in every Kilimanjaro package we run, for a hot shower and a real bed either side of the mountain.',
    'kilimanjaro_stay_note' => 'All mountain accommodation, huts or tents, is included in your trekking package price, along with all camping and hut fees.',

    'kilimanjaro_fees_badge' => '2026 fees',
    'kilimanjaro_fees_title' => 'Park fees',
    'kilimanjaro_fees_intro' => 'Fees are itemised per person and included in your trekking package, shown here so you know exactly what you are paying for.',
    'kilimanjaro_table_category' => 'Fee',
    'kilimanjaro_table_basis' => 'Basis',
    'kilimanjaro_table_adult' => 'Adult (USD)',
    'kilimanjaro_table_child' => 'Child (5–15)',
    'kilimanjaro_fee_conservation' => 'Conservation fee',
    'kilimanjaro_fee_camping' => 'Camping fee',
    'kilimanjaro_fee_huts' => 'Hut fee (Marangu)',
    'kilimanjaro_fee_rescue' => 'Rescue fee',
    'kilimanjaro_fee_basis_day' => 'Per day',
    'kilimanjaro_fee_basis_night' => 'Per night',
    'kilimanjaro_fee_basis_once' => 'Once per trek',
    'kilimanjaro_fees_example' => 'For a 7-day Lemosho climb, park fees alone total roughly $956 per person. This is entirely separate from guide, porter, food and equipment costs.',
    'kilimanjaro_fees_note' => 'When you climb with us, all park fees are calculated and included in your quoted trekking price, with no separate payment needed at the gate.',

    'kilimanjaro_gallery_badge' => 'Kilimanjaro in pictures',
    'kilimanjaro_gallery_title' => 'The mountain',
    'kilimanjaro_gallery_caption_1' => 'Savanna at the mountain\'s base',
    'kilimanjaro_gallery_caption_2' => 'Wildlife in the surrounding plains',
    'kilimanjaro_gallery_caption_3' => 'A guide with climbers before the ascent',

    'kilimanjaro_back_to_parks' => 'Compare all nine parks',

    'kilimanjaro_faq_badge' => 'FAQ',
    'kilimanjaro_faq_title' => 'Common questions',
    'kilimanjaro_faq_q1' => 'Do I need climbing experience?',
    'kilimanjaro_faq_a1' => 'No. Kilimanjaro is a long walk, not a technical climb: there is no rope work or scrambling. What it demands is stamina for five to nine days of walking and the ability to cope with thin air.',
    'kilimanjaro_faq_q2' => 'Which route has the highest success rate?',
    'kilimanjaro_faq_a2' => 'The Northern Circuit and Lemosho, both around 90–95%, thanks to their longer acclimatisation profile. Marangu, the shortest route, has the lowest success rate at roughly 50–60%.',
    'kilimanjaro_faq_q3' => 'What about altitude sickness?',
    'kilimanjaro_faq_a3' => 'Mild headaches and breathlessness are normal above 4,000m. Our guides check oxygen saturation twice daily and carry a first-aid kit. If a guide judges you must descend, you descend, no exceptions.',
    'kilimanjaro_faq_q4' => 'How fit do I need to be?',
    'kilimanjaro_faq_a4' => 'No technical climbing fitness is required, but several hours of hiking-based training beforehand makes a real difference. The challenge is endurance and altitude, not strength.',
    'kilimanjaro_faq_q5' => 'What is the minimum number of days?',
    'kilimanjaro_faq_a5' => 'Five days (Marangu) is the legal minimum, but we recommend at least six to seven for a meaningfully better chance of reaching the summit.',
    'kilimanjaro_faq_q6' => 'Can beginners climb Kilimanjaro?',
    'kilimanjaro_faq_a6' => 'Yes, no prior trekking experience is required, though some hiking fitness helps. Many of our climbers have never done a multi-day trek before.',
    'kilimanjaro_faq_q7' => 'What is included in a trekking package?',
    'kilimanjaro_faq_a7' => 'All park fees, a certified guide, cook and porters, meals and drinking water on the mountain, camping or hut fees, and transfers in Arusha. See the full included/excluded list on our trekking page.',
    'kilimanjaro_faq_q8' => 'Is portable oxygen used?',
    'kilimanjaro_faq_a8' => 'Not routinely. It is available on request as an extra safety measure, but proper acclimatisation through route choice is the primary strategy we rely on.',

    'kilimanjaro_cta_title' => 'Ready to climb Kilimanjaro?',
    'kilimanjaro_cta_intro' => 'Send us your dates and preferred route. We reply with a written itinerary and full price, no obligation.',
    'kilimanjaro_cta_whatsapp' => 'Message us on WhatsApp',
    'kilimanjaro_cta_safaris' => 'See trekking packages',

    'ruaha_meta_title' => 'Ruaha National Park Guide (2026) | Serengeti Budget Safari',
    'ruaha_meta_description' => "Ruaha National Park guide: Tanzania's largest park, roughly 10% of the world's lions, huge elephant herds, wild dog, 2026 park fees and where to stay.",
    'ruaha_hero_badge' => 'Ruaha National Park',
    'ruaha_hero_title' => 'Ruaha National Park',
    'ruaha_hero_sub' => "Tanzania's largest national park: rugged, remote, and home to roughly a tenth of the world's remaining lions.",
    'ruaha_hero_cta_quote' => 'Request a quote',

    'ruaha_intro_badge' => 'Overview',
    'ruaha_intro_title' => 'Big, wild and nearly empty',
    'ruaha_intro_p1' => "Ruaha is Tanzania's largest national park at over 20,000 km², bigger than the Serengeti, yet it receives a fraction of the visitors, thanks to the extra flight required from Dar es Salaam rather than a road transfer from Arusha.",
    'ruaha_intro_p2' => "That remoteness is exactly its appeal: vast baobab-studded plains, the Great Ruaha River, and some of the highest predator densities in Africa, seen from a vehicle you will often have entirely to yourself.",
    'ruaha_intro_p3' => "It rewards travellers who have already done the northern circuit and want somewhere genuinely different: bigger skies, rougher tracks, and wildlife that reacts to vehicles the way it should, as a novelty rather than a daily occurrence.",
    'ruaha_fact_area' => 'Area',
    'ruaha_fact_rank' => 'Size ranking',
    'ruaha_fact_rank_value' => "Tanzania's largest park",
    'ruaha_fact_lions' => 'Lion population',
    'ruaha_fact_lions_of_world' => '~10% of the world\'s wild lions',
    'ruaha_fact_elephants' => 'Elephant population',
    'ruaha_fact_kudu' => 'Notable species',
    'ruaha_fact_kudu_value' => 'Greater & lesser kudu',
    'ruaha_fact_visitors' => 'Visitor density',
    'ruaha_fact_visitors_value' => 'Very low',
    'ruaha_fact_stay' => 'Recommended stay',
    'ruaha_fact_days' => '3–4 days',
    'ruaha_fact_from_dar' => 'From Dar es Salaam',
    'ruaha_fact_by_air' => 'By light aircraft',

    'ruaha_regions_badge' => 'The landscape',
    'ruaha_regions_title' => 'What to see',
    'ruaha_regions_intro' => 'Ruaha shifts between three distinct landscapes across its vast area.',
    'ruaha_region_river_name' => 'The Great Ruaha River',
    'ruaha_region_river_desc' => 'The lifeline of the park. During the dry season, wildlife concentrates along its banks and sandbanks in numbers that rival any northern-circuit river crossing, minus the crowds.',
    'ruaha_region_baobab_name' => 'Baobab plains',
    'ruaha_region_baobab_desc' => 'Rolling hills studded with ancient baobab trees, some estimated at over a thousand years old, giving Ruaha a distinctive silhouette unlike any northern park.',
    'ruaha_region_miombo_name' => 'Miombo woodland',
    'ruaha_region_miombo_desc' => 'Vast tracts of miombo woodland cover much of the park\'s interior, home to species like greater kudu and sable antelope that prefer this habitat over open grassland.',

    'ruaha_wildlife_badge' => 'What lives here',
    'ruaha_wildlife_title' => 'Wildlife',
    'ruaha_wildlife_intro' => 'Ruaha sits at the overlap of East and Southern African species, giving it one of the most diverse wildlife lists of any Tanzanian park.',
    'ruaha_animal_lion' => 'Lion',
    'ruaha_animal_elephant' => 'Elephant',
    'ruaha_animal_leopard' => 'Leopard',
    'ruaha_animal_cheetah' => 'Cheetah',
    'ruaha_animal_wilddog' => 'African wild dog',
    'ruaha_animal_buffalo' => 'Buffalo',
    'ruaha_animal_giraffe' => 'Giraffe',
    'ruaha_animal_zebra' => 'Zebra',
    'ruaha_animal_kudu' => 'Greater kudu',
    'ruaha_animal_hippo' => 'Hippo',
    'ruaha_wildlife_p1' => "Ruaha holds roughly 10% of the world's remaining wild lions and an elephant population among the largest in East Africa, alongside healthy numbers of leopard and one of Tanzania's best chances of encountering African wild dog.",
    'ruaha_wildlife_p2' => 'The mix of East African species (lion, giraffe, zebra) and Southern African species (greater kudu, sable, roan antelope) found nowhere else in the northern circuit is part of what makes Ruaha genuinely distinct.',

    'ruaha_when_badge' => 'Planning',
    'ruaha_when_title' => 'When to go',
    'ruaha_when_intro' => 'Ruaha is best visited in the dry season, when wildlife concentrates predictably along the river.',
    'ruaha_when_p1' => 'June to October is peak dry season: the river shrinks to pools and sandbanks, drawing large concentrations of game and the best predator sightings of the year.',
    'ruaha_when_p2' => 'November to May brings the rains: the park turns green, many camps close for the season, and roads can become impassable. This is not a realistic window for most visitors.',

    'ruaha_stay_badge' => 'Where to stay',
    'ruaha_stay_title' => 'Accommodation',
    'ruaha_stay_intro' => "Ruaha's remoteness means fewer properties than the northern circuit, but a good spread across budget tiers close to the river.",
    'ruaha_stay_budget_title' => 'Budget camps',
    'ruaha_stay_budget_price' => 'Camping / basic tented',
    'ruaha_stay_budget_desc' => 'Simple tented camps with shared facilities, run by small local operators. The most affordable way to experience the park.',
    'ruaha_stay_mid_title' => 'Mid-range camps',
    'ruaha_stay_mid_price' => 'Tented camp, en-suite',
    'ruaha_stay_mid_desc' => 'Comfortable permanent tented camps with private bathrooms, often set along the riverbank for wildlife views from camp itself.',
    'ruaha_stay_luxury_title' => 'Luxury camps',
    'ruaha_stay_luxury_price' => 'Premium tented camp',
    'ruaha_stay_luxury_desc' => 'A small number of high-end camps offer private guiding, elevated viewing decks and a genuinely exclusive feel given how few visitors the park receives.',
    'ruaha_stay_note' => 'We can arrange accommodation at any tier as part of your Ruaha itinerary, including the light aircraft transfer from Dar es Salaam.',

    'ruaha_fees_badge' => '2026 fees',
    'ruaha_fees_title' => 'Park entrance fees',
    'ruaha_fees_intro' => 'Fees are per person per 24-hour period and include 18% VAT. Paid by card or pre-loaded park card. Cash is not accepted at the gate.',
