    'ruaha_faq_badge' => 'FAQ',
    'ruaha_faq_title' => 'Common questions',
    'ruaha_faq_q1' => 'How do I get to Ruaha?',
    'ruaha_faq_a1' => 'By light aircraft from Dar es Salaam. There is no practical road route from Arusha. Flights typically take around two hours.',
    'ruaha_faq_q2' => 'Is Ruaha worth the extra flight cost?',
    'ruaha_faq_a2' => 'For travellers who have already seen the northern circuit, yes. The wildlife density rivals the Serengeti with a fraction of the vehicles, which is a genuinely different experience.',
    'ruaha_faq_q3' => 'How many days do I need?',
    'ruaha_faq_a3' => 'Three to four days lets you properly explore the riverine and woodland areas without feeling rushed, given the driving distances involved.',
    'ruaha_faq_q4' => 'Can I combine Ruaha with other southern parks?',
    'ruaha_faq_a4' => 'Yes, Ruaha pairs naturally with Nyerere (Selous) for a southern circuit safari, both reached from Dar es Salaam.',
    'ruaha_faq_q5' => 'Will I see wild dog?',
    'ruaha_faq_a5' => 'Ruaha is one of the better places in Tanzania for African wild dog, though sightings are never guaranteed for any wild animal. A multi-day stay improves your odds considerably.',
    'ruaha_faq_q6' => 'Is Ruaha good for photography?',
    'ruaha_faq_a6' => 'Very. The low vehicle density means uninterrupted sightings and the baobab landscape offers dramatic backdrops rarely available in the busier northern parks.',
    'ruaha_faq_q7' => 'What is the best time to see lions?',
    'ruaha_faq_a7' => 'Year-round, but the dry season (June–October) concentrates them more predictably along the river, where prey animals also gather.',
    'ruaha_faq_q8' => 'Is Ruaha suitable for a first-time safari?',
    'ruaha_faq_a8' => "It can be, but most first-time visitors are better served starting with the northern circuit for its shorter transfers and more developed infrastructure. Ruaha rewards travellers who already know what they want from a safari.",

    'ruaha_cta_title' => 'Ready to visit Ruaha?',
    'ruaha_cta_intro' => 'Send us your dates and group size. We reply with a written itinerary and full price, no obligation.',
    'ruaha_cta_whatsapp' => 'Message us on WhatsApp',
