    'mikumi_meta_title' => 'Mikumi National Park Guide (2026) | Serengeti Budget Safari',
    'mikumi_meta_description' => "Mikumi National Park guide: Tanzania's most affordable real safari, four hours from Dar es Salaam by road, no flight needed. 2026 fees, wildlife and when to go.",
    'mikumi_hero_badge' => 'Mikumi National Park',
    'mikumi_hero_title' => 'Mikumi National Park',
    'mikumi_hero_sub' => "The cheapest genuine safari in Tanzania: four hours from Dar es Salaam by road, no internal flight required.",
    'mikumi_hero_cta_quote' => 'Request a quote',

    'mikumi_intro_badge' => 'Overview',
    'mikumi_intro_title' => 'A real safari without the flight',
    'mikumi_intro_p1' => "Mikumi is the most accessible of Tanzania's southern parks: a straightforward four-hour drive from Dar es Salaam on a sealed road, with no internal flight required. That accessibility, combined with lower park fees than the northern circuit, makes it the most affordable genuine safari in the country.",
    'mikumi_intro_p2' => "Its centrepiece is the Mkata floodplain, an open grassland often compared to the Serengeti in miniature: wide horizons, easy game viewing, and none of the flight logistics of Ruaha or Nyerere.",
    'mikumi_intro_p3' => "It works well as a weekend safari from Dar es Salaam, a stopover on the road to Ruaha or Nyerere, or a budget-conscious introduction to Tanzanian wildlife.",
    'mikumi_fact_area' => 'Area',
    'mikumi_fact_established' => 'Established',
    'mikumi_fact_status' => 'Access',
    'mikumi_fact_status_value' => 'By road, no flight needed',
    'mikumi_fact_lions' => 'Predators',
    'mikumi_fact_lions_value' => 'Lion, leopard present',
    'mikumi_fact_birds' => 'Bird species',
    'mikumi_fact_entry' => 'Entry fee tier',
    'mikumi_fact_stay' => 'Recommended stay',
    'mikumi_fact_days' => '1–2 days',
