    'mikumi_regions_badge' => 'The landscape',
    'mikumi_regions_title' => 'What to see',
    'mikumi_regions_intro' => 'Mikumi is centred on two contrasting habitats.',
    'mikumi_region_mkata_name' => 'Mkata Floodplain',
    'mikumi_region_mkata_desc' => "The park's heart: open grassland flanked by the Uluguru and Lumango mountains, holding the highest wildlife concentrations and the easiest game viewing in the park.",
    'mikumi_region_miombo_name' => 'Miombo woodland',
    'mikumi_region_miombo_desc' => 'Hillside miombo woodland surrounds the floodplain, home to less commonly seen species like eland and sable antelope for visitors who explore beyond the plain.',

    'mikumi_wildlife_badge' => 'What lives here',
    'mikumi_wildlife_title' => 'Wildlife',
    'mikumi_wildlife_intro' => 'Mikumi holds a genuine cross-section of East African wildlife, concentrated on the open Mkata floodplain.',
    'mikumi_animal_lion' => 'Lion',
    'mikumi_animal_elephant' => 'Elephant',
    'mikumi_animal_leopard' => 'Leopard',
    'mikumi_animal_wilddog' => 'African wild dog',
    'mikumi_animal_buffalo' => 'Buffalo',
    'mikumi_animal_giraffe' => 'Giraffe',
    'mikumi_animal_zebra' => 'Zebra',
    'mikumi_animal_wildebeest' => 'Wildebeest',
    'mikumi_animal_hippo' => 'Hippo',
    'mikumi_wildlife_p1' => 'The floodplain hosts large herds of buffalo, zebra and wildebeest year-round, with elephant commonly seen along the seasonal watercourses that cross the grassland.',
    'mikumi_wildlife_p2' => 'Lion and leopard are both present and regularly sighted, and Mikumi is one of the few parks where African wild dog occasionally passes through. Never guaranteed, but a real possibility.',

    'mikumi_when_badge' => 'Planning',
    'mikumi_when_title' => 'When to go',
    'mikumi_when_intro' => 'Mikumi is a year-round destination given its low altitude and easy road access.',
    'mikumi_when_p1' => 'June to October (dry season) offers the best game viewing, as wildlife concentrates around the remaining water sources on the floodplain.',
    'mikumi_when_p2' => 'November to May is greener and quieter, with lower rates at most camps: a good option for a shorter, more affordable visit if peak-season game viewing is not the priority.',

    'mikumi_stay_badge' => 'Where to stay',
    'mikumi_stay_title' => 'Accommodation',
    'mikumi_stay_intro' => "Mikumi's easy access from Dar es Salaam has attracted a good spread of accommodation across every budget tier.",
    'mikumi_stay_budget_title' => 'Budget camps',
    'mikumi_stay_budget_price' => 'Camping / basic tented',
    'mikumi_stay_budget_desc' => 'Simple campsites and basic tented options near the park gate, the most affordable way to base yourself for a day-trip-style visit.',
    'mikumi_stay_mid_title' => 'Mid-range lodges',
    'mikumi_stay_mid_price' => 'Lodge, en-suite',
    'mikumi_stay_mid_desc' => 'Comfortable lodges overlooking the floodplain, offering a good balance of comfort and value for a one- or two-night stay.',
    'mikumi_stay_luxury_title' => 'Luxury lodges',
    'mikumi_stay_luxury_price' => 'Premium lodge',
    'mikumi_stay_luxury_desc' => 'A smaller number of higher-end properties offer private verandas and elevated views over the plain, for travellers wanting extra comfort close to Dar.',
    'mikumi_stay_note' => 'We can arrange accommodation at any tier as part of your Mikumi itinerary, including transport from Dar es Salaam.',

    'mikumi_access_badge' => 'Getting there',
    'mikumi_access_title' => 'Access from Dar es Salaam',
    'mikumi_access_intro' => "Mikumi's biggest advantage over Ruaha and Nyerere is that it needs no internal flight.",
    'mikumi_access_p1' => 'A sealed road connects Dar es Salaam to Mikumi in around four hours, making it realistic as a weekend trip or a stopover on a longer southern-circuit itinerary toward Ruaha.',
    'mikumi_access_p2' => 'This road access is the single biggest reason Mikumi is the most budget-friendly genuine safari in Tanzania. No charter flight costs to factor into your trip.',

    'mikumi_fees_badge' => '2026 fees',
    'mikumi_fees_title' => 'Park entrance fees',
    'mikumi_fees_intro' => 'Fees are per person per 24-hour period and include 18% VAT, among the lowest of any Tanzanian national park. Paid by card or pre-loaded park card. Cash is not accepted at the gate.',
