    'mikumi_faq_badge' => 'FAQ',
    'mikumi_faq_title' => 'Common questions',
    'mikumi_faq_q1' => 'Do I need to fly to Mikumi?',
    'mikumi_faq_a1' => 'No. Mikumi is reached by a four-hour drive on a sealed road from Dar es Salaam, which is exactly what makes it the most affordable safari option in Tanzania.',
    'mikumi_faq_q2' => 'Is Mikumi good for a weekend trip?',
    'mikumi_faq_a2' => 'Yes, its short drive from Dar es Salaam makes it realistic as a two-day weekend safari, something none of the other southern or northern parks can easily offer.',
    'mikumi_faq_q3' => 'Will I see the Big Five?',
    'mikumi_faq_a3' => 'Lion, elephant and buffalo are seen regularly. Leopard is present but elusive, and rhino is not found in Mikumi. For a realistic Big Five chance, Ngorongoro remains the better choice.',
    'mikumi_faq_q4' => 'How does Mikumi compare to Ruaha or Nyerere?',
    'mikumi_faq_a4' => 'Mikumi is smaller and easier to access, with lower fees, but Ruaha and Nyerere offer greater wildlife density and a more remote feel. Mikumi is the budget and convenience choice of the three.',
    'mikumi_faq_q5' => 'Can I combine Mikumi with Ruaha?',
    'mikumi_faq_a5' => 'Yes, Mikumi sits on the road route toward Ruaha, making it a natural stopover on a longer southern-circuit itinerary.',
    'mikumi_faq_q6' => 'What is the best time to visit?',
    'mikumi_faq_a6' => 'June to October for the best game viewing, though the park is accessible and worthwhile year-round given its low altitude and easy road access.',
    'mikumi_faq_q7' => 'Is Mikumi suitable for a first safari?',
    'mikumi_faq_a7' => 'Yes, its accessibility and lower cost make it a sensible introduction to Tanzanian wildlife, especially for travellers based in or arriving via Dar es Salaam.',
    'mikumi_faq_q8' => 'Is a 4x4 vehicle necessary?',
    'mikumi_faq_a8' => "Yes, as with any Tanzanian national park, we provide a private 4x4 with driver-guide as standard on every Mikumi itinerary.",

