    'pkg5d_faq_title' => 'Frequently asked questions',
    'pkg5d_faq_q1' => 'Is this safari private?',
    'pkg5d_faq_a1' => 'Yes, the vehicle and guide are private to your group unless you specifically book a Group Joining departure. You set the pace and stops.',
    'pkg5d_faq_q2' => 'Can I customize the safari?',
    'pkg5d_faq_a2' => 'Yes, extra days, different parks or a Zanzibar extension can all be added. Tell us what you have in mind and we will adjust the itinerary and price.',
    'pkg5d_faq_q3' => 'Can I start on any date?',
    'pkg5d_faq_a3' => 'Yes, private safaris depart on any date you choose, subject to lodge availability in peak season (June–October).',
    'pkg5d_faq_q4' => 'Is airport pickup included?',
    'pkg5d_faq_a4' => 'Yes, pickup from Kilimanjaro International Airport or your Arusha hotel is included in the price.',
    'pkg5d_faq_q5' => 'What should I bring?',
    'pkg5d_faq_a5' => 'Neutral-coloured clothing, a warm layer for early mornings, sunscreen, a hat, binoculars and a camera. We send a full packing list once your trip is confirmed.',
    'pkg5d_faq_q6' => 'Is this safari suitable for children?',
    'pkg5d_faq_a6' => 'Yes, most lodges on this route welcome children of all ages, though some have a minimum age for game drives. Let us know the ages travelling and we will confirm.',

