    'safari_park_serengeti_desc' => 'The Great Migration, the highest predator density in Africa, and 14,763 km² of plains.',
    'safari_park_ngorongoro_desc' => '25,000 animals in a 260 km² caldera, and the only realistic black rhino in Tanzania.',
    'safari_park_tarangire_desc' => 'Baobabs, 3,000 elephants and 550 bird species, two hours from Arusha and rarely busy.',
