    'safari_park_nyerere_desc' => "Africa's largest park. Boat safaris on the Rufiji, walking safaris and wild dog.",
    'safari_park_ruaha_desc' => "Tanzania's largest park, ~10% of the world's lions, and almost no other vehicles.",
