    'safari_parks_title' => 'Read about the parks first',
    'safari_parks_subtitle' => 'Before you pick an itinerary, it helps to know what each park actually offers. These guides are written by our own guides and cover wildlife, 2026 fees, when to go and where to stay.',
    'safari_parks_beyond_title' => 'Beyond the northern circuit',
    'safari_parks_beyond_desc' => 'Three more parks are reached from Dar es Salaam rather than Arusha. Bigger, emptier and cheaper to enter, with boat and walking safaris that the northern parks cannot offer.',
    'safari_parks_full_guide' => 'Full guide',
    'safari_parks_compare_all' => 'Compare all nine parks side by side',

    'safari_faq_title' => 'Common questions',
    'safari_faq_q1' => 'How much does a safari in Tanzania actually cost?',
    'safari_faq_a1' => 'Budget from around $200 per person per day, mid-range $250–350, and luxury from $600. The biggest variables are the standard of accommodation and the size of your group: park fees and the vehicle are fixed costs, so four people sharing pay noticeably less each than two.',
    'safari_faq_q2' => 'When is the best time to come?',
    'safari_faq_a2' => 'June to October is the classic dry season with the easiest game viewing. January and February bring the calving season in Ndutu. November to May is greener, quieter and cheaper, with some rain in the afternoons.',
    'safari_faq_q3' => 'Will we see the Big Five?',
    'safari_faq_a3' => 'Lion, elephant, buffalo and leopard are seen regularly on a four-day northern circuit safari. Black rhino is the difficult one: the Ngorongoro Crater is the best chance in Tanzania, but no operator can guarantee a sighting of a wild animal.',
    'safari_faq_q4' => 'How many days do we need?',
    'safari_faq_a4' => 'Three days is the practical minimum to reach the Serengeti without spending the whole trip driving. Four to five days is the sweet spot. Anything shorter is better spent on Tarangire, Manyara and the Ngorongoro Crater, which are far closer to Arusha.',

