    'parks_meta_title' => 'Tanzania National Parks: All 9 Parks Compared (2026) | Serengeti Budget Safari',
    'parks_meta_description' => 'Compare Tanzania\'s national parks side by side: Serengeti, Ngorongoro, Tarangire, Manyara, Arusha, Kilimanjaro, Nyerere, Ruaha and Mikumi. 2026 fees, wildlife and days needed.',

    'parks_hero_badge' => 'Park guides',
    'parks_hero_title' => 'Tanzania\'s national parks',
    'parks_hero_sub' => 'Nine parks compared side by side: wildlife, 2026 fees, days needed and which one suits your trip. Then read the full guide for the ones that interest you.',

    'parks_northern_badge' => 'Northern parks',
    'parks_northern_title' => 'The northern circuit',
    'parks_northern_intro' => 'Five parks within a day\'s drive of Arusha, and the destination of the overwhelming majority of Tanzanian safaris.',

    'parks_southern_badge' => 'Southern parks',
    'parks_southern_title' => 'The southern circuit',
    'parks_southern_intro' => 'Reached from Dar es Salaam rather than Arusha. Bigger, emptier, cheaper to enter and more expensive to reach. Where you go on a second trip.',

    'parks_full_guide' => 'Full guide',

    'parks_serengeti_name' => 'Serengeti',
    'parks_serengeti_desc' => '14,763 km² of plains, the Great Migration, and the highest density of large predators in Africa. Needs three days minimum.',
    'parks_ngorongoro_name' => 'Ngorongoro',
    'parks_ngorongoro_desc' => 'The largest intact caldera on earth with 25,000 animals inside it, and the only realistic chance of black rhino in Tanzania.',
    'parks_tarangire_name' => 'Tarangire',
    'parks_tarangire_desc' => 'Baobabs and 2,500–3,000 elephants, two hours from Arusha, and the quietest of the main four parks.',
    'parks_manyara_name' => 'Lake Manyara',
    'parks_manyara_desc' => 'Groundwater forest, flamingos, huge baboon troops, and the only night drive and canopy walkway on the circuit.',
    'parks_arusha_name' => 'Arusha National Park',
    'parks_arusha_desc' => 'Forty minutes from town, and the one place on the circuit where you can walk, canoe and climb. No lions.',
    'parks_kilimanjaro_name' => 'Kilimanjaro',
    'parks_kilimanjaro_desc' => 'Africa\'s highest mountain at 5,895 m, climbed over five to nine days on seven official routes.',
    'parks_nyerere_name' => 'Nyerere (Selous)',
    'parks_nyerere_desc' => 'The largest national park in Africa, where you can do a boat safari, a walking safari and a game drive in the same day.',
    'parks_ruaha_name' => 'Ruaha',
    'parks_ruaha_desc' => 'Tanzania\'s largest park, holding around 10% of the world\'s lions and 12,000 elephants, with almost no other vehicles.',
    'parks_mikumi_name' => 'Mikumi',
    'parks_mikumi_desc' => 'The only major park reachable from a city by road in a morning. Open plains, resident lions, cheapest real safari in Tanzania.',

