    'parks_want_walking' => 'To walk, not drive',
    'parks_why_walking' => 'All three permit proper walking safaris.',
    'parks_want_oneday' => 'Only one day',
    'parks_why_oneday' => 'Both reachable and rewarding in a day from Arusha.',
    'parks_want_budget' => 'No flight, low budget',
    'parks_why_budget' => 'Four hours from Dar by road, the cheapest entry fee.',

    'parks_see_safaris' => 'See our safari itineraries',

    'parks_faq_badge' => 'FAQ',
    'parks_faq_title' => 'Tanzanian national parks: frequently asked questions',
    'parks_faq_q1' => 'Which is the best national park in Tanzania?',
    'parks_faq_a1' => 'It depends what you want. The Serengeti for the migration and predators, Ngorongoro for density and rhino, Tarangire for elephants, Ruaha for lions and solitude, Nyerere for boat safaris. Most good itineraries combine two or three rather than choosing one.',
    'parks_faq_q2' => 'How much do Tanzanian park fees cost in 2026?',
    'parks_faq_a2' => 'Serengeti, Ngorongoro and Kilimanjaro are $82.60 per adult per day; Tarangire, Lake Manyara, Arusha NP and Nyerere are $59.00; Ruaha and Mikumi are $35.40. All include 18% VAT. Ngorongoro adds $295 per vehicle to descend into the crater.',
    'parks_faq_q3' => 'What is the difference between the northern and southern circuits?',
    'parks_faq_a3' => 'The northern circuit runs from Arusha and includes the Serengeti, Ngorongoro, Tarangire, Manyara, Arusha NP and Kilimanjaro. The southern circuit runs from Dar es Salaam and covers Nyerere, Ruaha and Mikumi: bigger, emptier, cheaper to enter and more expensive to reach.',
    'parks_faq_q4' => 'Which parks can I visit in one day from Arusha?',
    'parks_faq_a4' => 'Arusha National Park at 40 minutes, Tarangire and Lake Manyara at two hours, and Ngorongoro at three to four hours. The Serengeti is 7–8 hours and not realistic as a day trip.',
    'parks_faq_q5' => 'Which is the cheapest park?',
    'parks_faq_a5' => 'Ruaha and Mikumi at $35.40 per adult. But entry is only part of the cost: Mikumi needs no flight and is genuinely the cheapest safari in Tanzania, while Ruaha requires a two-hour flight from Dar.',
    'parks_faq_q6' => 'Which park is best for the Big Five?',
    'parks_faq_a6' => 'Ngorongoro, because it is the only one where black rhino is realistically achievable. The Serengeti gives you four of the five easily but essentially no rhino. Combining the two is the standard solution.',
    'parks_faq_q7' => 'When is the best time to visit Tanzanian parks?',
    'parks_faq_a7' => 'June to October is the dry season and easiest everywhere. January and February suit the Serengeti calving season. March to May is wet: the northern parks stay open, but most camps in Ruaha and Nyerere close entirely.',
    'parks_faq_q8' => 'How many days do I need for a Tanzanian safari?',
    'parks_faq_a8' => 'Two days covers Tarangire and Ngorongoro well. Four to five adds the Serengeti properly. Six to eight lets you follow the migration or do the southern circuit.',
    'parks_faq_q9' => 'Can I pay park fees in cash?',
    'parks_faq_a9' => 'No. TANAPA and NCAA gates are cashless. Fees are paid by card or pre-loaded park cards. When you travel with us this is handled for you and included in the quoted price.',
    'parks_faq_q10' => 'Do I need to visit all the parks?',
    'parks_faq_a10' => 'No, and on a short trip you should not try. Two parks done properly beat four rushed. A common mistake is squeezing the Serengeti into a four-day trip and spending most of it in the vehicle.',

    'parks_cta_title' => 'Not sure which parks to choose?',
    'parks_cta_intro' => 'Tell us how many days you have and what you most want to see. We will tell you honestly which parks are worth it for your dates, including when the answer is "skip that one".',
    'parks_cta_whatsapp' => 'Message us on WhatsApp',
    'parks_cta_contact_form' => 'Contact form',

    // ---------- Serengeti National Park page ----------
    'serengeti_meta_title' => 'Serengeti National Park: The Complete Guide (2026) | Serengeti Budget Safari',
    'serengeti_meta_description' => 'Everything about Serengeti National Park: the Great Migration month by month, the five regions, wildlife, 2026 park fees, where to stay and when to go.',

    'serengeti_hero_badge' => 'Park guide',
    'serengeti_hero_title' => 'Serengeti National Park',
    'serengeti_hero_sub' => 'The complete guide to Tanzania\'s most famous park: the Great Migration month by month, where to stay, what it costs and when to come.',
    'serengeti_hero_cta_quote' => 'Request a quote',

    'serengeti_intro_badge' => 'Introduction',
    'serengeti_intro_title' => 'What is the Serengeti?',
    'serengeti_intro_p1' => 'The Serengeti National Park covers 14,763 km² of northern Tanzania, roughly the size of Northern Ireland, and is the oldest national park in the country, gazetted in 1951. Its name comes from the Maasai word siringet, "the place where the land runs on forever".',
    'serengeti_intro_p2' => 'It is famous for one thing above all: the Great Migration, the year-round movement of around 1.3 million wildebeest, 250,000 zebra and several hundred thousand gazelle following the rains in a roughly circular route between the southern plains and Kenya\'s Masai Mara. This is the largest overland movement of animals left on earth, and it happens continuously. There is no month when it stops.',
    'serengeti_intro_p3' => 'The Serengeti also holds one of the densest lion populations in Africa (roughly 3,000 animals) and more than 500 recorded bird species. Together with the Ngorongoro Conservation Area it forms a single ecosystem of about 30,000 km², and it has been a UNESCO World Heritage Site since 1981.',

    'serengeti_fact_area' => 'Area',
    'serengeti_fact_established' => 'Established',
    'serengeti_fact_status' => 'Status',
    'serengeti_fact_lions' => 'Lions',
    'serengeti_fact_wildebeest' => 'Wildebeest',
    'serengeti_fact_stay' => 'Suggested stay',
    'serengeti_fact_nights' => 'nights',
    'serengeti_fact_from_arusha' => 'From Arusha',
    'serengeti_fact_by_air' => 'By air',

    'serengeti_regions_badge' => 'Where to go',
    'serengeti_regions_title' => 'The five regions of the Serengeti',
    'serengeti_regions_intro' => 'The park is larger than some countries, and where you stay determines what you see. These are the main areas, and when each one is at its best.',
    'serengeti_region_seronera_name' => 'Seronera (Central Serengeti)',
    'serengeti_region_seronera_desc' => 'The heart of the park and the safest choice for a first visit. The river valley holds water year-round, so resident game never leaves: lions, leopards, elephants, buffalo and cheetah are here in every month. Best all year, ideal for 2–3 night first-time visits.',
    'serengeti_region_ndutu_name' => 'Ndutu and the southern plains',
    'serengeti_region_ndutu_desc' => 'From December to March the migration herds concentrate here to calve, and the density of predators that follows them is extraordinary. It is the best time and place in Tanzania to watch a hunt. Outside those months the plains empty out almost completely.',
    'serengeti_region_western_name' => 'Western Corridor and the Grumeti River',
    'serengeti_region_western_desc' => 'A long arm of the park reaching west towards Lake Victoria. The herds pass through around May to July, and the Grumeti crossings happen here, smaller than the Mara, but with some of the largest crocodiles in Africa waiting in the pools.',
    'serengeti_region_kogatende_name' => 'Kogatende and the Northern Serengeti',
    'serengeti_region_kogatende_desc' => 'Rolling hills and thick bush along the Mara River, on the Kenyan border. From July to October this is where the river crossings happen. Outside crossing season it is one of the quietest and most beautiful parts of the park.',

    'serengeti_migration_badge' => 'Great Migration',
    'serengeti_migration_title' => 'The Great Migration, month by month',
    'serengeti_migration_intro' => 'The migration is not an event with a date. It is a continuous circuit driven by rainfall, and the herds are somewhere in the ecosystem in every month of the year.',
    'serengeti_table_months' => 'Months',
    'serengeti_table_where' => 'Where the herds are',
    'serengeti_table_what_happens' => 'What happens',
    'serengeti_mig_ndutu' => 'Ndutu & southern plains',
    'serengeti_mig_calving' => 'Calving season. Around 400,000 calves born, with predator action at its highest of the year.',
    'serengeti_mig_moving_nw' => 'Moving north-west',
    'serengeti_mig_rains' => 'Long rains. The columns form and move through the central Serengeti towards the Western Corridor.',
    'serengeti_mig_western' => 'Western Corridor',
    'serengeti_mig_grumeti' => 'Grumeti River crossings. Smaller than the Mara but with enormous crocodiles and a fraction of the vehicles.',
    'serengeti_mig_northern' => 'Northern Serengeti & Masai Mara',
    'serengeti_mig_mara' => 'Mara River crossings: the classic image. August and September are the peak months.',
    'serengeti_mig_returning' => 'Returning south',
    'serengeti_mig_south' => 'Short rains pull the herds back down through the eastern Serengeti towards the calving grounds.',
    'serengeti_migration_note' => 'Rain shifts this pattern by two or three weeks in either direction. No operator can promise a crossing on a fixed date.',

    'serengeti_wildlife_badge' => 'Wildlife',
    'serengeti_wildlife_title' => 'Wildlife: what you will actually see',
    'serengeti_wildlife_intro' => 'On a three-day safari in the central Serengeti, based on our guides\' sighting records.',
    'serengeti_animal_lion' => 'Lion, highest density in Africa',
    'serengeti_animal_leopard' => 'Leopard, Seronera valley',
    'serengeti_animal_elephant' => 'Elephant',
    'serengeti_animal_buffalo' => 'Buffalo',
    'serengeti_animal_cheetah' => 'Cheetah, southern plains',
    'serengeti_animal_zebra' => 'Zebra',
    'serengeti_animal_giraffe' => 'Giraffe',
    'serengeti_animal_hyena' => 'Spotted hyena',
    'serengeti_animal_rhino' => 'Black rhino, very rare, Moru Kopjes only',
    'serengeti_wildlife_p1' => 'Lion, leopard, elephant and buffalo are all realistic on a three-day Serengeti safari. Black rhino is not: a small protected population survives around the Moru Kopjes, but sightings are rare and usually distant. If seeing rhino matters to you, add the Ngorongoro Crater to your itinerary.',
    'serengeti_wildlife_p2' => 'The Serengeti\'s lion population of around 3,000 is the largest in Africa, organised into prides that hold territory for generations. Cheetah favour the open southern plains where they can run; leopard favour the riverine acacias. Spotted hyena are far more numerous than most visitors expect and are accomplished hunters in their own right.',

    'serengeti_when_badge' => 'Best time',
    'serengeti_when_title' => 'When to visit',
    'serengeti_when_intro' => 'There is no closed season. What changes is what you see, how many other vehicles are at the sighting, and what you pay.',
    'serengeti_when_p1' => 'First safari, want it easy: June to October. Sparse vegetation, animals concentrated at water, reliable weather. Want the most wildlife drama: late January to February in Ndutu.',
    'serengeti_when_p2' => 'Want value and space: March, April, May or November. You will get rain, and you will also get the park almost to yourself at a fraction of the price.',

    'serengeti_stay_badge' => 'Accommodation',
    'serengeti_stay_title' => 'Where to stay',
    'serengeti_stay_intro' => 'Accommodation is the single biggest variable in what a Serengeti safari costs. The distances are so large that where you sleep determines how much of your day is spent driving rather than watching.',
    'serengeti_stay_budget_title' => 'Budget',
    'serengeti_stay_budget_price' => 'from $35.40/night park fee + camping',
    'serengeti_stay_budget_desc' => 'Public campsite: your own tent, shared long-drop toilets and cold showers, cook prepares meals on site. Inside the park, for the adventurous.',
    'serengeti_stay_mid_title' => 'Mid-range',
    'serengeti_stay_mid_price' => '$150–400/night',
    'serengeti_stay_mid_desc' => 'Lodge or tented camp inside the park: permanent building or canvas with proper beds and en-suite bathrooms. You wake up inside the ecosystem.',
    'serengeti_stay_luxury_title' => 'Luxury',
    'serengeti_stay_luxury_price' => '$300–700+/night',
    'serengeti_stay_luxury_desc' => 'Mobile camps that relocate to follow the migration, or premium tented camps. Small, remote, few vehicles nearby.',
    'serengeti_stay_note' => 'Sleeping inside the park costs more: a concession fee of $59.00 per adult per night on top of the room rate. But you are already in the middle of the action at dawn and dusk, when predators are most active.',

    'serengeti_fees_badge' => 'Costs',
    'serengeti_fees_title' => 'Park fees (2026)',
    'serengeti_fees_intro' => 'Fees are set by TANAPA, the Tanzania National Parks Authority, and are identical for every operator.',
    'serengeti_table_category' => 'Category',
    'serengeti_table_adult' => 'Adult (16+)',
    'serengeti_table_child' => 'Child (5–15)',
    'serengeti_fee_entry' => 'Entry, per 24 hours',
    'serengeti_fee_concession' => 'Concession, sleeping inside park (per night)',
    'serengeti_fee_campsite' => 'Public campsite (per night)',
    'serengeti_fees_note' => 'All figures include 18% VAT. Children under 5 enter free. Fees are reviewed by the government and can change without notice. Your written quote from us always states the exact amount for your dates.',

    'serengeti_gallery_badge' => 'Gallery',
    'serengeti_gallery_title' => 'Serengeti in pictures',
    'serengeti_gallery_caption_1' => 'Lion pride with a kill',
    'serengeti_gallery_caption_2' => 'Leopard resting in a tree',
    'serengeti_gallery_caption_3' => 'Zebra herd on the plains',
    'serengeti_gallery_caption_4' => 'Cheetahs in the shade',
    'serengeti_gallery_caption_5' => 'Lions stalking zebra',
    'serengeti_gallery_caption_6' => 'Leopard, wide view',

    'serengeti_back_to_parks' => 'Compare all parks',

    'serengeti_faq_badge' => 'FAQ',
    'serengeti_faq_title' => 'Serengeti National Park: frequently asked questions',
    'serengeti_faq_q1' => 'How much does it cost to enter the Serengeti?',
    'serengeti_faq_a1' => 'The 2026 non-resident entry fee is $82.60 per adult and $23.60 per child aged 5–15, per 24 hours, including 18% VAT. Children under 5 enter free. If you sleep inside the park there is also a concession fee of $59.00 per adult per night, or $35.40 for a public campsite.',
    'serengeti_faq_q2' => 'How many days do I need in the Serengeti?',
    'serengeti_faq_a2' => 'Three days is the realistic minimum, and four to five is the sweet spot. With fewer than three days the long drive from Arusha consumes most of your trip. You would see more wildlife by visiting Tarangire, Lake Manyara and the Ngorongoro Crater instead.',
    'serengeti_faq_q3' => 'When is the best time to visit the Serengeti?',
    'serengeti_faq_a3' => 'June to October for the easiest game viewing and the Mara River crossings. Late January and February for the calving season in Ndutu, which is arguably the better wildlife spectacle. March to May is wet, empty and cheapest.',
    'serengeti_faq_q4' => 'Will I definitely see a river crossing?',
    'serengeti_faq_a4' => 'No, and be sceptical of anyone who promises one. Crossings are unpredictable: herds can wait on the bank for a full day and then walk away. Three nights at Kogatende between July and October gives you a good chance, not a guarantee.',
    'serengeti_faq_q5' => 'Can I see the Big Five in the Serengeti?',
    'serengeti_faq_a5' => 'Four of them reliably: lion, leopard, elephant and buffalo. Black rhino survive only in small numbers around the Moru Kopjes and are rarely seen. For rhino, add the Ngorongoro Crater to your itinerary.',
    'serengeti_faq_q6' => 'How do I get from Arusha to the Serengeti?',
    'serengeti_faq_a6' => 'By road it is about 325 km and 7–8 hours to Seronera, usually broken with a stop in Ngorongoro or Karatu. By light aircraft it is around 1 hour 15 minutes. Many itineraries drive one way and fly the other.',
    'serengeti_faq_q7' => 'Can I do a Serengeti safari on a budget?',
    'serengeti_faq_a7' => 'Yes, camping safaris start from around $200 per person per day. You get the same guide, the same vehicle and the same animals; you save on where you sleep. Travelling in a group of four rather than two also cuts the per-person cost substantially.',
    'serengeti_faq_q8' => 'Is the Serengeti better than the Masai Mara?',
    'serengeti_faq_a8' => 'They are the same ecosystem divided by a border. The Serengeti is roughly fifteen times larger, has more varied habitats and far more space between vehicles; the Mara is more compact, so sightings come faster but with more crowding.',

    'serengeti_cta_title' => 'Ready to plan your Serengeti safari?',
    'serengeti_cta_intro' => 'Send us your dates, group size and budget. We reply with a written itinerary and a full price breakdown, no obligation.',
    'serengeti_cta_whatsapp' => 'Message us on WhatsApp',
    'serengeti_cta_safaris' => 'See safari itineraries',

    'ngorongoro_meta_title' => 'Ngorongoro Crater: The Complete Guide (2026) | Serengeti Budget Safari',
    'ngorongoro_meta_description' => 'Everything about the Ngorongoro Crater: black rhino odds, the 2026 $295 descent fee, when to go, where to stay and the Maasai who live there.',

    'ngorongoro_hero_badge' => 'Park guide',
    'ngorongoro_hero_title' => 'Ngorongoro Crater',
    'ngorongoro_hero_sub' => 'The largest intact caldera on earth, 25,000 animals inside a 260 km² bowl, and the best chance of black rhino in Tanzania, all in a single day.',
    'ngorongoro_hero_cta_quote' => 'Request a quote',

    'ngorongoro_intro_badge' => 'Introduction',
    'ngorongoro_intro_title' => 'What is the Ngorongoro Crater?',
    'ngorongoro_intro_p1' => 'The Ngorongoro Crater is the largest intact volcanic caldera on earth: a bowl 19 km across, 610 m deep and 260 km² in area, with walls that rise almost vertically from the floor. Around 25,000 large animals live inside it permanently, giving it the highest density of big game anywhere in Africa.',
    'ngorongoro_intro_p2' => 'The crater sits within the much larger Ngorongoro Conservation Area, 8,292 km² of highlands, forest and plains that also contains Olduvai Gorge, the Empakaai and Olmoti craters, and the Ndutu plains where the Great Migration calves. It is a UNESCO World Heritage Site and unusual in Africa for being a multiple-use area: around 100,000 Maasai live here with their cattle alongside the wildlife.',
    'ngorongoro_intro_p3' => 'For most visitors one fact settles it: this is the most reliable place in Tanzania to see black rhino, and therefore the place where completing the Big Five in a single day is genuinely possible.',

    'ngorongoro_fact_crater_area' => 'Crater floor',
    'ngorongoro_fact_nca_area' => 'Conservation Area',
    'ngorongoro_fact_status' => 'Status',
    'ngorongoro_fact_rhino' => 'Black rhino',
    'ngorongoro_fact_animals' => 'Animals in crater',
    'ngorongoro_fact_stay' => 'Suggested stay',
    'ngorongoro_fact_day' => 'day',
    'ngorongoro_fact_from_arusha' => 'From Arusha',
    'ngorongoro_fact_descent_limit' => 'Crater descent limit',

    'ngorongoro_areas_badge' => 'Understanding the area',
    'ngorongoro_areas_title' => 'The crater vs. the wider Conservation Area',
    'ngorongoro_areas_intro' => 'People often say "Ngorongoro" to mean two different things. Here is the distinction, and why it matters for your itinerary.',
    'ngorongoro_area_floor_name' => 'The crater floor',
    'ngorongoro_area_floor_desc' => 'The 260 km² caldera itself: a self-contained bowl where most of the animals live year-round because the walls keep them in. This is what almost everyone means when they say "Ngorongoro Crater", and it is where you spend your game-drive day.',
    'ngorongoro_area_wider_name' => 'The Conservation Area',
    'ngorongoro_area_wider_desc' => 'The full 8,292 km² region surrounding the crater: highlands, forest, the Ndutu plains and two further craters, Empakaai and Olmoti. It is a UNESCO-listed multiple-use area where roughly 100,000 Maasai live alongside the wildlife, unlike a national park where people are excluded.',
    'ngorongoro_area_olduvai_name' => 'Olduvai Gorge',
    'ngorongoro_area_olduvai_desc' => 'Half an hour from the crater, on the road to the Serengeti, Olduvai Gorge cuts 90 m through two million years of volcanic sediment. Louis and Mary Leakey worked here from the 1930s and found hominin remains that reshaped what was known about human origins, including Paranthropus boisei in 1959. There is a small museum, and it fits easily into the drive between Ngorongoro and the Serengeti.',

    'ngorongoro_maasai_badge' => 'People',
    'ngorongoro_maasai_title' => 'The Maasai who live here',
    'ngorongoro_maasai_intro' => 'Ngorongoro is not a national park, and the distinction is deliberate.',
    'ngorongoro_maasai_p1' => 'When the Serengeti was gazetted in 1959 the Maasai living there were moved out; Ngorongoro was created as a multiple-use conservation area where people, livestock and wildlife share the land. Around 100,000 Maasai live in the Conservation Area today with roughly a million head of cattle, grazing the crater floor by day and returning to the rim at night.',
    'ngorongoro_maasai_p2' => 'Visiting a Maasai boma is possible and is arranged through the conservation authority. Quality varies. Some visits are heavily staged. We work with communities we have long relationships with, where the fee reaches the village and you can genuinely ask questions.',

    'ngorongoro_wildlife_badge' => 'Wildlife',
    'ngorongoro_wildlife_title' => 'Wildlife: what you will actually see',
    'ngorongoro_wildlife_intro' => 'Sighting probabilities for a single full day on the crater floor. Unusually high, because the animals cannot disperse.',
    'ngorongoro_animal_lion' => 'Lion, around 95% odds',
    'ngorongoro_animal_rhino' => 'Black rhino, around 60% odds',
    'ngorongoro_animal_buffalo' => 'Buffalo, near-certain',
    'ngorongoro_animal_zebra' => 'Zebra, near-certain',
    'ngorongoro_animal_elephant' => 'Elephant, Lerai Forest bulls',
    'ngorongoro_animal_hippo' => 'Hippo, Gorigor Swamp',
    'ngorongoro_animal_hyena' => 'Spotted hyena',
    'ngorongoro_animal_flamingo' => 'Flamingo, Lake Magadi',
    'ngorongoro_animal_leopard' => 'Leopard, rare, rim forest only',
    'ngorongoro_wildlife_p1' => 'Lion, buffalo, elephant and black rhino are all realistic on a single crater day: a genuine chance at the Big Five in 24 hours, which is unusual anywhere in Africa. Only leopard is a real long shot: they live in the rim forest and are seldom seen from the floor. There are no giraffe at all: the descent roads are too steep for them.',
    'ngorongoro_wildlife_p2' => 'The crater lions are among the most studied in the world and illustrate the cost of isolation: the population is effectively closed, genetic diversity is low, and a disease outbreak in 1962 reduced them to a handful of animals. Numbers today sit around 60, and they are highly habituated to vehicles. Around 30 black rhino live in the crater under round-the-clock ranger protection, usually seen at a distance across open grass, so bring binoculars.',

    'ngorongoro_when_badge' => 'Best time',
    'ngorongoro_when_title' => 'When to visit',
    'ngorongoro_when_intro' => 'The crater works in every month. The animals do not migrate out, so unlike the Serengeti there is no wrong season for game viewing.',
    'ngorongoro_when_p1' => 'June to October is driest, coldest at dawn and busiest: expect other vehicles at every sighting. March to May brings the long rains: slippery descent roads and mist that can sit on the rim until mid-morning, but also the greenest crater and the cheapest rates.',
    'ngorongoro_when_p2' => 'More important than the month is being on the floor at 06:30. Predators are active in the first two hours, the light is soft, and you are ahead of the vehicles that descend at nine. This single decision changes the quality of the day more than the season does.',

    'ngorongoro_stay_badge' => 'Accommodation',
    'ngorongoro_stay_title' => 'Where to stay',
    'ngorongoro_stay_intro' => 'Three broad choices, and the decision is mostly about how early you can be at the descent gate.',
    'ngorongoro_stay_budget_title' => 'Budget',
    'ngorongoro_stay_budget_price' => 'from $35.40/night camping fee',
    'ngorongoro_stay_budget_desc' => 'Simba public campsite, on the rim itself: your own tent, basic shared facilities, and buffalo or zebra sometimes wandering through camp at night. Cold at 2,400 m: a proper sleeping bag is not optional.',
    'ngorongoro_stay_mid_title' => 'Karatu',
    'ngorongoro_stay_mid_price' => '$60–200/night',
    'ngorongoro_stay_mid_desc' => 'A real town 30–45 minutes from the gate: far better value, warmer, more choice of restaurants. The trade-off is an early start, leaving around 05:30 to be first at the descent road.',
    'ngorongoro_stay_luxury_title' => 'Crater rim lodge',
    'ngorongoro_stay_luxury_price' => '$250–800+/night',
    'ngorongoro_stay_luxury_desc' => 'The view straight down into the crater from your room, and ten minutes from the descent road so you can be first onto the floor. Expensive, cold at night, and often booked out months ahead.',
    'ngorongoro_stay_note' => 'If you are visiting for one day only and cost is not the deciding factor, stay on the rim. Being first onto the floor is worth a great deal. If you have several days in the area, Karatu is the sensible base and the money saved can pay for an extra night in the Serengeti.',

    'ngorongoro_fees_badge' => 'Costs',
    'ngorongoro_fees_title' => 'Park fees (2026)',
    'ngorongoro_fees_intro' => 'Ngorongoro is administered by the NCAA, not TANAPA, and it has one charge that catches people out: a separate fee simply to drive down into the crater, charged per vehicle rather than per person.',
    'ngorongoro_table_category' => 'Category',
    'ngorongoro_table_adult' => 'Adult (16+)',
    'ngorongoro_table_child' => 'Child (5–15)',
    'ngorongoro_fee_entry' => 'Conservation Area entry, per 24 hours',
    'ngorongoro_fee_descent' => 'Crater service fee (descent, per vehicle)',
    'ngorongoro_fee_descent_value' => '$295.00 per vehicle',
    'ngorongoro_fee_concession' => 'Concession, sleeping inside the NCA (per night)',
    'ngorongoro_fee_campsite' => 'Public campsite (per night)',
    'ngorongoro_fees_note' => 'All figures include 18% VAT. Children under 5 enter free. The crater descent fee is per vehicle, not per person, so the cost per head drops sharply with group size: roughly $148 each for two people, under $50 each for six. It applies every time you descend, so a second crater day means paying it twice. Fees can change without notice; your written quote always states the exact amount for your dates.',

    'ngorongoro_gallery_badge' => 'Gallery',
    'ngorongoro_gallery_title' => 'Ngorongoro in pictures',
    'ngorongoro_gallery_caption_1' => 'The crater from the rim',
    'ngorongoro_gallery_caption_2' => 'Rhino in the grassland',
    'ngorongoro_gallery_caption_3' => 'Elephant under an acacia tree',
    'ngorongoro_gallery_caption_4' => 'Male lion on the crater floor',
    'ngorongoro_gallery_caption_5' => 'Spotted hyena on the plains',
    'ngorongoro_gallery_caption_6' => 'Elephant family at sunset',

    'ngorongoro_back_to_parks' => 'Compare all parks',

    'ngorongoro_faq_badge' => 'FAQ',
    'ngorongoro_faq_title' => 'Ngorongoro Crater: frequently asked questions',
    'ngorongoro_faq_q1' => 'How much does it cost to visit the Ngorongoro Crater?',
    'ngorongoro_faq_a1' => 'In 2026, $82.60 per adult per 24 hours to enter the Conservation Area, plus a crater service fee of $295.00 per vehicle for the descent. Children 5–15 pay $23.60; under-fives are free. All figures include 18% VAT.',
    'ngorongoro_faq_q2' => 'Why is the crater descent fee so high?',
    'ngorongoro_faq_a2' => 'It is charged per vehicle rather than per person and funds conservation and the rhino protection programme. Because it is per vehicle, the cost per head drops sharply with group size: around $148 each for two people, under $50 each for six.',
    'ngorongoro_faq_q3' => 'Will I see black rhino in the crater?',
    'ngorongoro_faq_a3' => 'Around 30 live in the crater and the odds on a full day are roughly 60%, but usually at a distance across open grass. Bring binoculars. Early morning gives the best chance, before they retreat towards the swamp margins.',
    'ngorongoro_faq_q4' => 'Can I see the Big Five in one day?',
    'ngorongoro_faq_a4' => 'In Ngorongoro this is genuinely possible, which is unusual. Lion, buffalo and elephant are near-certain, rhino is likely, and only leopard is a real long shot: they live in the rim forest and are seldom seen from the floor.',
    'ngorongoro_faq_q5' => 'How long can I stay in the crater?',
    'ngorongoro_faq_a5' => 'Six hours from the moment you descend. The limit is enforced at the exit gate and exists to control vehicle numbers on a small floor.',
    'ngorongoro_faq_q6' => 'How far is Ngorongoro from Arusha, and can I do it as a day trip?',
    'ngorongoro_faq_a6' => 'About 180 km, three to four hours by road. Yes, a day trip is possible, leaving around 05:30 and returning after dark, and it remains one of our most requested one-day safaris, since it lies directly on the route to the Serengeti.',
    'ngorongoro_faq_q7' => 'What is the difference between the crater and the Conservation Area?',
    'ngorongoro_faq_a7' => 'The crater is the 260 km² caldera floor. The Conservation Area is the 8,292 km² region surrounding it, which also includes Olduvai Gorge, the Empakaai and Olmoti craters, the Ndutu plains and around 100,000 Maasai residents.',
    'ngorongoro_faq_q8' => 'Should I stay on the rim or in Karatu?',
    'ngorongoro_faq_a8' => 'Rim lodges cost $250–800 and let you be first onto the floor. Karatu costs $60–200 and adds a 30–45 minute pre-dawn drive. For a single crater day the rim is worth it; for longer stays Karatu is the better value.',

    'ngorongoro_cta_title' => 'Ready to plan your Ngorongoro safari?',
    'ngorongoro_cta_intro' => 'Send us your dates, group size and budget. We reply with a written itinerary and a full price breakdown, no obligation.',
    'ngorongoro_cta_whatsapp' => 'Message us on WhatsApp',
    'ngorongoro_cta_safaris' => 'See safari itineraries',

    'tarangire_meta_title' => 'Tarangire National Park: The Complete Guide (2026) | Serengeti Budget Safari',
    'tarangire_meta_description' => 'Everything about Tarangire National Park: elephants, ancient baobabs, 550 bird species, 2026 park fees, where to stay and when to go.',

    'tarangire_hero_badge' => 'Park guide',
    'tarangire_hero_title' => 'Tarangire National Park',
    'tarangire_hero_sub' => 'Ancient baobabs, the largest elephant herds in northern Tanzania and more bird species than any other park in the country. Two hours from Arusha, and far quieter than its neighbours.',
    'tarangire_hero_cta_quote' => 'Request a quote',

    'tarangire_intro_badge' => 'Introduction',
    'tarangire_intro_title' => 'What is Tarangire?',
    'tarangire_intro_p1' => 'Tarangire National Park covers 2,850 km² of dry acacia woodland and baobab country two hours south of Arusha. It is the sixth-largest park in Tanzania and, for reasons that are hard to justify, the most consistently overlooked on the northern circuit.',
    'tarangire_intro_p2' => 'It is named after the Tarangire River, which flows through the length of the park and is the only permanent water for miles in every direction. In the dry season that single fact transforms the place: animals from across a much larger ecosystem converge on the river, and the concentration of game between June and October rivals anything in the Serengeti.',
    'tarangire_intro_p3' => 'Tarangire is best known for two things: elephants, with a resident population of 2,500 to 3,000 and herds of fifty or more being unremarkable here, and baobabs, the enormous swollen-trunked trees that give the landscape a character found nowhere else on the circuit. It also holds over 550 recorded bird species, the highest count of any Tanzanian park.',

    'tarangire_fact_area' => 'Area',
    'tarangire_fact_established' => 'Established',
    'tarangire_fact_elephants' => 'Elephants',
    'tarangire_fact_baobabs' => 'Baobabs',
    'tarangire_fact_baobabs_value' => 'Thousands',
    'tarangire_fact_birds' => 'Bird species',
    'tarangire_fact_stay' => 'Suggested stay',
    'tarangire_fact_days' => 'days',
    'tarangire_fact_from_arusha' => 'From Arusha',
    'tarangire_fact_river' => 'Tarangire River',
    'tarangire_fact_river_value' => 'Permanent water',

    'tarangire_zones_badge' => 'Where to go',
    'tarangire_zones_title' => 'The areas of Tarangire',
    'tarangire_zones_intro' => 'The park is smaller than the Serengeti, but where you go still changes what you see. These are the main areas, and what each one is known for.',
    'tarangire_zone_river_name' => 'The Tarangire River circuit',
    'tarangire_zone_river_desc' => 'The heart of the park and the classic first visit. The river holds water year-round, and in the dry season it draws elephants, buffalo, zebra and lion down to drink and dig for water in the sandy bed. Most lodges and the main game-drive network sit along this stretch.',
    'tarangire_zone_silale_name' => 'Silale Swamp',
    'tarangire_zone_silale_desc' => 'A large seasonal swamp in the centre of the park that holds water into the dry season. It attracts elephant, buffalo and exceptional numbers of birds and raptors, and it is worth the extra drive from the main river circuit.',
    'tarangire_zone_south_name' => 'The southern reaches',
    'tarangire_zone_south_desc' => 'Drier, wilder and rarely visited by day trippers. This is where the dry-country antelope live (fringe-eared oryx, lesser kudu and gerenuk), and where two-day visitors are rewarded with the quietest game viewing in the park.',
    'tarangire_zone_north_name' => 'The northern gate area',
    'tarangire_zone_north_desc' => 'Around the Kwa Kuchinja entrance gate, the closest part of the park to Arusha. Rolling baobab-studded hills and open grassland make this the easiest stretch for a day trip, with good game viewing close to the gate itself.',

    'tarangire_wildlife_badge' => 'Wildlife',
    'tarangire_wildlife_title' => 'Wildlife: what you will actually see',
    'tarangire_wildlife_intro' => 'Sighting probabilities for a full day in the dry season (June–October), based on our guides\' records. In the wet season the animals disperse and every figure drops substantially.',
    'tarangire_animal_elephant' => 'Elephant, huge herds, 99%',
    'tarangire_animal_zebra' => 'Zebra',
    'tarangire_animal_buffalo' => 'Buffalo',
    'tarangire_animal_giraffe' => 'Giraffe',
    'tarangire_animal_wildebeest' => 'Wildebeest',
    'tarangire_animal_lion' => 'Lion, sometimes in trees',
    'tarangire_animal_leopard' => 'Leopard, around 25%',
    'tarangire_animal_hyena' => 'Spotted hyena',
    'tarangire_animal_oryx' => 'Fringe-eared oryx, southern reaches',
    'tarangire_wildlife_p1' => 'Elephant, buffalo and lion are all realistic on a Tarangire safari, and elephant is close to a certainty in the dry season. Leopard is possible but uncommon at around 25%, cheetah is genuine luck, and there is no rhino here at all. For the full Big Five, combine Tarangire with the Ngorongoro Crater.',
    'tarangire_wildlife_p2' => 'What makes Tarangire worth watching rather than merely counting is elephant behaviour: in the dry months you can watch matriarchs dig wells a metre deep in the sand of the riverbed, with zebra, impala and baboon waiting a respectful distance away to drink once the elephants move off. Tarangire\'s dry southern reaches also hold three antelope difficult to find on the rest of the northern circuit: fringe-eared oryx, lesser kudu and the gerenuk, which stands on its hind legs to browse.',

    'tarangire_when_badge' => 'Best time',
    'tarangire_when_title' => 'When to visit',
    'tarangire_when_intro' => 'Tarangire is the most strongly seasonal park on the northern circuit. The difference between August and April is not a matter of degree. It is a different park.',
    'tarangire_when_p1' => 'July to October is exceptional: the river is the only water for miles and everything comes to it, with elephant herds at their largest. June is very good and quieter still. November and December bring the short rains. Animals begin dispersing, but it is superb for birds and photogenic green landscapes.',
    'tarangire_when_p2' => 'March to May, the long rains, is the weakest period for game, with animals spread over a huge area, but it is the best time for birding and for having the park to yourself. If big game is your priority and you can only visit during the long rains, consider spending that day in Ngorongoro instead, where the crater animals do not disperse.',

    'tarangire_stay_badge' => 'Accommodation',
    'tarangire_stay_title' => 'Where to stay',
    'tarangire_stay_intro' => 'Because Tarangire is only two hours from Arusha, staying overnight is a choice rather than a necessity, but it changes what you see. The best elephant activity is at dawn and dusk, and day visitors miss both.',
    'tarangire_stay_budget_title' => 'Budget',
    'tarangire_stay_budget_price' => 'from $35.40/night park fee + camping',
    'tarangire_stay_budget_desc' => 'Public campsite inside the park: your own tent, basic long-drop toilets and cold water, cook prepares meals on site. The cheapest way to sleep inside Tarangire.',
    'tarangire_stay_mid_title' => 'Mid-range',
    'tarangire_stay_mid_price' => '$150–400/night',
    'tarangire_stay_mid_desc' => 'Lodge or tented camp inside the park, several sitting on the escarpment overlooking the river. You can watch elephants from the terrace and are first on the tracks in the morning.',
    'tarangire_stay_luxury_title' => 'Outside the gate',
    'tarangire_stay_luxury_price' => '$60–150/night',
    'tarangire_stay_luxury_desc' => 'Lodges just outside the park boundary, only 15–30 minutes from the gate. The most competitive outside-the-park option on the whole circuit, and how we recommend trimming a budget without losing the experience.',
    'tarangire_stay_note' => 'Sleeping inside the park costs more: a concession fee of $47.20 per adult per night on top of the room rate. But you are already in the middle of the action at dawn and dusk, when elephant activity peaks.',

    'tarangire_fees_badge' => 'Costs',
    'tarangire_fees_title' => 'Park fees (2026)',
    'tarangire_fees_intro' => 'Tarangire is a "select" park under the TANAPA tariff, which makes it substantially cheaper than the Serengeti or Ngorongoro, one of the reasons it delivers such good value.',
    'tarangire_table_category' => 'Category',
    'tarangire_table_adult' => 'Adult (16+)',
    'tarangire_table_child' => 'Child (5–15)',
    'tarangire_fee_entry' => 'Entry, per 24 hours',
    'tarangire_fee_concession' => 'Concession, sleeping inside park (per night)',
    'tarangire_fee_campsite' => 'Public campsite (per night)',
    'tarangire_fees_note' => 'All figures include 18% VAT. Children under 5 enter free. Fees are reviewed by the government and can change without notice. Your written quote from us always states the exact amount for your dates.',

    'tarangire_gallery_badge' => 'Gallery',
    'tarangire_gallery_title' => 'Tarangire in pictures',
    'tarangire_gallery_caption_1' => 'Elephant family at sunset',
    'tarangire_gallery_caption_2' => 'Elephant close-up portrait',
    'tarangire_gallery_caption_3' => 'Savanna sunrise among acacia trees',
    'tarangire_gallery_caption_4' => 'Elephant sheltering under an acacia',
    'tarangire_gallery_caption_5' => 'Zebra herd on the plains',
    'tarangire_gallery_caption_6' => 'Lion resting in the grass',

    'tarangire_back_to_parks' => 'Compare all parks',

    'tarangire_faq_badge' => 'FAQ',
    'tarangire_faq_title' => 'Tarangire National Park: frequently asked questions',
    'tarangire_faq_q1' => 'How much does it cost to enter Tarangire?',
    'tarangire_faq_a1' => 'The 2026 non-resident fee is $59.00 per adult and $17.70 per child aged 5–15, per 24 hours, including 18% VAT. Children under 5 are free. Staying inside the park adds a concession fee of $47.20 per adult per night, or $35.40 for a public campsite.',
    'tarangire_faq_q2' => 'Is Tarangire worth visiting?',
    'tarangire_faq_a2' => 'In the dry season, unequivocally. The elephant concentrations along the river rival anything in Tanzania, with a fraction of the vehicles and a lower entry fee than the Serengeti. Between March and May the game disperses and it is the weakest of the northern parks.',
    'tarangire_faq_q3' => 'When is the best time to visit Tarangire?',
    'tarangire_faq_a3' => 'July to October. The Tarangire River is the only permanent water for a long way in every direction, so in the dry months the entire ecosystem converges on it. June is very good and quieter still.',
    'tarangire_faq_q4' => 'How many elephants are in Tarangire?',
    'tarangire_faq_a4' => 'Between 2,500 and 3,000 resident animals. Herds of fifty or more are routine in the dry season, and several hundred elephants in a single day is normal.',
    'tarangire_faq_q5' => 'Can I visit Tarangire as a day trip?',
    'tarangire_faq_a5' => 'Yes, and it is one of our most popular one-day safaris. Leave Arusha around 06:00, spend the day in the park, return in the evening. Staying a night is better, because the best elephant activity is at dawn and dusk.',
    'tarangire_faq_q6' => 'Can I see the Big Five in Tarangire?',
    'tarangire_faq_a6' => 'Three of them: elephant, buffalo and lion. Leopard is possible but uncommon at around 25%. There are no rhino. For the full Big Five, combine Tarangire with the Ngorongoro Crater.',
    'tarangire_faq_q7' => 'How do I get from Arusha to Tarangire?',
    'tarangire_faq_a7' => 'About 118 km, roughly two hours on good tarmac with a short gravel stretch to the main gate at Kwa Kuchinja. It is the closest of the northern circuit\'s major parks, which makes it a practical full-day trip or an easy first night on a longer safari.',
    'tarangire_faq_q8' => 'Why are there so many baobabs here?',
    'tarangire_faq_a8' => 'The soil and rainfall suit them, and the park has protected them for over fifty years. Some are more than a thousand years old. The deep vertical scars on the trunks are tusk marks from elephants stripping fibre for its moisture.',

    'tarangire_cta_title' => 'Ready to plan your Tarangire safari?',
    'tarangire_cta_intro' => 'Send us your dates, group size and budget. We reply with a written itinerary and a full price breakdown, no obligation.',
    'tarangire_cta_whatsapp' => 'Message us on WhatsApp',
    'tarangire_cta_safaris' => 'See safari itineraries',

    'nyerere_meta_title' => 'Nyerere National Park (Selous): The Complete Guide (2026) | Serengeti Budget Safari',
    'nyerere_meta_description' => 'Nyerere National Park, formerly Selous: Africa\'s largest park, boat safaris on the Rufiji River, walking safaris and African wild dog. 2026 fees, when to go and how to get there from Dar.',

    'nyerere_hero_badge' => 'Park guide',
    'nyerere_hero_title' => 'Nyerere National Park',
    'nyerere_hero_sub' => 'Formerly Selous: the largest national park in Africa, where you can do a boat safari, a walking safari and a game drive in the same day.',
    'nyerere_hero_cta_quote' => 'Request a quote',

    'nyerere_intro_badge' => 'Introduction',
    'nyerere_intro_title' => 'What is Nyerere National Park?',
    'nyerere_intro_p1' => 'Nyerere National Park was created in 2019 out of the northern section of the old Selous Game Reserve, and at over 30,893 km² it is the largest national park in Africa, bigger than Belgium, and roughly twice the size of the Serengeti. It sits in south-eastern Tanzania, reached from Dar es Salaam rather than Arusha, which makes it the natural gateway to the southern safari circuit.',
    'nyerere_intro_p2' => 'Most travellers still know it as Selous. The remaining southern portion keeps that name as a game reserve; the part you visit as a tourist is now Nyerere, named after Tanzania\'s first president.',
    'nyerere_intro_p3' => 'What sets it apart is water. The Rufiji River runs through it, spreading into a network of lakes, channels and sandbanks, and that changes what a safari here is: you can do a boat safari, a walking safari and a game drive in the same day, a combination that simply is not possible in the Serengeti.',

    'nyerere_fact_area' => 'Area',
    'nyerere_fact_rank' => 'Rank',
    'nyerere_fact_rank_value' => 'Largest park in Africa',
    'nyerere_fact_established' => 'Established',
    'nyerere_fact_status' => 'Status',
    'nyerere_fact_boat' => 'Boat safaris',
    'nyerere_fact_boat_value' => 'Yes, Rufiji River',
    'nyerere_fact_wilddog' => 'Wild dog',
    'nyerere_fact_wilddog_value' => 'Major stronghold',
    'nyerere_fact_stay' => 'Suggested stay',
    'nyerere_fact_nights' => 'nights',
    'nyerere_fact_from_dar' => 'From Dar es Salaam',
    'nyerere_fact_minutes' => 'min by air',

    'nyerere_regions_badge' => 'Where to go',
    'nyerere_regions_title' => 'The areas of Nyerere',
    'nyerere_regions_intro' => 'The park is vast, and almost all tourism is concentrated in a small northern section around the river and lakes. These are the main areas, and what each one offers.',
    'nyerere_region_rufiji_name' => 'The Rufiji River and lake system',
    'nyerere_region_rufiji_desc' => 'The largest river in East Africa by volume slows, spreads and splits into a network of channels, oxbow lakes and sandbanks as it crosses the park. Five main lakes (Tagalala, Manze, Nzerakera, Siwandu and Mzizimia) sit here in the section where most camps are based, each with its own hippo pods and resident birds. This is where the boat safaris happen, and it is unlike anywhere in the northern circuit.',
    'nyerere_region_stieglers_name' => 'Stiegler\'s Gorge and the northern tourist zone',
    'nyerere_region_stieglers_desc' => 'The main visitor area, easily reached from the airstrips near the Rufiji camps. Stiegler\'s Gorge, 100 m deep and 100 m wide, cuts through the north of the park. This zone combines game drives, walking safaris and boat trips within a short distance of each lodge, which is why nearly every visitor stays here.',
    'nyerere_region_south_name' => 'The southern wilderness',
    'nyerere_region_south_desc' => 'The vast majority of Nyerere\'s 30,893 km² lies south of the tourist zone, and it is genuinely remote: few roads, few camps, and rarely visited even by Tanzanian standards. It is not part of a typical itinerary, but it underlines what makes this park different from the northern circuit: space, and an almost complete absence of other vehicles.',

    'nyerere_activities_badge' => 'What makes it different',
    'nyerere_activities_title' => 'Boat safaris, walking safaris and more',
    'nyerere_activities_intro' => 'This is why you come to Nyerere rather than adding another northern park.',
    'nyerere_table_activity' => 'Activity',
    'nyerere_table_duration' => 'Duration',
    'nyerere_table_highlight' => 'What it gives you',
    'nyerere_act_boat_name' => 'Boat safari on the Rufiji',
    'nyerere_act_boat_desc' => 'Drifting the river and its lakes at eye level with hippo pods and crocodiles on the sandbanks, watching elephants come down to drink and fish eagles work the channels. The best boat safari in Tanzania.',
    'nyerere_act_walking_name' => 'Walking safari',
    'nyerere_act_walking_desc' => 'With an armed ranger, generally at first light. Nyerere was one of the first places in Tanzania to offer walking safaris and remains one of the best. You track on foot and encounter animals at ground level.',
    'nyerere_act_flycamp_name' => 'Fly-camping',
    'nyerere_act_flycamp_unit' => 'night',
    'nyerere_act_flycamp_desc' => 'A night out under canvas away from the main camp, with a guide and a ranger. Simple, and often the most memorable night of the whole trip.',
    'nyerere_act_drive_name' => 'Game drive',
    'nyerere_act_drive_desc' => 'Classic vehicle safari through miombo woodland and open grassland, usually combined with a boat trip or a walk on the same day.',
    'nyerere_activities_note' => 'Boat safaris, walking safaris and fly-camping are charged separately by the camps. Tell us in advance which you want, since they are the main reason to come.',

    'nyerere_wildlife_badge' => 'Wildlife',
    'nyerere_wildlife_title' => 'Wildlife: what you will actually see',
    'nyerere_wildlife_intro' => 'On a three-day visit combining game drives and boat safaris in the dry season, based on our guides\' sighting records.',
    'nyerere_animal_hippo' => 'Hippo, huge pods on the Rufiji',
    'nyerere_animal_crocodile' => 'Crocodile',
    'nyerere_animal_elephant' => 'Elephant',
    'nyerere_animal_lion' => 'Lion',
    'nyerere_animal_buffalo' => 'Buffalo',
    'nyerere_animal_wilddog' => 'African wild dog, global stronghold',
    'nyerere_animal_leopard' => 'Leopard',
    'nyerere_animal_zebra' => 'Zebra',
    'nyerere_animal_rhino' => 'Black rhino, almost none left',
    'nyerere_wildlife_p1' => 'Hippo and crocodile are close to a certainty on the river, and elephant, lion and buffalo are all realistic across a three-day stay. Nyerere holds one of the largest remaining populations of African wild dog on the continent, around a 35% chance of a sighting on a three-day visit, which is exceptional for a species with fewer than 7,000 individuals left in the wild.',
    'nyerere_wildlife_p2' => 'Black rhino are effectively absent: a tiny number survive in the wider ecosystem, but for practical purposes you should not plan a trip here expecting to see one. For rhino in Tanzania, the Ngorongoro Crater is the realistic option. Unlike the Serengeti, Nyerere has no migration. Instead it has large resident populations that are present year-round.',

    'nyerere_when_badge' => 'Best time',
    'nyerere_when_title' => 'When to visit',
    'nyerere_when_intro' => 'Nyerere effectively shuts for the long rains, a real difference from the northern parks, which operate year-round.',
    'nyerere_when_p1' => 'June to October is best: the dry season concentrates game along the Rufiji, boat safaris are at their finest and temperatures are comfortable. November and December bring the short rains: green scenery, good birding and fewer visitors, still very workable.',
    'nyerere_when_p2' => 'January and February are hot and humid but still good for game and excellent for birds. March to May, the long rains, is when most camps close and roads flood. We do not recommend travelling then.',

    'nyerere_stay_badge' => 'Accommodation',
    'nyerere_stay_title' => 'Where to stay',
    'nyerere_stay_intro' => 'Check carefully what is included. At the luxury end, boat safaris, walking safaris and park fees are often bundled; at the mid-range they usually are not, and adding them changes the real price considerably. We itemise all of it in writing.',
    'nyerere_stay_budget_title' => 'Budget',
    'nyerere_stay_budget_price' => 'from $35.40/night park fee + camping',
    'nyerere_stay_budget_desc' => 'Public campsite or simple bandas near the Mtemere gate, often used by road-based trips from Dar. Basic facilities; you need your own equipment or ours.',
    'nyerere_stay_mid_title' => 'Mid-range',
    'nyerere_stay_mid_price' => '$200–400/night',
    'nyerere_stay_mid_desc' => 'Comfortable tented camp near the lakes. Activities such as boat safaris and walks are usually charged separately from the room rate.',
    'nyerere_stay_luxury_title' => 'Luxury',
    'nyerere_stay_luxury_price' => '$450–1,000+/night',
    'nyerere_stay_luxury_desc' => 'Small camps on Lake Manze or Siwandu, fully inclusive with boat and walking safaris built in. Hippos calling outside the tent at night.',
    'nyerere_stay_note' => 'Where to base yourself: the northern lake section around Manze and Siwandu is where the boat safaris and most game viewing happen. Camps further south are cheaper but you spend more of the day driving to the water.',

    'nyerere_fees_badge' => 'Costs',
    'nyerere_fees_title' => 'Park fees (2026)',
    'nyerere_fees_intro' => 'Fees are set by TANAPA, the Tanzania National Parks Authority, and are identical for every operator.',
    'nyerere_table_category' => 'Category',
    'nyerere_table_adult' => 'Adult (16+)',
    'nyerere_table_child' => 'Child (5–15)',
    'nyerere_fee_entry' => 'Entry, per 24 hours',
    'nyerere_fee_concession' => 'Concession, sleeping inside park (per night)',
    'nyerere_fee_campsite' => 'Public campsite (per night)',
    'nyerere_fees_note' => 'All figures include 18% VAT. Children under 5 enter free. Boat safaris, walking safaris and fly-camping are charged separately by the camps. Fees are reviewed by the government and can change without notice. Your written quote from us always states the exact amount for your dates.',

    'nyerere_gallery_badge' => 'Gallery',
    'nyerere_gallery_title' => 'Nyerere in pictures',
    'nyerere_gallery_caption_1' => 'Watching hippos from the boat',
    'nyerere_gallery_caption_2' => 'Rhino grazing at dusk',
    'nyerere_gallery_caption_3' => 'Elephant family at sunset',
    'nyerere_gallery_caption_4' => 'Lion resting near the water',
    'nyerere_gallery_caption_5' => 'Spotted hyena on the savanna',
    'nyerere_gallery_caption_6' => 'Elephant under an acacia tree',

    'nyerere_back_to_parks' => 'Compare all parks',

    'nyerere_faq_badge' => 'FAQ',
    'nyerere_faq_title' => 'Nyerere National Park: frequently asked questions',
    'nyerere_faq_q1' => 'Is Nyerere the same as Selous?',
    'nyerere_faq_a1' => 'Nyerere National Park was created in 2019 from the northern section of the Selous Game Reserve. The remaining southern portion is still called Selous. The area tourists visit is now Nyerere, though many operators still use the old name.',
    'nyerere_faq_q2' => 'How much does it cost to enter Nyerere?',
    'nyerere_faq_a2' => 'The 2026 non-resident fee is $59.00 per adult and $17.70 per child aged 5–15, per 24 hours, including 18% VAT. Boat safaris, walking safaris and fly-camping are charged separately by the camps.',
    'nyerere_faq_q3' => 'How do I get to Nyerere?',
    'nyerere_faq_a3' => 'About 45 minutes by light aircraft from Dar es Salaam, with daily scheduled flights, or five to six hours by road. Nyerere is reached from Dar, not Arusha, which changes the logistics of a trip compared with the northern parks.',
    'nyerere_faq_q4' => 'Can I do a boat safari in Nyerere?',
    'nyerere_faq_a4' => 'Yes, and it is the main reason to come. Two or three hours on the Rufiji River and its lakes brings you level with hippo pods and crocodiles, with elephants coming down to drink. It is the best boat safari in Tanzania.',
    'nyerere_faq_q5' => 'Can I walk in Nyerere?',
    'nyerere_faq_a5' => 'Yes, with an armed ranger, usually at first light for two to three hours. Nyerere was among the first places in Tanzania to offer walking safaris and remains one of the best for them.',
    'nyerere_faq_q6' => 'Will I see wild dog?',
    'nyerere_faq_a6' => 'Roughly a 35% chance on a three-day visit, outstanding for a species with fewer than 7,000 individuals left in the wild. Nyerere holds one of the largest remaining populations in Africa.',
    'nyerere_faq_q7' => 'How many days do I need in Nyerere?',
    'nyerere_faq_a7' => 'Three to four days. That gives you a boat safari, a walking safari and several game drives without rushing, which is the whole point of coming here rather than adding another northern park.',
    'nyerere_faq_q8' => 'Are there rhino in Nyerere?',
    'nyerere_faq_a8' => 'A very small number of black rhino survive in the wider ecosystem, but you should assume you will not see one. For rhino in Tanzania, the Ngorongoro Crater is the realistic option.',

    'nyerere_cta_title' => 'Ready to plan your Nyerere safari?',
    'nyerere_cta_intro' => 'Send us your dates, group size and budget. We reply with a written itinerary and a full price breakdown, no obligation.',
    'nyerere_cta_whatsapp' => 'Message us on WhatsApp',
    'nyerere_cta_safaris' => 'See safari itineraries',

    // ===== Day Trips listing =====
    'daytrips_meta_title' => 'Day Trips from Arusha | Tarangire, Ngorongoro & More | Serengeti Budget Safari',
    'daytrips_meta_description' => 'One-day excursions from Arusha: Tarangire, Ngorongoro Crater, Lake Manyara, Arusha National Park, Materuni waterfalls, Chemka hot springs, a Maasai village and more.',
    'daytrips_hero_badge' => 'Day Trips',
    'daytrips_hero_title' => 'Day trips from Arusha',
    'daytrips_hero_sub' => 'One-day excursions for the days before your safari, after your Kilimanjaro climb, or whenever you have a spare day in town.',
    'daytrips_hero_quote' => 'Request a quote',
    'daytrips_hero_whatsapp' => 'WhatsApp',
    'daytrips_grid_badge' => 'Choose your day',
    'daytrips_grid_title' => 'One-day trips & excursions',
    'daytrips_grid_intro' => 'Leaving Arusha early and back the same evening or afternoon. Prices per person, two people sharing, including park fees (where applicable), vehicle, guide and lunch.',
    'daytrips_1day' => 'Full Day',
    'daytrips_halfday' => 'Half Day',
    'daytrips_from_pp' => 'from · p.p.',
    'daytrips_ask_price' => 'Ask for price',
    'daytrips_know_badge' => 'Good to know',
    'daytrips_know_title' => 'Planning your day trip',
    'daytrips_pickup_title' => 'Pick-up',
    'daytrips_pickup_desc' => 'We collect you from any hotel in Arusha or Moshi. Departure is usually between 06:00 and 08:00 depending on the destination.',
    'daytrips_bring_title' => 'What to bring',
    'daytrips_bring_desc' => 'Closed shoes, a light jacket for the early morning, sunscreen, a hat and a swimming costume for Chemka or Materuni.',
    'daytrips_combine_title' => 'Combining trips',
    'daytrips_combine_desc' => 'Materuni and Chemka fit comfortably into a single day. So do Lake Duluti and an Arusha city tour. Ask and we will build the day around your flight times.',
    'daytrips_booking_title' => 'Booking',
    'daytrips_booking_desc' => 'Most day trips can be arranged with 24 hours\' notice. Park-based safaris are better booked a few days ahead in high season.',
    'daytrips_final_title' => 'Plan your day trip with us',
    'daytrips_final_intro' => 'Send us your dates, group size and budget. We reply with a written itinerary and a full price breakdown, no obligation.',
    'daytrips_final_whatsapp' => 'Message us on WhatsApp',
    'daytrips_final_contact' => 'Contact form',

    'daytrip_tarangire_title' => 'Tarangire',
    'daytrip_tarangire_desc' => 'Two hours from Arusha. Baobabs and the largest elephant herds in northern Tanzania, especially from July to October.',
    'daytrip_ngorongoro_title' => 'Ngorongoro Crater',
    'daytrip_ngorongoro_desc' => 'A long day, but the densest concentration of wildlife in Africa, and the best chance of black rhino anywhere in the country.',
    'daytrip_manyara_title' => 'Lake Manyara',
    'daytrip_manyara_desc' => 'Flamingos on the soda lake, tree-climbing lions and dense forest at the foot of the Rift Valley escarpment.',
    'daytrip_arushanp_title' => 'Arusha National Park',
    'daytrip_arushanp_desc' => 'Closest to town, with giraffe, colobus monkeys and the Momella lakes. Walking safaris are allowed here, which is rare in Tanzania.',
    'daytrip_materuni_title' => 'Materuni Waterfalls & Coffee',
    'daytrip_materuni_desc' => 'A walk through banana and coffee plantations on the slopes of Kilimanjaro to a 90-metre waterfall, followed by roasting and grinding coffee with a Chagga family.',
    'daytrip_chemka_title' => 'Chemka Hot Springs',
    'daytrip_chemka_desc' => 'A turquoise natural pool in the middle of dry bush, warm all year and shaded by fig roots. The best afternoon swim in the region.',
    'daytrip_maasai_title' => 'Maasai Village',
    'daytrip_maasai_desc' => 'A visit to a working boma with our Maasai guide Elius: the houses, the herding, the dances, and time to ask real questions. Not a staged performance.',
    'daytrip_duluti_title' => 'Lake Duluti',
    'daytrip_duluti_desc' => 'A crater lake twenty minutes from Arusha: canoeing among cormorants and monitor lizards, and a walk around the forested rim.',
    'daytrip_arushacity_title' => 'Arusha City Tour',
    'daytrip_arushacity_desc' => 'The central market, the Tanzanite dealers, the Maasai craft market and the clocktower said to mark the midpoint between Cairo and Cape Town.',
    'daytrip_kiliday_title' => 'Kilimanjaro One-Day Trek',
    'daytrip_kiliday_desc' => 'Up to Mandara hut at 2,700 m through the rainforest and back down the same day: the mountain without the week.',

