    // ===== Tarangire Day Trip (specific) =====
    'daytrip_tarangire_meta_title' => '1-Day Tarangire Safari from Arusha | Serengeti Budget Safari',
    'daytrip_tarangire_meta_description' => 'A full-day safari from Arusha to Tarangire National Park: elephant herds, ancient baobabs and a game drive with pickup, lunch and park fees included.',
    'daytrip_tarangire_type' => 'Day Trip',
    'daytrip_tarangire_budget' => 'Budget',
    'daytrip_tarangire_hero_title' => '1-Day Tarangire Wildlife Safari',
    'daytrip_tarangire_hero_route' => 'Arusha → Tarangire National Park → Arusha',
    'daytrip_tarangire_start_val' => 'Arusha',
    'daytrip_tarangire_route_park' => 'Tarangire National Park',
    'daytrip_tarangire_overview_title' => 'A day of wildlife in Tarangire',
    'daytrip_tarangire_overview_p1' => 'Spend a full day exploring Tarangire National Park, famous for its elephants, giant baobab trees and diverse wildlife. Depart from Arusha in the morning, enjoy a full-day game drive and return to Arusha in the evening.',
    'daytrip_tarangire_love_1' => 'Full-day game drive',
    'daytrip_tarangire_love_2' => 'Great elephant sightings',
    'daytrip_tarangire_love_3' => 'Professional local guide',
    'daytrip_tarangire_love_4' => 'Lunch included',
    'daytrip_tarangire_love_5' => 'Return to Arusha same day',
    'daytrip_tarangire_exp_wildlife_val' => 'Lions, elephants, giraffes, zebras and more',
    'daytrip_tarangire_exp_landscape_val' => 'Baobabs, savannah and spectacular scenery',
    'daytrip_tarangire_tl1_title' => 'Hotel pickup, Arusha',
    'daytrip_tarangire_tl1_desc' => 'Your driver-guide meets you at your hotel just after sunrise, Land Cruiser loaded and ready. By the time most people are ordering breakfast, you are already on the road south.',
    'daytrip_tarangire_tl2_title' => 'Into baobab country',
    'daytrip_tarangire_tl2_desc' => 'The park gate marks the start of Tarangire, home to some of the oldest baobab trees in Tanzania and the largest elephant herds outside the Serengeti ecosystem. The morning game drive follows the Tarangire River, where wildlife gathers even in the driest months.',
    'daytrip_tarangire_tl3_title' => 'Picnic lunch in the bush',
    'daytrip_tarangire_tl3_desc' => 'A packed lunch at a scenic spot chosen by your guide, often with a view over the river valley and its resident elephant families.',
    'daytrip_tarangire_tl4_title' => 'Afternoon game drive',
    'daytrip_tarangire_tl4_desc' => 'The light softens and the bush comes alive again after the midday heat. This is prime time for photography, and for spotting the giraffes, zebras and elephants that Tarangire is known for.',
    'daytrip_tarangire_tl5_title' => 'Last look, then the gate',
    'daytrip_tarangire_tl5_desc' => 'One final pass along the river before exiting through the main gate, the baobabs catching the late sun as you begin the drive back.',
    'daytrip_tarangire_tl6_title' => 'Arrival back in Arusha',
    'daytrip_tarangire_tl6_desc' => 'Drop-off at your hotel in the evening, with a full day of wildlife behind you and, if you\'re continuing on safari, just one night\'s sleep before you\'re back to it.',
    'daytrip_tarangire_wl_elephant' => 'Elephants',
    'daytrip_tarangire_wl_lion' => 'Lions',
    'daytrip_tarangire_wl_giraffe' => 'Giraffes',
    'daytrip_tarangire_wl_zebra' => 'Zebras',
    'daytrip_tarangire_wl_buffalo' => 'Buffalo',
    'daytrip_tarangire_wl_warthog' => 'Warthogs',
    'daytrip_tarangire_faq_q1' => 'Is this a private safari?',
    'daytrip_tarangire_faq_a1' => 'Yes, by default it\'s a private vehicle for your group. A group-joining option is also available at a lower per-person price. Ask us for current dates.',
    'daytrip_tarangire_faq_q2' => 'Can I join as a solo traveler?',
    'daytrip_tarangire_faq_a2' => 'Yes. Solo travellers pay the 1-person rate for a private trip, or can ask us to join an existing group departure to reduce the cost.',
    'daytrip_tarangire_faq_q3' => 'What time do we leave Arusha?',
    'daytrip_tarangire_faq_a3' => 'Pickup is usually 06:30, so we reach the park gate as it opens and get the best morning wildlife activity.',
    'daytrip_tarangire_faq_q4' => 'Is lunch included?',
    'daytrip_tarangire_faq_a4' => 'Yes, a picnic lunch and drinking water are included in the price.',
    'daytrip_tarangire_faq_q5' => 'Can children join?',
    'daytrip_tarangire_faq_a5' => 'Yes, Tarangire is a great first safari for families. The game drive is relaxed and elephant sightings are near-guaranteed in the dry season.',
    'daytrip_final_title' => 'Your Tanzania adventure starts here',
    'daytrip_final_intro' => 'One day. Incredible wildlife. Unforgettable memories.',
    'daytrip_final_whatsapp' => 'Ask on WhatsApp',

    // ===== About Us =====
    'about_meta_title' => 'About Us | Serengeti Budget Safari: Local Tanzania Safari Operator',
    'about_meta_description' => 'Meet the local team behind Serengeti Budget Safari, a Tanzania-based operator built on local knowledge, honest pricing and personal service across the Serengeti, Ngorongoro and beyond.',

    'about_hero_title' => 'We don\'t just plan safaris. We share Tanzania.',
    'about_hero_sub' => 'Authentic journeys. Local knowledge. Unforgettable experiences.',
    'about_hero_cta1' => 'Explore Our Safaris',
    'about_hero_cta2' => 'Talk to Our Team',

    'about_intro_badge' => 'Who We Are',
    'about_intro_title' => 'Your journey starts with people who know Tanzania',
    'about_intro_p1' => 'We are a Tanzania-based safari company dedicated to creating memorable journeys across the country\'s most extraordinary destinations. From the endless plains of the Serengeti to the dramatic Ngorongoro Crater and the beaches of Zanzibar, we combine local knowledge, experienced guides and thoughtful planning to make every journey special.',

    'about_story_badge' => 'Our Story',
    'about_story_title' => 'How it all started',
    'about_story_intro' => 'A short history of where we began and how we got here.',
    'about_story_y1_title' => 'Our journey begins',
