    // ===== Blog article: How Much Does a Safari Cost =====
    'blogcost_meta_title' => 'How Much Does a Tanzania Safari Cost? (2026 Breakdown) | Serengeti Budget Safari',
    'blogcost_meta_description' => 'What a Tanzanian safari really costs in 2026, broken down line by line: park fees, accommodation, vehicle and guide, plus what is never included and how to spend less without ruining the trip.',
    'blogcost_h1' => 'How much does a Tanzania safari cost?',
    'blogcost_hero_sub' => 'The real numbers, itemised: park fees, beds, vehicle and the extras nobody mentions until the invoice arrives.',
    'blogcost_updated' => 'Updated 2026',
    'blogcost_author' => 'Serengeti Budget Safari Team',
    'blogcost_date' => 'August 2026',
    'blogcost_quick_badge' => 'Quick answers',
    'blogcost_quick_title' => 'Safari costs in short',
    'blogcost_quick_intro' => 'The headline numbers before the detail.',
    'blogcost_qq1_q' => 'Budget safari?',
    'blogcost_qq1_a' => 'From about $200 per person per day.',
    'blogcost_qq2_q' => 'Luxury safari?',
    'blogcost_qq2_a' => 'From about $600 per person per day.',
    'blogcost_qq3_q' => 'Biggest fixed cost?',
    'blogcost_qq3_a' => 'Park fees: $82.60/day in the Serengeti.',
    'blogcost_qq4_q' => 'Cheapest way to save?',
    'blogcost_qq4_a' => 'Be four rather than two: the vehicle cost divides.',
    'blogcost_qq5_q' => 'What is not included?',
    'blogcost_qq5_a' => 'Flights, visa, insurance, tips and drinks.',
    'blogcost_qq6_q' => 'Very cheap quote?',
    'blogcost_qq6_a' => 'Ask for it itemised. Park fees are fixed for everyone.',
    'blogcost_see_faq' => 'See all FAQs',
    'blogcost_toc_title' => 'Contents',
    'blogcost_toc_1' => 'The short answer',
    'blogcost_toc_2' => 'Park fees',
    'blogcost_toc_3' => 'Accommodation',
    'blogcost_toc_4' => 'Vehicle & guide',
    'blogcost_toc_5' => 'What is not included',
    'blogcost_toc_6' => 'How to spend less',
    'blogcost_toc_7' => 'Real itinerary costs',
    'blogcost_toc_8' => 'FAQ',
    'blogcost_s1_badge' => 'In brief',
    'blogcost_s1_title' => 'The short answer',
    'blogcost_s1_p1' => 'A Tanzanian safari costs roughly <strong>$200 to $600 per person per day</strong>, all inclusive. The spread is wide because three things move the number more than anything else: <strong>which parks you visit</strong>, <strong>where you sleep</strong> and <strong>how many people share the vehicle</strong>.',
    'blogcost_t1_h1' => 'Level',
    'blogcost_t1_h2' => 'Per person / day',
    'blogcost_t1_h3' => 'What you get',
    'blogcost_t1_r1_a' => 'Budget / camping',
    'blogcost_t1_r1_c' => 'Camping or simple lodges outside the parks, shared vehicle',
    'blogcost_t1_r2_a' => 'Mid-range',
    'blogcost_t1_r2_c' => 'Comfortable lodges, private vehicle',
    'blogcost_t1_r3_a' => 'Fly-in',
    'blogcost_t1_r3_c' => 'Light aircraft instead of long transfers',
    'blogcost_t1_r4_a' => 'Luxury',
    'blogcost_t1_r4_c' => 'Camps inside the parks, private guide, full service',
    'blogcost_s1_p2' => 'Below, we break that down into the actual line items so you can see where the money goes, and where you can realistically save.',
    'blogcost_cta_label' => 'Related Safari',
    'blogcost_cta_title' => '5-Day Serengeti & Ngorongoro Safari',
    'blogcost_cta_price' => 'From $650 per person',
    'blogcost_s2_badge' => 'Park fees',
    'blogcost_s2_title' => '1. Park fees: the biggest fixed cost',
    'blogcost_s2_p1' => 'Park fees are set by the government and are <strong>identical for every operator</strong>. Nobody can discount them, and on a Serengeti itinerary they often account for a third of the total price.',
    'blogcost_t2_h1' => 'Park',
    'blogcost_t2_h2' => 'Adult / 24h',
    'blogcost_t2_h3' => 'Concession / night',
    'blogcost_per_vehicle' => 'per vehicle',
    'blogcost_s2_example_title' => 'A worked example',
    'blogcost_s2_example_intro' => 'Two people, four days, Tarangire + Serengeti (2 nights) + Ngorongoro, sleeping outside the parks:',
    'blogcost_t3_h1' => 'Item',
    'blogcost_t3_h2' => 'Calculation',
    'blogcost_t3_h3' => 'Total',
    'blogcost_t3_r1_a' => 'Tarangire entry',
    'blogcost_t3_r2_a' => 'Serengeti entry',
    'blogcost_t3_r3_a' => 'Ngorongoro entry',
    'blogcost_t3_r4_a' => 'Crater descent',
    'blogcost_t3_r5_a' => 'Park fees alone',
    'blogcost_s2_p2' => 'That is before a single night\'s accommodation, litre of fuel or day of a guide\'s wages.',
    'blogcost_s3_badge' => 'Accommodation',
    'blogcost_s3_title' => '2. Accommodation: the biggest variable',
    'blogcost_s3_p1' => 'This is the line that decides whether your safari is "budget" or "luxury". The wildlife is identical either way.',
    'blogcost_t4_h1' => 'Type',
    'blogcost_t4_h2' => 'Per person / night',
    'blogcost_t4_r1_a' => 'Public campsite (inside park)',
    'blogcost_plus_camping' => 'park fee + camping costs',
    'blogcost_t4_r2_a' => 'Lodge outside the park',
    'blogcost_t4_r3_a' => 'Lodge inside the park',
    'blogcost_plus_concession' => '+ concession fee',
    'blogcost_t4_r4_a' => 'Tented camp inside the park',
    'blogcost_t4_r5_a' => 'Mobile migration camp',
    'blogcost_t4_r6_a' => 'Ultra-luxury',
    'blogcost_s3_p2' => 'Note the concession fee: sleeping <em>inside</em> a park adds $47–59 per adult per night on top of the room rate. It buys you dawn and dusk inside the ecosystem, which is when predators are active. Genuinely worth it on a short trip, less so on a long one.',
    'blogcost_s3_link' => 'Talk to us about accommodation options',
    'blogcost_s4_badge' => 'Vehicle',
    'blogcost_s4_title' => '3. Vehicle and guide: why group size matters so much',
    'blogcost_s4_p1' => 'A Land Cruiser with a driver-guide costs the same whether there are two of you or six. Fuel, the vehicle, the guide\'s wages and the crater descent fee are all <strong>per vehicle</strong>, not per person.',
    'blogcost_s4_p2' => 'This is the single most effective way to reduce the per-person price, and most travellers do not realise it.',
    'blogcost_t5_h1' => 'Group size',
    'blogcost_t5_h2' => 'Vehicle cost share',
    'blogcost_t5_h3' => 'Effect on per-person price',
    'blogcost_people' => 'people',
    'blogcost_each' => 'each',
    'blogcost_t5_r1_c' => 'Baseline',
    'blogcost_t5_r2_c' => 'Noticeably cheaper per head',
    'blogcost_t5_r3_c' => 'Substantially cheaper per head',
    'blogcost_s4_p3' => 'If you are two people on a tight budget, joining a <strong>shared group departure</strong> achieves the same saving. You give up some flexibility over timing and stops.',
    'blogcost_s5_badge' => 'Extras',
    'blogcost_s5_title' => '4. What is never included',
    'blogcost_s5_i1_t' => 'International flights',
    'blogcost_s5_i1_d' => 'the largest single cost for most travellers',
    'blogcost_s5_i2_t' => 'Tanzanian visa',
    'blogcost_s5_i2_d' => '$50 for most nationalities',
    'blogcost_s5_i3_t' => 'Travel insurance',
    'blogcost_s5_i3_d' => 'compulsory on our trips, and it must cover evacuation',
    'blogcost_s5_i4_t' => 'Tips',
    'blogcost_s5_i4_d' => 'roughly $20–25 per day for the guide from the group, plus camp staff',
    'blogcost_s5_i5' => 'Drinks other than water, and personal spending',
    'blogcost_s5_i6_t' => 'Optional extras',
    'blogcost_s5_i6_d' => 'balloon flight (~$599), night drives, cultural visits',
    'blogcost_s5_p1' => 'Budget an extra <strong>$300–500 per person</strong> for visa, tips and incidentals on a week-long trip, on top of the safari price.',
    'blogcost_s6_badge' => 'Saving money',
    'blogcost_s6_title' => 'How to spend less without ruining the trip',
    'blogcost_s6_sub1' => 'Things that save real money',
    'blogcost_s6_save1_t' => 'Travel in low season.',
    'blogcost_s6_save1_d' => 'April, May and November are substantially cheaper, and the wildlife is still there.',
    'blogcost_s6_save2_t' => 'Be four rather than two.',
    'blogcost_s6_save2_d' => 'The vehicle cost divides.',
    'blogcost_s6_save3_t' => 'Sleep outside the parks.',
    'blogcost_s6_save3_d' => 'Saves the concession fee and the room rate; costs you an hour of driving each morning.',
    'blogcost_s6_save4_t' => 'Choose cheaper parks.',
    'blogcost_s6_save4_d' => 'Tarangire and Manyara are $59.00 against the Serengeti\'s $82.60, and are two hours from Arusha rather than eight.',
    'blogcost_s6_save5_t' => 'Camp.',
    'blogcost_s6_save5_d' => 'Same guide, same vehicle, same animals. You save on the bed.',
    'blogcost_s6_save6_t' => 'Shorten the Serengeti, not the trip.',
    'blogcost_s6_save6_d' => 'Two Serengeti nights plus two Tarangire nights costs far less than four Serengeti nights.',
    'blogcost_s6_sub2' => 'Things that are false economies',
    'blogcost_s6_false1_t' => 'Cutting the trip to two days including the Serengeti.',
    'blogcost_s6_false1_d' => 'You pay full park fees to spend most of your time driving.',
    'blogcost_s6_false2_t' => 'Booking the cheapest quote you can find.',
    'blogcost_s6_false2_d' => 'Park fees are fixed, so a price far below the market is being funded by something, usually the crew, the food or the vehicle.',
    'blogcost_s6_false3_t' => 'Skipping travel insurance.',
    'blogcost_s6_false3_d' => 'Medical evacuation from the Serengeti costs many thousands of dollars.',
    'blogcost_s6_warn_t' => 'A word on suspiciously cheap quotes:',
    'blogcost_s6_warn_d' => 'the park fees on this page are public and identical for everyone. If a four-day Serengeti quote is barely above the fee total, ask the operator to itemise it. A reputable company will do so without hesitation.',
    'blogcost_s7_badge' => 'Examples',
    'blogcost_s7_title' => 'What real itineraries cost',
    'blogcost_s7_intro' => 'Guide prices per person, two people sharing, including park fees, vehicle, guide, accommodation and meals. Your written quote itemises every line.',
    'blogcost_t6_h1' => 'Itinerary',
    'blogcost_days_tarangire_ngoro' => 'days: Tarangire & Ngorongoro',
    'blogcost_days_serengeti_ngoro' => 'days: Serengeti & Ngorongoro',
    'blogcost_days_bigfive' => 'days: Big Five circuit',
    'blogcost_days_migration' => 'days: Migration safari',
    'blogcost_days_zanzibar' => 'days: Safari + Zanzibar',
    'blogcost_s7_note' => 'Indicative only. Prices vary with season, group size and availability.',
    'blogcost_faq_badge' => 'FAQ',
    'blogcost_faq_title' => 'Safari costs: frequently asked questions',
    'blogcost_faq_q1' => 'How much does a Tanzanian safari cost per day?',
    'blogcost_faq_a1' => 'Roughly $200–250 per person per day for budget camping, $250–350 mid-range, $400+ for fly-in and $600+ for luxury. Park fees alone account for a large share of that, and they are identical for every operator.',
    'blogcost_faq_q2' => 'What is included in a safari price?',
    'blogcost_faq_a2' => 'Normally: 4x4 vehicle with driver-guide, fuel, all park entrance fees in the itinerary, accommodation and meals as described, and drinking water. Not included: international flights, visa, insurance, drinks, tips and optional extras.',
    'blogcost_faq_q3' => 'How can I make a safari cheaper?',
    'blogcost_faq_a3' => 'Travel in low season, be four people rather than two so the vehicle cost divides, sleep outside the parks, choose Tarangire and Manyara over the Serengeti, and consider camping.',
    'blogcost_faq_q4' => 'Does group size really change the price?',
    'blogcost_faq_a4' => 'Substantially. The vehicle, guide, fuel and crater descent fee are all charged per vehicle, not per person. Four people sharing pay noticeably less each than two, and six pay less again.',
    'blogcost_faq_q5' => 'Should I be suspicious of very cheap quotes?',
    'blogcost_faq_a5' => 'Yes. Park fees are public and fixed for everyone, so a price barely above the fee total is being funded elsewhere. Ask any operator to itemise their quote.',
    'blogcost_faq_q6' => 'How much should I budget for tips?',
    'blogcost_faq_a6' => 'Around $20–25 per day for the driver-guide, from the group as a whole, plus $10–15 per day for camp staff. On a week-long trip for two people, budget roughly $200–300 in total.',
    'blogcost_faq_q7' => 'How much is the Tanzanian visa?',
    'blogcost_faq_a7' => 'US$50 for most nationalities, obtained online at visa.immigration.go.tz before travelling, or on arrival. Beware of unofficial sites charging additional fees for the same thing.',
    'blogcost_faq_q8' => 'Can I pay in instalments?',
    'blogcost_faq_a8' => 'Our standard terms are a 30% deposit to confirm and the balance 30 days before arrival. If you are booking a long way ahead we can usually be flexible about the timing, just ask.',
    'blogcost_related_badge' => 'Keep reading',
    'blogcost_related_title' => 'Continue exploring Tanzania',
    'blogcost_related_itineraries' => 'Our safari itineraries',
    'blogcost_final_title' => 'Want a real number for your trip?',
    'blogcost_final_intro' => 'Send us your dates and group size and we will send back an itemised quote: park fees, beds, vehicle and guide listed separately, so you can see exactly where the money goes.',
    'blogcost_final_whatsapp' => 'Message us on WhatsApp',
    'blogcost_final_contact' => 'Contact form',

    // ===== Blog article: The Great Migration Month by Month =====
    'blogmig_meta_title' => 'The Great Migration Month by Month (2026 Guide) | Serengeti Budget Safari',
    'blogmig_meta_description' => 'Where the Great Migration herds are in every month of the year, when the calving season and Mara River crossings happen, where to stay for each phase, and an honest account of what can and cannot be guaranteed.',
    'blogmig_h1' => 'The Great Migration, month by month',
    'blogmig_hero_sub' => 'Where the herds are in every month, when the calving and the river crossings happen, and what no operator can honestly promise you.',
    'blogmig_updated' => 'Updated 2026',
    'blogmig_quick_badge' => 'Quick answers',
    'blogmig_quick_title' => 'The migration in short',
    'blogmig_quick_intro' => 'The six questions we are asked most often.',
    'blogmig_qq1_q' => 'When is it?',
    'blogmig_qq1_a' => 'All year. It never stops, only the location changes.',
    'blogmig_qq2_q' => 'Calving season?',
    'blogmig_qq2_a' => 'Late January to February, in Ndutu.',
    'blogmig_qq3_q' => 'River crossings?',
    'blogmig_qq3_a' => 'July to October at the Mara, in the north.',
    'blogmig_qq4_q' => 'Where do I stay?',
    'blogmig_qq4_a' => 'Ndutu Dec–Mar, Kogatende Jul–Oct. It matters enormously.',
    'blogmig_qq5_q' => 'How many nights?',
    'blogmig_qq5_a' => 'Three minimum in the migration area.',
    'blogmig_qq6_q' => 'Guaranteed crossing?',
    'blogmig_qq6_a' => 'No. Anyone promising one is overselling.',
    'blogmig_toc_title' => 'Contents',
    'blogmig_toc_1' => 'What it actually is',
    'blogmig_toc_2' => 'Month by month',
    'blogmig_toc_3' => 'The calving season',
    'blogmig_toc_4' => 'The river crossings',
    'blogmig_toc_5' => 'Where to stay by month',
    'blogmig_toc_6' => 'How to plan it',
    'blogmig_toc_7' => 'Five common myths',
    'blogmig_toc_8' => 'FAQ',
    'blogmig_s1_badge' => 'The basics',
    'blogmig_s1_title' => 'What the Great Migration actually is',
    'blogmig_s1_p1' => 'The Great Migration is the year-round movement of roughly <strong>1.3 million wildebeest</strong>, <strong>250,000 zebra</strong> and several hundred thousand Thomson\'s and Grant\'s gazelle around the Serengeti–Masai Mara ecosystem. It is the largest overland movement of animals left on earth.',
    'blogmig_s1_p2' => 'The single most useful thing to understand is this: <strong>it is not an event with a date.</strong> The herds are somewhere in the ecosystem in every month of the year, moving in a roughly circular route driven by rainfall and the growth of new grass. There is no start and no finish. What changes month by month is <em>where</em> they are, and therefore where you need to be.',
    'blogmig_s1_p3' => 'A second thing worth knowing: the wildebeest do not travel as one enormous herd. They move in long columns and scattered groups spread over tens of kilometres, sometimes converging into the dense masses that appear in documentaries, sometimes dispersed across open plain. Both are the migration.',
    'blogmig_fact_wildebeest' => 'Wildebeest',
    'blogmig_fact_zebra' => 'Zebra',
    'blogmig_fact_gazelle' => 'Gazelle',
    'blogmig_fact_distance' => 'Annual distance',
    'blogmig_fact_calves' => 'Calves born',
    'blogmig_fact_year' => 'year',
    'blogmig_fact_ecosystem' => 'Ecosystem',
    'blogmig_s2_badge' => 'The calendar',
    'blogmig_s2_title' => 'Month by month: where the herds are',
    'blogmig_s2_intro' => 'The pattern below repeats every year, but rainfall shifts it by two or three weeks in either direction. Treat it as a strong probability, never a timetable.',
    'blogmig_t1_h1' => 'Month',
    'blogmig_t1_h2' => 'Where the herds are',
    'blogmig_t1_h3' => 'What is happening',
    'blogmig_t1_h4' => 'Stay at',
    'blogmig_m1_name' => 'January', 'blogmig_m1_where' => 'Southern plains & Ndutu', 'blogmig_m1_what' => 'Herds settle on the short-grass plains. Calving begins late in the month.', 'blogmig_m1_stay' => 'Ndutu',
    'blogmig_m2_name' => 'February', 'blogmig_m2_where' => 'Ndutu & southern Serengeti', 'blogmig_m2_what' => '<strong>Peak calving.</strong> Up to 8,000 births a day in a three-week window. Predator activity at its highest of the year.', 'blogmig_m2_stay' => 'Ndutu',
    'blogmig_m3_name' => 'March', 'blogmig_m3_where' => 'Southern plains, starting to move', 'blogmig_m3_what' => 'Calves strengthening. Long rains begin; the herds start drifting north-west.', 'blogmig_m3_stay' => 'Ndutu / Seronera',
    'blogmig_m4_name' => 'April', 'blogmig_m4_where' => 'Central & western Serengeti', 'blogmig_m4_what' => 'Long rains. Columns form and move. Green, dramatic, almost empty of tourists.', 'blogmig_m4_stay' => 'Seronera / Moru',
    'blogmig_m5_name' => 'May', 'blogmig_m5_where' => 'Western Corridor', 'blogmig_m5_what' => 'Rut: males fighting for mating rights. Long columns heading west.', 'blogmig_m5_stay' => 'Western Corridor',
    'blogmig_m6_name' => 'June', 'blogmig_m6_where' => 'Western Corridor & Grumeti River', 'blogmig_m6_what' => '<strong>Grumeti crossings.</strong> Smaller than the Mara but with enormous crocodiles and very few vehicles.', 'blogmig_m6_stay' => 'Western Corridor / Grumeti',
    'blogmig_m7_name' => 'July', 'blogmig_m7_where' => 'Northern Serengeti', 'blogmig_m7_what' => 'Herds reach the Mara River. First crossings, often tentative.', 'blogmig_m7_stay' => 'Kogatende',
    'blogmig_m8_name' => 'August', 'blogmig_m8_where' => 'Northern Serengeti & Masai Mara', 'blogmig_m8_what' => '<strong>Peak Mara River crossings.</strong> The most frequent and dramatic of the year.', 'blogmig_m8_stay' => 'Kogatende',
    'blogmig_m9_name' => 'September', 'blogmig_m9_where' => 'Northern Serengeti & Mara', 'blogmig_m9_what' => 'Crossings continue in both directions as herds move back and forth across the river.', 'blogmig_m9_stay' => 'Kogatende',
    'blogmig_m10_name' => 'October', 'blogmig_m10_where' => 'Northern Serengeti, drifting south', 'blogmig_m10_what' => 'Last crossings. Herds begin the return journey down the eastern Serengeti.', 'blogmig_m10_stay' => 'Kogatende / Lobo',
    'blogmig_m11_name' => 'November', 'blogmig_m11_where' => 'Eastern & central Serengeti', 'blogmig_m11_what' => 'Short rains pull the herds south. Long columns through Lobo and Seronera.', 'blogmig_m11_stay' => 'Lobo / Seronera',
    'blogmig_m12_name' => 'December', 'blogmig_m12_where' => 'Southern plains', 'blogmig_m12_what' => 'Arrival on the short-grass plains. The circuit begins again.', 'blogmig_m12_stay' => 'Ndutu / Seronera',
    'blogmig_s3_badge' => 'Calving',
    'blogmig_s3_title' => 'The calving season: the part most people miss',
    'blogmig_s3_p1' => 'Between late January and February, around <strong>400,000 wildebeest calves</strong> are born on the short-grass plains around <strong>Ndutu</strong>, with a peak of up to <strong>8,000 births in a single day</strong>. Roughly 80% of the females give birth within the same three-week window.',
    'blogmig_s3_sub1' => 'Why they all give birth at once',
    'blogmig_s3_p2' => 'It is a survival strategy called predator swamping. By flooding the plains with newborns in a concentrated burst, the herd guarantees that predators cannot possibly take them all. The lions, hyenas and cheetahs are simply overwhelmed. A calf born outside that window is far more likely to be killed.',
    'blogmig_s3_sub2' => 'Why Ndutu specifically',
    'blogmig_s3_p3' => 'The southern plains sit on volcanic ash blown from the Ngorongoro highlands, which created a hardpan close to the surface. Trees cannot root through it, so the plains stay open (good visibility against predators), and the short grass that grows there is unusually rich in calcium and phosphorus. It is exactly what a nursing mother needs to build bone in a calf.',
    'blogmig_s3_sub3' => 'What you actually see',
    'blogmig_s3_p4' => 'Newborns standing within minutes of birth and running within the hour. Nursery groups of hundreds of calves. And, inevitably, predation: this is the month when lion, cheetah and hyena hunt most successfully, and you will see kills. Some travellers find that difficult, so it is worth knowing in advance.',
    'blogmig_s3_note_t' => 'An honest opinion from our guides:',
    'blogmig_s3_note_d' => 'most people come in August for the river crossings. If you ask the guides which season they would choose for themselves, a clear majority say February in Ndutu. The wildlife activity is more constant, more varied, and there are far fewer vehicles.',
    'blogmig_s4_badge' => 'Crossings',
    'blogmig_s4_title' => 'The river crossings, and the truth about them',
    'blogmig_s4_p1' => 'The image everyone has of the migration, thousands of wildebeest plunging into a river while crocodiles wait, is real, and it happens at the <strong>Mara River</strong> in the northern Serengeti between July and October, and at the <strong>Grumeti River</strong> in the west around June.',
    'blogmig_s4_sub1' => 'What actually happens',
    'blogmig_s4_p2' => 'Herds gather on the bank, often in their thousands. They wait. Sometimes for twenty minutes, sometimes for six hours, sometimes all day. Then one animal commits and the rest follow in a few frantic minutes, or the whole herd turns around and walks away without crossing at all.',
    'blogmig_s4_p3' => 'Nobody controls this and nobody can predict it. Herds have been known to cross, graze on the far bank for an hour, and cross straight back.',
    'blogmig_s4_sub2' => 'The honest odds',
    'blogmig_s4_p4' => 'With <strong>three nights at Kogatende between late July and September</strong>, you have a good chance of witnessing at least one crossing. With one night, you are gambling. Any operator who guarantees a crossing on a specific date is either misinformed or selling you something they cannot deliver.',
    'blogmig_s4_note_t' => 'What we tell our clients:',
    'blogmig_s4_note_d' => 'book three nights minimum in the north if a crossing is the reason for your trip, go in August or early September, and accept that the mornings you spend waiting on a bank with nothing happening are part of the experience.',
    'blogmig_s4_sub3' => 'Grumeti vs Mara',
    'blogmig_s4_mara' => 'Mara River',
    'blogmig_s4_grumeti' => 'Grumeti River',
    'blogmig_s4_row_months' => 'Months',
    'blogmig_s4_mara_months' => 'July – October',
    'blogmig_s4_grumeti_months' => 'May – July',
    'blogmig_s4_row_scale' => 'Scale',
    'blogmig_s4_mara_scale' => 'Large, dramatic',
    'blogmig_s4_grumeti_scale' => 'Smaller, more scattered',
    'blogmig_s4_row_croc' => 'Crocodiles',
    'blogmig_s4_mara_croc' => 'Many',
    'blogmig_s4_grumeti_croc' => 'Fewer but enormous',
    'blogmig_s4_row_vehicles' => 'Vehicles',
    'blogmig_s4_mara_vehicles' => 'Many in peak season',
    'blogmig_s4_grumeti_vehicles' => 'Very few',
    'blogmig_s4_row_stay' => 'Where to stay',
    'blogmig_s4_mara_stay' => 'Kogatende',
    'blogmig_s4_grumeti_stay' => 'Western Corridor',
    'blogmig_s5_badge' => 'Accommodation',
    'blogmig_s5_title' => 'Where to stay for each phase',
    'blogmig_s5_p1' => 'This is where most migration trips go wrong. Booking "a lodge in the Serengeti" is not enough: the park is 14,763 km², and a lodge in the centre is a five-hour drive from the herds if they are in the north.',
    'blogmig_t2_h1' => 'If you travel in…',
    'blogmig_t2_h2' => 'Stay in…',
    'blogmig_t2_h3' => 'Why',
    'blogmig_t2_r1_a' => 'December – March', 'blogmig_t2_r1_b' => 'Ndutu', 'blogmig_t2_r1_c' => 'Calving season on the southern plains',
    'blogmig_t2_r2_a' => 'April – May', 'blogmig_t2_r2_b' => 'Seronera / Moru', 'blogmig_t2_r2_c' => 'Herds moving through the centre and west',
    'blogmig_t2_r3_a' => 'May – July', 'blogmig_t2_r3_b' => 'Western Corridor', 'blogmig_t2_r3_c' => 'Grumeti River crossings',
    'blogmig_t2_r4_a' => 'July – October', 'blogmig_t2_r4_b' => 'Kogatende', 'blogmig_t2_r4_c' => 'Mara River crossings in the north',
    'blogmig_t2_r5_a' => 'November', 'blogmig_t2_r5_b' => 'Lobo / Seronera', 'blogmig_t2_r5_c' => 'Return journey through the east',
    'blogmig_s5_sub1' => 'Mobile camps',
    'blogmig_s5_p2' => 'Several operators run mobile tented camps that physically relocate two or three times a year to follow the herds. They are the most reliable way to stay close to the migration, they are usually small and remote, and they cost roughly $300–700 per person per night. If the migration is the entire point of your trip, this is what you want.',
    'blogmig_s5_link' => 'Talk to us about accommodation options',
    'blogmig_s6_badge' => 'Planning',
    'blogmig_s6_title' => 'How to plan a migration safari',
    'blogmig_s6_step1_t' => 'Step 1: decide which phase you want',
    'blogmig_s6_step1_d' => 'Calving in Ndutu, or river crossings in the north. These are the two headline experiences and they happen at opposite ends of both the park and the calendar. You cannot do both in one trip.',
    'blogmig_s6_step2_t' => 'Step 2: book early',
    'blogmig_s6_step2_d' => 'Camps in Kogatende for August and September, and in Ndutu for February, sell out <strong>six to twelve months ahead</strong>. This is not a sales tactic. Those areas have limited beds, and the good small camps go first.',
    'blogmig_s6_step3_t' => 'Step 3: give it enough nights',
    'blogmig_s6_step3_d' => 'Three nights minimum in the migration area. Two is a gamble, one is a lottery ticket.',
    'blogmig_s6_step4_t' => 'Step 4: consider flying',
    'blogmig_s6_step4_d' => 'Kogatende is a two-day drive from Arusha. A 1 hour 15 minute flight converts four days of driving into four more days of game viewing. For a northern-Serengeti trip, flying is almost always the right call.',
    'blogmig_s6_step5_t' => 'Step 5: build in the rest of the ecosystem',
    'blogmig_s6_step5_d' => 'The migration is not the only thing worth seeing. Resident predators, the Ngorongoro Crater and Tarangire\'s elephants are all there regardless of where the herds are, and a good itinerary uses them to fill the days around your migration nights.',
    'blogmig_t3_h1' => 'Trip length',
    'blogmig_t3_h2' => 'Suggested shape',
    'blogmig_days' => 'days',
    'blogmig_t3_r1_b' => 'Fly in to the migration area for 3 nights, Ngorongoro on the way out',
    'blogmig_t3_r2_b' => 'Tarangire, Serengeti central 2 nights, migration area 3 nights, Ngorongoro',
    'blogmig_t3_r3_b' => 'Full northern circuit with 4 nights in the migration area, then Zanzibar',
    'blogmig_s7_badge' => 'Myths',
    'blogmig_s7_title' => 'Five things people get wrong',
    'blogmig_s7_myth1_t' => 'The migration happens in August',
    'blogmig_s7_myth1_d' => 'The <em>Mara River crossings</em> happen around August. The migration itself is continuous. The herds are always somewhere, and there is no month when nothing is happening.',
    'blogmig_s7_myth2_t' => 'I need to go to Kenya to see it',
    'blogmig_s7_myth2_d' => 'Around 80% of the migration\'s annual circuit is inside Tanzania. The herds spend roughly two to three months in the Masai Mara and the rest of the year in the Serengeti ecosystem.',
    'blogmig_s7_myth3_t' => 'A crossing is guaranteed if I go at the right time',
    'blogmig_s7_myth3_d' => 'It is not. Being in the right place in the right month gives you a good chance over several days. It gives nobody a guarantee on any single morning.',
    'blogmig_s7_myth4_t' => 'The migration is one giant herd',
    'blogmig_s7_myth4_d' => 'It is columns and scattered groups spread over tens of kilometres, sometimes converging and sometimes dispersed. The documentary shot of a solid mass is one moment, not the normal state.',
    'blogmig_s7_myth5_t' => 'The rainy season is a bad time',
    'blogmig_s7_myth5_d' => 'April and May are green, dramatic, almost empty of other vehicles and considerably cheaper, and the herds are moving through the centre and west, which is perfectly good viewing. If your priority is value and solitude rather than river crossings, the wet months are underrated.',
    'blogmig_faq_title' => 'The Great Migration: frequently asked questions',
    'blogmig_faq_q1' => 'When is the best time to see the Great Migration?',
    'blogmig_faq_a1' => 'It depends which phase you want. Late January to February for the calving season in Ndutu; July to October for the Mara River crossings in the northern Serengeti. Both are exceptional, and they happen at opposite ends of the park and the calendar.',
    'blogmig_faq_q2' => 'Can I see the migration all year round?',
    'blogmig_faq_a2' => 'Yes. The herds never leave the ecosystem. They move in a continuous circuit. What changes is where they are, so the region you stay in must match your month.',
    'blogmig_faq_q3' => 'Will I definitely see a river crossing?',
    'blogmig_faq_a3' => 'No, and be sceptical of anyone who promises one. Herds can wait on the bank for a full day and then walk away. Three nights at Kogatende between late July and September gives you a good chance, not a guarantee.',
    'blogmig_faq_q4' => 'Should I go to Tanzania or Kenya for the migration?',
    'blogmig_faq_a4' => 'Around 80% of the annual circuit is in Tanzania. The herds spend only two to three months in the Masai Mara. Tanzania also gives you the calving season, which Kenya does not.',
    'blogmig_faq_q5' => 'Where do I need to stay for the calving season?',
    'blogmig_faq_a5' => 'Ndutu, on the southern short-grass plains, between December and March. Note that Ndutu is technically inside the Ngorongoro Conservation Area rather than the Serengeti, though ecologically it is the same plain.',
    'blogmig_faq_q6' => 'How many days do I need for a migration safari?',
    'blogmig_faq_a6' => 'Three nights minimum in the migration area itself, plus travel days. Two nights is a gamble and one is a lottery ticket. Five to seven days total makes a comfortable trip.',
    'blogmig_faq_q7' => 'How many wildebeest are there?',
    'blogmig_faq_a7' => 'Around 1.3 million wildebeest, plus roughly 250,000 zebra and several hundred thousand gazelle. It is the largest overland movement of animals remaining on earth.',
    'blogmig_faq_q8' => 'What is a mobile camp?',
    'blogmig_faq_a8' => 'A tented camp that physically relocates two or three times a year to follow the herds. It is the most reliable way to stay close to the migration, typically $300–700 per person per night, and usually small and remote.',
    'blogmig_final_title' => 'Ready to plan your migration safari?',
    'blogmig_final_intro' => 'Tell us your dates and we\'ll tell you honestly whether it\'s calving season, crossing season, or somewhere in between, and build the itinerary around it.',

    // Blog article: Kenya vs Tanzania safari
    'blogkenya_meta_title' => 'Kenya vs Tanzania Safari: An Honest Comparison (2026)',
    'blogkenya_meta_description' => 'Kenya or Tanzania for safari? An honest comparison of the Serengeti and Masai Mara, migration months, park fees, vehicle density, off-road rules and which country suits which kind of trip.',
    'blogkenya_updated' => 'Updated 2026',
    'blogkenya_h1' => 'Kenya vs Tanzania safari',
    'blogkenya_hero_sub' => 'The same ecosystem, split by a border: what each country genuinely does better, written by a Tanzanian operator trying to be fair about it.',
    'blogkenya_author' => 'Serengeti Budget Safari',
    'blogkenya_date' => '2026',
    'blogkenya_quick_badge' => 'Quick answers',
    'blogkenya_quick_title' => 'Kenya or Tanzania, in short',
    'blogkenya_quick_intro' => 'The honest headlines.',
    'blogkenya_qq1_q' => 'Where is the migration?',
    'blogkenya_qq1_a' => '9–10 months in Tanzania, 2–3 in Kenya.',
    'blogkenya_qq2_q' => 'Calving season?',
    'blogkenya_qq2_a' => 'Tanzania only, at Ndutu in Jan–Feb.',
    'blogkenya_qq3_q' => 'Which is cheaper?',
    'blogkenya_qq3_a' => 'Kenya, generally: lower fees, shorter distances.',
    'blogkenya_qq4_q' => 'Fewer vehicles?',
    'blogkenya_qq4_a' => 'Tanzania, especially the southern circuit.',
    'blogkenya_qq5_q' => 'Short trip of 4–5 days?',
    'blogkenya_qq5_a' => 'Kenya, more wildlife per day.',
    'blogkenya_qq6_q' => 'Kilimanjaro?',
    'blogkenya_qq6_a' => 'Entirely in Tanzania.',
    'blogkenya_see_faq' => 'See all FAQs',
    'blogkenya_toc_title' => 'Contents – Kenya vs Tanzania safari',
    'blogkenya_toc_1' => 'The short answer',
    'blogkenya_toc_2' => 'Side by side',
    'blogkenya_toc_3' => 'Who has the migration?',
    'blogkenya_toc_4' => 'How they feel different',
    'blogkenya_toc_5' => 'Which to choose',
    'blogkenya_toc_6' => 'FAQ',
    'blogkenya_s1_badge' => 'In brief',
    'blogkenya_s1_title' => 'The short answer',
    'blogkenya_s1_p1' => 'They share the same ecosystem and the same migration, split by a border. Broadly:',
    'blogkenya_s1_li1_t' => 'Tanzania',
    'blogkenya_s1_li1_d' => 'for scale, variety and the calving season. It also has Kilimanjaro, Zanzibar and the Ngorongoro Crater.',
    'blogkenya_s1_li2_t' => 'Kenya',
    'blogkenya_s1_li2_d' => 'for convenience and lower cost. Sightings come faster in a smaller area, and it is generally cheaper.',
    'blogkenya_s1_p2' => 'Neither is objectively better. What follows is the honest detail, written, we should say plainly, by a Tanzanian operator. We have tried to be fair.',
    'blogkenya_s2_badge' => 'Comparison',
    'blogkenya_s2_title' => 'Side by side',
    'blogkenya_t1_h1' => 'Factor',
    'blogkenya_t1_h2' => 'Tanzania',
    'blogkenya_t1_h3' => 'Kenya',
    'blogkenya_t1_r1_a' => 'Flagship park size',
    'blogkenya_t1_r2_a' => 'Migration months',
    'blogkenya_t1_r2_b' => '~9–10 months a year',
    'blogkenya_t1_r2_c' => '~2–3 months (Jul–Oct)',
    'blogkenya_t1_r3_a' => 'Calving season',
    'blogkenya_t1_r4_a' => 'River crossings',
    'blogkenya_t1_r4_b' => 'Mara &amp; Grumeti',
    'blogkenya_t1_r5_a' => 'Park fees',
    'blogkenya_day' => 'day',
    'blogkenya_t1_r5_c' => 'Generally lower',
    'blogkenya_t1_r6_a' => 'Overall cost',
    'blogkenya_higher' => 'Higher',
    'blogkenya_lower' => 'Lower',
    'blogkenya_t1_r7_a' => 'Vehicle density',
    'blogkenya_t1_r7_b' => 'Lower (bigger areas)',
    'blogkenya_t1_r7_c' => 'Higher in the Mara',
    'blogkenya_t1_r8_a' => 'Off-road driving',
    'blogkenya_prohibited' => 'Prohibited',
    'blogkenya_t1_r8_c' => 'Permitted in conservancies',
    'blogkenya_t1_r9_a' => 'Black rhino',
    'blogkenya_t1_r9_b' => 'Ngorongoro (~60%)',
    'blogkenya_t1_r9_c' => 'Several reliable options',
    'blogkenya_t1_r10_a' => 'Highest mountain',
    'blogkenya_t1_r11_a' => 'Beach',
    'blogkenya_t1_r12_a' => 'Getting around',
    'blogkenya_t1_r12_b' => 'Longer drives',
    'blogkenya_t1_r12_c' => 'Shorter drives',
    'blogkenya_s3_badge' => 'Migration',
    'blogkenya_s3_title' => 'The migration: who has more of it?',
    'blogkenya_s3_p1' => 'This is the question most people are really asking, and the answer is clearer than the marketing on either side suggests.',
    'blogkenya_s3_p2' => 'The herds spend roughly <strong>nine to ten months of the year in Tanzania</strong> and two to three months in Kenya\'s Masai Mara. The famous Mara River crossings happen on the border, and can be watched from either side between July and October.',
    'blogkenya_s3_p3' => '<strong>What Tanzania has that Kenya does not:</strong> the calving season. Around 400,000 wildebeest are born at Ndutu in late January and February, and that happens nowhere else.',
    'blogkenya_s3_p4' => '<strong>What Kenya has that Tanzania does not:</strong> compactness. The Mara is a tenth the size of the Serengeti, so when the herds are there, they are concentrated and easy to reach.',
    'blogkenya_s4_badge' => 'Experience',
    'blogkenya_s4_title' => 'What the experience actually feels like',
    'blogkenya_s4_sub1' => 'Tanzania',
    'blogkenya_s4_p1' => 'Bigger, emptier, and slower. Drives between parks are long (Arusha to the Serengeti is seven to eight hours), and the landscapes change dramatically as you go. Off-road driving is prohibited, so you stay on tracks and sightings are at a respectful distance. In the less visited parks you can spend a morning without seeing another vehicle.',
    'blogkenya_s4_sub2' => 'Kenya',
    'blogkenya_s4_p2' => 'More compact and faster-paced. Drives are shorter, sightings come more quickly, and in the private conservancies bordering the Mara, off-road driving, night drives and walking are all permitted, which the national parks in Tanzania do not allow. The trade-off is vehicle density: a good sighting in the Mara in August can attract a crowd.',
    'blogkenya_s4_note_t' => 'The honest summary:',
    'blogkenya_s4_note_d' => 'if you want the greatest variety and the sense of enormous space, Tanzania. If you want the most wildlife per day and per dollar in a shorter trip, Kenya. Many experienced travellers eventually do both.',
    'blogkenya_s5_badge' => 'Choosing',
    'blogkenya_s5_title' => 'Which should you choose?',
    'blogkenya_t2_h1' => 'If you…',
    'blogkenya_t2_h2' => 'Choose',
    'blogkenya_t2_r1_a' => 'Want the calving season',
    'blogkenya_t2_r2_a' => 'Want to climb Kilimanjaro',
    'blogkenya_t2_r3_a' => 'Want a beach afterwards',
    'blogkenya_t2_r4_a' => 'Want the Ngorongoro Crater',
    'blogkenya_t2_r5_a' => 'Have 10+ days',
    'blogkenya_t2_r6_a' => 'Have 5 days or fewer',
    'blogkenya_t2_r7_a' => 'Are on a tighter budget',
    'blogkenya_t2_r8_a' => 'Want night drives and off-road',
    'blogkenya_conservancies' => 'conservancies',
    'blogkenya_t2_r9_a' => 'Want river crossings in Jul–Oct',
    'blogkenya_either' => 'Either',
    'blogkenya_t2_r10_a' => 'Want fewest other vehicles',
    'blogkenya_southern_circuit' => '(southern circuit)',
    'blogkenya_s5_sub1' => 'Can I do both?',
    'blogkenya_s5_p1' => 'Yes. The Serengeti and Masai Mara are adjacent, and combined itineraries are common, usually flying between them, since the land border crossing at Isebania is slow. Note that the <strong>East Africa Tourist Visa does not cover Tanzania</strong>: you need separate visas for each country. Budget 10 to 14 days to do both properly.',
    'blogkenya_faq_badge' => 'FAQ',
    'blogkenya_faq_title' => 'Kenya vs Tanzania: frequently asked questions',
    'blogkenya_faq_q1' => 'Is Tanzania or Kenya better for safari?',
    'blogkenya_faq_a1' => 'Neither is objectively better. Tanzania offers greater scale and variety, the calving season, Kilimanjaro, Ngorongoro and Zanzibar. Kenya is more compact, generally cheaper, and better for short trips.',
    'blogkenya_faq_q2' => 'Where is the Great Migration: Tanzania or Kenya?',
    'blogkenya_faq_a2' => 'Both, but the herds spend roughly nine to ten months of the year in Tanzania and only two to three in Kenya\'s Masai Mara. The famous river crossings happen on the border between July and October.',
    'blogkenya_faq_q3' => 'Which is cheaper, Kenya or Tanzania?',
    'blogkenya_faq_a3' => 'Kenya, generally. Tanzanian park fees are higher ($82.60 per day in the Serengeti) and the distances are greater, which means more fuel and more days. Kenya\'s compactness reduces the total trip cost.',
    'blogkenya_faq_q4' => 'Is the Serengeti better than the Masai Mara?',
    'blogkenya_faq_a4' => 'They are the same ecosystem divided by a border. The Serengeti is roughly ten times larger with more varied habitats and lower vehicle density; the Mara is compact so sightings come faster, but with more crowding in peak season.',
    'blogkenya_faq_q5' => 'Can I see the calving season in Kenya?',
    'blogkenya_faq_a5' => 'No. Calving happens on the southern short-grass plains at Ndutu, in Tanzania, in late January and February. It is one of the clearest reasons to choose Tanzania.',
    'blogkenya_faq_q6' => 'Can I visit both countries on one trip?',
    'blogkenya_faq_a6' => 'Yes, and combined itineraries are common, usually flying between the Serengeti and the Mara, since the land border crossing is slow. Budget 10 to 14 days, and note you need separate visas for each country.',
    'blogkenya_faq_q7' => 'Does the East Africa Tourist Visa cover Tanzania?',
    'blogkenya_faq_a7' => 'No. It covers Kenya, Uganda and Rwanda only. Tanzania requires its own visa, currently $50 for most nationalities.',
    'blogkenya_faq_q8' => 'Which country is better for the Big Five?',
    'blogkenya_faq_a8' => 'Both deliver four of the five easily. For black rhino, Kenya has several reliable options including Ol Pejeta and Lake Nakuru, while in Tanzania the Ngorongoro Crater is essentially the only realistic place.',
    'blogkenya_faq_q9' => 'Where are there fewer tourists?',
    'blogkenya_faq_a9' => 'Tanzania, particularly the southern circuit: Ruaha, Nyerere and Mikumi see a tiny fraction of the visitors of either the Serengeti or the Mara. Even Tarangire is quiet by East African standards.',
    'blogkenya_faq_q10' => 'Can I do night drives and off-road driving?',
    'blogkenya_faq_a10' => 'In Kenya\'s private conservancies, yes. In Tanzanian national parks, off-road driving is prohibited and night drives are not permitted except in Lake Manyara, Tarangire and some private concessions.',
    'blogkenya_faq_q11' => 'Which is better for a first safari?',
    'blogkenya_faq_a11' => 'If you have a week or more and want variety, Tanzania. If you have four or five days, Kenya delivers more wildlife per day because the distances are so much shorter.',
    'blogkenya_faq_q12' => 'What about Kilimanjaro: is it in Kenya or Tanzania?',
    'blogkenya_faq_a12' => 'Tanzania, entirely. The famous view of Kilimanjaro rising behind elephants is often photographed from Amboseli in Kenya, but the mountain itself and every climbing route are in Tanzania.',
    'blogkenya_related_badge' => 'Keep reading',
    'blogkenya_related_title' => 'Continue exploring Tanzania',
    'blogkenya_final_title' => 'Still deciding?',
    'blogkenya_final_intro' => 'Tell us your dates and how long you have. If Kenya genuinely suits your trip better than Tanzania, we will say so. We would rather be useful than win a booking you would regret.',
    'blogkenya_final_whatsapp' => 'Message us on WhatsApp',
    'blogkenya_final_contact' => 'Contact form',

    // Blog article: Best time to visit Tanzania
    'blogbest_meta_title' => 'Best Time to Visit Tanzania: Month by Month (2026) | Serengeti Budget Safari',
    'blogbest_meta_description' => 'When to visit Tanzania, month by month: dry season, the two rainy seasons, the calving season and Mara River crossings, temperatures by altitude, and the best months for safari, Kilimanjaro and Zanzibar.',
    'blogbest_h1' => 'Best time to visit Tanzania',
    'blogbest_hero_sub' => 'Month by month: what you see, how many vehicles you share it with, and what you pay. There is no closed season, only trade-offs.',
    'blogbest_updated' => 'Updated 2026',
    'blogbest_author' => 'Serengeti Budget Safari Team',
    'blogbest_date' => 'August 2026',
    'blogbest_quick_badge' => 'Quick answers',
    'blogbest_quick_title' => 'When to go, in short',
    'blogbest_quick_intro' => 'The answer depends on what you want most.',
    'blogbest_qq1_q' => 'Easiest game viewing?',
    'blogbest_qq1_a' => 'June to October, the dry season.',
    'blogbest_qq2_q' => 'Calving season?',
    'blogbest_qq2_a' => 'Late January and February, at Ndutu.',
    'blogbest_qq3_q' => 'River crossings?',
    'blogbest_qq3_a' => 'August and September in the north.',
    'blogbest_qq4_q' => 'Cheapest months?',
    'blogbest_qq4_a' => 'April and May: the long rains.',
    'blogbest_qq5_q' => 'Quietest?',
    'blogbest_qq5_a' => 'April, May and November.',
    'blogbest_qq6_q' => 'Is it cold?',
    'blogbest_qq6_a' => 'At dawn, yes: 5 °C on the Ngorongoro rim.',
    'blogbest_see_faq' => 'See all FAQs',
    'blogbest_toc_title' => 'Contents – Best time to visit Tanzania',
    'blogbest_toc_1' => 'The short answer',
    'blogbest_toc_2' => 'The two rainy seasons',
    'blogbest_toc_3' => 'Month by month',
    'blogbest_toc_4' => 'Best time for what you want',
    'blogbest_toc_5' => 'Temperatures',
    'blogbest_toc_6' => 'FAQ',
    'blogbest_s1_badge' => 'In brief',
    'blogbest_s1_title' => 'The short answer',
    'blogbest_s1_p1' => '<strong>June to October</strong> is the dry season and the easiest time to see wildlife almost everywhere in Tanzania. <strong>Late January and February</strong> bring the calving season in the southern Serengeti, which many guides consider the better spectacle. <strong>March to May</strong> is the long rains: green, quiet and considerably cheaper.',
    'blogbest_s1_p2' => 'There is no closed season. What changes is what you see, how many other vehicles you share it with, and what you pay.',
    'blogbest_t1_h1' => 'Season',
    'blogbest_t1_h2' => 'Months',
    'blogbest_t1_h3' => 'Game viewing',
    'blogbest_t1_h4' => 'Crowds',
    'blogbest_t1_h5' => 'Price',
