    'blogbest_t1_r2_c' => 'Excellent',
    'blogbest_t1_r2_d' => 'Moderate',
    'blogbest_t1_r2_e' => 'High',
    'blogbest_t1_r3_a' => 'Short rains',
    'blogbest_t1_r3_c' => 'Good',
    'blogbest_t1_r3_d' => 'Low',
    'blogbest_t1_r3_e' => 'Mid',
    'blogbest_t1_r4_a' => 'Long rains',
    'blogbest_t1_r4_c' => 'Variable',
    'blogbest_t1_r4_d' => 'Very low',
    'blogbest_t1_r4_e' => 'Lowest',
    'blogbest_s2_badge' => 'Seasons',
    'blogbest_s2_title' => 'Tanzania has two rainy seasons, not one',
    'blogbest_s2_p1' => 'Confusing these is the most common planning mistake, and they are genuinely different.',
    'blogbest_s2_sub1_title' => 'The long rains: March to May',
    'blogbest_s2_sub1_p' => 'Real rain, often for several hours a day, heaviest in April. Some tracks become impassable, black-cotton soil in the Western Corridor turns to glue, and a number of seasonal camps close entirely, particularly in Ruaha and Nyerere. It is also the cheapest time of year by a wide margin, the landscape is spectacular, and you can have parks almost to yourself.',
    'blogbest_s2_sub2_title' => 'The short rains: November to December',
    'blogbest_s2_sub2_p' => 'Brief, heavy showers in the late afternoon, with the rest of the day usually sunny. Nothing closes, nothing floods, the country turns green and prices are still moderate. For many travellers this is the best compromise of the year, and it is badly underrated.',
    'blogbest_s2_note_t' => 'Worth knowing:',
    'blogbest_s2_note_d' => 'rain in Tanzania rarely means a washed-out day. It usually means a heavy hour and then clear air, dramatic light and a landscape that photographs far better than dusty August.',
    'blogbest_s3_badge' => 'The calendar',
