    'blogbest_s4_badge' => 'Choosing',
    'blogbest_s4_title' => 'Best time by what you want',
    'blogbest_t3_h1' => 'If you want…',
    'blogbest_t3_h2' => 'Go in…',
    'blogbest_t3_h3' => 'Why',
    'blogbest_w1_want' => 'Easiest game viewing',
    'blogbest_w1_why' => 'Sparse vegetation, animals concentrated at water',
    'blogbest_w2_want' => 'Mara River crossings',
    'blogbest_w2_why' => 'Peak frequency in the northern Serengeti',
    'blogbest_w3_want' => 'Calving and predators',
    'blogbest_w3_why' => '400,000 births; constant hunting',
    'blogbest_w4_want' => 'Lowest prices',
    'blogbest_w4_why' => 'Long rains; camps discount heavily',
    'blogbest_w5_want' => 'Fewest vehicles',
    'blogbest_w5_why' => 'Parks almost empty',
    'blogbest_w6_want' => 'Birdwatching',
    'blogbest_w6_why' => 'Migrants present, residents in breeding plumage',
    'blogbest_w7_want' => 'Photography',
    'blogbest_w7_why' => 'Green landscapes, dramatic skies, clean air',
    'blogbest_w8_want' => 'Kilimanjaro',
    'blogbest_w8_why' => 'Driest and most stable on the mountain',
    'blogbest_w9_want' => 'Zanzibar',
    'blogbest_w9_why' => 'Dry, calm sea, good visibility for diving',
    'blogbest_w10_want' => 'Southern circuit',
    'blogbest_w10_why' => 'Ruaha and Nyerere largely close Mar–May',
    'blogbest_s5_badge' => 'Climate',
    'blogbest_s5_title' => 'What the weather is actually like',
    'blogbest_s5_p1' => 'Tanzania sits on the equator, but altitude matters far more than latitude. The northern parks are between 1,000 m and 2,400 m, which is why mornings are genuinely cold.',
    'blogbest_t4_h1' => 'Place',
    'blogbest_t4_h2' => 'Altitude',
    'blogbest_t4_h3' => 'Daytime',
    'blogbest_t4_h4' => 'Dawn',
    'blogbest_c1_place' => 'Ngorongoro rim',
    'blogbest_c2_place' => 'Serengeti',
    'blogbest_c3_place' => 'Arusha',
    'blogbest_c4_place' => 'Tarangire',
    'blogbest_c5_place' => 'Zanzibar',
    'blogbest_c6_place' => 'Kilimanjaro summit',
    'blogbest_sea_level' => 'Sea level',
    'blogbest_colder' => 'Colder',
    'blogbest_s5_p2' => 'The figure that surprises people is the Ngorongoro rim at dawn: around 5 °C, in an open vehicle, moving. Every visitor who packed only for "Africa" regrets it. Layers are not optional.',
    'blogbest_faq_badge' => 'FAQ',
    'blogbest_faq_title' => 'When to visit Tanzania: frequently asked questions',
    'blogbest_faq_q1' => 'When is the best time to visit Tanzania?',
    'blogbest_faq_a1' => 'June to October for the easiest game viewing everywhere, and late January to February for the calving season in the Serengeti. March to May is the long rains: green, quiet and by far the cheapest.',
    'blogbest_faq_q2' => 'What is the worst time to visit Tanzania?',
    'blogbest_faq_a2' => 'April is the wettest month and the one most people avoid. Tracks become difficult, some southern camps close entirely, and views are often obscured. It is also the cheapest month and the parks are nearly empty, so it suits some travellers very well.',
    'blogbest_faq_q3' => 'Can I go on safari in the rainy season?',
    'blogbest_faq_a3' => 'Yes. The northern parks operate year-round and rain usually comes in heavy bursts rather than all day. Ruaha and Nyerere in the south are different. Most camps there close between March and May.',
    'blogbest_faq_q4' => 'When are the Mara River crossings?',
    'blogbest_faq_a4' => 'July to October in the northern Serengeti, with August and September the peak months for frequency. Being there in the right month gives you a good chance over several days, never a guarantee on a given morning.',
    'blogbest_faq_q5' => 'When is the calving season?',
    'blogbest_faq_a5' => 'Late January and February, on the short-grass plains around Ndutu. Around 400,000 calves are born in a three-week window, and predator activity is at its highest of the year.',
    'blogbest_faq_q6' => 'Is it cold in Tanzania?',
    'blogbest_faq_a6' => 'At altitude, yes, and this surprises most visitors. The Ngorongoro rim drops to around 5 °C before dawn, and the Serengeti to 13–15 °C. Daytime is warm, so layers rather than one heavy coat is the answer.',
    'blogbest_faq_q7' => 'When is the cheapest time to go on safari?',
    'blogbest_faq_a7' => 'April and May, during the long rains, when camps discount heavily and parks are almost empty. November is the next cheapest and considerably drier: short afternoon showers rather than all-day rain.',
    'blogbest_faq_q8' => 'When is the best time to climb Kilimanjaro?',
    'blogbest_faq_a8' => 'January to early March and June to October. January and February have the warmest summit nights; June to October is driest and busiest. April and May are the long rains and best avoided on the mountain.',
    'blogbest_faq_q9' => 'When is the best time for Zanzibar?',
    'blogbest_faq_a9' => 'June to October is dry and less humid; December to February is hot with calm seas and excellent diving visibility. March to May is the long rains, when some hotels close.',
    'blogbest_faq_q10' => 'How busy is August?',
    'blogbest_faq_a10' => 'It is the peak month. Camps in the northern Serengeti sell out six to twelve months ahead, prices are at their highest, and you will share sightings. The wildlife is superb. You are simply not alone with it.',
    'blogbest_faq_q11' => 'Is November a good month?',
    'blogbest_faq_a11' => 'It is one of the most underrated. The short rains bring brief afternoon showers, the landscape turns green, migrants arrive for birders, prices are moderate and the parks are quiet. Nothing closes.',
    'blogbest_faq_q12' => 'Does the migration stop in the rainy season?',
    'blogbest_faq_a12' => 'No. The herds are in the ecosystem every month of the year. The rains are precisely what drives them. In April and May they are moving through the central and western Serengeti.',
    'blogbest_faq_q13' => 'What about Christmas and New Year?',
    'blogbest_faq_a13' => 'Busy and expensive. Many camps charge a peak-season supplement from around 20 December to 3 January and require minimum stays. Game viewing is good, but you pay for the dates.',
    'blogbest_faq_q14' => 'Can I combine safari and Zanzibar at any time of year?',
    'blogbest_faq_a14' => 'The seasons align well: June to October and December to February are good for both. In March to May you would be combining a wet safari with a wet coast, which is why that period is the cheapest.',
    'blogbest_related_badge' => 'Keep reading',
    'blogbest_related_title' => 'Continue exploring Tanzania',
    'blogbest_related_kili' => 'Kilimanjaro guide',
    'blogbest_final_title' => 'Tell us your dates',
    'blogbest_final_intro' => 'Send us the weeks you can travel and we will tell you honestly what you will see then, where the herds should be, and whether shifting by a fortnight would be worth it.',
    'blogbest_final_whatsapp' => 'Message us on WhatsApp',
    'blogbest_final_contact' => 'Contact form',

    // ===== Blog article: Tipping on Safari and Kilimanjaro =====
    'blogtip_meta_title' => 'Tipping on Safari and Kilimanjaro: How Much? (2026) | Serengeti Budget Safari',
    'blogtip_meta_description' => 'How much to tip in Tanzania: guideline amounts for safari guides, camp staff and cooks, plus the much larger Kilimanjaro crew tipping figures, with worked examples and practical advice on cash.',
    'blogtip_h1' => 'Tipping on safari and Kilimanjaro',
    'blogtip_hero_sub' => 'What is customary, what it adds up to, and why the Kilimanjaro figure surprises people, told before you book rather than on the mountain.',
    'blogtip_updated' => 'Updated 2026',
    'blogtip_author' => 'Serengeti Budget Safari Team',
    'blogtip_date' => 'August 2026',
    'blogtip_quick_badge' => 'Quick answers',
    'blogtip_quick_title' => 'Tipping in short',
    'blogtip_quick_intro' => 'Guideline amounts, from the group as a whole.',
    'blogtip_qq1_q' => 'Safari guide?',
    'blogtip_qq1_a' => '$20–25 per day, from the group.',
    'blogtip_qq2_q' => 'Camp staff?',
    'blogtip_qq2_a' => '$10–15 per day into the communal box.',
    'blogtip_qq3_q' => 'Kilimanjaro total?',
    'blogtip_qq3_a' => '$400–500 per climber on a 7-day route.',
    'blogtip_qq4_q' => 'Cash or card?',
    'blogtip_qq4_a' => 'Cash only. No ATMs in the parks.',
    'blogtip_qq5_q' => 'When?',
    'blogtip_qq5_a' => 'At the end, not daily.',
    'blogtip_qq6_q' => 'Note condition?',
    'blogtip_qq6_a' => 'US notes must be issued after 2009.',
    'blogtip_see_faq' => 'See all FAQs',
    'blogtip_toc_title' => 'Contents – Tipping on safari and Kilimanjaro',
    'blogtip_toc_1' => 'Why it matters',
    'blogtip_toc_2' => 'Safari tipping',
    'blogtip_toc_3' => 'Kilimanjaro tipping',
    'blogtip_toc_4' => 'Practical points',
    'blogtip_toc_5' => 'FAQ',
    'blogtip_s1_badge' => 'Context',
    'blogtip_s1_title' => 'Why tipping matters here',
    'blogtip_s1_p1' => 'Tipping in Tanzania is customary and forms a meaningful part of what guides, cooks, porters and camp staff earn. It is genuinely discretionary (nobody will pursue you for it), but it is expected, and it is budgeted for by the people receiving it.',
    'blogtip_s1_p2' => 'The figures below are the guidelines we give our own clients. They are not rules, and you should adjust them for service, group size and your own budget without guilt.',
    'blogtip_s2_badge' => 'Safari',
    'blogtip_s2_title' => 'Safari tipping guidelines',
    'blogtip_t1_h1' => 'Who',
    'blogtip_t1_h2' => 'Amount',
    'blogtip_t1_h3' => 'Basis',
    'blogtip_t1_r1_a' => 'Driver-guide',
    'blogtip_t1_r1_c' => 'From the group as a whole, not per person',
    'blogtip_t1_r2_a' => 'Camp / lodge staff',
    'blogtip_t1_r2_c' => 'Into the communal tip box, from the group',
    'blogtip_t1_r3_a' => 'Cook (camping safaris)',
    'blogtip_t1_r3_c' => 'From the group',
    'blogtip_t1_r4_a' => 'Airport transfer driver',
    'blogtip_t1_r4_c' => 'Per transfer',
    'blogtip_t1_r5_a' => 'Restaurant',
    'blogtip_t1_r5_c' => 'If service is not included',
    'blogtip_per_day' => 'per day',
    'blogtip_s2_example_title' => 'A worked example',
    'blogtip_s2_example_intro' => 'Two people, four-day safari, one driver-guide, lodge accommodation:',
    'blogtip_s2_ex_li1' => 'Guide: $22 × 4 days = <strong>$88</strong>',
    'blogtip_s2_ex_li2' => 'Lodge staff: $12 × 4 days = <strong>$48</strong>',
    'blogtip_s2_ex_li3' => '<strong>Total for the group: around $136</strong>, or $68 each',
    'blogtip_s3_badge' => 'Kilimanjaro',
    'blogtip_s3_title' => 'Kilimanjaro tipping',
    'blogtip_s3_p1' => 'A climb involves a much larger crew, typically three to four people per climber, and tipping is a substantial and expected part of their income. Amounts are <strong>per day, from the whole group</strong>.',
    'blogtip_t2_h1' => 'Role',
    'blogtip_t2_h2' => 'Per day, from the group',
    'blogtip_t2_r1_a' => 'Lead guide',
    'blogtip_t2_r2_a' => 'Assistant guide',
    'blogtip_t2_r3_a' => 'Cook',
    'blogtip_t2_r4_a' => 'Porter (each)',
    'blogtip_s3_sub_title' => 'What this adds up to',
    'blogtip_s3_p2' => 'Two climbers on a seven-day Machame route, with a crew of roughly eleven (one lead guide, one assistant, one cook and eight porters) should budget in the region of <strong>$800–1,000 in total tips</strong>, or $400–500 each.',
    'blogtip_s3_p3' => 'That is a significant sum and it surprises people, which is exactly why we tell you before you book rather than on the mountain. Factor it into your budget from the start.',
    'blogtip_s3_note_t' => 'How it works in practice:',
    'blogtip_s3_note_d' => 'tips are pooled by the group and handed over at a ceremony on the last morning, usually with the crew singing the Kilimanjaro song. Bring the cash with you. There are no ATMs on the mountain.',
    'blogtip_s4_badge' => 'Practical',
    'blogtip_s4_title' => 'Practical points',
    'blogtip_s4_i1_t' => 'Bring cash.',
    'blogtip_s4_i1_d' => 'US dollars are standard; Tanzanian shillings are also fine. There are no ATMs inside the parks or on the mountain.',
    'blogtip_s4_i2_t' => 'Notes must be issued after 2009.',
    'blogtip_s4_i2_d' => 'Older US notes are refused throughout Tanzania, including for tips.',
    'blogtip_s4_i3_t' => 'Bring small denominations.',
    'blogtip_s4_i3_d' => '$1, $5 and $10 notes make splitting tips practical.',
    'blogtip_s4_i4_t' => 'Tip at the end,',
    'blogtip_s4_i4_d' => 'not daily, except for one-off transfers.',
    'blogtip_s4_i5_t' => 'Hand tips over personally',
    'blogtip_s4_i5_d' => 'where you can, or use the communal box for camp staff so that kitchen and housekeeping are included.',
    'blogtip_s4_i6_t' => 'Adjust for service.',
    'blogtip_s4_i6_d' => 'These are guidelines. Exceptional guiding deserves more; poor service deserves less, and you should say why.',
    'blogtip_faq_badge' => 'FAQ',
    'blogtip_faq_title' => 'Tipping: frequently asked questions',
    'blogtip_faq_q1' => 'How much should I tip a safari guide?',
    'blogtip_faq_a1' => 'Around $20–25 per day from the group as a whole, not per person. For a four-day safari that is roughly $80–100 in total, however many of you there are in the vehicle.',
    'blogtip_faq_q2' => 'Is tipping compulsory in Tanzania?',
    'blogtip_faq_a2' => 'No, it is discretionary. But it is customary and forms a meaningful part of what guides, cooks and camp staff earn, and it is budgeted for by the people receiving it.',
    'blogtip_faq_q3' => 'How much should I tip on a Kilimanjaro climb?',
    'blogtip_faq_a3' => 'Budget roughly $800–1,000 in total for two climbers on a seven-day route with a crew of about eleven, around $400–500 each. Per day from the group: $20–25 lead guide, $15–18 assistant, $12–15 cook, $8–10 per porter.',
    'blogtip_faq_q4' => 'Why are Kilimanjaro tips so high?',
    'blogtip_faq_a4' => 'Because the crew is large, typically three to four people per climber, carrying your equipment, food and water at altitude. Tips are a substantial and expected part of their income, which is why we tell you the figure before you book.',
    'blogtip_faq_q5' => 'What currency should I tip in?',
    'blogtip_faq_a5' => 'US dollars are standard and Tanzanian shillings are also fine. Notes must be issued after 2009. Older US notes are refused throughout the country. Bring $1, $5 and $10 denominations.',
    'blogtip_faq_q6' => 'When should I tip?',
    'blogtip_faq_a6' => 'At the end of the safari or climb rather than daily, except for one-off airport transfers. On Kilimanjaro there is usually a tipping ceremony on the final morning.',
    'blogtip_faq_q7' => 'Should I tip per person or per group?',
    'blogtip_faq_a7' => 'Per group. The guideline figures assume the whole vehicle or climbing party contributes together, which is why a group of four does not pay four times what a couple pays.',
    'blogtip_faq_q8' => 'Do I tip camp staff separately?',
    'blogtip_faq_a8' => 'Yes, usually into a communal tip box so that kitchen, housekeeping and waiting staff are all included, people you may never meet but who did a great deal of the work.',
    'blogtip_faq_q9' => 'Can I tip by card?',
    'blogtip_faq_a9' => 'No. Bring cash. There are no ATMs inside the national parks or on Kilimanjaro, and lodge card machines depend on connectivity that is often unavailable.',
    'blogtip_faq_q10' => 'What if the service was poor?',
    'blogtip_faq_a10' => 'Tip less, and tell us why. Tipping guidelines are not obligations, and honest feedback is genuinely more useful to us than a tip given out of awkwardness.',
    'blogtip_faq_q11' => 'Should I tip the porters individually?',
    'blogtip_faq_a11' => 'On Kilimanjaro tips are normally pooled and distributed by the lead guide at the ceremony, which ensures a fair split. If you want to give something extra to a specific porter, do it directly and privately.',
    'blogtip_faq_q12' => 'Do I need to tip if service charge is included?',
    'blogtip_faq_a12' => 'At restaurants where a service charge appears on the bill, no additional tip is expected. Safari and climbing tips are separate and are not included in your trip price.',
    'blogtip_related_badge' => 'Keep reading',
    'blogtip_related_title' => 'Continue exploring Tanzania',
    'blogtip_related_contact' => 'Ask us a question',
    'blogtip_final_title' => 'Budgeting your trip?',
    'blogtip_final_intro' => 'Ask us for an itemised quote and we will include a realistic tipping estimate for your specific itinerary and group size, so there are no surprises.',
    'blogtip_final_whatsapp' => 'Message us on WhatsApp',
    'blogtip_final_contact' => 'Contact form',

    // Blog article: Tanzania visa and entry
    'blogvisa_meta_title' => 'Tanzania Visa and Entry Requirements (2026) | Serengeti Budget Safari',
    'blogvisa_meta_description' => 'How to get a Tanzanian visa in 2026: e-visa versus visa on arrival, the $50 cost, passport requirements, the Zanzibar mandatory insurance rule, yellow fever certificates and how to avoid unofficial fee-charging sites.',
    'blogvisa_updated' => 'Updated 2026',
    'blogvisa_h1' => 'Tanzania visa and entry',
    'blogvisa_hero_sub' => 'What you need, what it costs, how long it takes, and the two requirements that catch travellers out at the airport.',
    'blogvisa_author' => 'Serengeti Budget Safari Team',
    'blogvisa_date' => 'August 2026',

    'blogvisa_quick_badge' => 'Quick answers',
    'blogvisa_quick_title' => 'Visa in short',
    'blogvisa_quick_intro' => 'What most travellers need to know.',
    'blogvisa_qq1_q' => 'What does it cost?',
    'blogvisa_qq1_a' => '$50 for most nationalities. $100 for US citizens.',
    'blogvisa_qq2_q' => 'Where do I apply?',
    'blogvisa_qq2_a' => 'visa.immigration.go.tz, the only official site.',
    'blogvisa_qq3_q' => 'How long does it take?',
    'blogvisa_qq3_a' => 'Up to 10 working days. Apply three weeks ahead.',
    'blogvisa_qq4_q' => 'Passport validity?',
    'blogvisa_qq4_a' => 'Six months beyond entry, two blank pages.',
    'blogvisa_qq5_q' => 'Zanzibar?',
    'blogvisa_qq5_a' => 'Same visa, but mandatory local insurance (~$44).',
    'blogvisa_qq6_q' => 'Yellow fever?',
    'blogvisa_qq6_a' => 'Only if arriving from or transiting a risk country.',
    'blogvisa_see_faq' => 'See all FAQs',

    'blogvisa_toc_title' => 'Contents – Tanzania visa and entry',
    'blogvisa_toc_1' => 'The two routes',
    'blogvisa_toc_2' => 'What you need',
    'blogvisa_toc_3' => 'Zanzibar requirements',
    'blogvisa_toc_4' => 'Yellow fever',
    'blogvisa_toc_5' => 'FAQ',

    'blogvisa_s1_badge' => 'The options',
    'blogvisa_s1_title' => 'Two ways to get a visa',
    'blogvisa_s1_p1' => 'Most visitors need a visa for Tanzania. The standard tourist visa costs <strong>US$50</strong> for most nationalities, is valid for <strong>90 days</strong>, and can be obtained either online in advance or on arrival.',
    'blogvisa_s1_sub1' => 'e-Visa online, recommended',
    'blogvisa_s1_p2' => 'Apply at <strong>visa.immigration.go.tz</strong>, upload your documents and pay by card. A decision usually takes <strong>up to 10 working days</strong>, though it can be longer in busy periods. Start at least <strong>three weeks</strong> before you travel. You receive a PDF to print and present on arrival.',
    'blogvisa_s1_sub2' => 'Visa on arrival',
    'blogvisa_s1_p3' => 'Available at Kilimanjaro (JRO), Dar es Salaam and Zanzibar airports. It works, but it means queueing after a long flight, often for an hour or more at busy times, and paying in cash US dollars. If you have the time to apply online, do.',
    'blogvisa_s1_warn_t' => 'Beware of unofficial sites.',
    'blogvisa_s1_warn_d' => 'Searching for a Tanzanian visa returns many sites that look official and charge $50–100 in "service fees" for something you can do yourself in twenty minutes. The only official site is <strong>visa.immigration.go.tz</strong> and the visa costs $50.',

    'blogvisa_s2_badge' => 'Requirements',
    'blogvisa_s2_title' => 'What you need',
    'blogvisa_s2_i1_t' => 'Passport',
    'blogvisa_s2_i1_d' => 'valid at least six months from your date of entry, with two blank pages',
    'blogvisa_s2_i2' => 'A <strong>digital passport photo</strong>',
    'blogvisa_s2_i3' => 'Your <strong>return or onward ticket</strong>',
    'blogvisa_s2_i4' => 'The address of your <strong>first night\'s accommodation</strong>, which we provide with your booking confirmation',
    'blogvisa_s2_i5' => 'A credit or debit card for the online payment',
    'blogvisa_s2_sub1' => 'Nationalities that pay more',
    'blogvisa_s2_p1' => '<strong>US citizens</strong> are issued a multiple-entry visa costing <strong>$100</strong> rather than the standard $50 single-entry. A small number of nationalities require referral visas with a longer processing time. If you hold a passport from outside Europe, North America or the Commonwealth, check well in advance.',

    'blogvisa_s3_badge' => 'Zanzibar',
    'blogvisa_s3_title' => 'Zanzibar: same visa, extra insurance',
    'blogvisa_s3_p1' => 'Zanzibar is part of Tanzania, so <strong>you do not need a second visa</strong>. There is, however, an additional requirement that catches people out.',
    'blogvisa_s3_p2' => 'Since 2024, all foreign visitors to Zanzibar must hold <strong>mandatory travel insurance issued by a Zanzibar-approved provider</strong>, costing around <strong>US$44</strong> and purchased online before arrival. Your existing European or American travel policy, however comprehensive, <strong>does not satisfy this requirement</strong>. It is a separate, locally issued product.',
    'blogvisa_s3_p3' => 'This is checked at Zanzibar airport and the ferry terminal. Buy it in advance; we can arrange it with your booking.',

    'blogvisa_s4_badge' => 'Health entry',
    'blogvisa_s4_title' => 'Yellow fever certificate',
    'blogvisa_s4_p1' => 'A yellow fever certificate is required <strong>only</strong> if you are arriving from, or have transited for more than 12 hours through, a country with yellow fever risk.',
    'blogvisa_s4_p2' => 'Travellers flying directly from Europe, North America or Asia <strong>do not need it</strong>. Travellers connecting through Nairobi, Addis Ababa or other African hubs <strong>may</strong>, depending on the length of the layover. This is where people get caught out.',
    'blogvisa_s4_p3' => 'The certificate is checked on arrival, and without one where it is required you will be vaccinated at the airport at your own expense. Check your specific routing before you fly.',

    'blogvisa_faq_badge' => 'FAQ',
    'blogvisa_faq_title' => 'Tanzania visa: frequently asked questions',
    'blogvisa_faq_q1' => 'Do I need a visa for Tanzania?',
    'blogvisa_faq_a1' => 'Most nationalities do. The standard tourist visa costs US$50, is valid for 90 days, and can be obtained online in advance or on arrival at the main airports.',
    'blogvisa_faq_q2' => 'How much does a Tanzanian visa cost?',
    'blogvisa_faq_a2' => 'US$50 for most nationalities. US citizens pay $100 for a multiple-entry visa. Beware of unofficial websites charging $50–100 in additional service fees for the same thing.',
    'blogvisa_faq_q3' => 'How long does the e-visa take?',
    'blogvisa_faq_a3' => 'Usually up to 10 working days, sometimes longer in busy periods. Apply at least three weeks before you travel to be safe.',
    'blogvisa_faq_q4' => 'What is the official visa website?',
    'blogvisa_faq_a4' => 'visa.immigration.go.tz is the only official portal. Many convincing-looking sites charge substantial fees for a service you can complete yourself in about twenty minutes.',
    'blogvisa_faq_q5' => 'Can I get a visa on arrival?',
    'blogvisa_faq_a5' => 'Yes, at Kilimanjaro, Dar es Salaam and Zanzibar airports, paying in cash US dollars. It works, but expect to queue, sometimes over an hour after a long flight. Applying online is the calmer option.',
    'blogvisa_faq_q6' => 'Do I need a separate visa for Zanzibar?',
    'blogvisa_faq_a6' => 'No. Zanzibar is part of Tanzania and the same visa covers it. But since 2024 you do need mandatory travel insurance from a Zanzibar-approved provider, costing around US$44, purchased before arrival.',
    'blogvisa_faq_q7' => 'Does my normal travel insurance cover the Zanzibar requirement?',
    'blogvisa_faq_a7' => 'No. The Zanzibar mandatory insurance is a separate, locally issued product. Your European or American policy, however comprehensive, does not satisfy the requirement and it is checked on arrival.',
    'blogvisa_faq_q8' => 'How long must my passport be valid?',
    'blogvisa_faq_a8' => 'At least six months beyond your date of entry, with two blank pages. This is checked and enforced.',
    'blogvisa_faq_q9' => 'Do I need a yellow fever certificate?',
    'blogvisa_faq_a9' => 'Only if you are arriving from or have transited more than 12 hours through a yellow fever risk country. Direct flights from Europe do not require it, but a long layover in Nairobi or Addis Ababa may.',
    'blogvisa_faq_q10' => 'How long can I stay?',
    'blogvisa_faq_a10' => 'The standard tourist visa is valid for 90 days. Extensions are possible through immigration offices in Tanzania but are bureaucratic, so plan your dates properly.',
    'blogvisa_faq_q11' => 'Can I work or volunteer on a tourist visa?',
    'blogvisa_faq_a11' => 'No. Volunteering requires a different permit even when unpaid, and the rules are enforced. If you are planning volunteer work, arrange the correct permit well in advance.',
    'blogvisa_faq_q12' => 'What if my visa is refused or delayed?',
    'blogvisa_faq_a12' => 'Delays are more common than refusals. If your travel date approaches and no decision has arrived, visa on arrival remains available at the main airports as a fallback. Bring cash US dollars.',
    'blogvisa_faq_q13' => 'Do children need a visa?',
    'blogvisa_faq_a13' => 'Yes, every traveller needs their own visa regardless of age, and each child needs their own passport. Children travelling with only one parent may be asked for a consent letter from the other.',
    'blogvisa_faq_q14' => 'Is the East Africa Tourist Visa valid for Tanzania?',
    'blogvisa_faq_a14' => 'No. The East Africa Tourist Visa covers Kenya, Uganda and Rwanda but not Tanzania. If you are combining Tanzania with Kenya, you need separate visas for each.',

    'blogvisa_related_badge' => 'Keep reading',
    'blogvisa_related_title' => 'Continue exploring Tanzania',
    'blogvisa_related_contact' => 'Ask us a question',

    'blogvisa_final_title' => 'Need help with the paperwork?',
    'blogvisa_final_intro' => 'We provide the accommodation address your visa application needs, and can arrange the Zanzibar mandatory insurance with your booking. Just ask.',
    'blogvisa_final_whatsapp' => 'Message us on WhatsApp',
    'blogvisa_final_contact' => 'Contact form',

    // Blog article: Where to stay on safari
    'blogstay_meta_title' => 'Where to Stay on Safari in Tanzania: Lodge, Camp or Camping? | Serengeti Budget Safari',
    'blogstay_meta_description' => 'Safari accommodation in Tanzania explained: campsites, lodges, tented camps and mobile camps compared with real prices, plus whether to sleep inside or outside the national parks.',
    'blogstay_h1' => 'Where to stay on safari',
    'blogstay_hero_sub' => 'Campsite, lodge, tented camp or mobile camp: what each actually costs, what each is really like, and whether to sleep inside the park or outside it.',
    'blogstay_updated' => 'Updated 2026',
    'blogstay_author' => 'Serengeti Budget Safari Team',
    'blogstay_date' => 'August 2026',

    'blogstay_quick_badge' => 'Quick answers',
    'blogstay_quick_title' => 'Accommodation in short',
    'blogstay_quick_intro' => 'The decisions that actually matter.',
    'blogstay_qq1_q' => 'Inside or outside?',
    'blogstay_qq1_a' => 'Inside if you have 2–3 nights. Mix on longer trips.',
    'blogstay_qq2_q' => 'What is a concession fee?',
    'blogstay_qq2_a' => '$47–59 per adult per night to sleep inside a park.',
    'blogstay_qq3_q' => 'Cheapest option?',
    'blogstay_qq3_a' => 'Camping: $35.40 park fee plus camping costs.',
    'blogstay_qq4_q' => 'Classic experience?',
    'blogstay_qq4_a' => 'A permanent tented camp. Canvas, and every sound.',
    'blogstay_qq5_q' => 'Following the migration?',
    'blogstay_qq5_a' => 'A mobile camp, it relocates with the herds.',
    'blogstay_qq6_q' => 'Book how far ahead?',
    'blogstay_qq6_a' => '6–12 months for Kogatende or Ndutu in peak season.',

    'blogstay_toc_title' => 'Contents – Where to stay on safari',
    'blogstay_toc_1' => 'The five types',
    'blogstay_toc_2' => 'Inside or outside?',
    'blogstay_toc_3' => 'What each is really like',
    'blogstay_toc_4' => 'How to choose',
    'blogstay_toc_5' => 'FAQ',

    'blogstay_s1_badge' => 'The options',
    'blogstay_s1_title' => 'The five types of safari accommodation',
    'blogstay_s1_p1' => 'Where you sleep is the biggest single variable in what a safari costs, and, on a short trip, in how much wildlife you actually see. The animals are the same whichever you choose; what changes is comfort, and how far you are from the action at dawn.',
    'blogstay_t1_h1' => 'Type',
    'blogstay_t1_h2' => 'Per person / night',
    'blogstay_t1_h3' => 'What it is',
    'blogstay_t1_h4' => 'Best for',
    'blogstay_t1_r1_a' => 'Public campsite',
    'blogstay_t1_r1_b' => '$35.40 park fee<br>+ camping costs',
    'blogstay_t1_r1_c' => 'Your own tent inside the park, shared long-drop toilets, cold showers, cook preparing meals on site.',
    'blogstay_t1_r1_d' => 'Budget travellers, groups, the adventurous',
    'blogstay_t1_r2_a' => 'Lodge outside the park',
    'blogstay_t1_r2_c' => 'Solid rooms, hot water, restaurant, usually a pool. In Karatu or on a park boundary.',
    'blogstay_t1_r2_d' => 'Keeping costs down',
    'blogstay_t1_r3_a' => 'Lodge inside the park',
    'blogstay_t1_r3_c' => 'Permanent building, electricity, restaurant, often a pool with a view over a waterhole.',
    'blogstay_t1_r3_d' => 'Comfort plus convenience',
    'blogstay_t1_r4_a' => 'Tented camp',
    'blogstay_t1_r4_c' => 'Permanent canvas with proper beds and en-suite bathrooms. You hear everything at night.',
    'blogstay_t1_r4_d' => 'The classic safari experience',
    'blogstay_t1_r5_a' => 'Mobile camp',
    'blogstay_t1_r5_c' => 'Relocates two or three times a year to follow the migration. Small, remote, few other vehicles nearby.',
    'blogstay_t1_r5_d' => 'Migration-focused trips',

    'blogstay_s2_badge' => 'The key decision',
    'blogstay_s2_title' => 'Inside or outside the park?',
    'blogstay_s2_p1' => 'This is the decision that trips up most first-time planners, and it matters more than the star rating of the lodge.',
    'blogstay_s2_sub1' => 'Sleeping inside',
    'blogstay_s2_p2' => 'You pay a <strong>concession fee</strong> on top of the room rate: $59.00 per adult per night in the Serengeti and Ngorongoro, $47.20 in Tarangire, Manyara, Arusha NP and Nyerere. In return you are already in the middle of the ecosystem when the light is best, at dawn and dusk, which is precisely when predators are active.',
    'blogstay_s2_sub2' => 'Sleeping outside',
    'blogstay_s2_p3' => 'You save the concession fee and usually a large part of the room rate. The cost is time: the nearest gate can be 30 to 90 minutes away, which means leaving before dawn and returning after dark, and losing the two best hours of each day to driving.',
    'blogstay_t2_h1' => 'Inside the park',
    'blogstay_t2_h2' => 'Outside the park',
    'blogstay_t2_r1_a' => 'Cost',
    'blogstay_t2_r1_b' => 'Higher: room + $47–59/night concession',
    'blogstay_t2_r1_c' => 'Lower',
    'blogstay_t2_r2_a' => 'Dawn game drive',
    'blogstay_t2_r2_b' => 'Start immediately',
    'blogstay_t2_r2_c' => '30–90 min drive first',
    'blogstay_t2_r3_a' => 'Evening light',
    'blogstay_t2_r3_b' => 'Full use of it',
    'blogstay_t2_r3_c' => 'Must leave early to reach the gate',
    'blogstay_t2_r4_a' => 'Sounds at night',
    'blogstay_t2_r4_b' => 'Hyena, lion, hippo',
    'blogstay_t2_r4_c' => 'Usually quiet',
    'blogstay_t2_r5_a' => 'Facilities',
    'blogstay_t2_r5_b' => 'Varies; often simpler',
    'blogstay_t2_r5_c' => 'Often better value for comfort',
    'blogstay_tip_t' => 'What we usually recommend:',
    'blogstay_tip_d' => 'on a trip of three nights or fewer, stay inside the park even if it means a simpler room. The extra hours at dawn are worth more than the extra comfort. On a week or longer, mix: a couple of nights inside at the key moment, cheaper nights outside for the rest.',

    'blogstay_s3_badge' => 'Reality check',
    'blogstay_s3_title' => 'What each type is actually like',
    'blogstay_s3_sub1' => 'Camping',
    'blogstay_s3_p1' => 'A two-person dome tent on a public campsite, a shared ablution block with cold water, and a cook who produces genuinely good food over a fire. You will hear hyenas at night, and occasionally lions. Buffalo walk through some campsites. You are given a torch and told not to leave the tent after dark, and that instruction is not decorative.',
    'blogstay_s3_p2' => 'It is basic, it is not for everyone, and the people who choose it usually describe it as the best part of the trip.',
    'blogstay_s3_sub2' => 'Tented camp',
    'blogstay_s3_p3' => 'The word "tent" is misleading. These are permanent canvas structures on platforms, with real beds, en-suite bathrooms and hot water brought at dawn. What makes them special is the canvas: you hear everything, and at night an askari escorts you to your tent because animals move through camp.',
    'blogstay_s3_sub3' => 'Lodge',
    'blogstay_s3_p4' => 'A hotel in a national park. Solid walls, electricity, a restaurant, usually a swimming pool. Comfortable and reliable, and considerably less atmospheric than canvas. The best ones are built on escarpments or above waterholes and the view does the work.',
    'blogstay_s3_sub4' => 'Mobile camp',
    'blogstay_s3_p5' => 'Small, usually six to twelve tents, relocated seasonally to follow the herds. Solar power, bucket showers, no pool, no Wi-Fi. Remote and quiet, and if the migration is why you came, this puts you closest to it.',

    'blogstay_s4_badge' => 'Choosing',
    'blogstay_s4_title' => 'How to choose for your trip',
    'blogstay_t3_h1' => 'If you…',
    'blogstay_t3_h2' => 'Choose',
    'blogstay_t3_h3' => 'Why',
    'blogstay_t3_r1_a' => 'Have 2–3 nights only',
    'blogstay_t3_r1_b' => 'Inside the park',
    'blogstay_t3_r1_c' => 'Dawn and dusk are worth more than comfort',
    'blogstay_t3_r2_a' => 'Have a week or more',
    'blogstay_t3_r2_b' => 'Mix inside and outside',
    'blogstay_t3_r2_c' => 'Save on the ordinary nights, spend on the key ones',
    'blogstay_t3_r3_a' => 'Are on a tight budget',
    'blogstay_t3_r3_b' => 'Camping or outside lodges',
    'blogstay_t3_r3_c' => 'Same guide, same animals, much lower cost',
    'blogstay_t3_r4_a' => 'Are following the migration',
    'blogstay_t3_r4_b' => 'Mobile camp',
    'blogstay_t3_r4_c' => 'It moves with the herds',
    'blogstay_t3_r5_a' => 'Are travelling with children',
    'blogstay_t3_r5_b' => 'Lodge with a pool',
    'blogstay_t3_r5_c' => 'Somewhere to burn energy in the hot hours',
    'blogstay_t3_r6_a' => 'Want the classic experience',
    'blogstay_t3_r6_b' => 'Tented camp',
    'blogstay_t3_r6_c' => 'Canvas, sounds at night, an askari walking you back',
    'blogstay_t3_r7_a' => 'Are on honeymoon',
    'blogstay_t3_r7_b' => 'Small tented camp',
    'blogstay_t3_r7_c' => 'Private, quiet, and far better than a big lodge',

    'blogstay_s4_sub1' => 'Questions worth asking before you book',
    'blogstay_ask1' => 'Is the concession fee included in the quoted rate, or added?',
    'blogstay_ask2' => 'How far is it from the gate, and how long is the drive to the main game area?',
    'blogstay_ask3' => 'Is there electricity all night, or generator hours only?',
    'blogstay_ask4' => 'Are drinks included, and which ones?',
    'blogstay_ask5' => 'Is there a minimum age for children?',
    'blogstay_ask6' => 'Is Wi-Fi available, and where?',

    'blogstay_faq_badge' => 'FAQ',
    'blogstay_faq_title' => 'Safari accommodation: frequently asked questions',
    'blogstay_faq_q1' => 'Should I stay inside or outside the national park?',
    'blogstay_faq_a1' => 'On a trip of three nights or fewer, inside. You are already in the ecosystem at dawn and dusk when predators are active. On a longer trip, mix: cheaper nights outside, key nights inside. Sleeping inside adds a concession fee of $47–59 per adult per night.',
    'blogstay_faq_q2' => 'What is a concession fee?',
    'blogstay_faq_a2' => 'A per-person, per-night charge levied by the park authority when you sleep in a lodge or camp inside a national park. It is $59.00 per adult in the Serengeti and Ngorongoro and $47.20 in Tarangire, Manyara, Arusha NP and Nyerere, on top of the room rate.',
    'blogstay_faq_q3' => 'Is camping on safari safe?',
    'blogstay_faq_a3' => 'Yes, at designated public campsites, with the normal precautions: stay in the tent after dark, keep food sealed and away from the tent, and follow your guide\'s instructions. Animals do walk through campsites, which is exactly why those rules exist.',
    'blogstay_faq_q4' => 'What is the difference between a lodge and a tented camp?',
    'blogstay_faq_a4' => 'A lodge is a permanent building with solid walls and electricity. A tented camp is permanent canvas on a platform with real beds and en-suite bathrooms. The canvas is the point. You hear everything at night, which most people find is the memory that stays.',
    'blogstay_faq_q5' => 'What is a mobile camp?',
    'blogstay_faq_a5' => 'A small camp, usually six to twelve tents, that physically relocates two or three times a year to follow the migration. Solar power, bucket showers, no pool. If the migration is the reason for your trip, this puts you closest to it.',
    'blogstay_faq_q6' => 'How much does safari accommodation cost per night?',
    'blogstay_faq_a6' => 'Public campsites are $35.40 in park fees plus camping costs; lodges outside the parks $60–150; lodges inside $150–400; tented camps $200–600; mobile camps $300–700. Ultra-luxury runs from $700 upwards.',
    'blogstay_faq_q7' => 'Do I need to book accommodation in advance?',
    'blogstay_faq_a7' => 'Yes, particularly for June to October and for Ndutu in February. Camps in the northern Serengeti and Ndutu sell out six to twelve months ahead because the number of beds in those areas is limited.',
    'blogstay_faq_q8' => 'Is there electricity and Wi-Fi?',
    'blogstay_faq_a8' => 'Lodges usually have both. Tented camps often run generators for set hours and provide solar lighting the rest of the time. Mobile camps typically have solar power and no Wi-Fi at all. Ask before booking if it matters to you.',
    'blogstay_faq_q9' => 'Are meals included?',
    'blogstay_faq_a9' => 'Almost always on safari: full board is standard, and packed lunches are provided on full-day game drives. Drinks other than water and tea are usually charged separately except at the luxury end, where they are often included.',
    'blogstay_faq_q10' => 'Can I stay in a lodge with children?',
    'blogstay_faq_a10' => 'Most lodges accept children of any age. Some tented camps set a minimum of six or twelve years, because of the walking between tents at night. Tell us the ages when you enquire and we will filter accordingly.',
    'blogstay_faq_q11' => 'What happens at night in a tented camp?',
    'blogstay_faq_a11' => 'An askari, a night guard, escorts you between the dining area and your tent, because animals move through camp after dark. You will hear hippo, hyena and often lion. The tent zips shut and is entirely secure.',
    'blogstay_faq_q12' => 'Is a swimming pool worth paying for?',
    'blogstay_faq_a12' => 'With children, genuinely yes. The hot hours between game drives are long and a pool solves them. Without children it matters much less, and the money is usually better spent on location.',
    'blogstay_faq_q13' => 'What is the best value option?',
    'blogstay_faq_a13' => 'A lodge just outside a park boundary, at $60–150 per person. You avoid the concession fee and get better facilities for the money, at the cost of 30 to 90 minutes of driving each morning and evening.',

    'blogstay_related_badge' => 'Keep reading',
    'blogstay_related_title' => 'Continue exploring Tanzania',
    'blogstay_final_title' => 'Not sure which to choose?',
    'blogstay_final_intro' => 'Tell us your budget and how many nights you have. We will suggest a mix of inside and outside nights that gets you the most wildlife for the money.',
    'blogstay_final_whatsapp' => 'Message us on WhatsApp',
    'blogstay_final_contact' => 'Contact form',

    // Blog: The Big Five in Tanzania
    'blogbig5_meta_title' => 'The Big Five in Tanzania: Where and When to See Them | Serengeti Budget Safari',
    'blogbig5_meta_description' => 'Where to see lion, leopard, elephant, buffalo and black rhino in Tanzania, with honest sighting odds for each, the itineraries that give the best chance, and why rhino is the hard one.',
    'blogbig5_h1' => 'The Big Five in Tanzania',
    'blogbig5_hero_sub' => 'Where each one lives, what your realistic odds are, and how to plan an itinerary that gives you a genuine chance at all five.',
    'blogbig5_updated' => 'Updated 2026',
    'blogbig5_quick_badge' => 'Quick answers',
    'blogbig5_quick_title' => 'The Big Five in short',
    'blogbig5_quick_intro' => 'Honest odds, before the detail.',
    'blogbig5_qq1_q' => 'Which are easy?',
    'blogbig5_qq1_a' => 'Lion, elephant and buffalo: near-certain.',
    'blogbig5_qq2_q' => 'Leopard?',
    'blogbig5_qq2_a' => '55–60% in the Seronera valley over three days.',
    'blogbig5_qq3_q' => 'Black rhino?',
    'blogbig5_qq3_a' => '~60% on a full day in the Ngorongoro Crater. Nowhere else.',
    'blogbig5_qq4_q' => 'How many days?',
    'blogbig5_qq4_a' => 'Four to five for a realistic chance at all five.',
    'blogbig5_qq5_q' => 'What should I bring?',
    'blogbig5_qq5_a' => 'Binoculars matter more than a long lens for rhino.',
    'blogbig5_qq6_q' => 'Guaranteed?',
    'blogbig5_qq6_a' => 'Never. Anyone promising all five is overselling.',
    'blogbig5_toc_title' => 'Contents – The Big Five in Tanzania',
    'blogbig5_toc_1' => 'What they are',
    'blogbig5_toc_2' => 'Where to see each',
    'blogbig5_toc_3' => 'Best itineraries',
    'blogbig5_toc_4' => 'Beyond the Big Five',
    'blogbig5_toc_5' => 'FAQ',
    'blogbig5_s1_badge' => 'The basics',
    'blogbig5_s1_title' => 'What the Big Five are, and why',
    'blogbig5_s1_p1' => 'Lion, leopard, elephant, buffalo and black rhino. The term has nothing to do with size. The hippo and giraffe are both larger than a leopard. It comes from colonial-era big-game hunting, and referred to the <strong>five animals considered most dangerous to hunt on foot</strong>.',
    'blogbig5_s1_p2' => 'The name has outlived its origin and is now the standard checklist of a safari, which is slightly absurd but genuinely useful: between them the five cover most of the habitats and behaviours worth travelling to see.',
    'blogbig5_s1_p3' => 'The honest position on completing the set: four of the five are straightforward on a well-planned northern circuit safari. The <strong>black rhino is the difficulty</strong>, and everything below is really about how to solve that one.',
    'blogbig5_fact_lion_label' => 'Lion',
    'blogbig5_fact_lion_value' => 'Easy, Serengeti, Ngorongoro',
    'blogbig5_fact_elephant_label' => 'Elephant',
    'blogbig5_fact_elephant_value' => 'Easy, Tarangire, Ruaha',
    'blogbig5_fact_buffalo_label' => 'Buffalo',
    'blogbig5_fact_buffalo_value' => 'Easy, everywhere',
    'blogbig5_fact_leopard_label' => 'Leopard',
    'blogbig5_fact_leopard_value' => 'Moderate, Serengeti',
    'blogbig5_fact_rhino_label' => 'Black rhino',
    'blogbig5_fact_rhino_value' => 'Hard, Ngorongoro only',
    'blogbig5_fact_days_label' => 'Days for all five',
    'blogbig5_fact_days_value' => '4–5 realistically',
    'blogbig5_s2_badge' => 'The five',
    'blogbig5_s2_title' => 'Where to see each one',
    'blogbig5_s2_lion_h' => 'Lion',
    'blogbig5_s2_lion_p' => 'The easiest. The <strong>Serengeti</strong> holds around 3,000 and has one of the highest densities in Africa; the <strong>Ngorongoro Crater</strong> has roughly 60 in 260 km², so they are almost unavoidable. <strong>Ruaha</strong> in the south has prides of twenty or more that hunt buffalo and even young elephant.',
    'blogbig5_s2_lion_odds' => 'Best odds: 90–95% on a three-day northern circuit safari.',
    'blogbig5_s2_elephant_h' => 'Elephant',
    'blogbig5_s2_elephant_p' => '<strong>Tarangire</strong> in the dry season is the best on the northern circuit: 2,500 to 3,000 resident animals, with herds of fifty or more along the river. <strong>Ruaha</strong> has around 12,000, the largest population in East Africa.',
    'blogbig5_s2_elephant_odds' => 'Best odds: 95%+ in Tarangire July to October.',
    'blogbig5_s2_buffalo_h' => 'Buffalo',
    'blogbig5_s2_buffalo_p' => 'Common everywhere, usually in large herds. The Ngorongoro Crater and Serengeti both hold thousands. Old solitary bulls, known as dagga boys, are the ones to treat with respect.',
    'blogbig5_s2_buffalo_odds' => 'Best odds: 90%+ anywhere.',
    'blogbig5_s2_leopard_h' => 'Leopard',
    'blogbig5_s2_leopard_p' => 'The elusive one, but far from impossible. The <strong>Seronera valley</strong> in the central Serengeti is the single best place in Tanzania: leopards rest in the acacias along the river through the heat of the day. <strong>Ndutu</strong> is also excellent.',
    'blogbig5_s2_leopard_odds' => 'Best odds: 55–60% over three days in the central Serengeti.',
    'blogbig5_s2_rhino_h' => 'Black rhino',
    'blogbig5_s2_rhino_p1' => 'The hard one. Tanzania\'s population is small and scattered, and there is one place where you have a genuine chance: the <strong>Ngorongoro Crater</strong>, where around 30 live under 24-hour armed protection. A handful survive around the Moru Kopjes in the Serengeti, but sightings there are rare.',
    'blogbig5_s2_rhino_p2' => 'Expect to see them at a distance across open grass rather than close to the vehicle. A good pair of binoculars matters more here than a long lens, and early morning is when they are most likely to be out in the open.',
    'blogbig5_s2_rhino_odds' => 'Best odds: around 60% on a full day in the crater.',
    'blogbig5_s3_badge' => 'Planning',
    'blogbig5_s3_title' => 'Itineraries that give you the best chance',
    'blogbig5_t1_h1' => 'Trip',
    'blogbig5_t1_h2' => 'Parks',
    'blogbig5_t1_h3' => 'Realistic outcome',
    'blogbig5_t1_r1_a' => '2 days',
    'blogbig5_t1_r1_b' => 'Tarangire + Ngorongoro',
    'blogbig5_t1_r1_c' => 'Lion, elephant, buffalo near-certain; rhino likely; leopard unlikely. <strong>3–4 of 5.</strong>',
    'blogbig5_t1_r2_a' => '4 days',
    'blogbig5_t1_r2_b' => 'Tarangire, Serengeti, Ngorongoro',
    'blogbig5_t1_r2_c' => 'All four easy species, plus a real chance at both leopard and rhino. <strong>4–5 of 5.</strong>',
    'blogbig5_t1_r3_a' => '6 days',
    'blogbig5_t1_r3_b' => 'Full northern circuit',
    'blogbig5_t1_r3_c' => 'Time to work the Seronera valley for leopard and a full crater day for rhino. <strong>Best chance of all five.</strong>',
    'blogbig5_s3_warn_t' => 'Nobody can guarantee the Big Five.',
    'blogbig5_s3_warn_d' => 'These are wild animals in enormous areas. What a good operator can do is put you in the right places at the right times of day and be honest about the odds, which is what the numbers above are.',
    'blogbig5_s4_badge' => 'Beyond the five',
    'blogbig5_s4_title' => 'The animals worth more than the checklist',
    'blogbig5_s4_intro' => 'Ask a guide what they would rather show you, and the Big Five rarely tops the list.',
    'blogbig5_s4_i1_t' => 'Cheetah',
    'blogbig5_s4_i1_d' => 'the fastest land animal, hunting on the open southern plains. A cheetah hunt is a better spectacle than most lion sightings.',
    'blogbig5_s4_i2_t' => 'African wild dog',
    'blogbig5_s4_i2_d' => 'fewer than 7,000 left worldwide. Nyerere and Ruaha are two of the last strongholds, and a pack hunting is extraordinary.',
    'blogbig5_s4_i3_t' => 'The Great Migration',
    'blogbig5_s4_i3_d' => '1.3 million wildebeest. No single animal competes.',
    'blogbig5_s4_i4_t' => 'Giraffe',
    'blogbig5_s4_i4_d' => 'Tanzania\'s national animal, and somehow always more striking in person than expected.',
    'blogbig5_s4_i5_t' => 'Hippo',
    'blogbig5_s4_i5_d' => 'statistically the most dangerous large animal in Africa, and far more entertaining than the Big Five list suggests.',
    'blogbig5_s4_i6_t' => 'Serval, caracal, honey badger, aardvark: the sightings guides get genuinely excited about.',
    'blogbig5_s4_outro' => 'Our advice: use the Big Five to shape the itinerary, then forget the checklist once you are out there. The best safari mornings are almost never the ones spent ticking boxes.',
    'blogbig5_tag_lion' => 'Lion',
    'blogbig5_tag_leopard' => 'Leopard',
    'blogbig5_tag_elephant' => 'Elephant',
    'blogbig5_tag_buffalo' => 'Buffalo',
    'blogbig5_tag_rhino' => 'Black rhino',
    'blogbig5_tag_cheetah' => 'Cheetah',
    'blogbig5_tag_wilddog' => 'Wild dog',
    'blogbig5_tag_giraffe' => 'Giraffe',
    'blogbig5_tag_hippo' => 'Hippo',
    'blogbig5_faq_title' => 'The Big Five: frequently asked questions',
    'blogbig5_faq_q1' => 'What are the Big Five?',
    'blogbig5_faq_a1' => 'Lion, leopard, elephant, buffalo and black rhino. The term comes from colonial big-game hunting and referred to the five animals considered most dangerous to hunt on foot, not the largest.',
    'blogbig5_faq_q2' => 'Can I see the Big Five in Tanzania?',
    'blogbig5_faq_a2' => 'Yes, and a four to five day northern circuit safari gives a realistic chance of all five. Lion, elephant and buffalo are near-certain, leopard is around 55–60% in the Serengeti, and rhino around 60% on a full day in the Ngorongoro Crater.',
    'blogbig5_faq_q3' => 'Where is the best place to see black rhino?',
    'blogbig5_faq_a3' => 'The Ngorongoro Crater, where around 30 live under 24-hour armed protection. It is the only realistic option in Tanzania. Expect distant sightings across open grass. Bring binoculars.',
    'blogbig5_faq_q4' => 'Where is the best place to see leopard?',
    'blogbig5_faq_a4' => 'The Seronera valley in the central Serengeti. Leopards rest in the acacias along the river through the heat of the day, which makes them findable if you know where to look. Ndutu is also excellent.',
    'blogbig5_faq_q5' => 'Which park has the most elephants?',
    'blogbig5_faq_a5' => 'Ruaha with around 12,000, the largest population in East Africa. On the northern circuit, Tarangire is best: 2,500 to 3,000 resident animals and dry-season herds of fifty or more.',
    'blogbig5_faq_q6' => 'How many days do I need to see the Big Five?',
    'blogbig5_faq_a6' => 'Four to five realistically. Two days covers three or four of them. Six days gives the best chance, because you have time to work the Seronera valley for leopard and a full crater day for rhino.',
    'blogbig5_faq_q7' => 'Can I see the Big Five in the Serengeti alone?',
    'blogbig5_faq_a7' => 'Four of them, easily. Black rhino is the exception: a handful survive near the Moru Kopjes but sightings are rare. To complete the set, add the Ngorongoro Crater.',
    'blogbig5_faq_q8' => 'Is the Big Five guaranteed?',
    'blogbig5_faq_a8' => 'No, and be wary of anyone who says otherwise. These are wild animals in areas of thousands of square kilometres. A good operator improves your odds by being in the right place at the right time, and is honest about what those odds are.',
    'blogbig5_faq_q9' => 'Why is the black rhino so rare?',
    'blogbig5_faq_a9' => 'Poaching. Tanzania\'s black rhino population fell from thousands in the 1970s to a few dozen by the 1990s. Numbers are slowly recovering under intensive protection, but they remain critically endangered.',
    'blogbig5_faq_q10' => 'What is the difference between black and white rhino?',
    'blogbig5_faq_a10' => 'Mouth shape, mainly. Black rhino have a hooked lip for browsing on shrubs; white rhino have a wide flat lip for grazing grass. Tanzania has black rhino; white rhino are found mainly in southern Africa.',
    'blogbig5_faq_q11' => 'What is better than the Big Five?',
    'blogbig5_faq_a11' => 'Ask a guide and most will say a cheetah hunt, a wild dog pack, or the migration itself. The Big Five is a useful planning framework and a poor description of what makes a safari memorable.',
    'blogbig5_faq_q12' => 'Where can I see cheetah?',
    'blogbig5_faq_a12' => 'The open southern plains of the Serengeti, particularly around Ndutu during the calving season. Cheetah need open ground to run and avoid areas with high lion density, since lions kill them.',
    'blogbig5_faq_q13' => 'Are buffalo really dangerous?',
    'blogbig5_faq_a13' => 'Yes. Old solitary bulls, dagga boys, are responsible for more attacks on people than most other African animals. From a vehicle you are entirely safe; on foot, they are the reason walking safaris carry an armed ranger.',
    'blogbig5_faq_q14' => 'Do I need a long lens for the Big Five?',
    'blogbig5_faq_a14' => 'A 300 mm lens or longer helps considerably, particularly for rhino and leopard. But binoculars matter more than most people expect. Many sightings, especially rhino in the crater, are too distant for any realistic lens.',
    'blogbig5_related_title' => 'Continue exploring Tanzania',
    'blogbig5_related_ngorongoro' => 'Ngorongoro, for rhino',
    'blogbig5_final_title' => 'Plan a Big Five itinerary',
    'blogbig5_final_intro' => 'Tell us how many days you have and we will build the route that gives you the best genuine chance, and tell you plainly if your schedule makes all five unlikely.',

    // ===== Blog article: What to Pack for a Safari =====
    'blogpack_meta_title' => 'What to Pack for a Tanzania Safari (2026 Checklist) | Serengeti Budget Safari',
    'blogpack_meta_description' => 'A practical safari packing list: clothing, medical kit, photography gear, documents and money, plus what to leave at home, including items that are actually illegal in Tanzania.',
    'blogpack_h1' => 'What to pack for a safari',
    'blogpack_hero_sub' => 'Layers, neutral colours and 15 kg in a soft bag, plus the items travellers most often forget, and the ones that are actually illegal in Tanzania.',
    'blogpack_updated' => 'Updated 2026',
    'blogpack_author' => 'Serengeti Budget Safari Team',
    'blogpack_date' => 'August 2026',
    'blogpack_quick_badge' => 'Quick answers',
    'blogpack_quick_title' => 'Packing in short',
    'blogpack_quick_intro' => 'The essentials, before the full list.',
    'blogpack_qq1_q' => 'The one rule?',
    'blogpack_qq1_a' => 'Layers. 14 °C at dawn, 28 °C at midday.',
    'blogpack_qq2_q' => 'Baggage limit?',
    'blogpack_qq2_a' => '15 kg soft bag on internal flights. Strictly enforced.',
    'blogpack_qq3_q' => 'What colours?',
    'blogpack_qq3_a' => 'Khaki and olive. Avoid blue and black: tsetse flies.',
    'blogpack_qq4_q' => 'Most forgotten item?',
    'blogpack_qq4_a' => 'Binoculars. More useful than a long lens.',
    'blogpack_qq5_q' => 'What is banned?',
    'blogpack_qq5_a' => 'Camouflage clothing and single-use plastic bags.',
    'blogpack_qq6_q' => 'How many clothes?',
    'blogpack_qq6_a' => 'Four days\' worth. Laundry is available almost everywhere.',
    'blogpack_see_faq' => 'See all FAQs',
    'blogpack_toc_title' => 'Contents – What to pack for a safari',
    'blogpack_toc_1' => 'The one rule',
    'blogpack_toc_2' => 'Clothing',
    'blogpack_toc_3' => 'Medical kit',
    'blogpack_toc_4' => 'Photography kit',
    'blogpack_toc_5' => 'Documents & money',
    'blogpack_toc_6' => 'What to leave at home',
    'blogpack_toc_7' => 'FAQ',
    'blogpack_s1_badge' => 'The principle',
    'blogpack_s1_title' => 'The one rule that matters',
    'blogpack_s1_p1' => '<strong>Dress in layers.</strong> A safari day starts at around 14 °C (5 °C on the Ngorongoro rim) and reaches 28 °C by midday, and you will experience both from an open vehicle. One warm coat is the wrong answer; a base layer, a fleece and a windproof shell is the right one.',
    'blogpack_s1_p2' => 'The second rule, if you have internal flights: <strong>15 kg in a soft bag</strong>. Light aircraft in Tanzania enforce this strictly, and hard-shell suitcases are refused because they do not fit the hold. Most lodges offer same-day laundry, so packing for four days rather than ten is almost always the right call.',
    'blogpack_s2_badge' => 'Clothing',
    'blogpack_s2_title' => 'Clothing',
    'blogpack_s2_i1_t' => 'Fleece or insulated jacket',
    'blogpack_s2_i1_d' => 'essential, and the most commonly forgotten item',
    'blogpack_s2_i2_t' => 'Windproof shell',
    'blogpack_s2_i2_d' => 'the wind chill in an open vehicle at dawn is significant',
    'blogpack_s2_i3_t' => 'Long-sleeved shirts',
    'blogpack_s2_i3_d' => 'sun and mosquito protection',
    'blogpack_s2_i4' => 'T-shirts in breathable fabric',
    'blogpack_s2_i5' => 'Lightweight long trousers, more useful than shorts',
    'blogpack_s2_i6' => 'Wide-brimmed hat and sunglasses',
    'blogpack_s2_i7_t' => 'Closed comfortable shoes',
    'blogpack_s2_i7_d' => 'boots only if you are trekking',
    'blogpack_s2_i8_t' => 'A buff or scarf',
    'blogpack_s2_i8_d' => 'dry-season dust is relentless',
    'blogpack_s2_i9' => 'Swimwear, many lodges have pools',
    'blogpack_s2_i10' => 'Something smart-casual for dinner at the better lodges',
    'blogpack_s2_sub1' => 'Colours matter more than you think',
    'blogpack_s2_p1' => 'Wear <strong>khaki, olive, beige and brown</strong>. There are three specific things to avoid:',
    'blogpack_s2_n1_t' => 'Blue and black',
    'blogpack_s2_n1_d' => 'attract tsetse flies, which are present in Tarangire and the miombo woodland of the southern parks. Their bite is painful.',
    'blogpack_s2_n2_t' => 'White',
    'blogpack_s2_n2_d' => 'stops being white after half a day on a dusty track.',
    'blogpack_s2_n3_t' => 'Camouflage is illegal for civilians in Tanzania.',
    'blogpack_s2_n3_d' => 'It is reserved for the military, and wearing it can genuinely cause problems.',
    'blogpack_s3_badge' => 'Health',
    'blogpack_s3_title' => 'Medical kit and toiletries',
    'blogpack_s3_i1_t' => 'Antimalarial tablets',
    'blogpack_s3_i1_d' => 'prescribed by your doctor',
    'blogpack_s3_i2_t' => 'DEET insect repellent',
    'blogpack_s3_i2_d' => 'the strongest concentration you tolerate',
    'blogpack_s3_i3_t' => 'High-factor sunscreen',
    'blogpack_s3_i3_d' => 'and lip balm with SPF; UV at altitude is fierce',
    'blogpack_s3_i4' => 'Painkillers, anti-diarrhoeal and rehydration salts',
    'blogpack_s3_i5' => 'Plasters, antiseptic, blister treatment',
    'blogpack_s3_i6' => 'Any prescription medication <strong>in your hand luggage</strong>, with a copy of the prescription',
    'blogpack_s3_i7' => 'Hand sanitiser and wet wipes, genuinely useful on long drives',
    'blogpack_s3_i8' => 'Motion sickness tablets if you are prone; the tracks are rough',
    'blogpack_s3_link' => 'Full guide to vaccinations and health',
    'blogpack_s4_badge' => 'Photography',
    'blogpack_s4_title' => 'Photography and optics',
    'blogpack_tag_binoculars' => 'Binoculars',
    'blogpack_tag_lens' => '300mm+ lens',
    'blogpack_tag_wide' => 'Wide-angle lens',
    'blogpack_tag_battery' => 'Spare batteries',
    'blogpack_tag_memory' => 'Memory cards',
    'blogpack_tag_dustbag' => 'Dust-proof bag',
    'blogpack_tag_beanbag' => 'Bean bag',
    'blogpack_s4_p1' => '<strong>Binoculars</strong> are the single most under-packed item. Many sightings, particularly rhino in the crater, are simply too distant for a camera. Bring <strong>a 300 mm lens or longer</strong> if you are serious about wildlife photographs, but <strong>a wide-angle lens too</strong>: baobabs, the crater, the plains at dawn. You will regret only bringing a telephoto. Camps often run generators for limited hours only, so bring spare batteries and more memory cards than you think. A dust-proof bag matters: dry-season dust gets into everything, and changing lenses in a moving vehicle is how sensors get ruined. A bean bag or substitute is useful for steadying long lenses on the roof hatch.',
    'blogpack_s5_badge' => 'Documents',
    'blogpack_s5_title' => 'Documents and money',
    'blogpack_s5_i1_t' => 'Passport',
    'blogpack_s5_i1_d' => 'valid at least six months beyond entry, with two blank pages',
    'blogpack_s5_i2_t' => 'Printed visa confirmation',
    'blogpack_s5_i2_d' => 'and travel insurance policy',
    'blogpack_s5_i3_t' => 'Yellow fever certificate',
    'blogpack_s5_i3_d' => 'if you are arriving from or transiting a risk country',
    'blogpack_s5_i4' => '<strong>US dollars in cash</strong> for tips and extras, and this matters: <strong>notes must be issued after 2009</strong>. Older notes are refused throughout Tanzania.',
    'blogpack_s5_i5' => 'Small denominations for tipping ($1, $5, $10)',
    'blogpack_s5_i6' => 'A credit card as backup, though connectivity is unreliable',
    'blogpack_s5_i7_t' => 'Type G plug adapter',
    'blogpack_s5_i7_d' => 'the British three-pin standard',
    'blogpack_s5_i8' => 'Digital copies of everything, stored somewhere you can reach offline',
    'blogpack_s6_badge' => 'Do not bring',
    'blogpack_s6_title' => 'What to leave at home',
    'blogpack_s6_i1_t' => 'Hard-shell suitcases',
    'blogpack_s6_i1_d' => 'if you have internal flights, they will be refused',
    'blogpack_s6_i2_t' => 'Camouflage clothing',
    'blogpack_s6_i2_d' => 'illegal for civilians',
    'blogpack_s6_i3_t' => 'Single-use plastic bags',
    'blogpack_s6_i3_d' => 'banned throughout Tanzania since 2019, and confiscated at the airport',
    'blogpack_s6_i4_t' => 'Drones',
    'blogpack_s6_i4_d' => 'they require written TANAPA permission, which is rarely granted',
    'blogpack_s6_i5_t' => 'A hairdryer',
    'blogpack_s6_i5_d' => 'most lodges have them, and they drain limited generator power',
    'blogpack_s6_i6_t' => 'Ten days of clothes',
    'blogpack_s6_i6_d' => 'laundry is available almost everywhere and usually same-day',
    'blogpack_s6_i7_t' => 'Valuable jewellery',
    'blogpack_s6_i7_d' => 'there is nowhere to wear it and nowhere secure to leave it',
    'blogpack_tip_t' => 'The most useful single tip:',
    'blogpack_tip_d' => 'pack for four days, not ten, and use the laundry. Almost every traveller we host says afterwards that they brought roughly twice what they needed.',
    'blogpack_faq_badge' => 'FAQ',
    'blogpack_faq_title' => 'Safari packing: frequently asked questions',
    'blogpack_faq_q1' => 'What should I wear on safari?',
    'blogpack_faq_a1' => 'Layers in neutral colours: khaki, olive, beige, brown. Mornings are around 14 °C and afternoons near 28 °C, and you will experience both from an open vehicle. Avoid blue and black, which attract tsetse flies.',
    'blogpack_faq_q2' => 'Why should I avoid blue and black clothing?',
    'blogpack_faq_a2' => 'Tsetse flies are attracted to those colours, and they are present in Tarangire and the miombo woodland of the southern parks. The bite is painful, though there is no sleeping sickness risk in the main tourist areas.',
    'blogpack_faq_q3' => 'Can I wear camouflage clothing?',
    'blogpack_faq_a3' => 'No. Camouflage is reserved for the military in Tanzania and is illegal for civilians. Wearing it can cause genuine problems at checkpoints, so leave it at home.',
    'blogpack_faq_q4' => 'What is the baggage limit on internal flights?',
    'blogpack_faq_a4' => '15 kg in a soft bag, strictly enforced on light aircraft. Hard-shell suitcases are refused because they do not fit the hold. If you have a larger bag, most Arusha hotels will store it while you fly.',
    'blogpack_faq_q5' => 'Do I need hiking boots for a safari?',
    'blogpack_faq_a5' => 'No. Comfortable closed shoes are enough for a game-drive safari, since you spend most of your time in a vehicle. Proper boots are only needed for Kilimanjaro, Mount Meru or serious walking safaris.',
    'blogpack_faq_q6' => 'How cold does it actually get?',
    'blogpack_faq_a6' => 'The Ngorongoro rim drops to around 5 °C before dawn and the Serengeti to 13–15 °C. In an open vehicle moving at 30 km/h it feels considerably colder. A fleece and a windproof layer are not optional.',
    'blogpack_faq_q7' => 'Should I bring binoculars?',
    'blogpack_faq_a7' => 'Yes, and they are the most commonly forgotten item. Many sightings, rhino in the Ngorongoro Crater above all, are too distant for a camera lens but perfect through binoculars.',
    'blogpack_faq_q8' => 'What camera equipment do I need?',
    'blogpack_faq_a8' => 'A 300 mm lens or longer for wildlife, plus a wide-angle for landscapes. Bring spare batteries, since camps often run generators only at set hours, and a dust-proof bag, since dry-season dust destroys sensors.',
    'blogpack_faq_q9' => 'Can I do laundry on safari?',
    'blogpack_faq_a9' => 'Yes, at almost every lodge and camp, usually same-day. This is why packing for four days rather than ten is nearly always the right decision, particularly with a 15 kg flight limit.',
    'blogpack_faq_q10' => 'What money should I bring?',
    'blogpack_faq_a10' => 'US dollars in cash for tips and extras, in notes issued after 2009. Older notes are refused throughout Tanzania. Bring small denominations for tipping. Cards work at lodges but connectivity is unreliable.',
    'blogpack_faq_q11' => 'Are plastic bags really banned?',
    'blogpack_faq_a11' => 'Yes, since 2019, and it is enforced at the airport where they are confiscated on arrival. Bring fabric or mesh bags instead. Ziplock bags for toiletries are generally tolerated but the safest approach is to avoid all of them.',
    'blogpack_faq_q12' => 'Do I need a plug adapter?',
    'blogpack_faq_a12' => 'Yes, type G, the British three-pin standard. Voltage is 230V. Bring a multi-socket adapter if you have several devices, because camps often have only one or two sockets per tent.',
    'blogpack_faq_q13' => 'Can I bring a drone?',
    'blogpack_faq_a13' => 'Only with written permission from TANAPA, which is rarely granted for tourism. Flying without it risks confiscation and a fine. Assume the answer is no unless you have paperwork in hand.',
    'blogpack_related_badge' => 'Keep reading',
    'blogpack_related_title' => 'Continue exploring Tanzania',
    'blogpack_related_trekking' => 'Kilimanjaro packing differs',
    'blogpack_final_title' => 'Questions about what to bring?',
    'blogpack_final_intro' => 'Send us your itinerary and we will tell you exactly what you need for those specific parks and that season, including whether the 15 kg flight limit applies to you.',
    'blogpack_final_whatsapp' => 'Message us on WhatsApp',
    'blogpack_final_contact' => 'Contact form',

    // ===== Blog article: Vaccinations and Health =====
    'blogvax_meta_title' => 'Tanzania Vaccinations and Health Guide (2026) | Serengeti Budget Safari',
    'blogvax_meta_description' => 'What you actually need before travelling to Tanzania: vaccinations, malaria, water, altitude and the insurance clause most people overlook. Information, not medical advice.',
    'blogvax_updated' => 'Updated 2026',
    'blogvax_h1' => 'Vaccinations and health',
    'blogvax_hero_sub' => 'What you actually need before travelling to Tanzania: vaccinations, malaria, water, altitude and the insurance clause most people overlook.',
    'blogvax_author' => 'Serengeti Budget Safari Team',
    'blogvax_date' => 'August 2026',
    'blogvax_quick_badge' => 'Quick answers',
    'blogvax_quick_title' => 'Health in short',
    'blogvax_quick_intro' => 'The essentials, but see a travel clinic six to eight weeks ahead.',
    'blogvax_qq1_q' => 'Compulsory vaccination?',
    'blogvax_qq1_a' => 'Yellow fever only, and only from risk countries.',
    'blogvax_qq2_q' => 'Malaria?',
    'blogvax_qq2_a' => 'Yes, everywhere including Zanzibar. Take prophylaxis.',
    'blogvax_qq3_q' => 'Tap water?',
    'blogvax_qq3_a' => 'No. Bottled or filtered only.',
    'blogvax_qq4_q' => 'Insurance?',
    'blogvax_qq4_a' => 'Compulsory, and must cover evacuation.',
    'blogvax_qq5_q' => 'Climbing Kilimanjaro?',
    'blogvax_qq5_a' => 'Policy must cover trekking to 6,000 m.',
    'blogvax_qq6_q' => 'When to see a doctor?',
    'blogvax_qq6_a' => 'Six to eight weeks before you travel.',
    'blogvax_see_faq' => 'See all FAQs',
    'blogvax_toc_title' => 'Contents – Vaccinations and health',
    'blogvax_toc_1' => 'Read this first',
    'blogvax_toc_2' => 'Vaccinations',
    'blogvax_toc_3' => 'Malaria',
    'blogvax_toc_4' => 'Food & water',
    'blogvax_toc_5' => 'Altitude',
    'blogvax_toc_6' => 'Travel insurance',
    'blogvax_toc_7' => 'Other health points',
    'blogvax_toc_8' => 'FAQ',
    'blogvax_s0_badge' => 'Important',
    'blogvax_s0_title' => 'Before anything else',
    'blogvax_s0_warn_t' => 'This page is information, not medical advice.',
    'blogvax_s0_warn_d' => 'Speak to your doctor or a travel health clinic <strong>six to eight weeks before you travel</strong>. Requirements depend on your medical history, your exact itinerary and your routing, and only a clinician can advise you properly.',
    'blogvax_s0_p1' => 'With that said, here is what most travellers to Tanzania need to think about.',
    'blogvax_s1_badge' => 'Vaccinations',
    'blogvax_s1_title' => 'Vaccinations',
    'blogvax_s1_sub1' => 'Required in one specific case',
    'blogvax_s1_p1' => '<strong>Yellow fever</strong> is the only vaccination that is a legal entry requirement, and only if you are arriving from, or have transited more than 12 hours through, a country with yellow fever risk. Direct flights from Europe do not require it; a long layover in Nairobi or Addis Ababa may.',
    'blogvax_s1_sub2' => 'Recommended',
    'blogvax_t1_h1' => 'Vaccination',
    'blogvax_t1_h2' => 'Why',
    'blogvax_t1_h3' => 'Who',
    'blogvax_t1_r1_a' => 'Hepatitis A',
    'blogvax_t1_r1_b' => 'Food and water transmission',
    'blogvax_t1_r1_c' => 'All travellers',
    'blogvax_t1_r2_a' => 'Typhoid',
    'blogvax_t1_r2_b' => 'Food and water transmission',
    'blogvax_t1_r2_c' => 'Most travellers',
    'blogvax_t1_r3_a' => 'Tetanus, diphtheria, polio',
    'blogvax_t1_r3_b' => 'Routine boosters',
    'blogvax_t1_r3_c' => 'Check you are current',
    'blogvax_t1_r4_a' => 'Hepatitis B',
    'blogvax_t1_r4_b' => 'Blood and bodily fluids',
    'blogvax_t1_r4_c' => 'Longer stays',
    'blogvax_t1_r5_a' => 'Rabies',
    'blogvax_t1_r5_b' => 'Animal bites',
    'blogvax_t1_r5_c' => 'Long rural stays, or working with animals',
    'blogvax_t1_r6_a' => 'Meningitis ACWY',
    'blogvax_t1_r6_b' => 'Seasonal risk in parts of Africa',
    'blogvax_t1_r6_c' => 'Ask your doctor',
    'blogvax_s2_badge' => 'Malaria',
    'blogvax_s2_title' => 'Malaria: the one that matters most',
    'blogvax_s2_p1' => 'Malaria is present throughout Tanzania, <strong>including Zanzibar</strong>. Risk is lower at altitude (Arusha, Ngorongoro and the Serengeti highlands) and higher on the coast and in the low-lying southern parks such as Nyerere and Mikumi.',
    'blogvax_s2_sub1' => 'Prophylaxis',
    'blogvax_s2_p2' => 'Your doctor will prescribe one of the standard options (atovaquone/proguanil, doxycycline or mefloquine), each with different dosing schedules and side effects. Take it exactly as directed, including the doses <em>after</em> you return, which is the part people forget.',
    'blogvax_s2_sub2' => 'Bite prevention matters just as much',
    'blogvax_s2_p3' => 'No prophylaxis is 100% effective, so the physical measures are not optional:',
    'blogvax_s2_b1_t' => 'DEET repellent',
    'blogvax_s2_b1_d' => 'on exposed skin, reapplied at dusk',
    'blogvax_s2_b2_t' => 'Long sleeves and trousers',
    'blogvax_s2_b2_d' => 'after sunset, since the malarial mosquito bites between dusk and dawn',
    'blogvax_s2_b3_t' => 'Sleep under the net',
    'blogvax_s2_b3_d' => 'provided; check it for holes',
    'blogvax_s2_b4_t' => 'Air conditioning or a fan',
    'blogvax_s2_b4_d' => 'overnight where available',
    'blogvax_s2_warn_t' => 'After you get home:',
    'blogvax_s2_warn_d' => 'if you develop a fever within twelve months of returning, and particularly within the first three months, see a doctor immediately and tell them you have been in a malaria area. Malaria is entirely treatable when caught early and dangerous when it is not.',
    'blogvax_s3_badge' => 'Food & water',
    'blogvax_s3_title' => 'Food and water',
    'blogvax_s3_i1_t' => 'Drink only bottled or filtered water.',
    'blogvax_s3_i1_d' => 'It is provided in our vehicles throughout every game drive.',
    'blogvax_s3_i2' => 'Avoid ice where you are unsure of the water source.',
    'blogvax_s3_i3' => 'Peel fruit yourself.',
    'blogvax_s3_i4' => 'Lodge and camp food is prepared to a high standard and is safe.',
    'blogvax_s3_i5' => 'For street food, apply the usual test: freshly cooked, served hot, and busy with locals.',
    'blogvax_s3_i6' => 'Brush your teeth with bottled water if your stomach is sensitive.',
    'blogvax_s3_p1' => 'Travellers\' diarrhoea is the most common complaint, and it is usually mild. Bring rehydration salts and an anti-diarrhoeal, and see a doctor if it lasts more than a couple of days or involves fever or blood.',
    'blogvax_s4_badge' => 'Altitude',
    'blogvax_s4_title' => 'Altitude',
    'blogvax_s4_p1' => 'Most safari travellers will not have altitude problems, but two places are worth knowing about.',
    'blogvax_s4_p2' => 'The Ngorongoro rim sits at 2,200–2,400 m. A mild headache on the first night is common. Drink more water than you think you need and it usually passes.',
    'blogvax_s4_p3' => 'Kilimanjaro is a different matter entirely. At 5,895 m there is roughly half the oxygen available at sea level, and altitude sickness is the main reason climbs fail. Symptoms, prevention and the warning signs are covered in detail on our',
    'blogvax_s4_link' => 'Kilimanjaro guide',
    'blogvax_s5_badge' => 'Insurance',
    'blogvax_s5_title' => 'Travel insurance',
    'blogvax_s5_p1' => 'Travel insurance is <strong>compulsory</strong> on our trips, and this is not a formality. Inside the parks the nearest hospital can be hours away by road, and serious cases are flown to Arusha, Dar es Salaam or Nairobi. Medical evacuation costs many thousands of dollars.',
    'blogvax_s5_p2' => 'Your policy must cover:',
    'blogvax_s5_i1_t' => 'Medical expenses',
    'blogvax_s5_i1_d' => 'and hospital treatment',
    'blogvax_s5_i2' => 'Emergency evacuation and repatriation',
    'blogvax_s5_i3_t' => 'Trekking to 6,000 m',
    'blogvax_s5_i3_d' => 'if you are climbing Kilimanjaro or Meru, many standard policies exclude high-altitude activity, and this is the single most common gap',
    'blogvax_s5_i4' => 'Trip cancellation, which we also recommend',
    'blogvax_s5_p3' => 'For Zanzibar, remember the separate <strong>mandatory local insurance (~$44)</strong> introduced in 2024, which your normal policy does not replace.',
    'blogvax_s6_badge' => 'Practical',
    'blogvax_s6_title' => 'Other practical health points',
    'blogvax_s6_i1_t' => 'Sun.',
    'blogvax_s6_i1_d' => 'UV at 1,500–2,400 m near the equator is severe even when the air is cool. High-factor sunscreen, a hat and sunglasses, every day.',
    'blogvax_s6_i2_t' => 'Tsetse flies.',
    'blogvax_s6_i2_d' => 'Present in Tarangire and the southern miombo. The bite hurts; sleeping sickness is not a practical risk in the tourist areas. Avoid blue and black clothing.',
    'blogvax_s6_i3_t' => 'Dust.',
    'blogvax_s6_i3_d' => 'Dry-season dust irritates eyes and airways. Bring a buff, and eye drops if you wear contact lenses.',
    'blogvax_s6_i4_t' => 'Schistosomiasis (bilharzia).',
    'blogvax_s6_i4_d' => 'Present in some fresh water. Do not swim in lakes or rivers unless your guide confirms it is safe.',
    'blogvax_s6_i5_t' => 'Prescription medicines.',
    'blogvax_s6_i5_d' => 'Carry them in hand luggage in original packaging with a copy of the prescription.',
    'blogvax_s6_i6_t' => 'Pharmacies.',
    'blogvax_s6_i6_d' => 'Arusha and Moshi have well-stocked ones. Inside the parks there are none, so bring what you need.',
    'blogvax_faq_badge' => 'FAQ',
    'blogvax_faq_title' => 'Health and vaccinations: frequently asked questions',
    'blogvax_faq_q1' => 'What vaccinations do I need for Tanzania?',
    'blogvax_faq_a1' => 'Yellow fever is a legal requirement only if you arrive from or transit a risk country. Hepatitis A and typhoid are recommended for most travellers, along with routine tetanus, diphtheria and polio boosters. See a travel clinic six to eight weeks ahead.',
    'blogvax_faq_q2' => 'Do I need a yellow fever vaccination?',
    'blogvax_faq_a2' => 'Only if you are arriving from, or have transited more than 12 hours through, a yellow fever risk country. Travellers flying directly from Europe do not need it, but a long layover in Nairobi or Addis Ababa may trigger the requirement.',
    'blogvax_faq_q3' => 'Is there malaria in Tanzania?',
    'blogvax_faq_a3' => 'Yes, throughout the country including Zanzibar. Risk is lower at altitude in Arusha and the Ngorongoro highlands, and higher on the coast and in the low-lying southern parks. Prophylaxis plus bite prevention is the standard approach.',
    'blogvax_faq_q4' => 'Which antimalarial should I take?',
    'blogvax_faq_a4' => 'That is a decision for your doctor. The common options are atovaquone/proguanil, doxycycline and mefloquine, each with different dosing and side effects. Take the full course including the doses after you return home.',
    'blogvax_faq_q5' => 'Is there malaria in Zanzibar?',
    'blogvax_faq_a5' => 'Yes. Zanzibar is a malaria area and being on the coast means the risk is higher than in the northern highlands, not lower. Take the same precautions there as on safari.',
    'blogvax_faq_q6' => 'Can I drink the tap water?',
    'blogvax_faq_a6' => 'No. Drink bottled or filtered water only, avoid ice where you are unsure of the source, and peel your own fruit. Drinking water is provided in our vehicles throughout every game drive.',
    'blogvax_faq_q7' => 'Do I need travel insurance?',
    'blogvax_faq_a7' => 'Yes, it is compulsory on our trips. It must cover medical expenses and emergency evacuation, because the nearest hospital to a park can be hours away and serious cases are flown out at considerable cost.',
    'blogvax_faq_q8' => 'Does my insurance need to cover altitude?',
    'blogvax_faq_a8' => 'If you are climbing Kilimanjaro or Mount Meru, yes, it must explicitly cover trekking to 6,000 m. Many standard travel policies exclude high-altitude activity, and this is the most common gap we see.',
    'blogvax_faq_q9' => 'What if I get sick on safari?',
    'blogvax_faq_a9' => 'Tell your guide immediately. Guides carry first-aid kits and know the nearest facilities. Arusha and Moshi have good private clinics; from remote parks, serious cases are evacuated by air, which is what your insurance is for.',
    'blogvax_faq_q10' => 'Is there altitude sickness on safari?',
    'blogvax_faq_a10' => 'Rarely. The Ngorongoro rim at 2,200–2,400 m can cause a mild headache on the first night, usually resolved by drinking more water. Kilimanjaro is an entirely different matter and is covered in our Kilimanjaro guide.',
    'blogvax_faq_q11' => 'Are tsetse flies dangerous?',
    'blogvax_faq_a11' => 'The bite is painful but sleeping sickness is not a practical risk in the main tourist areas. They are present in Tarangire and the southern miombo woodland, and are attracted to dark blue and black clothing.',
    'blogvax_faq_q12' => 'Can I swim in lakes and rivers?',
    'blogvax_faq_a12' => 'Not unless your guide confirms it is safe. Bilharzia is present in some fresh water, and hippos and crocodiles are present in much of it. Lodge pools are fine, and the hot springs at Maji Moto in Nyerere are safe to swim in.',
    'blogvax_faq_q13' => 'What if I develop a fever after returning home?',
    'blogvax_faq_a13' => 'See a doctor immediately and tell them you have been in a malaria area. Malaria can appear up to twelve months after exposure, most commonly within three months. It is entirely treatable when caught early.',
    'blogvax_related_badge' => 'Keep reading',
    'blogvax_related_title' => 'Continue exploring Tanzania',
    'blogvax_related_contact' => 'Ask us a question',
    'blogvax_final_title' => 'Questions about your trip?',
    'blogvax_final_intro' => 'We cannot give medical advice, but we can tell you exactly which areas and altitudes your itinerary covers, useful information to take to your travel clinic.',
    'blogvax_final_whatsapp' => 'Message us on WhatsApp',
    'blogvax_final_contact' => 'Contact form',

    // ===== Blog article: Serengeti vs Ngorongoro =====
    'blogsvn_meta_title' => 'Serengeti vs Ngorongoro: Which Should You Choose? | Serengeti Budget Safari',
    'blogsvn_meta_description' => 'Serengeti or Ngorongoro Crater: an honest comparison of size, cost, wildlife density and what each actually delivers, from an operator who runs both.',
    'blogsvn_updated' => 'Updated 2026',
    'blogsvn_h1' => 'Serengeti vs Ngorongoro',
    'blogsvn_hero_sub' => 'Two of Tanzania\'s best-known parks, next door to each other and completely different in character. Which one fits your trip?',
    'blogsvn_quick_badge' => 'Quick answers',
    'blogsvn_quick_title' => 'Serengeti or Ngorongoro, in short',
    'blogsvn_quick_intro' => 'The headline differences before the detail.',
    'blogsvn_qq1_q' => 'Which is bigger?',
    'blogsvn_qq1_a' => 'The Serengeti, by far: 14,763 km² against the crater\'s 260 km².',
    'blogsvn_qq2_q' => 'Which has rhino?',
    'blogsvn_qq2_a' => 'Ngorongoro. The Serengeti has almost none.',
    'blogsvn_qq3_q' => 'Which has the migration?',
    'blogsvn_qq3_a' => 'The Serengeti, most of the year. Ngorongoro only sees it briefly.',
    'blogsvn_qq4_q' => 'Which takes less time?',
    'blogsvn_qq4_a' => 'Ngorongoro, one full day covers the crater.',
    'blogsvn_qq5_q' => 'Which costs more?',
    'blogsvn_qq5_a' => 'Ngorongoro, once you add the $295 crater descent fee.',
    'blogsvn_qq6_q' => 'Can I do both?',
    'blogsvn_qq6_a' => 'Yes, and most itineraries do. They are next door to each other.',
    'blogsvn_see_faq' => 'See all FAQs',
    'blogsvn_toc_title' => 'Contents – Serengeti vs Ngorongoro',
    'blogsvn_toc_1' => 'The short answer',
    'blogsvn_toc_2' => 'Side by side',
    'blogsvn_toc_3' => 'What the Serengeti does best',
    'blogsvn_toc_4' => 'What Ngorongoro does best',
    'blogsvn_toc_5' => 'Doing both',
    'blogsvn_toc_6' => 'FAQ',
    'blogsvn_s1_badge' => 'In brief',
    'blogsvn_s1_title' => 'The short answer',
    'blogsvn_s1_p1' => 'They are not really competitors. Most itineraries visit <strong>both</strong>, because they sit next to each other and do different jobs. The Serengeti is vast, varied, and home to the Great Migration for most of the year. The Ngorongoro Crater is small, self-contained, and delivers the densest concentration of wildlife in Africa in a single day, including the black rhino the Serengeti largely lacks.',
    'blogsvn_s1_p2' => 'If you can only choose one: pick the Serengeti for scale and the migration, pick Ngorongoro if your time is very short and you want maximum wildlife per hour.',
    'blogsvn_cta_label' => 'See Both On One Trip',
    'blogsvn_s2_badge' => 'Comparison',
    'blogsvn_s2_title' => 'Side by side',
    'blogsvn_t1_h1' => 'Factor',
    'blogsvn_t1_r1_a' => 'Size',
    'blogsvn_crater_floor' => 'crater floor',
    'blogsvn_t1_r2_a' => 'Established',
    'blogsvn_t1_r3_a' => 'Status',
    'blogsvn_t1_r3_b' => 'UNESCO World Heritage Site',
    'blogsvn_t1_r3_c' => 'UNESCO World Heritage Site',
    'blogsvn_t1_r4_a' => 'Entry fee (2026)',
    'blogsvn_per_vehicle' => 'per vehicle to descend',
    'blogsvn_t1_r5_a' => 'Best for',
    'blogsvn_t1_r5_b' => 'Scale, variety, the migration',
    'blogsvn_t1_r5_c' => 'Density, rhino, a single unforgettable day',
    'blogsvn_t1_r6_a' => 'Lions',
    'blogsvn_t1_r6_c' => '~60 (in 260 km²)',
    'blogsvn_t1_r7_a' => 'Black rhino',
    'blogsvn_t1_r8_a' => 'Typical visit length',
    'blogsvn_t1_r8_b' => '2–4 nights',
    'blogsvn_t1_r8_c' => '1 full day',
    'blogsvn_s2_note' => 'Figures from our own park guides. See the full Serengeti and Ngorongoro pages for detail.',
    'blogsvn_s3_badge' => 'Serengeti',
    'blogsvn_s3_title' => 'What the Serengeti does best',
    'blogsvn_s3_p1' => 'The Serengeti is Tanzania\'s flagship park for a reason: it is enormous, ecologically varied, and holds one of the highest lion densities in Africa. It is also the year-round home of the Great Migration. The herds are somewhere inside the ecosystem in every single month, moving in a continuous circuit driven by rainfall.',
    'blogsvn_s3_i1' => 'Endless plains and varied habitats, from open grassland to riverine forest',
    'blogsvn_s3_i2' => 'The Great Migration, in some form, almost every month of the year',
    'blogsvn_s3_i3' => 'Some of the best leopard viewing in Tanzania, especially the Seronera valley',
    'blogsvn_s3_p2' => 'What it does not have: meaningful numbers of black rhino, and a genuinely private feeling in peak season near the popular central areas.',
    'blogsvn_s3_link' => 'Full Serengeti park guide',
    'blogsvn_s4_badge' => 'Ngorongoro',
    'blogsvn_s4_title' => 'What Ngorongoro does best',
    'blogsvn_s4_p1' => 'The Ngorongoro Crater is a collapsed volcanic caldera, 260 km² of grassland walled in by a 600-metre rim. Nothing migrates out, so wildlife density is extraordinary. Roughly 25,000 large animals live inside it year-round, visible from a single day\'s game drive.',
    'blogsvn_s4_i1' => 'The most reliable place in Tanzania to see black rhino, with around 30 living under protection',
    'blogsvn_s4_i2' => 'Unmatched wildlife density for the time invested, one day, not several',
    'blogsvn_s4_i3' => 'Spectacular scenery from the rim, looking down into the crater floor',
    'blogsvn_s4_warn_t' => 'The catch:',
    'blogsvn_s4_warn_d' => 'a separate $295 per-vehicle fee just to descend into the crater, charged every time you go down, on top of the standard park entry. It drops sharply per person as your group grows.',
    'blogsvn_s4_p2' => 'What it does not have: the Serengeti\'s scale, or the migration for most of the year. Ngorongoro is technically part of the same ecosystem (the calving grounds at Ndutu sit inside the Conservation Area), but the crater floor itself sees the herds only briefly.',
    'blogsvn_s4_link' => 'Full Ngorongoro park guide',
    'blogsvn_s5_badge' => 'Together',
    'blogsvn_s5_title' => 'Why most people do both',
    'blogsvn_s5_p1' => 'The two parks are adjacent, connected by a short drive, which is why the vast majority of northern-circuit itineraries combine them rather than choosing one. A typical shape: two or three nights in the Serengeti for the space and variety, then one night at or near the crater rim for an early descent the following morning. The crater is best done at first light, before the day-trippers arrive from Karatu.',
    'blogsvn_s5_p2' => 'Our own <strong>5-Day Serengeti & Ngorongoro Safari</strong> is built around exactly this combination.',
    'blogsvn_faq_badge' => 'FAQ',
    'blogsvn_faq_title' => 'Serengeti vs Ngorongoro: frequently asked questions',
    'blogsvn_faq_q1' => 'Is Ngorongoro part of the Serengeti?',
    'blogsvn_faq_a1' => 'No, they are separate protected areas administered differently (the Serengeti by TANAPA, Ngorongoro by the NCAA), though they are ecologically connected and adjacent to each other.',
    'blogsvn_faq_q2' => 'Which is better for the Big Five?',
    'blogsvn_faq_a2' => 'Together, not separately. The Serengeti gives you lion, leopard, elephant and buffalo easily; Ngorongoro is essentially the only reliable place in Tanzania for black rhino. Visiting both is how most travellers complete the set.',
    'blogsvn_faq_q3' => 'How many days do I need for Ngorongoro?',
    'blogsvn_faq_a3' => 'One full day covers the crater floor thoroughly. It is small enough that a single game drive, done early, sees most of what there is to see.',
    'blogsvn_faq_q4' => 'How many days do I need for the Serengeti?',
    'blogsvn_faq_a4' => 'Two to four nights minimum to appreciate its scale. Which region you stay in should match the month, since the migration moves through different parts of the park across the year.',
    'blogsvn_faq_q5' => 'Why is Ngorongoro so much more expensive per day?',
    'blogsvn_faq_a5' => 'The $295 crater descent fee, charged per vehicle every time you go down. Spread across a group it becomes reasonable, roughly $50 each for six people, but for two people it is a real cost on top of standard park entry.',
    'blogsvn_faq_q6' => 'Can I skip one and just do the other?',
    'blogsvn_faq_a6' => 'Yes. If your time is very short, Ngorongoro alone delivers dense wildlife viewing in a single day. If you have a week or more, the Serengeti alone gives you scale and variety. Most travellers with 4+ days do both.',
    'blogsvn_related_parks' => 'All parks compared',
    'blogsvn_final_title' => 'Still deciding between the two?',
    'blogsvn_final_intro' => 'Tell us how many days you have and what matters most to you. We will tell you honestly whether to do one, the other, or both.',

