    // ===== Privacy Policy =====
    'privacy_meta_title' => 'Privacy Policy | Serengeti Budget Safari',
    'privacy_meta_description' => 'How Serengeti Budget Safari collects, uses and protects your personal data, and the rights you have under the GDPR.',
    'privacy_h1' => 'Privacy Policy',
    'privacy_intro' => 'This notice explains what personal data <strong>Serengeti Budget Safari</strong> collects when you visit this website or ask us for a quote, why we process it, and what rights you have. We handle personal data in line with EU Regulation 2016/679 (GDPR).',
    'privacy_h2_1' => '1. Who we are',
    'privacy_h2_2' => '2. What we collect',
    'privacy_h3_1' => 'Information you give us',
    'privacy_you_i1' => 'your name;',
    'privacy_you_i2' => 'email address and phone number;',
    'privacy_you_i3' => 'country of residence;',
    'privacy_you_i4' => 'travel dates, number of travellers and the preferences in your enquiry;',
    'privacy_you_i5' => 'anything else you choose to tell us (dietary requirements, accessibility needs, special occasions).',
    'privacy_h3_2' => 'Information collected automatically',
    'privacy_auto_i1' => 'IP address, browser and device type;',
    'privacy_auto_i2' => 'pages visited and the date and time of your visit;',
    'privacy_auto_i3' => 'the site you arrived from.',
    'privacy_h2_3' => '3. Why we process it',
    'privacy_why_i1' => '<strong>To answer your enquiry</strong> and prepare a quote. Lawful basis: steps taken at your request before entering a contract (Art. 6(1)(b) GDPR).',
    'privacy_why_i2' => '<strong>To organise and run the trip</strong> you have booked. Lawful basis: performance of a contract (Art. 6(1)(b) GDPR).',
    'privacy_why_i3' => '<strong>To meet tax and accounting obligations</strong>. Lawful basis: legal obligation (Art. 6(1)(c) GDPR).',
    'privacy_why_i4' => '<strong>To improve this website</strong> using aggregated statistics. Lawful basis: legitimate interest (Art. 6(1)(f) GDPR).',
    'privacy_why_note' => 'We do not send marketing messages without your explicit consent, and we never sell your data.',
    'privacy_h2_4' => '4. Who we share it with',
    'privacy_share_intro' => 'We share your details only with those who need them to deliver your trip:',
    'privacy_share_i1' => 'lodges, tented camps and hotels where you stay;',
    'privacy_share_i2' => 'airlines operating internal flights, and transfer companies;',
    'privacy_share_i3' => 'national park authorities, where entry permits require visitor details;',
    'privacy_share_i4' => 'technical suppliers for this website (hosting, email);',
    'privacy_share_i5' => 'public authorities, where the law requires it.',
    'privacy_share_note' => 'Because we operate from Tanzania, your data is also processed outside the European Economic Area. This transfer is made under Art. 49(1)(b) GDPR, as it is necessary to perform the travel contract you have requested.',
    'privacy_h2_5' => '5. How long we keep it',
    'privacy_keep_i1' => '<strong>Enquiries that did not lead to a booking:</strong> 24 months from last contact.',
    'privacy_keep_i2' => '<strong>Confirmed trips:</strong> 10 years, for accounting and tax purposes.',
    'privacy_keep_i3' => '<strong>Website analytics:</strong> up to 26 months in aggregated form.',
    'privacy_h2_6' => '6. Cookies',
    'privacy_cookies_p1' => 'This site uses only technical storage needed to run the pages and remember the language you chose. We also load fonts and icons from external services (Google Fonts, Font Awesome via CDN), which may record your IP address. You can block or delete cookies in your browser settings; some features may then work less smoothly. See our',
    'privacy_cookies_link' => 'cookie policy',
    'privacy_h2_7' => '7. Your rights',
    'privacy_rights_intro' => 'Under Articles 15–22 of the GDPR you have the right to:',
    'privacy_rights_i1' => 'access your data and receive a copy;',
    'privacy_rights_i2' => 'have it corrected or erased;',
    'privacy_rights_i3' => 'restrict or object to processing;',
    'privacy_rights_i4' => 'receive your data in a portable format;',
    'privacy_rights_i5' => 'withdraw consent at any time;',
    'privacy_rights_i6' => 'lodge a complaint with your national data protection authority.',
    'privacy_rights_note' => 'To exercise any of these, email <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a>. We respond within 30 days.',
    'privacy_h2_8' => '8. Security',
    'privacy_security_p1' => 'We apply reasonable technical and organisational measures to protect your data against unauthorised access, loss or disclosure. No internet transmission is completely secure: please never send us full card numbers by email or WhatsApp.',
    'privacy_h2_9' => '9. Children',
    'privacy_children_p1' => 'This website is not directed at children under 16. Details of minors travelling with us are provided by their parents or legal guardians.',
    'privacy_h2_10' => '10. Changes',
    'privacy_changes_p1' => 'We may update this notice; the date at the top of the page always shows the current version.',

    // ===== Terms & Conditions =====
    'terms_meta_title' => 'Terms & Conditions | Serengeti Budget Safari',
    'terms_meta_description' => 'Booking terms for Serengeti Budget Safari: deposits, payments, cancellation charges, insurance requirements, liability and complaints.',
    'terms_h1' => 'Terms & Conditions',
    'terms_intro' => 'These terms govern bookings for safaris, treks, day trips and Zanzibar stays organised by <strong>Serengeti Budget Safari</strong>, based in Arusha, Tanzania. By confirming a booking you confirm that you have read and accepted them.',
    'terms_note_title' => 'Important:',
    'terms_note_body' => 'the amounts, percentages and deadlines below are our standard terms. The binding terms for your trip are those set out in the written quote we send you. Where the two differ, the quote prevails.',
    'terms_h2_1' => '1. Booking and confirmation',
    'terms_booking_i1' => 'Requesting a quote is free and places you under no obligation.',
    'terms_booking_i2' => 'A booking is confirmed once you receive our written confirmation and the deposit has been received.',
    'terms_booking_i3' => 'Lodge and camp space is not held until confirmation. In high season availability can change within hours.',
    'terms_booking_i4' => 'Please give us names exactly as they appear in your passport; later corrections may attract charges from lodges and airlines.',
    'terms_h2_2' => '2. Prices',
    'terms_prices_i1' => 'Prices are quoted in euros (EUR) or US dollars (USD) as stated in your quote, per person unless indicated otherwise.',
    'terms_prices_i2' => 'Unless your quote says otherwise, the price covers: a 4x4 vehicle with driver-guide, fuel, entrance fees for the parks in your itinerary, accommodation and meals as described, and drinking water during game drives.',
    'terms_prices_i3' => 'The price excludes: international flights, visa, travel insurance, drinks, tips, personal expenses, optional excursions, and internal flights unless expressly listed.',
    'terms_prices_i4' => 'Park entrance fees are set by the Tanzanian authorities (TANAPA, NCAA). If they increase after your booking is confirmed, the difference is payable by the traveller.',
    'terms_h2_3' => '3. Payment',
    'terms_pay_deposit_t' => 'Deposit:',
    'terms_pay_deposit_d' => '30% of the total on confirmation.',
    'terms_pay_balance_t' => 'Balance:',
    'terms_pay_balance_d' => 'due 30 days before departure. For bookings made within 30 days of departure, the full amount is payable on confirmation.',
    'terms_pay_i3' => 'Bank and transfer charges are payable by the traveller.',
    'terms_pay_i4' => 'If the balance is not paid by the due date we may treat the booking as cancelled and apply the charges in clause 4.',
    'terms_h2_4' => '4. Cancellation by you',
    'terms_cancel_intro' => 'Cancellations must be made in writing. The following charges apply, calculated on the total trip price:',
    'terms_cancel_th1' => 'Notice before departure',
    'terms_cancel_th2' => 'Charge',
    'terms_cancel_r1_a' => 'More than 60 days',
    'terms_cancel_r1_b' => 'Deposit retained (30%)',
    'terms_cancel_r2_a' => '60 to 30 days',
    'terms_cancel_r2_b' => '50% of the total',
    'terms_cancel_r3_a' => '29 to 15 days',
    'terms_cancel_r3_b' => '75% of the total',
    'terms_cancel_r4_a' => 'Fewer than 15 days, or no-show',
    'terms_cancel_r4_b' => '100% of the total',
    'terms_cancel_note' => 'Some lodges, mobile camps and internal flights impose stricter conditions of their own; where they do, we tell you in the quote.',
    'terms_h2_5' => '5. Changes',
    'terms_changes_i1' => 'Changes requested more than 30 days before departure are free of charge, apart from any difference in the cost of services and supplier fees.',
    'terms_changes_i2' => 'Changes requested within 30 days of departure are treated as a cancellation and rebooking.',
    'terms_changes_i3' => 'We may alter an itinerary for reasons of safety, weather, road conditions, park closures or accommodation availability, providing services of an equivalent standard.',
    'terms_h2_6' => '6. Travel insurance',
    'terms_insurance_p1' => '<strong>Travel insurance is compulsory</strong> on all our trips. It must cover medical expenses, emergency evacuation and repatriation. For Kilimanjaro and Mount Meru, your policy must explicitly cover high-altitude trekking up to 6,000 m. We also recommend cancellation cover. We are not responsible for costs arising from inadequate insurance.',
    'terms_h2_7' => '7. Documents, health and safety',
    'terms_docs_i1' => 'Your passport must be valid for at least six months from the date of entry and have two blank pages.',
    'terms_docs_i2' => 'Obtaining a Tanzanian visa is the traveller\'s responsibility.',
    'terms_docs_i3' => 'A yellow fever certificate is required if you are arriving from, or have transited, a risk country.',
    'terms_docs_i4' => 'Please tell us at the time of booking about any medical conditions, allergies or medication relevant to the trip.',
    'terms_docs_i5' => 'On game drives you must follow your guide\'s instructions: do not leave the vehicle without permission and do not approach animals.',
    'terms_h2_8' => '8. Liability',
    'terms_liability_i1' => 'We organise your trip with professional care and are responsible for the proper delivery of the services we provide directly.',
    'terms_liability_i2' => 'We are not liable for delays, cancellations or losses caused by events beyond our reasonable control: weather, natural disasters, epidemics, civil unrest, strikes, decisions of authorities or failures of public infrastructure.',
    'terms_liability_i3' => 'We are not liable for services you book independently with third parties.',
    'terms_liability_i4' => 'Wildlife sightings occur in nature and cannot be guaranteed.',
    'terms_liability_i5' => 'Luggage and personal belongings remain the traveller\'s responsibility.',
    'terms_h2_9' => '9. Conduct',
    'terms_conduct_p1' => 'We reserve the right to remove from a trip, without refund, anyone who endangers their own or others\' safety, damages the environment or wildlife, or behaves with serious disrespect towards local communities or our staff.',
    'terms_h2_10' => '10. Complaints',
    'terms_complaints_p1' => 'If something goes wrong during your trip, tell your guide or our office straight away. Most issues can be resolved on the spot. Written complaints should reach <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a> within 30 days of the end of your trip.',
    'terms_h2_11' => '11. Governing law',
    'terms_law_p1' => 'This contract is governed by the law of the United Republic of Tanzania. Before taking legal action, both parties agree to attempt an amicable settlement.',
    'terms_contact_title' => 'Questions before booking?',
    'terms_contact_body' => 'Email <a href="mailto:serengetibudgetsafari@gmail.com">serengetibudgetsafari@gmail.com</a> or message us on <a href="https://wa.me/255697612865" rel="noopener">WhatsApp +255 697 612 865</a>. We reply every day between 07:00 and 21:00 Tanzanian time.',

