    'cookies_meta_title' => 'Cookie Policy | Serengeti Budget Safari',
    'cookies_meta_description' => 'Which cookies and third-party services this website uses, and how to control them in your browser.',
    'cookies_h1' => 'Cookie Policy',
    'cookies_intro' => 'Cookies are small text files a website stores on your device. This page explains what we use and how you can control it.',
    'cookies_h2_1' => '1. Technical storage',
    'cookies_technical_intro' => 'Needed for the site to work; no consent is required:',
    'cookies_th_name' => 'Name',
    'cookies_th_purpose' => 'Purpose',
    'cookies_th_duration' => 'Duration',
    'cookies_row_lang_purpose' => 'Remembers the language you chose so you are not asked on every visit',
