    'cookies_embed_p1' => 'Some pages may embed video or maps hosted elsewhere (for example YouTube or Google Maps). Where they do, that provider may set its own cookies once you start playback or interact with the map.',
    'cookies_h2_4' => '4. What we do not use',
    'cookies_notuse_p1' => 'We do not use advertising or profiling cookies, and we do not sell browsing data to advertisers.',
    'cookies_h2_5' => '5. Managing cookies',
    'cookies_manage_intro' => 'You can block or delete cookies in your browser settings:',
