    'bsg_intro_title' => 'Why Tanzania for Your Budget Safari?',
    'bsg_intro_p1' => 'Tanzania is not just another safari destination. It is <strong>the</strong> safari destination. With over 20 national parks, the largest concentration of wildlife on the planet, and the legendary Great Migration, Tanzania offers a safari experience that is unmatched anywhere else in the world.',
    'bsg_intro_p2' => 'But here\'s the truth most travel companies won\'t tell you: <strong>Tanzania can be done on a budget.</strong> Not a "backpacker" budget, but a comfortable, authentic, unforgettable safari that won\'t break the bank. The secret is understanding the system: park fees, accommodation tiers, seasonal pricing, group dynamics, and local knowledge.',
    'bsg_intro_p3' => 'This guide comes from our own team of Arusha-based guides. It\'s the guide we wish every traveler read before requesting a quote, because once you understand where the money goes, you\'ll know exactly what a fair price looks like.',
    'bsg_intro_box' => '<strong>What makes this guide different:</strong> Every figure here comes from real experience: our own vehicles, our own routes, our own negotiated prices at every campsite and lodge. This is not theory, it\'s the practical knowledge of a local operator who lives and works in Tanzania.',

    'bsg_quick_title' => 'Quick Answer: How Much Does a Tanzania Budget Safari Cost?',
    'bsg_quick_p1' => 'A budget safari in Tanzania typically costs <strong>$150–$300 per person per day</strong>. The range depends on a few factors:',
    'bsg_quick_li1' => '<strong>Group size:</strong> more people means a lower per-person cost: a group of 6 can pay as little as $150 per person per day.',
    'bsg_quick_li2' => '<strong>Season:</strong> the green season (March–May) offers the lowest rates; the dry season (June–October) is more expensive.',
    'bsg_quick_li3' => '<strong>Accommodation type:</strong> camping is the most affordable option; tented camps and lodges increase the cost.',
    'bsg_quick_li4' => '<strong>Parks visited:</strong> Serengeti and Ngorongoro have higher fees than Tarangire or Lake Manyara.',
    'bsg_quick_li5' => '<strong>Vehicle type:</strong> group sharing is cheaper than a private vehicle.',
    'bsg_quick_p2' => 'For a <strong>3-day safari</strong>, budget roughly <strong>$550–$750</strong>. For a <strong>5-day safari</strong>, expect <strong>$1,000–$1,500</strong>. For a <strong>7-day safari</strong>, budget <strong>$1,300–$2,000</strong>.',
    'bsg_quick_pro' => '<strong>Pro tip:</strong> the single biggest factor in keeping costs down is <strong>group size</strong>. Travel with 4–6 people and you\'ll save 20–40% compared to a private safari. The second biggest factor is <strong>season</strong>: the green season offers the best value.',
    'bsg_quick_see_breakdown' => 'See the full cost breakdown',

    'bsg_read_more' => 'Read more',
    'bsg_read_less' => 'Read less',
    'bsg_toc_jump' => 'Jump to section',

