    'bsg_cost_title' => 'Deep Cost Breakdown: Where Every Euro Goes',
    'bsg_cost_p1' => 'One of the biggest fears travelers have is hidden costs. We believe in complete transparency. Here is exactly where your safari money goes.',
    'bsg_cost_th1' => 'Component',
    'bsg_cost_th2' => 'What it covers',
    'bsg_cost_th3' => 'Typical % of total',
    'bsg_cost_row1_label' => 'Park fees &amp; conservation levies',
    'bsg_cost_row1_desc' => 'Entry to national parks, crater fees, anti-poaching rangers, habitat conservation',
    'bsg_cost_row1_pct' => '30–40%',
    'bsg_cost_row2_label' => 'Transport &amp; vehicle hire',
    'bsg_cost_row2_desc' => '4×4 safari vehicle, fuel, driver-guide salary, maintenance, insurance',
    'bsg_cost_row2_pct' => '25–35%',
    'bsg_cost_row3_label' => 'Accommodation',
    'bsg_cost_row3_desc' => 'Camping fees, tented camp, or lodge, varies by type',
    'bsg_cost_row3_pct' => '15–20%',
    'bsg_cost_row4_label' => 'Meals',
    'bsg_cost_row4_desc' => 'Full board: breakfast, lunch (often bush picnic), dinner',
    'bsg_cost_row4_pct' => '10–15%',
    'bsg_cost_row5_label' => 'Guide &amp; staff',
    'bsg_cost_row5_desc' => 'Your guide\'s expertise, spotting skills, safety training',
    'bsg_cost_row5_pct' => '8–12%',
    'bsg_cost_insider' => '<strong>Insider secret:</strong> park fees make up 30–40% of the total cost. This is why choosing the right parks matters. A 5-day safari with Serengeti and Ngorongoro will have about $300–$400 in park fees alone; a 5-day safari with Tarangire, Manyara and Arusha NP will have about $150–$200.',

    'bsg_parks_title' => 'Parks Deep Dive: Fees & Best Time',
    'bsg_parks_p1' => 'Every park has its own entry fee, character and ideal season. Here is an honest breakdown of the parks we run safaris to most often.',
    'bsg_park1_name' => 'Serengeti',
    'bsg_park1_tier' => 'high',
    'bsg_park1_fee' => 'Entry: $82/day',
    'bsg_park1_desc' => 'The world\'s most famous park. Endless plains, the Great Migration, and the highest density of predators on Earth.',
    'bsg_park1_best' => 'Best time: Dec–Jul for migration, Aug–Oct for river crossings. Recommended: 2–4 nights.',
    'bsg_park2_name' => 'Ngorongoro Crater',
    'bsg_park2_tier' => 'medium',
    'bsg_park2_fee' => 'Entry: $71/day + $295 crater',
    'bsg_park2_desc' => 'A natural amphitheatre with the highest density of wildlife in Africa: all Big Five present, including black rhino.',
    'bsg_park2_best' => 'Best time: year-round. Recommended: 1–2 nights.',
    'bsg_park3_name' => 'Tarangire',
    'bsg_park3_tier' => 'low',
    'bsg_park3_fee' => 'Entry: $53/day',
    'bsg_park3_desc' => 'Home to the largest elephant herds in Tanzania and iconic baobab trees, with fewer crowds than Serengeti.',
    'bsg_park3_best' => 'Best time: Jun–Oct (dry season). Recommended: 1–2 nights.',
    'bsg_park4_name' => 'Lake Manyara',
    'bsg_park4_tier' => 'low',
    'bsg_park4_fee' => 'Entry: $53/day',
    'bsg_park4_desc' => 'Famous for tree-climbing lions, flamingos on the soda lake, and a lush groundwater forest.',
    'bsg_park4_best' => 'Best time: year-round. Recommended: 1 night.',
    'bsg_park5_name' => 'Arusha National Park',
    'bsg_park5_tier' => 'low',
    'bsg_park5_fee' => 'Entry: $53/day',
    'bsg_park5_desc' => 'Walking safaris, Mount Meru views and colobus monkeys: a great half-day or full-day option.',
    'bsg_park5_best' => 'Best time: year-round. Recommended: 1 day.',
    'bsg_park6_name' => 'Mikumi',
    'bsg_park6_tier' => 'low',
    'bsg_park6_fee' => 'Entry: $35/day',
    'bsg_park6_desc' => '"Little Serengeti": classic savannah wildlife, easy access from Dar es Salaam. Great for short, budget safaris.',
    'bsg_park6_best' => 'Best time: year-round. Recommended: 1–2 nights.',
    'bsg_park7_name' => 'Nyerere (Selous)',
    'bsg_park7_tier' => 'medium',
    'bsg_park7_fee' => 'Entry: $53/day',
    'bsg_park7_desc' => 'Africa\'s largest protected area. Boat safaris on the Rufiji River, walking safaris, wild dogs, elephants and hippos.',
    'bsg_park7_best' => 'Best time: Jun–Oct (dry). Recommended: 2–3 nights.',
    'bsg_park8_name' => 'Ruaha',
    'bsg_park8_tier' => 'medium',
    'bsg_park8_fee' => 'Entry: $35/day',
    'bsg_park8_desc' => 'Remote, wild and stunning: huge elephant herds, wild dogs and beautiful baobab landscapes.',
    'bsg_park8_best' => 'Best time: Jun–Oct (dry). Recommended: 2–4 nights.',
    'bsg_parks_legend' => '$ = most affordable (under $40 entry) · $$ = moderate ($40–$60) · $$$ = higher cost (over $60)',
    'bsg_parks_strategy' => '<strong>Budget strategy:</strong> if you\'re on a tight budget, focus on parks with lower entry fees: Mikumi ($35), Ruaha ($35), Tarangire ($53) and Lake Manyara ($53). Serengeti and Ngorongoro cost more but offer unmatched wildlife. Most travelers combine 2 days in Tarangire, 2 in Serengeti, 1 in Ngorongoro and 1 in Manyara.',

    'bsg_acc_title' => 'Budget Accommodation: Real 2026 Prices',
    'bsg_acc_p1' => 'Your accommodation choice has the biggest impact on your safari budget. Here are honest options near the main parks, with current prices.',
    'bsg_acc1_name' => 'Public Campsites (inside parks)',
    'bsg_acc1_price' => '$25–$30 <small>per person / night</small>',
    'bsg_acc1_loc' => 'Serengeti, Ngorongoro, Tarangire',
    'bsg_acc1_desc' => 'Basic facilities, incredible wildlife sounds. Seronera, Simba and Kikoti campsites are the most popular. Book early.',
    'bsg_acc2_name' => 'Budget Tented Camps',
    'bsg_acc2_price' => '$80–$120 <small>per person / night</small>',
    'bsg_acc2_loc' => 'Various parks',
    'bsg_acc2_desc' => 'Walk-in safari tents with real beds and en-suite bathrooms: a great middle ground between camping and lodges.',
    'bsg_acc3_name' => 'Karatu Budget Lodges',
    'bsg_acc3_price' => '$50–$80 <small>per room / night</small>',
    'bsg_acc3_loc' => 'Karatu (near Ngorongoro)',
    'bsg_acc3_desc' => 'Affordable lodges just outside Ngorongoro, much cheaper than the crater rim, with similar access.',
    'bsg_acc4_name' => 'Arusha &amp; Moshi Guesthouses',
    'bsg_acc4_price' => '$35–$60 <small>per room / night</small>',
    'bsg_acc4_loc' => 'Arusha / Moshi',
    'bsg_acc4_desc' => 'Basic but clean rooms with breakfast: a good base before and after your safari.',
    'bsg_acc_tip' => '<strong>Accommodation tip:</strong> public campsites inside national parks fill up quickly in peak season (June–October). Book 2–3 months ahead. For budget lodges, check places just outside the parks: often 30–50% cheaper than inside.',

    'bsg_tips_title' => 'Local Secrets: From Our Own Guides',
    'bsg_tips_p1' => 'Insider tips from our team of Tanzanian guides, things you won\'t find in a guidebook. These will save you money and improve your experience.',
    'bsg_tip1' => '<strong>The "golden hour" secret</strong> — game drives are best at sunrise (6:00–8:30am) and late afternoon (4:00–6:30pm). Many budget travelers skip the early morning drive — don\'t be one of them.',
    'bsg_tip2' => '<strong>Save on the crater fee</strong> — the Ngorongoro descent fee ($295 per vehicle) is expensive, but staying overnight on the rim for a full-day game drive gets far more value than a half-day.',
    'bsg_tip3' => '<strong>Eat like a local</strong> — a plate of ugali with fish or meat at a local "mama lishe" stall costs $3–$5: safe, delicious and a fraction of tourist-restaurant prices.',
    'bsg_tip4' => '<strong>Vehicle choice matters</strong> — for budget safaris, insist on a pop-up roof 4×4. Minibuses are cheaper but offer poor visibility and struggle on rough park roads.',
    'bsg_tip5' => '<strong>Shoulder season sweet spot</strong> — November and December (short rains) are usually brief afternoon showers, not constant rain — and offer lower rates with the same incredible wildlife.',
    'bsg_tip6' => '<strong>Stay outside the park</strong> — towns like Mto wa Mbu (near Manyara) or Karatu (near Ngorongoro) are 50–70% cheaper than lodges inside the park, while you still do full-day game drives.',
    'bsg_tip7' => '<strong>The "early bird" strategy</strong> — leave camp at 5:30am to be first in the park, catch predators hunting, and beat the crowds that start arriving around 9am.',
    'bsg_tip8' => '<strong>Low season is underrated</strong> — April and May bring short bursts of rain, incredibly green landscapes, spectacular birdlife, and the parks almost to yourself.',
    'bsg_tip9' => '<strong>Tip well, tip wisely</strong> — the standard is $10–$20 per day for your guide and $5–$10 per day for camp staff, in cash.',
    'bsg_tip10' => '<strong>Pack light</strong> — safari vehicles have limited space. A soft-sided duffel bag beats a hard suitcase.',

    'bsg_best_time_title' => 'Best Time to Go: Seasonal Guide',
    'bsg_best_time_p1' => 'Tanzania is a year-round destination, but the wildlife experience changes with the seasons.',
    'bsg_month_jan' => 'Calving begins · Warm & dry',
    'bsg_month_feb' => 'Peak calving · Excellent viewing',
    'bsg_month_mar' => 'Calving ends · Lush landscapes',
    'bsg_month_apr' => 'Long rains · Lowest rates',
    'bsg_month_may' => 'Rains taper · Excellent value',
    'bsg_month_jun' => 'Dry season · Grumeti crossings',
    'bsg_month_jul' => 'Mara crossings · Peak season',
    'bsg_month_aug' => 'Mara crossings · Busiest month',
    'bsg_month_sep' => 'Northern herds · Still busy',
    'bsg_month_oct' => 'Herds move south · Good value',
    'bsg_month_nov' => 'Short rains · Excellent value',
    'bsg_month_dec' => 'Green season · Great photography',
    'bsg_best_time_box' => '<strong>Best budget-friendly windows:</strong> November–December (short rains) and March–May (long rains) offer lower rates, fewer crowds and lush landscapes: ideal for value-seekers.',

    'bsg_itin_title' => 'Sample Itineraries',
    'bsg_itin_p1' => 'A day-by-day look at what our most popular budget packages actually include.',
    'bsg_itin1_name' => '3-Day Classic Serengeti Safari',
    'bsg_itin1_days' => '3 days / 2 nights',
    'bsg_itin1_route' => 'Arusha → Serengeti Central → Ngorongoro → Arusha',
    'bsg_itin1_detail' => '<strong>Day 1:</strong> Arusha → Serengeti, game drive en route, overnight tented camp.<br><strong>Day 2:</strong> Full-day Serengeti game drive, overnight tented camp.<br><strong>Day 3:</strong> Ngorongoro Crater descent, return to Arusha.',
    'bsg_itin1_price' => 'From $1,000 per person',
    'bsg_itin2_name' => '5-Day Classic Northern Circuit',
    'bsg_itin2_days' => '5 days / 4 nights',
    'bsg_itin2_route' => 'Arusha → Tarangire → Serengeti → Ngorongoro → Arusha',
    'bsg_itin2_detail' => '<strong>Day 1:</strong> Arusha → Tarangire, afternoon game drive.<br><strong>Day 2:</strong> Tarangire → Serengeti, game drive en route.<br><strong>Day 3:</strong> Full-day Serengeti game drive.<br><strong>Day 4:</strong> Serengeti → Ngorongoro, crater descent.<br><strong>Day 5:</strong> Return to Arusha.',
    'bsg_itin2_price' => 'From $1,450 per person',

    'bsg_faq_title' => 'Frequently Asked Questions',
    'bsg_faq_q1' => 'How much does a Tanzania budget safari cost?',
    'bsg_faq_a1' => 'Typically $150–$300 per person per day, depending on group size, season, accommodation and parks visited.',
    'bsg_faq_q2' => 'What is the cheapest month for a Tanzania safari?',
    'bsg_faq_a2' => 'April and May (the long rains) offer the lowest rates, with lush green landscapes and fewer crowds.',
    'bsg_faq_q3' => 'Which is the cheapest national park in Tanzania?',
    'bsg_faq_a3' => 'Mikumi, Arusha National Park and Lake Manyara have the lowest park entry fees.',
    'bsg_faq_q4' => 'Is camping safe on a Tanzania safari?',
    'bsg_faq_a4' => 'Yes, public campsites inside national parks are patrolled and widely used by budget travelers. Guides brief you on camp safety on arrival.',
    'bsg_faq_q5' => 'Can I negotiate safari prices in Tanzania?',
    'bsg_faq_a5' => 'Prices from licensed local operators are usually already fair and transparent. Be wary of unusually cheap quotes, since they often hide extra costs at the gate.',
    'bsg_faq_q6' => 'Do I need a private vehicle for a budget safari?',
    'bsg_faq_a6' => 'No, group-sharing safaris with 4–6 travelers significantly reduce the per-person cost while still giving everyone a window seat.',
    'bsg_faq_q7' => 'What is included in a budget safari package?',
    'bsg_faq_a7' => 'Typically a driver-guide, 4×4 vehicle, park fees, accommodation as specified, full board meals and drinking water. Always confirm exact inclusions before booking.',
    'bsg_faq_q8' => 'How far in advance should I book?',
    'bsg_faq_a8' => 'For peak season (June–October), book 3–6 months ahead. For shoulder and low season, 4–6 weeks is usually enough.',

    'bsg_book_title' => 'Book Your Budget Safari',
    'bsg_book_p1' => 'Fill in the details below and our team will reply within 24 hours with availability and an exact price.',
