    'lsg_intro_title' => 'The Art of the Luxury Safari',
    'lsg_intro_p1' => 'A luxury safari in Tanzania is not just a holiday. It is a life-changing experience. Waking to the golden African sunrise, the distant roar of a lion across the plains, tracking a leopard with a guide who has spent decades learning the secrets of the wild.',
    'lsg_intro_p2' => 'But luxury is not simply about price. It is about <strong>exclusivity, personalization and meticulous attention to detail</strong>. A private vehicle and a dedicated guide who anticipates your needs. Lodges that are architectural wonders blending into the landscape while offering every modern comfort.',
    'lsg_intro_p3' => 'This guide comes from our own team of Arusha-based specialists who have curated luxury safaris for years. Every lodge and experience listed here has been personally vetted. We don\'t just sell luxury, we curate it.',
    'lsg_intro_box' => '<strong>What sets us apart:</strong> we are not a booking platform. We are a local team who has been crafting luxury safaris for years. Every lodge and every experience is personally vetted, so you gain access to insider knowledge you won\'t find anywhere else.',

    'lsg_quick_title' => 'Quick Answer: How Much Does a Luxury Tanzania Safari Cost?',
    'lsg_quick_p1' => 'A luxury safari in Tanzania typically costs <strong>$350–$1,200+ per person per night</strong>. This wide range reflects the diversity of luxury offerings, from boutique tented camps to ultra-exclusive private villas.',
    'lsg_quick_li1' => '<strong>Premium luxury:</strong> $350–$600/night: excellent tented camps, private vehicle, elevated service.',
    'lsg_quick_li2' => '<strong>Ultra-luxury:</strong> $600–$900/night: world-class lodges, elite guides, often private charters.',
    'lsg_quick_li3' => '<strong>Exclusive private:</strong> $900–$1,200+/night: private villas, butler service, complete exclusivity.',
    'lsg_quick_li4' => '<strong>Season:</strong> shoulder months (November–December, February) offer the same lodges at 20–30% lower rates.',
    'lsg_quick_li5' => '<strong>Private vs group:</strong> a private vehicle and guide cost more but define what "luxury" actually means.',
    'lsg_quick_p2' => 'For a <strong>5-day luxury safari</strong>, budget roughly <strong>$1,800–$3,500 per person</strong>. For a <strong>7-day safari</strong>, expect <strong>$2,500–$5,000</strong>. For a <strong>10-day safari with Zanzibar</strong>, budget <strong>$3,800–$7,000+</strong>.',
    'lsg_quick_pro' => '<strong>Pro tip:</strong> the best value in luxury safaris comes from traveling in the <strong>shoulder seasons</strong> (November–December and February). Same exclusive lodges, same expert guides, often 20–30% lower rates, with fewer crowds and a more intimate experience.',

