    'lsg_cost_insider' => '<strong>The real difference:</strong> a "premium" safari offers good quality but you\'ll likely share a vehicle and have less flexibility. A <strong>luxury safari</strong> means complete exclusivity: a private vehicle, a dedicated guide who knows your preferences, and experiences tailored entirely to you.',

