    'lsg_exp_title' => 'Exclusive Experiences: The Luxury Difference',
    'lsg_exp_p1' => 'What truly sets a luxury safari apart are experiences money can\'t normally buy, but that we can arrange.',
    'lsg_exp1' => '<strong>Hot air balloon safari</strong> — float silently over the Serengeti at sunrise with a champagne breakfast in the bush. From $500 per person.',
    'lsg_exp2' => '<strong>Private bush dinner</strong> — a candlelit dinner in the wilderness with a private chef, fine wines and a personal waiter. From $300 per couple.',
    'lsg_exp3' => '<strong>Fly-in safari</strong> — skip long drives and fly directly to your lodge in a private charter, using modern aircraft with strong safety records. From $500 per flight.',
    'lsg_exp4' => '<strong>Walking safari with an elite guide</strong> — track animals and learn the bush on foot with an expert guide. From $200 per person.',
    'lsg_exp5' => '<strong>Private photographic safari</strong> — dedicated game drives with a guide trained in wildlife photography, positioning for the best light. From $300 extra per day.',
    'lsg_exp6' => '<strong>Spa &amp; wellness retreat</strong> — unwind after game drives with treatments inspired by African traditions. From $100 per treatment.',
    'lsg_exp_box' => '<strong>Our promise:</strong> every experience we offer is personally vetted. We work with the best operators, guides and venues to ensure it is flawless. If it\'s not up to our standard, we don\'t recommend it.',

