    'lsg_itin2_detail' => '<strong>Days 1–2:</strong> Serengeti: 2 nights at an ultra-luxury lodge, full migration coverage.<br><strong>Days 3–4:</strong> Serengeti: 2 nights at a mobile camp following the migration.<br><strong>Day 5:</strong> Serengeti → Ngorongoro, private charter, overnight at the crater rim.<br><strong>Day 6:</strong> Ngorongoro → Manyara, private charter.<br><strong>Day 7:</strong> Manyara → Arusha, departure.',
