    'lsg_faq_title' => 'Frequently Asked Questions',
    'lsg_faq_q1' => 'How much does a luxury Tanzania safari cost?',
    'lsg_faq_a1' => 'Typically $350–$1,200+ per person per night, depending on the lodge tier, whether the vehicle and guide are private, and the season.',
    'lsg_faq_q2' => 'What is the most exclusive lodge in the Serengeti?',
    'lsg_faq_a2' => 'Singita Sasakwa, &Beyond Serengeti Under Canvas and Ngorongoro Crater Lodge are among the most exclusive properties we work with.',
    'lsg_faq_q3' => 'What is included in a luxury safari?',
