    'mgg_meta_title' => 'The Great Migration Guide: Month-by-Month, River Crossings, Prices & Packages',
    'mgg_meta_description' => 'The definitive guide to the Serengeti Great Migration. Month-by-month movements, river crossing strategy, calving season, accommodation and trusted migration safari packages.',

    'mgg_badge' => 'The Complete Migration Guide 2026',
    'mgg_h1' => 'The Great Migration: The Complete Guide',
    'mgg_price_highlight' => 'From $200',
    'mgg_price_highlight_small' => 'per person / day',
    'mgg_hero_intro' => 'Everything you need before you book: where the herds are each month, how river crossings actually work, honest accommodation prices, and, once you know what you\'re chasing, our trusted migration packages.',
    'mgg_hero_cta_packages' => 'View Migration Packages',
