    'mgg_intro_title' => 'The Greatest Wildlife Spectacle on Earth',
    'mgg_intro_p1' => 'The Great Migration is not just a wildlife event. It is the single greatest wildlife spectacle on the planet. Every year, over <strong>1.5 million wildebeest</strong>, joined by <strong>200,000 zebras</strong>, move in a continuous, circular pilgrimage across the Serengeti-Mara ecosystem, covering roughly <strong>800 kilometers</strong> a year.',
    'mgg_intro_p2' => 'But the Great Migration is not just about numbers. It\'s about drama, survival and the raw power of nature. It\'s the thunder of hooves across the plains, the heart-stopping spectacle of river crossings, and the intimate moments of birth and predation.',
    'mgg_intro_p3' => 'This guide comes from our own team of Arusha-based guides who track the herds year-round. We know where to find them, when to find them, and how to give you the best possible experience.',
    'mgg_intro_box' => '<strong>Why this guide is different:</strong> we don\'t just read about the Migration. Our guides are in the Serengeti tracking the herds and predicting their movements. Every piece of advice here comes from real experience, not generic information.',

    'mgg_route_title' => 'The Migration Route: Understanding the Cycle',
    'mgg_route_p1' => 'The migration follows a circular route across the Serengeti-Mara ecosystem, driven entirely by rainfall and the availability of fresh grass. Understanding this route is essential for planning your safari.',
    'mgg_route_box' => '<strong>Southern Serengeti (Ndutu)</strong> → January–March (Calving)<br><strong>Central &amp; Western Serengeti</strong> → April–May (Dispersal)<br><strong>Western Corridor (Grumeti)</strong> → June–July (Grumeti Crossings)<br><strong>Northern Serengeti (Mara River)</strong> → July–September (Mara Crossings)<br><strong>Central Serengeti</strong> → October–November (Return South)<br><strong>Southern Serengeti (Ndutu)</strong> → December (Pre-Calving)',
    'mgg_route_tip' => '<strong>Key insight:</strong> the migration is not a single herd moving together. It is a series of herds moving in different directions. Understanding the broad pattern helps you plan, but local guides can tell you exactly where the herds are at any given time.',

    'mgg_months_title' => 'Month-by-Month: Where, What &amp; Why',
    'mgg_months_p1' => 'A detailed, month-by-month breakdown of the Great Migration. For each month, exactly where the herds are and what you can expect to see.',
