    'mgg_crossings_title' => 'River Crossings: The Ultimate Expert Guide',
    'mgg_crossings_p1' => 'The river crossings are the most iconic and dramatic moments of the Great Migration. Two rivers provide the stage: the Grumeti River in the Western Corridor and the Mara River in the north.',
    'mgg_crossings_grumeti_title' => 'Grumeti River Crossings: The Western Drama',
    'mgg_crossings_grumeti_p' => 'The Grumeti crossings are the first major water obstacles the herds face. Less famous than the Mara River, but equally dramatic and far less crowded, home to some of the largest crocodiles in Africa.',
    'mgg_crossings_grumeti_tip' => '<strong>Best time:</strong> late May to early July. <strong>Insider secret:</strong> the Grumeti crossings are often more chaotic than the Mara. The wildebeest are less experienced, making the crossings wilder.',
    'mgg_crossings_mara_title' => 'Mara River Crossings: The World-Famous Spectacle',
    'mgg_crossings_mara_p' => 'The Mara River crossings are the most famous wildlife spectacle on Earth. Hundreds of thousands of wildebeest and zebras gather on the riverbanks before plunging into crocodile-infested waters.',
    'mgg_crossings_mara_tip' => '<strong>Best time:</strong> mid-July to late August. <strong>Viewing tip:</strong> crossings are unpredictable. You may need to wait several hours, most likely in the early morning or late afternoon.',
    'mgg_crossings_pro' => '<strong>Pro tip:</strong> to avoid the crowds at the Mara River, consider the Grumeti River crossings in June: similar drama, a fraction of the tourists, and lower prices.',

    'mgg_calving_title' => 'Calving Season: The Circle of Life',
    'mgg_calving_p1' => 'Between <strong>January and March</strong>, the southern Serengeti becomes the stage for one of nature\'s most remarkable events: the wildebeest calving season. Over <strong>500,000 calves</strong> are born in a matter of weeks, with up to <strong>8,000 births per day</strong> at the peak.',
    'mgg_calving_p2' => 'This is a time of intense predator action: lions, cheetahs, leopards and hyenas follow the herds closely, taking advantage of the abundance of newborn calves.',
    'mgg_calving_box' => '<strong>Calving season fast facts:</strong> 500,000+ calves born annually, 8,000+ births per day at peak, best viewing in the Ndutu area, excellent for photography thanks to short grass and soft morning light.',

    'mgg_acc_title' => 'Where to Stay: Migration Accommodation',
    'mgg_acc_p1' => 'Choosing the right accommodation for the right migration phase matters. Here are honest options across every budget.',
    'mgg_acc1_name' => 'Serengeti &amp; Ndutu Public Campsites',
    'mgg_acc1_price' => '$25–$30 <small>per person / night</small>',
    'mgg_acc1_loc' => 'Seronera, Ndutu, Grumeti',
    'mgg_acc1_desc' => 'Basic facilities, incredible wildlife sounds, inside the park. Book early. These fill up fast in peak season.',
    'mgg_acc2_name' => 'Mid-Range Tented Camps',
    'mgg_acc2_price' => '$150–$250 <small>per person / night</small>',
    'mgg_acc2_loc' => 'Central &amp; Western Serengeti',
    'mgg_acc2_desc' => 'En-suite bathrooms, central dining, excellent migration access without the ultra-luxury price tag.',
    'mgg_acc3_name' => 'Mobile Camps Following the Herds',
    'mgg_acc3_price' => '$120–$180 <small>per person / night</small>',
    'mgg_acc3_loc' => 'Moves with the migration',
    'mgg_acc3_desc' => 'Camps that relocate through the season to stay close to the action: unbeatable wildlife access.',
    'mgg_acc4_name' => 'Luxury Lodges on the Crater Rim',
    'mgg_acc4_price' => '$750–$1,300 <small>per person / night</small>',
    'mgg_acc4_loc' => 'Ngorongoro Crater rim',
    'mgg_acc4_desc' => 'Stunning views and exceptional service, ideal for pairing a migration safari with the crater.',
    'mgg_acc_tip' => '<strong>Booking tip:</strong> for peak migration months (July–September), book 6–12 months ahead. The best-located camps sell out first, regardless of budget tier.',

    'mgg_best_time_title' => 'Best Time to Visit: A Seasonal Guide',
    'mgg_best_time_p1' => 'The best time depends entirely on what you want to see. Each season offers a unique experience.',
    'mgg_month_jan' => 'Calving begins · Ndutu',
    'mgg_month_feb' => 'Peak calving · Predator action',
    'mgg_month_mar' => 'Calving ends · Herds disperse',
    'mgg_month_apr' => 'Long rains · Grumeti buildup',
    'mgg_month_may' => 'Grumeti crossings begin',
    'mgg_month_jun' => 'Herds push north · Crossings',
    'mgg_month_jul' => 'Mara crossings begin',
    'mgg_month_aug' => 'Peak Mara crossings',
    'mgg_month_sep' => 'Crossings continue',
    'mgg_month_oct' => 'Herds move south · Good value',
    'mgg_month_nov' => 'Short rains · Herds return south',
    'mgg_month_dec' => 'Pre-calving · Southern plains',
    'mgg_best_time_box' => '<strong>Migration expert advice:</strong> "There\'s no bad time to see the Migration. Every season offers something unique. Want drama? Visit in August. Want intimacy? Visit in February. Want solitude? Visit in April."',

    'mgg_itin_title' => 'Sample Migration Itineraries',
    'mgg_itin_p1' => 'A day-by-day look at what our most requested migration packages actually include.',
    'mgg_itin1_name' => '5-Day Calving Season Safari',
    'mgg_itin1_days' => '5 days / 4 nights',
    'mgg_itin1_route' => 'Ndutu + Ngorongoro + Central Serengeti (Jan–Mar)',
    'mgg_itin1_detail' => '<strong>Day 1:</strong> Arrive Arusha → transfer to Ndutu, afternoon game drive.<br><strong>Day 2:</strong> Full day in Ndutu: calving viewing and predator action.<br><strong>Day 3:</strong> Ndutu → Ngorongoro Crater, full-day descent.<br><strong>Day 4:</strong> Ngorongoro → Central Serengeti, game drive en route.<br><strong>Day 5:</strong> Morning game drive, return to Arusha.',
    'mgg_itin1_price' => 'From $1,150 per person',
    'mgg_itin2_name' => '8-Day Mara River Crossings Safari',
    'mgg_itin2_days' => '8 days / 7 nights',
    'mgg_itin2_route' => 'Northern Serengeti + Ngorongoro (Jul–Sep)',
    'mgg_itin2_detail' => '<strong>Day 1:</strong> Arrive Arusha → transfer to Northern Serengeti.<br><strong>Days 2–4:</strong> Full days at the Mara River, waiting for the crossings.<br><strong>Day 5:</strong> Northern → Central Serengeti, game drive.<br><strong>Day 6:</strong> Full day Central Serengeti.<br><strong>Day 7:</strong> Serengeti → Ngorongoro, crater descent.<br><strong>Day 8:</strong> Ngorongoro → Arusha, departure.',
    'mgg_itin2_price' => 'From $2,450 per person',

    'mgg_tips_title' => 'Local Tips: From Guides Who Track the Herds',
    'mgg_tips_p1' => 'Insider tips from our migration specialists, things you won\'t find in a guidebook.',
    'mgg_tip1' => '<strong>The waiting game</strong> — for river crossings, be prepared to wait. The herds can take hours to decide to cross. Bring snacks, water and patience — the payoff is worth it.',
    'mgg_tip2' => '<strong>Crossing prediction</strong> — experienced guides can predict crossings by watching the wildebeest gather and pace on the riverbank. The tension is palpable before a crossing.',
    'mgg_tip3' => '<strong>Camp selection matters</strong> — for calving season stay in Ndutu, for Grumeti crossings stay in the Western Corridor, for Mara crossings stay in Northern Serengeti. Choosing the right base saves hours of driving daily.',
    'mgg_tip4' => '<strong>Book early — really early</strong> — for peak migration season (July–September), book accommodation 6–12 months in advance. The best-located camps sell out over a year ahead.',
    'mgg_tip5' => '<strong>Follow the predators</strong> — the migration is not just about the wildebeest. Lions, cheetahs and leopards follow the herds, and following them often leads to the most dramatic moments.',
    'mgg_tip6' => '<strong>Golden hour photography</strong> — the best light for crossings is at sunrise and sunset. The warm light makes the drama even more powerful.',
    'mgg_tip7' => '<strong>Shoulder season value</strong> — October–December and February are excellent value, with smaller crowds and lower prices while wildlife viewing remains exceptional.',
    'mgg_tip8' => '<strong>Travel insurance is essential</strong> — medical evacuation from the Serengeti is expensive but necessary. Make sure your policy covers safari activities.',

    'mgg_faq_title' => 'Frequently Asked Questions',
    'mgg_faq_q1' => 'When is the best time to see the Great Migration?',
    'mgg_faq_a1' => 'It depends on what you want to see: calving in January–February, Grumeti crossings in June–July, Mara crossings in July–September, and the return south in October–December.',
    'mgg_faq_q2' => 'Where is the best place to see the wildebeest crossing?',
    'mgg_faq_a2' => 'The Mara River crossings in northern Serengeti (July–September) are the most famous, while the Grumeti River crossings (June–July) are also spectacular with far fewer crowds.',
    'mgg_faq_q3' => 'How much does a migration safari cost?',
    'mgg_faq_a3' => 'From $150–$300 per person per day for budget camping, $300–$600 for mid-range, and $800+ for luxury lodges and mobile camps.',
    'mgg_faq_q4' => 'Can I see the migration in the green season?',
    'mgg_faq_a4' => 'Yes. The green season (March–May) offers lush landscapes, fewer crowds and lower prices, with the herds spreading out across the Western Corridor.',
    'mgg_faq_q5' => 'How far in advance should I book a migration safari?',
    'mgg_faq_a5' => 'For peak season (July–September), book 6–12 months ahead. For calving season and shoulder months, 3–4 months is usually enough.',
    'mgg_faq_q6' => 'Is the migration predictable?',
    'mgg_faq_a6' => 'The migration follows the rains, but exact timing can vary by a few weeks each year. Local guides track real-time conditions to predict movements.',
    'mgg_faq_q7' => 'Can children join a migration safari?',
    'mgg_faq_a7' => 'Yes, most migration safaris are family-friendly, and several partner lodges offer family suites and activities for children.',
    'mgg_faq_q8' => 'What is the difference between the Grumeti and Mara crossings?',
    'mgg_faq_a8' => 'The Grumeti crossings (June–July) are less crowded with large crocodiles. The Mara crossings (July–September) are more famous, larger in scale, and busier.',

    'mgg_book_title' => 'Book Your Migration Safari',
    'mgg_book_p1' => 'Tell us your travel dates and our migration specialist will reply within 24 hours with exactly what you\'ll see and an exact price.',
    'mgg_cta_title' => 'Ready to Witness the Greatest Wildlife Spectacle?',
    'mgg_cta_p' => 'Get a free, no-obligation quote from a local Arusha operator who tracks the herds year-round.',
    'mgg_cta_button' => 'Get Your Free Quote',
    'mgg_share_label' => 'Share this guide:',
    'mgg_print' => 'Print Guide',

