    'dtg_intro_title' => 'The Ultimate Day Trip Resource',
    'dtg_intro_p1' => 'Tanzania is a vast country with an incredible diversity of experiences, and you don\'t need a week to enjoy them. Day trips are the perfect way to explore the highlights, whether you\'re in Arusha, Moshi or just passing through on a longer safari.',
    'dtg_intro_p2' => 'What makes this guide different? Every trip here has been personally tested by our team of local guides. We\'ve included insider tips and practical advice that you won\'t find anywhere else, whether you\'re a solo traveler, a couple or a family.',
    'dtg_intro_box' => '<strong>Why trust us?</strong> Our team has organized day trips for over 15 years. We know the best guides, the best times to visit and the hidden spots most tourists miss. This guide is based on real experience, not generic information.',

    'dtg_trips_title' => 'All Day Trips: By Category',
    'dtg_trips_p1' => 'Below you\'ll find the main day trip categories, organized by type. Each has detailed pricing and local tips further down this guide.',
    'dtg_trip1_name' => 'Safari Day Trips',
    'dtg_trip1_desc' => 'Ngorongoro Crater, Tarangire, Lake Manyara and Arusha National Park: incredible wildlife viewing in just a few hours from Arusha or Moshi.',
    'dtg_trip2_name' => 'Cultural Day Trips',
    'dtg_trip2_desc' => 'Mto wa Mbu villages, Maasai communities, and Hadzabe &amp; Datoga tribes near Lake Eyasi: authentic cultural immersion.',
    'dtg_trip3_name' => 'Kilimanjaro Day Hikes',
    'dtg_trip3_desc' => 'Mandara Hut or Shira Plateau day hikes: experience Kilimanjaro\'s lower slopes without committing to the full climb.',
    'dtg_trip4_name' => 'Lake Natron &amp; Hidden Gems',
    'dtg_trip4_desc' => 'Flamingos, waterfalls and dramatic landscapes off the well-trodden safari circuit.',

