    'dtg_tips_title' => 'Local Tips: From Our Own Guides',
    'dtg_tips_p1' => 'Insider tips from our team of Tanzanian guides, things that will save you time, money and disappointment.',
    'dtg_tip1' => '<strong>Leave early</strong> — for Ngorongoro, leave Arusha by 5:30am to catch the best morning predator action. The crater gets busy after 10am.',
    'dtg_tip2' => '<strong>Dry season concentrates wildlife</strong> — Tarangire in June–October offers incredible elephant herds around the river as water becomes scarce elsewhere.',
    'dtg_tip3' => '<strong>Don\'t skip the forest walk</strong> — at Lake Manyara, the groundwater forest walk is often overlooked but is a great way to see blue monkeys and bushbuck up close.',
    'dtg_tip4' => '<strong>Book Hadzabe trips in the morning</strong> — the Hadzabe hunt at dawn, so a morning visit gives you the most authentic experience of their daily life.',
    'dtg_tip5' => '<strong>Combine trips wisely</strong> — Lake Manyara and Mto wa Mbu village can be combined in one day without feeling rushed, saving you a day of your trip.',
    'dtg_tip6' => '<strong>Pack layers</strong> — mornings can be cool, especially near Ngorongoro and Kilimanjaro, but midday sun is intense. Dress in layers you can remove.',
    'dtg_tip7' => '<strong>Confirm pickup time the night before</strong> — traffic in Arusha can vary; a quick WhatsApp confirmation the evening before avoids any mix-ups.',
    'dtg_tip8' => '<strong>Bring cash for tips and souvenirs</strong> — village visits and cultural trips are a great place to buy authentic crafts directly from artisans, but card payment is rarely available.',

    'dtg_prices_title' => 'Day Trip Price Guide',
    'dtg_prices_p1' => 'Prices vary mainly by distance from Arusha and park entry fees. Here is an honest breakdown.',
    'dtg_prices_th1' => 'Day Trip',
    'dtg_prices_th2' => 'Distance from Arusha',
    'dtg_prices_th3' => 'Typical Price',
    'dtg_prices_row1_label' => 'Arusha National Park',
    'dtg_prices_row1_dist' => '30 minutes',
    'dtg_prices_row1_price' => '$130',
    'dtg_prices_row2_label' => 'Mto wa Mbu Cultural Trip',
    'dtg_prices_row2_dist' => '2 hours',
    'dtg_prices_row2_price' => '$90',
    'dtg_prices_row3_label' => 'Lake Manyara',
    'dtg_prices_row3_dist' => '2 hours',
    'dtg_prices_row3_price' => '$160',
    'dtg_prices_row4_label' => 'Tarangire',
    'dtg_prices_row4_dist' => '2 hours',
    'dtg_prices_row4_price' => '$180',
    'dtg_prices_row5_label' => 'Hadzabe &amp; Datoga (Lake Eyasi)',
    'dtg_prices_row5_dist' => '3 hours',
    'dtg_prices_row5_price' => '$140',
    'dtg_prices_row6_label' => 'Ngorongoro Crater',
    'dtg_prices_row6_dist' => '3 hours',
    'dtg_prices_row6_price' => '$250',
    'dtg_prices_insider' => '<strong>Insider tip:</strong> group size matters here too: sharing a vehicle with 3–4 other travelers can bring the per-person price down by 20–30% compared to a private day trip.',

    'dtg_best_time_title' => 'Best Time for Day Trips',
    'dtg_best_time_p1' => 'Most day trips work well year-round, but a few things shift with the seasons.',
    'dtg_best_time_li1' => '<strong>Ngorongoro Crater:</strong> good year-round, but early morning departures matter most in the dry season (June–October) when the crater gets busiest.',
    'dtg_best_time_li2' => '<strong>Tarangire:</strong> best June–October when wildlife concentrates around the river during the dry season.',
    'dtg_best_time_li3' => '<strong>Cultural trips (Hadzabe, Mto wa Mbu):</strong> good year-round, though roads to Lake Eyasi can be tougher during the March–May long rains.',
    'dtg_best_time_li4' => '<strong>Kilimanjaro day hikes:</strong> clearest views June–October and January–March, avoid the long rains (March–May).',
    'dtg_best_time_box' => '<strong>General rule:</strong> if you only have one day and want the highest chance of great wildlife photos, aim for June–October and depart before 6am.',

    'dtg_packing_title' => 'What to Bring',
    'dtg_packing_p1' => 'A day trip needs far less than a multi-day safari, but a few essentials make a real difference.',
    'dtg_packing_li1' => 'Neutral-colored clothing (khaki, olive, tan), avoid bright colors and pure white',
    'dtg_packing_li2' => 'A light jacket or fleece for early morning departures',
    'dtg_packing_li3' => 'Sunscreen, sunglasses and a wide-brimmed hat',
    'dtg_packing_li4' => 'Binoculars, most day trip vehicles have space for personal gear',
    'dtg_packing_li5' => 'A camera with a zoom lens, plus spare batteries',
    'dtg_packing_li6' => 'Cash (Tanzanian shillings or USD) for tips and souvenirs',
    'dtg_packing_li7' => 'A reusable water bottle, drinking water is provided but bring a bottle to refill',

    'dtg_faq_title' => 'Frequently Asked Questions',
    'dtg_faq_q1' => 'What is the best day trip from Arusha?',
    'dtg_faq_a1' => 'The Ngorongoro Crater day trip is the most popular for wildlife, but Tarangire and the Hadzabe cultural trip are excellent alternatives depending on your interests.',
    'dtg_faq_q2' => 'How much does a day safari cost in Tanzania?',
    'dtg_faq_a2' => 'Day safaris typically range from $90–$250 per person, depending on the park and group size.',
    'dtg_faq_q3' => 'Can I visit the Hadzabe in a day?',
    'dtg_faq_a3' => 'Yes, from Arusha or Karatu, a day trip to the Hadzabe and Datoga tribes near Lake Eyasi is entirely possible.',
    'dtg_faq_q4' => 'What time do day trips depart?',
    'dtg_faq_a4' => 'Most depart between 5:30am and 7:00am for wildlife trips, and around 8:00am for cultural trips. Earlier departures generally mean better wildlife viewing.',
    'dtg_faq_q5' => 'Is lunch included?',
    'dtg_faq_a5' => 'Yes, every day trip package includes a picnic lunch and drinking water.',
    'dtg_faq_q6' => 'Can I combine two day trips in one day?',
    'dtg_faq_a6' => 'Some combinations work well (like Lake Manyara with Mto wa Mbu village), but Ngorongoro and Tarangire are each best done as a dedicated full day.',
    'dtg_faq_q7' => 'Do I need to book in advance?',
    'dtg_faq_a7' => '2–3 days notice is usually enough, though peak season (June–October) benefits from booking a week ahead.',
    'dtg_faq_q8' => 'Is hotel pickup included?',
    'dtg_faq_a8' => 'Yes, every day trip includes pickup and drop-off at your hotel in Arusha or Moshi.',

    'dtg_book_title' => 'Book Your Day Trip',
    'dtg_book_p1' => 'Fill in the details below and our team will reply within 24 hours with availability and an exact price.',
    'dtg_cta_title' => 'Ready to Make the Most of Your Day?',
    'dtg_cta_p' => 'Get a free, no-obligation quote from a local Arusha operator: honest prices, no middlemen.',
    'dtg_cta_button' => 'Get Your Free Quote',
    'dtg_share_label' => 'Share this guide:',
    'dtg_print' => 'Print Guide',

