    // ===== Tarangire Express Safari (1 day package detail page) =====
    'pkg1d_meta_title' => 'Tarangire Express Safari: 1-Day Tour from Arusha | Serengeti Budget Safari',
    'pkg1d_meta_description' => 'A full-day Tarangire National Park safari from Arusha: massive elephant herds, iconic baobabs, a picnic lunch in the bush, from $165 per person.',
    'pkg1d_hero_badge' => 'Land of giants',
    'pkg1d_hero_title' => 'Tarangire Express Safari',
    'pkg1d_hero_sub' => 'A full day among Tanzania\'s largest elephant herds and ancient baobab trees, an easy introduction to safari without leaving Arusha for the night.',

    'pkg1d_fact_duration' => 'Duration',
    'pkg1d_fact_duration_val' => '1 day',
    'pkg1d_fact_difficulty' => 'Difficulty',
    'pkg1d_fact_difficulty_val' => 'Easy, no walking',
    'pkg1d_fact_group' => 'Group size',
    'pkg1d_fact_group_val' => 'Private vehicle',
    'pkg1d_fact_best_time' => 'Best time',
    'pkg1d_fact_best_time_val' => 'June to October',
    'pkg1d_fact_pickup' => 'Pickup',
    'pkg1d_fact_pickup_val' => 'Arusha or Moshi hotel',
    'pkg1d_fact_start' => 'Departs',
    'pkg1d_fact_start_val' => 'Every day',

    'pkg1d_intro_p1' => 'Imagine starting your morning surrounded by the sounds of the African wilderness, driving beneath ancient baobab trees while elephants move peacefully across the savannah, and before the day ends, sitting with Maasai people for a glimpse of one of Tanzania\'s most fascinating cultures.',
    'pkg1d_intro_p2' => 'This is more than a safari. It is a full day of wildlife, adventure, photography and authentic Tanzanian culture, all in one unforgettable experience.',

    'pkg1d_itinerary_badge' => 'Your day',
    'pkg1d_itinerary_title' => 'How the day unfolds',
    'pkg1d_itinerary_intro' => 'One full day, from an early pickup in Arusha to a golden Tarangire sunset, with a free Maasai cultural visit along the way.',
    'pkg1d_day_label' => 'Day 1',
    'pkg1d_day1_title' => 'Arusha to Tarangire National Park',
    'pkg1d_day1_mood' => 'Elephants, baobabs and your first taste of the wild.',
    'pkg1d_day1_drive' => '~2.5 hours from Arusha',
    'pkg1d_day1_meals' => 'Picnic lunch included',
    'pkg1d_day1_stay' => 'Return to Arusha same day',
    'pkg1d_day1_tl1_time' => '06:30',
    'pkg1d_day1_tl1_title' => 'Pickup from Arusha',
    'pkg1d_day1_tl1_desc' => 'Your professional guide collects you from your hotel, lodge or the airport in a 4x4 vehicle with a pop-up roof, then briefs you on the day\'s program as the scenery changes from busy town to open countryside and Maasai communities.',
    'pkg1d_day1_tl2_time' => '09:00',
    'pkg1d_day1_tl2_title' => 'Arrival and morning game drive',
    'pkg1d_day1_tl2_desc' => 'Welcome to Tarangire, the "Paradise of Elephants." Your guide reads the landscape and tracks animal movement in search of elephants, lions, giraffes, zebras, buffaloes, wildebeest, warthogs, monkeys and spectacular birdlife.',
    'pkg1d_day1_tl3_time' => '11:00',
    'pkg1d_day1_tl3_title' => 'The baobab moment',
    'pkg1d_day1_tl3_desc' => 'Stops at Tarangire\'s spectacular baobab landscapes, standing beneath a giant, ancient tree while elephants walk across the golden savannah in the distance, one of the most recognisable safari scenes in Tanzania.',
    'pkg1d_day1_tl4_time' => '12:30',
    'pkg1d_day1_tl4_title' => 'Picnic lunch in the wild',
    'pkg1d_day1_tl4_desc' => 'Lunch at a designated picnic area, surrounded by the sounds and scenery of the African bush, followed by a short rest before the afternoon adventure.',
    'pkg1d_day1_tl5_time' => '13:30',
    'pkg1d_day1_tl5_title' => 'Afternoon game drive',
    'pkg1d_day1_tl5_desc' => 'Continue exploring different areas of the park as your guide explains animal behaviour, tracks and signs, the Tarangire ecosystem and how wildlife survives the dry season around the river and its seasonal wetlands.',
    'pkg1d_day1_tl6_time' => '16:00',
    'pkg1d_day1_tl6_title' => 'Free Maasai cultural experience',
    'pkg1d_day1_tl6_desc' => 'A complimentary visit to a Maasai community near Tarangire, subject to availability: traditional homes, livestock and pastoral life, songs and dancing, and a chance to meet local artisans and ask questions.',
    'pkg1d_day1_tl7_time' => '17:00',
    'pkg1d_day1_tl7_title' => 'Depart Tarangire, arrive Arusha',
    'pkg1d_day1_tl7_desc' => 'After saying goodbye to your Maasai hosts, the drive back to Arusha gives you time to relax and look back through your photographs. Drop-off at your hotel or lodge around 19:00–20:00.',

    'pkg1d_calc_heading' => 'Calculate your price',
    'pkg1d_calc_subtext' => 'The more you travel together, the lower the price per person.',
    'pkg1d_calc_people_label' => 'Travellers',
    'pkg1d_calc_pp_label' => 'Per person',
    'pkg1d_calc_total_label' => 'Total',
    'pkg1d_calc_book' => 'Book This Safari',
    'pkg1d_calc_cta' => 'Ask on WhatsApp',
    'pkg1d_calc_note' => 'Prices drop automatically for larger groups. Contact us for a group of more than 20.',
    'pkg1d_calc_wa_template' => 'Hi! I\'m interested in the Tarangire Express Safari for {people} people (${pp} per person, ${total} total). Can you confirm availability?',

    'pkg1d_maasai_badge' => 'A free bonus',
    'pkg1d_maasai_title' => 'Free Maasai cultural experience',
    'pkg1d_maasai_intro' => 'We want you to experience more than what you paid for. Instead of finishing your day after the game drive, we add a cultural encounter where possible, at no additional tour charge.',
    'pkg1d_maasai_p1' => 'After your wildlife adventure, we head toward a Maasai community near the Tarangire area for a complimentary cultural experience, subject to the community\'s availability and local arrangements on the day. This is your opportunity to experience Tanzania beyond the safari vehicle.',
    'pkg1d_maasai_li1' => 'Meet Maasai community members',
    'pkg1d_maasai_li2' => 'See traditional homes and a boma',
    'pkg1d_maasai_li3' => 'Learn about livestock and pastoral life',
    'pkg1d_maasai_li4' => 'Enjoy traditional songs and dancing',
    'pkg1d_maasai_li5' => 'Learn about Maasai traditions and customs',
    'pkg1d_maasai_li6' => 'Meet local artisans and see traditional beadwork',
    'pkg1d_maasai_note' => 'Safari + culture = two unforgettable Tanzanian experiences in one day. The complimentary visit depends on community availability and operational timing; it does not include personal purchases, donations or optional activities.',

    'pkg1d_why_badge' => 'Why travel with us',
    'pkg1d_why_title' => 'Why book this 1-day safari?',
    'pkg1d_why1_title' => 'See the "Elephant Paradise"',
    'pkg1d_why1_desc' => 'Tarangire is renowned for its elephant population and is one of the strongest wildlife experiences in northern Tanzania.',
    'pkg1d_why2_title' => 'Experience the iconic baobabs',
    'pkg1d_why2_desc' => 'You don\'t simply see wildlife, you experience one of Tanzania\'s most spectacular landscapes.',
    'pkg1d_why3_title' => 'A full-day wildlife experience',
    'pkg1d_why3_desc' => 'We maximise your time in the park rather than rushing through a short game drive.',
    'pkg1d_why4_title' => 'Free Maasai cultural bonus',
    'pkg1d_why4_desc' => 'Wildlife in the morning and culture in the afternoon, giving you a richer Tanzanian experience.',
    'pkg1d_why5_title' => 'Perfect for photographers',
    'pkg1d_why5_desc' => 'Elephants, baobabs, open savannah and dramatic landscapes make for incredible photography opportunities.',
    'pkg1d_why6_title' => 'A professional safari guide',
    'pkg1d_why6_desc' => 'Your guide isn\'t simply a driver. They help you understand what you\'re seeing, where to look and why the ecosystem works the way it does.',
