    'pkg1d_faq_title' => 'Tarangire Express Safari: frequently asked questions',
    'pkg1d_faq_q1' => 'What makes Tarangire different from the Serengeti?',
    'pkg1d_faq_a1' => 'Tarangire is famous for its huge elephant herds, sometimes over 300 in a single sighting, and its iconic baobab trees. It sees far fewer visitors than the Serengeti, so it feels wilder and quieter for a day trip close to Arusha.',
    'pkg1d_faq_q2' => 'Is this a full day or a half day?',
    'pkg1d_faq_a2' => 'A full day, roughly 07:00 to 18:00, with a picnic lunch inside the park included.',
    'pkg1d_faq_q3' => 'Can I combine this with other parks later?',
    'pkg1d_faq_a3' => 'Yes. Many travellers use this as their first day before continuing to Ngorongoro or the Serengeti on a longer itinerary. Ask us and we will build a multi-day route around it.',

    'pkg1d_cta_title' => 'Ready for your Tarangire day?',
    'pkg1d_cta_intro' => 'Tell us your travel dates and group size, and we will confirm availability and an exact price within hours.',
