    'pkg1d_cta_contact_form' => 'Book This Safari',

    'pkg6d_meta_title' => 'Ngorongoro Crater Day Trip: 1-Day Tour from Arusha | Serengeti Budget Safari',
    'pkg6d_meta_description' => 'A full-day descent into the Ngorongoro Crater from Arusha: dense wildlife, the crater floor, a picnic lunch on the rim, from $228 per person.',
    'pkg6d_hero_title' => 'Ngorongoro Crater Day Trip',
    'pkg6d_fact_duration_val' => '1 day',
    'pkg6d_fact_pickup_val' => 'Arusha or Moshi hotel',
    'pkg6d_fact_start_val' => 'Every day',

    'pkg6d_intro_p1' => 'Imagine descending 600 metres into the floor of the world\'s largest intact volcanic caldera, surrounded on every side by crater walls, with one of the densest concentrations of wildlife anywhere in Africa spread out before you.',
    'pkg6d_intro_p2' => 'This is the Ngorongoro Crater, often called Africa\'s Garden of Eden. In a single day you can see lions, elephants, buffaloes, hippos, flamingos and, if you are fortunate, the endangered black rhino, all within one self-contained ecosystem.',

    'pkg6d_highlights_heading' => 'Highlights',
    'pkg6d_highlight_1' => 'Full-day game drive on the Ngorongoro Crater floor',
    'pkg6d_highlight_2' => 'One of Africa\'s best chances to see the "Big Five" in a single day',
    'pkg6d_highlight_3' => 'Free Maasai village visit, time permitting',

    'pkg6d_included_heading' => 'Included',
    'pkg6d_included_1' => 'Private or shared safari vehicle with driver-guide',
    'pkg6d_included_2' => 'Hotel pickup and drop-off in Arusha',
    'pkg6d_included_3' => 'Ngorongoro Conservation Area and crater fees',
    'pkg6d_included_4' => 'Picnic lunch and bottled water',
    'pkg6d_included_5' => 'Complimentary Maasai village visit, time permitting',
    'pkg6d_included_6' => '24/7 support during your trip',
