    'pkg6d_itinerary_title' => 'How the day unfolds',
    'pkg6d_day1_tl1_time' => '05:30',
    'pkg6d_day1_tl1_title' => 'Early pickup from Arusha',
    'pkg6d_day1_tl1_desc' => 'Your driver-guide collects you from your hotel or lodge in a 4x4 safari vehicle with a pop-up roof for the scenic drive toward the Ngorongoro Conservation Area, climbing through highland farmland and forest as the sun rises.',
    'pkg6d_day1_tl2_time' => '08:00',
    'pkg6d_day1_tl2_title' => 'Arrival at the crater rim',
    'pkg6d_day1_tl2_desc' => 'Your first view of the caldera from the rim, roughly 2,300 metres above sea level, before the vehicle begins its descent 600 metres down to the crater floor.',
    'pkg6d_day1_tl3_time' => '09:00',
    'pkg6d_day1_tl3_title' => 'Game drive on the crater floor',
    'pkg6d_day1_tl3_desc' => 'Hours exploring one of the densest wildlife concentrations in Africa: lions, elephants, buffaloes, hyenas, and with good fortune the endangered black rhino, alongside flamingo-lined Lake Magadi.',
    'pkg6d_day1_tl4_time' => '12:30',
    'pkg6d_day1_tl4_title' => 'Picnic lunch by the Hippo Pool',
    'pkg6d_day1_tl4_desc' => 'Lunch at a designated picnic site near the crater\'s hippo pool, watching hippos wallow just metres away while you rest before the afternoon session.',
    'pkg6d_day1_tl5_time' => '13:30',
    'pkg6d_day1_tl5_title' => 'Afternoon game drive',
    'pkg6d_day1_tl5_desc' => 'Continue exploring different sections of the crater floor as your guide tracks predators and explains how such a self-contained ecosystem supports so much wildlife year-round.',
    'pkg6d_day1_tl6_time' => '15:30',
    'pkg6d_day1_tl6_title' => 'Free Maasai village visit',
    'pkg6d_day1_tl6_desc' => 'Time permitting, a complimentary stop at a Maasai village on the crater highlands: traditional homes, songs and dancing, and a chance to meet local families.',
    'pkg6d_day1_tl7_time' => '16:30',
    'pkg6d_day1_tl7_title' => 'Ascend the crater rim, return to Arusha',
    'pkg6d_day1_tl7_desc' => 'The vehicle climbs back up to the rim for a final panoramic view before the drive back to Arusha. Drop-off at your hotel or lodge around 18:30–19:30.',

    'pkg6d_maasai_title' => 'Free Maasai village experience',
    'pkg6d_maasai_p1' => 'Time permitting, we stop at a Maasai village on the Ngorongoro highlands for a complimentary cultural visit, subject to local arrangements on the day. This is your chance to meet the people who have lived alongside this landscape\'s wildlife for generations.',
    'pkg6d_maasai_li1' => 'Meet Maasai community members',
    'pkg6d_maasai_li2' => 'See traditional homes and a boma',
    'pkg6d_maasai_li3' => 'Learn about livestock and pastoral life',
    'pkg6d_maasai_li4' => 'Enjoy traditional songs and dancing',
    'pkg6d_maasai_li5' => 'Learn about Maasai traditions and customs',
    'pkg6d_maasai_li6' => 'Meet local artisans and see traditional beadwork',
    'pkg6d_maasai_note' => 'The complimentary visit depends on timing and community availability on the day; it does not include personal purchases, donations or optional activities.',

    'pkg6d_why_title' => 'Why book this 1-day safari?',
    'pkg6d_why1_title' => 'Africa\'s best Big Five odds in one day',
    'pkg6d_why1_desc' => 'The crater\'s dense, contained wildlife population gives you one of the strongest single-day chances anywhere in Africa to see all of the Big Five.',
    'pkg6d_why2_title' => 'A self-contained ecosystem',
    'pkg6d_why2_desc' => 'Because most animals stay within the caldera year-round, sightings are far more reliable than on open plains where wildlife can range widely.',
    'pkg6d_why3_title' => 'A full-day wildlife experience',
    'pkg6d_why3_desc' => 'We maximise your time on the crater floor rather than rushing through a short visit.',
    'pkg6d_why4_title' => 'Free Maasai cultural bonus',
    'pkg6d_why4_desc' => 'Wildlife in the morning and afternoon, with a chance to meet a Maasai community when timing allows.',
    'pkg6d_why5_title' => 'Perfect for photographers',
    'pkg6d_why5_desc' => 'Dramatic crater walls, open grassland and dense wildlife make for exceptional photography opportunities.',
    'pkg6d_why6_title' => 'A professional safari guide',
    'pkg6d_why6_desc' => 'Your guide helps you understand what you\'re seeing, where to look and why the crater supports so much wildlife.',
    'pkg6d_why7_title' => 'Great value with limited time',
    'pkg6d_why7_desc' => 'If you only have one day available, you can still experience Tanzania\'s most iconic wildlife destination without committing to several nights.',

    'pkg6d_faq_title' => 'Ngorongoro Crater Day Trip: frequently asked questions',
    'pkg6d_faq_q1' => 'Is the Ngorongoro Crater worth visiting in just one day?',
    'pkg6d_faq_a1' => 'Yes. Because the crater is a self-contained ecosystem roughly 260 square kilometres in size, a single full day on the crater floor gives you excellent wildlife sightings, often including all of the Big Five.',
    'pkg6d_faq_q2' => 'Is this a full day or a half day?',
    'pkg6d_faq_a2' => 'A full day, roughly 05:30 to 19:00 including pickup and drop-off, with a picnic lunch on the crater floor included.',
    'pkg6d_faq_q3' => 'Can I combine this with other parks later?',
    'pkg6d_faq_a3' => 'Yes. Many travellers use this as one day within a longer northern circuit itinerary covering Tarangire, Serengeti and Lake Manyara. Ask us and we will build a multi-day route around it.',

