    'pkg4d_day4_tl3_time' => '12:30',
    'pkg4d_day4_tl3_title' => 'Free Maasai cultural visit',
    'pkg4d_day4_tl3_desc' => 'A complimentary visit to a Maasai community near Ngorongoro, subject to availability: traditional homes, songs and dancing, and a chance to meet local families.',
    'pkg4d_day4_tl4_time' => '15:00',
    'pkg4d_day4_tl4_title' => 'Return to Arusha',
    'pkg4d_day4_tl4_desc' => 'The drive back to Arusha, with time to relax and look back through your photographs from four unforgettable days. Drop-off at your hotel in the early evening.',

    'pkg4d_why_title' => 'Why book this 4-day safari?',
    'pkg4d_why1_title' => 'Three parks, properly paced',
    'pkg4d_why1_desc' => 'Enough time in each park to experience it fully, rather than rushing between destinations.',
    'pkg4d_why2_title' => 'The endless Serengeti plains',
    'pkg4d_why2_desc' => 'A full day and a half dedicated to one of the world\'s most famous wildlife destinations.',
    'pkg4d_why3_title' => 'Africa\'s best Big Five odds',
    'pkg4d_why3_desc' => 'The Ngorongoro Crater\'s contained ecosystem gives you one of the strongest single-day chances anywhere in Africa to see all of the Big Five.',
    'pkg4d_why4_title' => 'Free Maasai cultural bonus',
    'pkg4d_why4_desc' => 'A complimentary community visit near Ngorongoro, adding a cultural dimension to the wildlife experience.',
    'pkg4d_why5_title' => 'Comfortable lodge and camp stays',
    'pkg4d_why5_desc' => 'Three nights at Ngare Lodge and Tukaone Camp, positioned for easy access to each park.',
    'pkg4d_why6_title' => 'A professional safari guide',
    'pkg4d_why6_desc' => 'Your guide helps you understand what you\'re seeing and why each ecosystem works the way it does.',
    'pkg4d_why7_title' => 'Excellent value for a multi-day circuit',
    'pkg4d_why7_desc' => 'A complete northern circuit itinerary at a price that remains accessible for budget-conscious travellers.',

    'pkg4d_faq_title' => 'Tarangire, Serengeti &amp; Ngorongoro Safari: frequently asked questions',
    'pkg4d_faq_q1' => 'Is 4 days enough to see the Serengeti properly?',
    'pkg4d_faq_a1' => 'Yes. This itinerary dedicates a full day and a half to the Serengeti, which is enough time for excellent game viewing, especially when combined with Tarangire and Ngorongoro on the same trip.',
    'pkg4d_faq_q2' => 'What is the accommodation like?',
    'pkg4d_faq_a2' => 'You stay at Ngare Lodge near Karatu and Tukaone Camp in the Serengeti, both comfortable, well-located properties chosen for easy access to each park.',
    'pkg4d_faq_q3' => 'Can I see the Great Migration on this route?',
    'pkg4d_faq_a3' => 'It depends on the season, since the migration herds move throughout the year across the Serengeti ecosystem. Tell us your travel dates and we will advise on the best route for migration viewing.',

