    'pkgnc_meta_title' => 'The Ultimate Northern Circuit: 5-Day Safari | Serengeti Budget Safari',
    'pkgnc_meta_description' => 'A 5-day safari covering the full northern circuit: Arusha, Tarangire, Ngorongoro, Serengeti and Lake Manyara, from $925 per person.',
    'pkgnc_hero_title' => 'The Ultimate Northern Circuit',
    'pkgnc_fact_duration_val' => '5 days',
    'pkgnc_fact_pickup_val' => 'Arusha or Moshi hotel',
    'pkgnc_fact_start_val' => 'Every day',
    'pkgnc_calc_cta' => 'Ask on WhatsApp',

    'pkgnc_intro_p1' => 'The complete northern Tanzania experience in five days: Tarangire\'s elephant herds, a full-day Ngorongoro Crater descent, the endless plains of the Serengeti, and tree-climbing lions at Lake Manyara.',
    'pkgnc_intro_p2' => 'This is our most complete circuit, covering every major park in the north at a comfortable pace, from Arusha and back.',

    'pkgnc_highlights_heading' => 'Highlights',
    'pkgnc_highlight_1' => 'Full coverage of Tarangire, Ngorongoro, Serengeti and Lake Manyara',
    'pkgnc_highlight_2' => 'A full-day Ngorongoro Crater descent with excellent Big Five odds',
    'pkgnc_highlight_3' => 'Rare tree-climbing lions and thousands of flamingos at Lake Manyara',

    'pkgnc_included_heading' => 'Included',
    'pkgnc_included_1' => 'Professional English-speaking safari guide',
    'pkgnc_included_2' => '4x4 safari vehicle with pop-up roof',
    'pkgnc_included_3' => 'Park entry fees and conservation levies for all four parks',
    'pkgnc_included_4' => '4 nights accommodation (Arusha, Karatu/Mto wa Mbu and Serengeti)',
    'pkgnc_included_5' => 'Full board meals and bottled drinking water during game drives',
    'pkgnc_included_6' => 'Airport transfers on arrival and departure',
    'pkgnc_excluded_heading' => 'Not included',
    'pkgnc_excluded_1' => 'International flights and Tanzania visa fees',
    'pkgnc_excluded_2' => 'Travel insurance (compulsory)',
    'pkgnc_excluded_3' => 'Tips for guide and staff, alcoholic drinks and sodas',
    'pkgnc_excluded_4' => 'Personal expenses and optional activities (balloon safari, Maasai village visits)',

    'pkgnc_itinerary_title' => 'How your 5 days unfold',
    'pkgnc_day1_label' => 'Day 1',
    'pkgnc_day1_heading' => 'Arrival in Arusha, the gateway to safari',
    'pkgnc_day1_tl1_time' => 'On arrival',
    'pkgnc_day1_tl1_title' => 'Welcome to Arusha',
    'pkgnc_day1_tl1_desc' => 'On arrival at Kilimanjaro International Airport, your professional safari guide meets you and transfers you to your hotel, briefing you on the days ahead as Mount Meru comes into view.',
    'pkgnc_day1_tl2_time' => 'Afternoon',
    'pkgnc_day1_tl2_title' => 'Settle in at Green Mountain Hotel',
    'pkgnc_day1_tl2_desc' => 'A peaceful hotel on the slopes of Mount Meru, with beautiful gardens and, on a clear day, views across to Kilimanjaro. Depending on your arrival time, explore Arusha\'s local markets or the Cultural Heritage Centre.',
    'pkgnc_day1_tl3_time' => 'Evening',
    'pkgnc_day1_tl3_title' => 'Briefing and dinner',
    'pkgnc_day1_tl3_desc' => 'Your guide reviews the full itinerary with you over dinner, answers any questions, and makes sure you are ready for an early start into Tarangire tomorrow.',
    'pkgnc_day2_label' => 'Day 2',
    'pkgnc_day2_heading' => 'Tarangire National Park, land of giants',
    'pkgnc_day2_tl1_time' => 'Morning',
    'pkgnc_day2_tl1_title' => 'Drive to Tarangire',
    'pkgnc_day2_tl1_desc' => 'After breakfast, a scenic ~2.5-hour drive through the Maasai Steppe, past local villages and acacia-dotted landscapes, to Tarangire National Park.',
    'pkgnc_day2_tl2_time' => 'Midday',
    'pkgnc_day2_tl2_title' => 'Game drive among the elephant herds',
    'pkgnc_day2_tl2_desc' => 'Tarangire is famous for elephant herds sometimes over 300 strong, and its iconic ancient baobab trees. Watch for lions, leopards, giraffes, zebra and over 550 bird species, with a picnic lunch overlooking the Tarangire River.',
    'pkgnc_day2_tl3_time' => 'Evening',
    'pkgnc_day2_tl3_title' => 'Check in near Karatu',
    'pkgnc_day2_tl3_desc' => 'Settle in to your lodge near Karatu or Mto wa Mbu for dinner, ready for tomorrow\'s crater descent.',
    'pkgnc_day3_label' => 'Day 3',
    'pkgnc_day3_heading' => 'Ngorongoro Crater and into the Serengeti, a day of two wonders',
    'pkgnc_day3_tl1_time' => 'Early morning',
    'pkgnc_day3_tl1_title' => 'Descend into the crater',
    'pkgnc_day3_tl1_desc' => 'An early drive to the Ngorongoro Conservation Area, then down the winding crater road onto a floor roughly 20 kilometres wide, enclosed by walls rising 600 metres, home to one of the best single-day chances in Africa to see all of the Big Five.',
    'pkgnc_day3_tl2_time' => 'Midday',
    'pkgnc_day3_tl2_title' => 'Picnic lunch by the hippo pool',
    'pkgnc_day3_tl2_desc' => 'Watch black rhino, lion prides, buffalo herds, hippos and flamingos on Lake Magadi before a picnic lunch on the crater floor and the ascent back to the rim.',
    'pkgnc_day3_tl3_time' => 'Afternoon',
    'pkgnc_day3_tl3_title' => 'Into the endless Serengeti plains',
    'pkgnc_day3_tl3_desc' => 'The landscape opens into the Serengeti\'s rolling grasslands, over 14,000 square kilometres and the largest concentration of wildlife on the planet, with an afternoon game drive before arriving at your Serengeti camp for dinner under the stars.',
    'pkgnc_day4_label' => 'Day 4',
    'pkgnc_day4_heading' => 'Serengeti to Karatu, a final day of wildlife',
    'pkgnc_day4_tl1_time' => 'Early morning',
    'pkgnc_day4_tl1_title' => 'Sunrise game drive',
    'pkgnc_day4_tl1_desc' => 'The best time to see predators hunting: lions, cheetahs and leopards are most active in the golden morning light, alongside elephants, giraffes and, in season, the Great Migration herds.',
    'pkgnc_day4_tl2_time' => 'Midday',
    'pkgnc_day4_tl2_title' => 'Bush breakfast and departure',
    'pkgnc_day4_tl2_desc' => 'A final Serengeti breakfast before the ~4-hour drive back through the Ngorongoro Conservation Area, with stunning views of the crater rim, terraced highland farms and Maasai villages along the way.',
    'pkgnc_day4_tl3_time' => 'Evening',
    'pkgnc_day4_tl3_title' => 'Return to Karatu',
    'pkgnc_day4_tl3_desc' => 'Check in to your lodge near Karatu or Mto wa Mbu for a relaxed final night before Lake Manyara tomorrow.',
    'pkgnc_day5_label' => 'Day 5',
    'pkgnc_day5_heading' => 'Lake Manyara National Park, a hidden gem',
    'pkgnc_day5_tl1_time' => 'Morning',
    'pkgnc_day5_tl1_title' => 'Tree-climbing lions and flamingos',
    'pkgnc_day5_tl1_desc' => 'A short drive to Lake Manyara National Park, famous for its rare tree-climbing lions resting in acacia branches, and thousands of flamingos lining the soda lake, plus elephants, hippos and a lush groundwater forest.',
    'pkgnc_day5_tl2_time' => 'Midday',
    'pkgnc_day5_tl2_title' => 'Picnic lunch overlooking the lake',
    'pkgnc_day5_tl2_desc' => 'Lunch with views across the turquoise lake, the green forest and the dramatic Rift Valley escarpment.',
    'pkgnc_day5_tl3_time' => 'Afternoon',
    'pkgnc_day5_tl3_title' => 'Return to Arusha',
    'pkgnc_day5_tl3_desc' => 'The drive back to Arusha through scenic landscapes and local villages, arriving in the late afternoon to reflect on five unforgettable days across Tanzania\'s northern circuit.',

    'pkgnc_why_title' => 'Why book this 5-day safari?',
    'pkgnc_why1_title' => 'The complete northern circuit',
    'pkgnc_why1_desc' => 'Every major northern park in one itinerary, rather than choosing between them.',
    'pkgnc_why2_title' => 'Africa\'s best Big Five odds',
    'pkgnc_why2_desc' => 'The Ngorongoro Crater\'s contained ecosystem gives you one of the strongest single-day chances anywhere in Africa to see all of the Big Five, including the black rhino.',
    'pkgnc_why3_title' => 'The endless Serengeti plains',
    'pkgnc_why3_desc' => 'A full day and a half dedicated to one of the world\'s most famous wildlife destinations.',
    'pkgnc_why4_title' => 'Rare tree-climbing lions',
    'pkgnc_why4_desc' => 'Lake Manyara is one of the few places on Earth where lions regularly climb trees, a genuinely rare and memorable sighting.',
    'pkgnc_why5_title' => 'A choice of quality lodges and camps',
    'pkgnc_why5_desc' => 'Comfortable, well-reviewed properties near Karatu or Mto wa Mbu and in the Serengeti, chosen for easy access to each park.',
    'pkgnc_why6_title' => 'A professional safari guide',
    'pkgnc_why6_desc' => 'Your guide helps you understand what you\'re seeing and why each ecosystem works the way it does.',
    'pkgnc_why7_title' => 'Excellent value for a complete circuit',
    'pkgnc_why7_desc' => 'The full northern circuit at a price that remains accessible for budget-conscious travellers, with the price per person dropping for larger groups.',

    'pkgnc_faq_title' => 'The Ultimate Northern Circuit: frequently asked questions',
    'pkgnc_faq_q1' => 'Is 5 days enough to cover the whole northern circuit?',
    'pkgnc_faq_a1' => 'Yes. This itinerary is designed to give each park a genuine, unrushed visit: Tarangire, Ngorongoro, the Serengeti and Lake Manyara, all within five comfortably paced days.',
    'pkgnc_faq_q2' => 'What is the accommodation like?',
    'pkgnc_faq_a2' => 'You stay at Green Mountain Hotel in Arusha, a lodge near Karatu or Mto wa Mbu (Ngare Lodge, Fig Tree Lodge or Foresight Eco Lodge), and a Serengeti camp (Tukaone Camps or Tanzania Bush Camp), each chosen for easy access to the next day\'s park.',
    'pkgnc_faq_q3' => 'Can I see the Great Migration on this route?',
    'pkgnc_faq_a3' => 'It depends on the season, since the migration herds move throughout the year across the Serengeti ecosystem. Tell us your travel dates and we will advise on the best route for migration viewing.',

    'pkgnc_price_banner_label' => 'Starting from',
    'pkgnc_price_banner_group' => 'for 2 travellers',

    'pkgnc_pricing_heading' => 'Price per person',
    'pkgnc_pricing_note' => 'The more you travel together, the lower the price per person.',
    'pkgnc_pricing_guests' => 'Travellers',

