    'pkgnc_quick_contact_email' => 'Email us',

    // ===== GREAT MIGRATION SEASON PAGES (mig1-mig5) =====
    'mig1_meta_title' => 'Calving Season Safari (Jan-Mar): Ndutu & Southern Serengeti | Serengeti Budget Safari',
    'mig1_meta_description' => 'Witness the Great Migration calving season in Ndutu and the Southern Serengeti, January to March, from $1,250 per person. 5 real itinerary options, honest advice, no fake promises.',
    'mig1_hero_title' => 'Calving Season Safari: Ndutu & Southern Serengeti',
    'mig1_hero_sub' => 'Where thousands of new lives begin',
    'mig1_fact_months_val' => 'January to March',
    'mig1_fact_region_val' => 'Ndutu & Southern Serengeti',
    'mig1_fact_options_val' => '5 itinerary options',
    'mig1_intro_p1' => 'Every year between January and March, the Great Migration herds gather on the short-grass plains of Ndutu and the Southern Serengeti for one of nature\'s most moving events: the birth of nearly half a million wildebeest calves in the space of a few weeks. February is the peak of calving season, when thousands of calves are born each day, drawing lions, cheetahs and hyenas close behind.',
    'mig1_intro_p2' => 'This is the best migration season for first-time safari-goers and photographers alike: predictable herd locations, dramatic predator action and golden light across open plains. We build every calving-season itinerary from Arusha, and offer fly-in options from Zanzibar for travellers combining beach and bush.',
    'mig1_highlights_heading' => 'Highlights',
    'mig1_highlight_1' => 'Peak wildebeest calving in February, with newborns, zebra and gazelles across the plains',
    'mig1_highlight_2' => 'Lions, cheetahs and hyenas hunting close to the herds, some of the best predator action of the year',
    'mig1_highlight_3' => '5 real itinerary options, from a 4-day Ndutu focus to a fly-in/fly-out Zanzibar combo',
    'mig1_honesty_box' => 'We don\'t promise nature, we take you into it. A wildebeest birth, a predator kill or a river crossing are wild, natural events controlled by rainfall, grass, water levels and animal behaviour, never by a company\'s schedule. We follow the migration, we don\'t make promises on behalf of nature.',
    'mig1_included_heading' => 'Included',
    'mig1_included_1' => 'Private 4x4 safari vehicle (Land Cruiser) with pop-up roof, large windows and comfortable seats',
    'mig1_included_2' => 'USB and Type-C charging, fridge, binoculars and safari radio on board',
    'mig1_included_3' => 'Professional English-speaking safari guide',
    'mig1_included_4' => 'Fuel, all game drives and vehicle running costs',
