    'mig1_why3_desc' => 'From a fast 4-day Ndutu trip to a 6-day extended circuit, choose the option that matches your time and budget.',
    'mig1_why4_title' => 'Honest, local guiding',
    'mig1_why4_desc' => 'We tell you what nature can realistically offer this season, we do not oversell a guaranteed spectacle.',
    'mig1_faq_title' => 'Frequently asked questions',
    'mig1_faq_q1' => 'Can I combine this with other parks or a beach extension?',
    'mig1_faq_a1' => 'Yes. Every itinerary here can be extended with Tarangire, Lake Manyara, Zanzibar or a Ngorongoro Crater add-on. Tell us your dates and interests and we will adapt one of the options below or build a custom route.',
    'mig1_faq_q2' => 'Can you guarantee we will see the migration or a river crossing?',
    'mig1_faq_a2' => 'No, and we would not trust an operator who claims otherwise. A wildebeest birth, a predator kill or a river crossing are wild, natural events controlled by rainfall, grass, water levels and animal behaviour, not by any company\'s schedule. We follow the migration, we do not make promises on behalf of nature. What we do guarantee is an experienced guide who reads the conditions, tracks and other vehicles\' reports to give you the best realistic chance.',
    'mig1_faq_q3' => 'Is February really the best month?',
    'mig1_faq_a3' => 'February is generally considered the peak of calving season and the single best month for first-timers and photographers, but January and March also offer strong wildlife viewing as the migration arrives and then prepares to move. We can advise on the best window for your exact travel dates.',
    'mig1_faq_q4' => 'Which option should I choose?',
    'mig1_faq_a4' => 'If you have only 4 days, choose the Pure Ndutu Migration Experience or the Fly-In & Fly-Out Migration Safari. If you want the classic northern circuit plus calving, choose the 5-day Classic Northern Circuit + Ndutu. If you have more time and want deeper Big Five coverage, the 6-day Extended Calving & Big Five Safari adds Tarangire and Central Serengeti.',
    'mig1_price_banner_label' => 'Starting from',
    'mig1_price_banner_value' => '$1,250',
    'mig1_price_banner_sub' => '5 itinerary options available below',
    'mig1_enquiry_title' => 'Need more info?',
    'mig1_enquiry_adults' => 'Adults',
    'mig1_enquiry_children' => 'Children',
