    'mig1_calc_cta' => 'Ask on WhatsApp',
    'mig2_meta_title' => 'Migration in Motion Safari (Apr-Jun): Southern to Western Serengeti | Serengeti Budget Safari',
    'mig2_meta_description' => 'Follow the Great Migration herds on the move, April to June, through the Southern, Central and Western Serengeti, from $1,250 per person. 5 real itinerary options, fewer tourists, honest guiding.',
    'mig2_hero_title' => 'Migration in Motion Safari: Follow the Herds',
    'mig2_hero_sub' => 'Follow the herds as the great journey begins',
    'mig2_fact_months_val' => 'April to June',
    'mig2_fact_region_val' => 'Southern, Central & Western Serengeti',
    'mig2_fact_options_val' => '5 itinerary options',
    'mig2_intro_p1' => 'From April to June, the herds leave the calving grounds of the south and begin their long walk toward fresh grass in the west. May is when the migration is truly "in motion", large columns of wildebeest and zebra stretching across the plains, and June sees the Western Corridor and the Grumeti region grow in importance as the herds keep moving.',
    'mig2_intro_p2' => 'This is a rewarding, less-crowded season: the drama of a migrating herd without the peak-season crowds of July and August. We build road safaris from Arusha and fly-in options from Zanzibar, all following the same moving herds.',
    'mig2_highlights_heading' => 'Highlights',
    'mig2_highlight_1' => 'Large migrating herds moving from the south toward the Western Corridor',
    'mig2_highlight_2' => 'Fewer tourists than peak season, with lions, cheetahs, leopards and hyenas following the herds',
    'mig2_highlight_3' => '5 real itinerary options, from a 4-day Ngorongoro combo to a 6-day deep migration experience',
    'mig2_honesty_box' => 'We don\'t promise nature, we take you into it. A wildebeest birth, a predator kill or a river crossing are wild, natural events controlled by rainfall, grass, water levels and animal behaviour, never by a company\'s schedule. We follow the migration, we don\'t make promises on behalf of nature.',
    'mig2_included_heading' => 'Included',
