    'mig2_acc_budget_name' => 'Budget / Comfortable',
    'mig2_acc_budget_desc' => 'Good-value camps and lodges close to the action, comfortable without the luxury price tag.',
    'mig2_acc_midrange_name' => 'Mid-Range',
    'mig2_acc_midrange_desc' => 'Comfortable tented camps in good locations, a popular balance of comfort and value for a migration trip.',
    'mig2_acc_premium_name' => 'Premium / Luxury',
    'mig2_acc_premium_desc' => 'High-end camps in exceptional locations with outstanding comfort and service.',
    'mig2_acc_tip' => 'Migration tip: for a migration-focused trip, camp location relative to the expected herd movement matters more than luxury level. We help you choose based on your season and dates.',
    'mig2_why_title' => 'Why book this safari with us',
    'mig2_why1_title' => 'Fewer crowds, same drama',
    'mig2_why1_desc' => 'April to June sees far fewer visitors than the Mara River season, while the herds are just as active.',
    'mig2_why2_title' => 'Western Corridor access',
    'mig2_why2_desc' => 'Several options take you into the Grumeti region as the herds begin to arrive, ahead of the July crowds.',
    'mig2_why3_title' => 'Flexible durations',
    'mig2_why3_desc' => 'Choose from a 4-day Ngorongoro combo for limited time, up to a 6-day deep migration experience.',
    'mig2_why4_title' => 'Zanzibar combinations',
    'mig2_why4_desc' => 'Fly in from the beach, follow the migration, then either fly back or drive out via Ngorongoro.',
    'mig2_faq_title' => 'Frequently asked questions',
    'mig2_faq_q1' => 'Can I combine this with other parks or a beach extension?',
    'mig2_faq_a1' => 'Yes. Every itinerary here can be extended with Tarangire, Lake Manyara, Zanzibar or a Ngorongoro Crater add-on. Tell us your dates and interests and we will adapt one of the options below or build a custom route.',
    'mig2_faq_q2' => 'Can you guarantee we will see the migration or a river crossing?',
    'mig2_faq_a2' => 'No, and we would not trust an operator who claims otherwise. A wildebeest birth, a predator kill or a river crossing are wild, natural events controlled by rainfall, grass, water levels and animal behaviour, not by any company\'s schedule. We follow the migration, we do not make promises on behalf of nature. What we do guarantee is an experienced guide who reads the conditions, tracks and other vehicles\' reports to give you the best realistic chance.',
    'mig2_faq_q3' => 'Will we definitely see the migrating herds?',
    'mig2_faq_a3' => 'The herds are on the move throughout this season and our guides track their location daily using field reports and experience, so sightings are very likely. That said, exact positions shift with rainfall and grass growth, we do not promise a specific location on a specific day.',
    'mig2_faq_q4' => 'Which option should I choose?',
    'mig2_faq_a4' => 'For limited time, choose the 4-day Migration + Ngorongoro or the Fly-In & Fly-Out Migration. For the classic road safari, choose the 5-day Classic Migration Road Safari. For the most complete coverage of the moving herds, choose the 6-day Deep Migration Experience.',
    'mig2_price_banner_label' => 'Starting from',
    'mig2_price_banner_value' => '$1,250',
