    'mig2_calc_cta' => 'Ask on WhatsApp',
    'mig3_meta_title' => 'Grumeti River Migration Safari (May-Jul): Western Serengeti | Serengeti Budget Safari',
    'mig3_meta_description' => 'Follow the Great Migration into the Western Corridor and the Grumeti region, May to July, from $1,350 per person. 5 real itinerary options, honest advice on crossing chances.',
    'mig3_hero_title' => 'Grumeti River Migration Safari: Western Corridor',
    'mig3_hero_sub' => 'Where the migration meets the river',
    'mig3_fact_months_val' => 'May to July',
    'mig3_fact_region_val' => 'Western Serengeti & Grumeti Region',
    'mig3_fact_options_val' => '5 itinerary options',
    'mig3_intro_p1' => 'From May to July, the migration pushes west, drawn by fresh grass and greener landscapes in the Western Corridor. June is the key month, when the herds concentrate around the Grumeti region, and by July the movement begins shifting north. This stretch of the migration is famous for the Grumeti River itself, home to some of the Serengeti\'s largest crocodiles.',
    'mig3_intro_p2' => 'A Grumeti River crossing is one of the great sights of the migration, but it is never guaranteed: it depends entirely on rainfall, pasture, water levels and the herds\' own behaviour. What we can guarantee is a guide who understands the region and gives you the best realistic chance of seeing the migration at the river.',
    'mig3_highlights_heading' => 'Highlights',
    'mig3_highlight_1' => 'The Western Corridor and Grumeti region as the herds push west',
    'mig3_highlight_2' => 'The Grumeti River itself, with hippos and some of the Serengeti\'s largest crocodiles',
    'mig3_highlight_3' => '5 real itinerary options, from a 4-day fly-in to a 6-day extended Western Corridor safari',
    'mig3_honesty_box' => 'We don\'t promise nature, we take you into it. A wildebeest birth, a predator kill or a river crossing are wild, natural events controlled by rainfall, grass, water levels and animal behaviour, never by a company\'s schedule. We follow the migration, we don\'t make promises on behalf of nature.',
