    'mig3_why1_desc' => 'May to July is when the migration is concentrated in the Western Corridor, before moving north.',
    'mig3_why2_title' => 'An honest crossing forecast',
    'mig3_why2_desc' => 'We never guarantee a Grumeti crossing, we tell you the real odds based on current conditions.',
    'mig3_why3_title' => 'Fewer crowds than the Mara',
    'mig3_why3_desc' => 'The Western Corridor sees noticeably fewer vehicles than the Northern Serengeti in peak season.',
    'mig3_why4_title' => 'Five ways to experience it',
    'mig3_why4_desc' => 'From a fast fly-in/fly-out to a 6-day extended circuit, we match the itinerary to your time and interests.',
    'mig3_faq_title' => 'Frequently asked questions',
    'mig3_faq_q1' => 'Can I combine this with other parks or a beach extension?',
    'mig3_faq_a1' => 'Yes. Every itinerary here can be extended with Tarangire, Lake Manyara, Zanzibar or a Ngorongoro Crater add-on. Tell us your dates and interests and we will adapt one of the options below or build a custom route.',
    'mig3_faq_q2' => 'Can you guarantee we will see the migration or a river crossing?',
    'mig3_faq_a2' => 'No, and we would not trust an operator who claims otherwise. A wildebeest birth, a predator kill or a river crossing are wild, natural events controlled by rainfall, grass, water levels and animal behaviour, not by any company\'s schedule. We follow the migration, we do not make promises on behalf of nature. What we do guarantee is an experienced guide who reads the conditions, tracks and other vehicles\' reports to give you the best realistic chance.',
    'mig3_faq_q3' => 'Will we see a Grumeti River crossing?',
    'mig3_faq_a3' => 'We cannot promise it. A crossing happens when the herds decide conditions are right, driven by rainfall, pasture and water levels on both banks. Our guides track the herds\' movement daily and position you with the best realistic chance, but nobody, including us, can guarantee a wild crossing on a fixed schedule.',
    'mig3_faq_q4' => 'Which option should I choose?',
    'mig3_faq_a4' => 'For very limited time, the 4-day Fly-In & Fly-Out Western Serengeti works well. For a balanced classic road safari, choose the 5-day Classic Grumeti Migration Safari. For travellers who want meaningful time in the Western Corridor, we recommend the 6-day Extended Grumeti & Western Serengeti.',
    'mig3_price_banner_label' => 'Starting from',
    'mig3_price_banner_value' => '$1,350',
