    'mig4_meta_title' => 'Mara River Crossing Safari (Jul-Oct): Northern Serengeti | Serengeti Budget Safari',
    'mig4_meta_description' => 'Witness the iconic Mara River crossings in Northern Serengeti and Kogatende, July to October, from $1,550 per person. 5 real itinerary options, honest advice, no fake guarantees.',
    'mig4_hero_title' => 'Mara River Crossing Safari: Northern Serengeti',
    'mig4_hero_sub' => 'The river, the herds, the moment you cannot predict',
    'mig4_fact_months_val' => 'July to October',
    'mig4_fact_region_val' => 'Northern Serengeti, Kogatende & Mara River',
    'mig4_fact_options_val' => '5 itinerary options',
    'mig4_intro_p1' => 'From July to October, the Great Migration reaches Northern Serengeti and the Mara River, home to the most famous image of the migration: thousands of wildebeest and zebra plunging across crocodile-filled waters. August is peak migration atmosphere and the most popular month for first-time visitors and photographers, September brings a high chance of dramatic action as the herds\' exact location shifts constantly, and October sees numbers begin to thin as some herds start moving south, with excellent viewing and fewer crowds.',
    'mig4_intro_p2' => 'A Mara crossing can never be guaranteed. It is controlled entirely by rainfall, grass, water levels and the herds\' own instincts, our guides search based on tracks, radio reports and the position of other vehicles, giving you the best realistic chance of witnessing this moment.',
    'mig4_highlights_heading' => 'Highlights',
    'mig4_highlight_1' => 'Thousands of wildebeest and zebra at the Mara River, with Nile crocodiles waiting below',
    'mig4_highlight_2' => 'Northern Serengeti and the Kogatende area, lions, leopards, cheetahs and elephants',
    'mig4_highlight_3' => '5 real itinerary options, from a fast 4-day Mara focus to a 6-day extended migration circuit',
    'mig4_honesty_box' => 'We don\'t promise nature, we take you into it. A wildebeest birth, a predator kill or a river crossing are wild, natural events controlled by rainfall, grass, water levels and animal behaviour, never by a company\'s schedule. We follow the migration, we don\'t make promises on behalf of nature.',
