    'mig4_acc_tip' => 'Migration tip: for a migration-focused trip, camp location relative to the expected herd movement matters more than luxury level. We help you choose based on your season and dates.',
    'mig4_why_title' => 'Why book this safari with us',
    'mig4_why1_title' => 'The most iconic migration moment',
    'mig4_why1_desc' => 'The Mara River crossing is the single most photographed scene of the Great Migration.',
    'mig4_why2_title' => 'Guides who read the conditions',
    'mig4_why2_desc' => 'We track herd movement daily through tracks, radio reports and other vehicles to maximise your chances.',
    'mig4_why3_title' => 'Flexible timing across four months',
    'mig4_why3_desc' => 'July through October each offer a different balance of crowds, weather and crossing likelihood.',
    'mig4_why4_title' => 'Zanzibar add-on available',
    'mig4_why4_desc' => 'Fly in from the beach for a faster, more direct route to the Mara River action.',
    'mig4_faq_title' => 'Frequently asked questions',
    'mig4_faq_q1' => 'Can I combine this with other parks or a beach extension?',
    'mig4_faq_a1' => 'Yes. Every itinerary here can be extended with Tarangire, Lake Manyara, Zanzibar or a Ngorongoro Crater add-on. Tell us your dates and interests and we will adapt one of the options below or build a custom route.',
    'mig4_faq_q2' => 'Can you guarantee we will see the migration or a river crossing?',
    'mig4_faq_a2' => 'No, and we would not trust an operator who claims otherwise. A wildebeest birth, a predator kill or a river crossing are wild, natural events controlled by rainfall, grass, water levels and animal behaviour, not by any company\'s schedule. We follow the migration, we do not make promises on behalf of nature. What we do guarantee is an experienced guide who reads the conditions, tracks and other vehicles\' reports to give you the best realistic chance.',
    'mig4_faq_q3' => 'What is the single best month to see a crossing?',
    'mig4_faq_a3' => 'August is generally considered the peak migration atmosphere and the most popular month for first-timers and photographers, though September often brings dramatic action too as herds move constantly along the river. No month can guarantee a crossing on any specific day.',
    'mig4_faq_q4' => 'Which option should I choose?',
    'mig4_faq_a4' => 'If time is very limited, the Mara River Focus Safari (4 days) concentrates entirely on the north. For a balanced classic itinerary, the 5-Day Classic Mara River Safari is one of our most popular. For more searching time, the 6-Day Extended Mara River Migration adds an extra full day at the river.',
