    'mig5_meta_title' => 'Zanzibar to Serengeti Great Migration Safari (Jul-Oct) | Serengeti Budget Safari',
    'mig5_meta_description' => 'Combine the beach and the bush: fly from Zanzibar straight into the Great Migration in Northern Serengeti, July to October, from $1,850 per person. 3 real itinerary options.',
