    'mig5_intro_p1' => 'For travellers who want the Indian Ocean and the Great Migration in a single trip, this is the Zanzibar-first way to experience the same July to October migration season as our Mara River Crossing Safari, just built around a beach start rather than a road departure from Arusha. July sees the migration building in the north, August is peak Mara activity and our most popular month, September remains excellent, and October is still rewarding as some herds begin drifting south.',
    'mig5_intro_p2' => 'If migration is your main priority, we recommend 6 days. If you want migration plus Ngorongoro Crater, 5 days is the balanced choice. If you have limited time, the 4-day fly-in/fly-out option gets you into the action fastest.',
    'mig5_highlights_heading' => 'Highlights',
