    'mig5_faq_a2' => 'No, and we would not trust an operator who claims otherwise. A wildebeest birth, a predator kill or a river crossing are wild, natural events controlled by rainfall, grass, water levels and animal behaviour, not by any company\'s schedule. We follow the migration, we do not make promises on behalf of nature. What we do guarantee is an experienced guide who reads the conditions, tracks and other vehicles\' reports to give you the best realistic chance.',
    'mig5_faq_q3' => 'Which duration should I choose?',
    'mig5_faq_a3' => 'If migration is your priority, choose 6 days. If you want migration plus Ngorongoro Crater, choose 5 days. If you have limited time, choose the 4-day fly-in/fly-out option.',
    'mig5_faq_q4' => 'Is this different from the Mara River Crossing Safari?',
    'mig5_faq_a4' => 'Both cover the same July to October migration season in Northern Serengeti. Our Mara River Crossing Safari is built primarily as a road safari from Arusha with an optional Zanzibar add-on, while this page is Zanzibar-first, designed specifically for beach-and-safari combination travellers.',
    'mig5_price_banner_label' => 'Starting from',
    'mig5_price_banner_value' => '$1,850',
    'mig5_price_banner_sub' => '3 itinerary options available below',
    'mig5_enquiry_title' => 'Need more info?',
    'mig5_enquiry_adults' => 'Adults',
