    'lux1_calc_cta' => 'Ask on WhatsApp',

    'lux1_intro_p1' => 'A private luxury safari designed for travellers who want to experience two of northern Tanzania\'s finest parks without compromising on comfort or time. This safari is designed for travellers who believe the journey matters just as much as the destination.',
    'lux1_intro_p2' => 'Three days is enough to properly explore the elephant herds and ancient baobabs of Tarangire and descend into the Ngorongoro Crater for one of the richest wildlife experiences in Africa, all from comfortable luxury lodges.',

    'lux1_highlights_heading' => 'Highlights',
