    'lux1_day3_tl1_title' => 'Drive to Ngorongoro',
    'lux1_day3_tl1_desc' => 'An early breakfast, then the drive up to the Ngorongoro Crater rim, with sweeping views over the volcanic caldera before the descent.',
    'lux1_day3_tl2_time' => 'Late morning',
    'lux1_day3_tl2_title' => 'Crater floor game drive',
    'lux1_day3_tl2_desc' => 'Hours exploring the crater floor in search of the Big Five, including lion, buffalo, zebra, wildebeest, hippo and the elusive black rhino.',
