    'lux1_why2_title' => 'One of Africa\'s best Big Five odds',
    'lux1_why2_desc' => 'The contained ecosystem of the Ngorongoro Crater gives you one of the strongest single-day chances anywhere in Africa to see all of the Big Five.',
