    'lux1_faq_q1' => 'What is included in the price?',
    'lux1_faq_a1' => 'The price includes your private vehicle and guide, all park and conservation fees, luxury lodge accommodation, meals as specified and airport transfers. International flights, visa, insurance, tips and personal expenses are not included.',
    'lux1_faq_q2' => 'Is a wildlife sighting guaranteed?',
    'lux1_faq_a2' => 'The wild does not follow a schedule, nothing is guaranteed, and that is exactly why it is so special. Our guides know the parks intimately and give you the best possible chance of remarkable sightings.',
    'lux1_faq_q3' => 'Can I extend this safari or add extra nights?',
    'lux1_faq_a3' => 'Yes, extra nights, private flights and additional cultural experiences can all be arranged on request. Contact us and we will tailor the itinerary to your dates.',

