    'lux4_intro_p2' => 'Luxury is not only about where you sleep, it is having the time to experience what matters to you. Six days is enough to properly explore Tarangire, spend two full nights in the Serengeti, descend into the Ngorongoro Crater and finish among the forests and lake shores of Lake Manyara.',

